def find_most_frequent(array):
    # Define a dictionary to store the occurrence of each string.
    occur_dict = {}
    for word in array:
        if word in occur_dict:
            occur_dict[word] += 1
        else:
            occur_dict[word] = 1
    # Find the most frequent item
    most_frequent = max(occur_dict, key=lambda key: occur_dict[key])
    return most_frequent

