public class UniqueArray {
 public static void main(String[] args) {
  // Input string
  String input = "foo, bar, foo";

  // Split the string
  String[] inputArray = input.split(",");

  // Create a new array with the size of the input array
  String[] uniqueArray = new String[inputArray.length];

  // Iterate over the input array
  int index = 0;
  for (String s : inputArray) {
   // Check if the current string is already present in the unique array
   if (!contains(uniqueArray, s)) {
    // If not, add it to unique array
    uniqueArray[index++] = s;
   }
  }

  // Print the unique array
  System.out.println(Arrays.toString(uniqueArray));
 }

 // Helper method to check if a given string is present in the given array
 private static boolean contains(String[] array, String s) {
  for (String string : array) {
   if (string != null && string.equals(s)) {
    return true;
   }
  }
  return false;
 }
}

