function getCallerFuncName() {
 var funcName;
 try {
 throw new Error();
 }
 catch (e) {
 var errLines = e.stack.split("\n");
 var callerIndex = 0;
// First line is 'Error' so start with the second line
 for (var i = 1; i < errLines.length; i++){
 // Search for the first line with "at"
 if (errLines[i].indexOf('at ') >= 0){
 callerIndex = i;
 break;
 }
 }
// The line with 'at' could be the line of the anonymous
// function that called the parent function so check
// the previous line
 if (errLines[callerIndex - 1].indexOf('at ') >= 0){
 callerIndex--;
 }
// Get the function name from the line
// Format will be 'at FUNC_NAME (...)'
 funcName = errLines[callerIndex]
 .replace('at ', '')
 .split(' ')[0];
 }
 return funcName;
}

