// Function to generate random passwords of different length and complexity
function generatePassword(length, complexity){
 // Validate length and complexity
 if(typeof length !== 'number' || length < 3 || !Number.isInteger(length))
  throw new Error("You must specify a password length that is a whole number greater than 3.");
 if(typeof complexity !== "string" || complexity.length > 3 || complexity.length < 1)
  throw new Error("You must specify a password complexity of 1 to 3 characters.");

 // Define what characters can be used in the password
 let acceptableComplexities = {
  l : "abcdefghijklmnopqrstuvwxyz",
  u : "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
  d : "0123456789",
  s : "!@#$%^&*(){}[]?/<>"
 };

 // Get acceptable password characters based on the specified complexity
 let acceptableCharacters = "";
 for(let i = 0; i < complexity.length; i++){
  acceptableCharacters += acceptableComplexities[complexity[i]];
 }

 // Generate password
 let password = "";
 for(let i = 0; i < length; i++){
  let chosenCharacterIndex = Math.floor(Math.random() * acceptableCharacters.length);
  let chosenCharacter = acceptableCharacters[chosenCharacterIndex];
  password += chosenCharacter;
 }

 // Return password
 return password;
}

