void printCombination(int n, int num) 
{ 
    int nums[n]; 

    // Fill the array with the numbers from 1 to n 
    for (int i = 0; i < n; i++) 
        nums[i] = i + 1; 

    // Print all possible numbers combination 
    for (int i = 0; i < num; i++) { 
        for (int j = 0; j < n; j++) 
            std::cout << nums[j] << " "; 
        std::cout << std::endl; 

        // Generate next combination 
        int m = n - 1; 
        while (m >= 0 && nums[m] == num - n + m) 
            m--; 
        if (m >= 0) { 
            nums[m]++; 
            for (int k = m + 1; k < n; k++) 
                nums[k] = nums[k - 1] + 1; 
        } 
    } 
} 

