void bubble_sort(int array[], int len) {
 int i, j, tmp, is_sorted = 0;
 for (i = 0; i < len; i++) {
 if (is_sorted) break;
 is_sorted = 1;
 for (j = 0; j < len - 1 - i; j++) {
 if (array[j] > array[j+1]) {
 tmp = array[j];
 array[j] = array[j+1];
 array[j+1] = tmp;
 is_sorted = 0;
 }
 }
 }
}

