def check_bracket_balance(string):
    stack = []
    for char in string:
        if char == '[' or char == '{' or char == '(':
            stack.append(char)
        elif(char == ']' or char == '}' or char == ')'):
            if ((len(stack) > 0) and
               ((stack[-1] == '[' and char == ']') or
               (stack[-1] == '(' and char == ')') or
                (stack[-1] == '{' and char == '}'))):
                stack.pop()
            else:
                return False

    if len(stack) == 0:
        return True
    else:
        return False

