import nltk

def detect_spam(message):
    # Process message
    tokens = nltk.word_tokenize(message) 
    message_words = [word.lower() for word in tokens if word.isalpha()]

    # Calculate the probability of the message being spam
    spam_probability = 0 
    for word in message_words:
        if word in spam_words:
            spam_probability += 1

    # Make a decision based on the probability
    if spam_probability >= 5:
        return 'SPAM'
    else:
        return 'NOT SPAM'

