def quicksort(xs: Array[Int]):
  def sort(l: Int, r: Int):
    val pivot = xs((l + r) / 2)
    var i = l
    var j = r
    while (i <= j) {
      while (xs(i) < pivot) i += 1
      while (xs(j) > pivot) j -= 1
      if (i <= j) {
        val tmp = xs(i)
        xs(i) = xs(j)
        xs(j) = tmp
        i += 1
        j -= 1
      }
    }

    if (l < j) sort(l, j)
    if (j < r) sort(i, r)

  sort(0, xs.length - 1)
}

