class PrimeNumber { 
    public static void findPrimeInRange(int lower, int upper) 
	{ 
		while (lower < upper) { 
			boolean isPrime = true; 

			for (int i = 2; i*i <= lower; i++) { 
				if (lower % i == 0) {
					isPrime = false; 
					break; 
				} 
			} 

			if (isPrime) 
				System.out.print(lower + " ");

			lower++; 
		} 
	} 

	public static void main(String args[]) 
	{ 
		int lower = 2, upper = 20; 
		System.out.print("Prime numbers between " + lower +" and " + upper + " are:"); 
		findPrimeInRange(lower, upper); 
	} 
}

