    n = len(items)
    dp = [[0 for w in range(maxWeight+1)] for i in range(n+1)]
    for i in range(1, n+1):
        for w in range(1, maxWeight+1):
            if items[i-1]['weight'] <= w:
                dp[i][w] = max(dp[i-1][w], dp[i-1][w - items[i-1]['weight']] + items[i-1]['value'])
