def is_valid(grid, row, col, num): 
    # Check if 'num' is not already placed  
    # in current row, current column and current 3x3 box 
    if not used_in_row(grid, row, num) and not used_in_col(grid, col, num) and not used_in_box(grid, row - row%3, col - col%3, num):
        return True
    return False

def used_in_row(grid, row, num): 
    for col in range(9):
        if grid[row][col] == num:
            return True
    return False
def used_in_col(grid, col, num): 
    for row in range(9):
        if grid[row][col] == num:
            return True
    return False    
def used_in_box(grid, row_start, col_start, num): 
    for row in range(3): 
        for col in range(3):
            if grid[row + row_start][col + col_start] == num: 
                return True
    return False

