def quick_sort(array):
    if len(array) <= 1:
        return array

    pivot = array.pop()
    greater, lesser = [], []

    for x in array:
        if x <= pivot:
            lesser.append(x)
        else:
            greater.append(x)

    return quick_sort(lesser) + [pivot] + quick_sort(greater)

