    HashSet<Integer> hs = new HashSet<>();  
    // Insert elements of array in set  
    for (int i = 0; i < arr.length; i++) {  
        Integer ptr = arr[i];  
        hs.add(ptr);  
    }  

    // Find most frequent element 
    int maxCount = 0;  
    int element = Integer.MIN_VALUE;  
    for (Integer ptr : hs) {  
        int count = 0;  
        for (int i = 0; i < arr.length; i++) {  
