function insert(head, val, n) {
    let node = new Node(val);
    if (n === 0) {
        node.next = head;
        return node;
    }
    let pointer = head;
    let counter = 0;
    while (pointer && counter < n - 1) {
        pointer = pointer.next;
        counter++;
    }
    node.next = pointer.next;
    pointer.next = node;
    return head;
}

