def optimize_function(x,y):
    x_opt = 2
    y_opt = 2
    min_val = 100 
    step_size = 0.1

    while True:
        val = (x-x_opt)**2 + (y-y_opt)**2
        if val <= min_val:
            min_val = val
            x_opt = x
            y_opt = y
        else:
            break

        x += step_size
        y += step_size

    return (x_opt, y_opt)

