def longestCommonSubsequence(x, y): 
    m = len(x) 
    n = len(y) 

    # Create a 2D array to store lengths of subsequences 
    L = [[None] * (n + 1) for i in range(m + 1)] 

    # Fill the 2D array in bottom up manner 
    for i in range(m + 1): 
        for j in range(n + 1): 
            if i == 0 or j == 0: 
                L[i][j] = 0
            elif x[i - 1] == y[j - 1]: 
                L[i][j] = L[i - 1][j - 1] + 1
            else: 
                L[i][j] = max(L[i - 1][j], L[i][j - 1]) 

    # Generate the longest common subsequence 
    index = L[m][n] 

    lcs = [""] * (index + 1) 
    lcs[index] = "" 

    # Start from the right-most-bottom-most corner and 
    # one by one store characters in lcs[] 
    i, j = m, n 
    while i > 0 and j > 0: 

        if x[i - 1] == y[j - 1]: 
            lcs[index - 1] = x[i - 1] 
            i -= 1
            j -=1
            index -= 1

        elif L[i - 1][j] > L[i][j - 1]: 
            i -= 1
        else: 
            j -= 1

    return "".join(lcs)

