void spiralPrint(int m, int n){
  int i, j;
  int startRow = 0;
  int startCol = 0;

  while ( startRow < m && startCol < n ) {
    for (i = startCol; i < n; i++){
      cout << m*i + startRow + 1 << " ";
    }
    startRow++;

    for (j = startRow; j < m; j++) {
      cout << m*(n-1) + j + 1 << " ";
    }
    n--;

    if ( startRow < m) {
      for (i = n-1; i >= startCol; i--) {
        cout << m*i + startRow + 1<< " ";
      }
      m--;
    }

    if (startCol < n) {
      for (j = m-1; j >= startRow; j--) {
        cout << m*startCol + j + 1 << " ";
      }
      startCol++;
    }

  }
}

