function quicksort(arr) {
  if (arr.length <= 1) return arr;

  const pivot = arr[arr.length - 1];  // always use last element as the pivot
  let left = [];
  let right = [];

  for (let i = 0; i < arr.length - 1; i++) {
    if (arr[i] < pivot) {
      left.push(arr[i]);
    } else {
      right.push(arr[i]);
    }
  }

  return [...quicksort(left), pivot, ...quicksort(right)];
}

