Node* mergeTwoLists(Node* list1, Node* list2) 
{ 
    Node* result = NULL; 

    /* Base cases */
    if (list1 == NULL) 
        return(list2); 
    else if (list2 == NULL) 
        return(list1); 

    /* Pick either a or b, and recur */
    if (list1->data <= list2->data) 
    { 
        result = list1; 
        result->next = mergeTwoLists(list1->next, list2); 
    } 
    else 
    { 
        result = list2; 
        result->next = mergeTwoLists(list1, list2->next); 
    } 
    return(result); 
}

