import React, { useEffect, useState } from "react";
import { scaleLinear } from "d3-scale";
import { max } from "d3-array";
import { select } from "d3-selection";

const barchart = (props) => {
  const { data } = props;
  const [barData, setBarData] = useState([]);

  useEffect(() => {
    if (data && data.length > 0) {
      setBarData(
        data.map((d) => {
          return {
            name: d.name,
            age: +d.age,
            gender: d.gender,
          };
        })
      );
    }
  }, [data]);

  useEffect(() => {
    // set up a svg
    const svg = select('svg');

    // setup the scale
    const xValue = (d) => d.age;
    const xAxisLabel = "Age";
    const yValue = (d) => d.name;
    const yAxisLabel = "Name";

    const width = 960;
    const height = 500;

    const margin = { top: 80, right: 20, bottom: 120, left: 120 };
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    const xScale = scaleLinear().domain([0, max(barData, xValue)]).range([0, innerWidth]);
    const yScale = scaleLinear().domain([0, max(barData, yValue)]).range([0, innerHeight]);

    const xAxis = (g) =>
      g
        .attr("transform", `translate(${margin.left}, ${margin.top + innerHeight})`)
        .call(d3.axisBottom(xScale).tickFormat(d3.format(".2s")).tickSize(-innerHeight))
        .call((g) => g.select(".domain").remove());

    const yAxis = (g) =>
      g
        .attr("transform", `translate(${margin.left}, ${margin.top})`)
        .call(d3.axisLeft(yScale).ticks(10))
        .call((g) => g.select(".domain").remove());

    // create a rect for each entry in the data
    const g = svg
      .append("g")
      .attr("transform", `translate(${margin.left}, ${margin.top})`)
      .selectAll(".bar")
      .data(barData);

    const rect = g
      .enter()
      .append("rect")
      .attr("x", 0)
      .attr("y", (d) => yScale(yValue(d)))
      .attr("width", (d) => xScale(xValue(d)))
      .attr("height", yScale.bandwidth())
      .attr("fill", (d) => {
        if (d.gender === "M") {
          return "blue";
        } else {
          return "pink";
        }
      });

    const xAxisG = svg.append("g").call(xAxis);

    xAxisG
      .select(".domain")
      .remove()
      .append("text")
      .attr("x", innerWidth / 2)
      .attr("y", margin.bottom * 0.9)
      .text(xAxisLabel);

    const yAxisG = svg.append("g").call(yAxis);

    yAxisG
      .select(".domain")
      .remove()
      .append("text")
      .attr("x", -innerHeight / 2)
      .attr("y", -margin.left * 0.8)
      .attr("fill", "black")
      .attr("transform", "rotate(-90)")
      .text(yAxisLabel);
  }, [barData]);

  return (
    <div>
      <svg width={width} height={height}></svg>
    </div>
  );
};

