func fibonacci(n: Int) -> [Int] {
    var sequence = [0, 1]
    if n <= 1 {
        return sequence
    }

    for _ in 0..<n-2 {
        let first = sequence[sequence.count - 2]
        let second = sequence.last!
        sequence.append(first + second)
    }

    return sequence
}

