def detect_fraud(transactions):
    # Keep track of anomalous transactions
    suspicious_indices = []
    for i, transaction in enumerate(transactions):
        # Check for duplicates
        if transaction in transactions[:i]:
            suspicious_indices.append(i)
        # Check for suspicious amounts
        if transaction.amount > 1000 or transaction.amount < 0.01:
            suspicious_indices.append(i)
    return suspicious_indices

public class FuzzySearch {

 public static float getSimilarityScore(String s1, String s2) {
 int s1Length = s1.length();
 int s2Length = s2.length();

 int maxLength = Math.max(s1Length, s2Length);

 int i = 0;
 int j = 0;
 int difference = 0;

 while (i < s1Length && j < s2Length) {
 if (s1.charAt(i) == s2.charAt(j)) {
 i++;
 j++;
 }
 else {
 i++;
 j++;
 difference++;
 }
 }

 float similarity = 1.0f - (float) difference / maxLength;
 return similarity;
 }

 public static void main(String[] args) {
 String s1 = "hello world";
 String s2 = "hi world";

 float similarityScore = getSimilarityScore(s1, s2);

 System.out.println("Similarity score: " + similarityScore);
 } 
}

