public class ArraySpiralPrinting {
    public static void PrintSpiral(int[][] a) { 
        int i, m = a.length, n = a[0].length;  

        int k = 0, l = 0; 
        while (k < m && l < n) { 
            for (i = l; i < n; ++i) {  
                Console.Write(a[k][i] + " "); 
            } 
            k++; 

            for (i = k; i < m; ++i) {  
                Console.Write(a[i][n - 1] + " "); 
            } 
            n--; 

            if (k < m) { 
                for (i = n - 1; i >= l; --i) {  
                    Console.Write(a[m - 1][i] + " "); 
                } 
                m--; 
            } 

            if (l < n) { 
                for (i = m - 1; i >= k; --i) { 
                    Console.Write(a[i][l] + " "); 
                } 
                l++; 
            } 
        } 
    }
}

def get_anagram_substrings(string1, string2):
