  row_max = len(arr) - 1
  col_min = 0
  col_max = len(arr[0]) - 1

  while (row_min <= row_max and col_min <= col_max):
    # printing the first row
    for i in range(col_min, col_max+1):
      print(arr[row_min][i], end=" ")
    row_min += 1

    # printing the last column
    for i in range(row_min, row_max+1):
      print(arr[i][col_max], end=" ")
    col_max -= 1

    # printing the last row
    if row_min <= row_max:
      for i in range(col_max, col_min-1, -1):
        print(arr[row_max][i], end=" ")
      row_max -= 1

    # printing the first column
    if col_min <= col_max:
      for i in range(row_max, row_min-1, -1):
        print(arr[i][col_min], end=" ")
      col_min += 1

