void vigenere_encrypt(char str[], char key[])
{
    int i, j;
    int str_len = strlen(str);
    int key_len = strlen(key);

    for(i = 0, j = 0; i < str_len; i++, j++)
    {
        if(j == key_len)
            j = 0;

        if(isupper(str[i]))
        {
            str[i] = ((str[i] - 'A' + (key[j] - 'A')) % 26) + 'A';
        }
        else if(islower(str[i]))
        {
            str[i] = ((str[i] - 'a' + (key[j] - 'a')) % 26) + 'a';
        }
    }
}

