public static List<Integer> sortInDescendingOrder(List<Integer> data) { 
	// Create a List to store result 
	List<Integer> result = new ArrayList<>(data);  
	// Use selection sort to sort in descending order 
	for (int i = 0; i < result.size() - 1; i++) {  
		int max = result.get(i); 
		int index = i; 

		for (int j = i + 1; j< result.size(); j++) { 
			if (result.get(j) > max) { 
				max = result.get(j); 
				index = j; 
			} 
		} 

		// Swap data 
		int temp = result.get(i); 
		result.set(i, max); 
		result.set(index, temp); 
	} 

	// return sorted list 
	return result; 
}

