public class LocationTracker extends Service {

  private Location currentLocation;

  private FusedLocationProviderClient fusedLocationClient;

  //Set up a FusedLocationProviderClient
  onCreate(Bundle bundle){
    fusedLocationClient = LocationServices.getFusedLocationProviderClient(this); 
  }

  //Get the user's current location
  public void getCurrentLocation(){
    //Access the user's current location
    fusedLocationClient.getLastLocation().addOnSuccessListener(this, new OnSuccessListener<Location>() {
      @Override
      public void onSuccess(Location location) {
        // Got last known location. In some rare situations this can be null.
        if (location != null) {
          currentLocation = location;
        }
      }
    });
  }

  //Method to track the user's location
  public void trackLocation(){
    //Set up a LocationRequest object to track the user's location in real time
    LocationRequest locationRequest = LocationRequest.create();
    locationRequest.setInterval(10000);
    locationRequest.setFastestInterval(3000);
    locationRequest.setPriority(LocationRequest.PRIORITY_HIGH_ACCURACY);

    //Set up a new location callback to track the user's location
    LocationCallback locationCallback = new LocationCallback() {
      @Override
      public void onLocationResult(LocationResult locationResult) {
        if (locationResult == null) {
            return;
        }
        currentLocation = locationResult.getLastLocation();
      };
    };

    //Start tracking the user's location using the location request and callback
    fusedLocationClient.requestLocationUpdates(locationRequest, locationCallback, null);
  }

}

