function findClosest(arr1, arr2) {
  let min = Infinity;
  let result = [];

  for (let i = 0; i < arr1.length; i++) {
    for (let j = 0; j < arr2.length; j++) {
      let diff = Math.abs(arr1[i] - arr2[j]);

      if (diff < min) {
        result = [arr1[i], arr2[j]];
        min = diff;
      }
    }
  }

  return result;
}

