def isSubstring(s, t): 
    M = len(s) 
    N = len(t) 

    # A loop to slide pat[] one by one 
    for i in range(N - M + 1): 

        # For current index i, check for pattern match 
        for j in range(M): 
            if (t[i + j] != s[j]): 
                break

        if (j == M - 1): 
            return i 

    return -1

