def optimize_route(locations, start, end):
 # create a graph in the form of an adjacency list
 graph = {}

 for location in locations:
 source, target, distance = location
 if source in graph:
 graph[source][target] = distance
 else:
 graph[source] = {target: distance}

 # create the distance table
 distance_table = {start: {start: 0}}

 for item in graph[start]:
 distance_table[item] = {start: graph[start][item]}

 # fill out the remaining values of the distance table
 for destination in graph:
 if destination != start:
 shortest_distances = {}
 for item in graph[destination]:
 if item in distance_table and destination in distance_table[item]:
 shortest_distances[item] = min(graph[destination][item] + distance_table[item][start], 
 distance_table[destination][start]
 )
 else:
 shortest_distances[item] = graph[destination][item]
 distance_table[destination] = shortest_distances

 # return the optimal route
 route = [end]
 distance = 0
 predecessor = distance_table[end]

 while start not in route:
 current = min(predecessor.keys(), key=(lambda k: predecessor[k]))
 if current not in route:
 route.append(current)
 distance += predecessor[current]
 predecessor = distance_table[current]

 route.append(start)

 return route[::-1], distance

