fn combinations(n: usize, m: usize) -> Vec<Vec<usize>> {
 let mut result: Vec<Vec<usize>> = Vec::new();
 let mut combination: Vec<usize> = Vec::new();

 combination_helper(n, m, 0, &mut combination, &mut result);

 return result;
}

fn combination_helper(n: usize, m: usize, index: usize, combination: &mut Vec<usize>, result: &mut Vec<Vec<usize>>) {
 if (m == 0) {
  result.push(combination.clone());
  return;
 }

 let offset = index;
 while offset < n {
  combination.push(offset + 1);
  combination_helper(n, m - (offset + 1), offset + 1, combination, result);
  combination.pop();
  offset += 1;
 }
}

