function addNum(arr1, arr2) 
{ 
    let carry = 0; 
    let result = [];
    let len = Math.max(arr1.length, arr2.length); 

    for (let i = 0; i < len; i++) { 
        let sum = 0; 
        if (arr1[i] > 0 || arr2[i] > 0) { 
            let x = arr1[i] ? arr1[i] : 0; 
            let y = arr2[i] ? arr2[i] : 0; 
            sum += x + y + carry; 
            if (sum >= 10) { 
                sum %= 10; 
                carry = 1; 
            } else 
                carry = 0; 
            result.push(sum); 
        } 

        // If last sum is greater than 10 
        // Who's digit will be added to the result set 
        if (i === len - 1 && carry > 0) 
            result.push(carry); 
    } 

    return result; 
}

