// function to calculate gcd of two numbers 
int gcd(int num1, int num2) 
{ 
    // base condition 
    if (num1 == 0) 
        return num2; 
    if (num2 == 0) 
        return num1; 

    // recursive condition 
    if (num1 == num2) 
        return num1; 

    // num1 is greater 
    if (num1 > num2) 
        return gcd(num1 - num2, num2); 

    return gcd(num1, num2 - num1); 
}

