def knapsack(items, max_weight): 
   n = len(items) 
   res = [[0 for x in range(max_weight+1)] for x in range(n+1)]   

   for i in range(n+1): 
       for w in range(max_weight+1): 
           if i==0 or w==0: 
               res[i][w] = 0
           elif items[i-1][1] <= w: 
               res[i][w] = max(items[i-1][2] + res[i-1][w-items[i-1][1]],  res[i-1][w]) 
           else: 
               res[i][w] = res[i-1][w] 
   return res[n][max_weight] 

