public static int SumOfDigits(int n) {
  int sum = 0;
  // Iteratively compute the sum
  while (n > 0) {
    // Extract the rightmost digit
    int digit = n % 10;
    // Add the rightmost digit to the sum
    sum = sum + digit;
    // Remove the rightmost digit
    n = n / 10;
  }
  return sum;
}

