def number_of_ways_sum(sum, denominations):
    n = len(denominations) 
    dp = [[0 for x in range(sum+1)] for y in range(n+1)]     

    for i in range(n+1): 
        dp[i][0] = 1

    for i in range(1, n+1): 
        for j in range(1, sum+1): 
            if denominations[i-1] <= j: 
                dp[i][j] = dp[i-1][j] + dp[i][j-denominations[i-1]] 
            else: 
                dp[i][j] = dp[i-1][j]

    return dp[n][sum] 

