public static ListNode mergeTwoLists( ListNode l1, ListNode l2) {
    if (l1 == null && l2 == null)
        return null;
    ListNode mergedList;

    ListNode tempList = new ListNode();
    mergedList = tempList;

    while (l1 != null && l2 != null) {
        if (l1.data < l2.data) {
            tempList.next = l1;
            l1 = l1.next;
        }
        else {
            tempList.next = l2;
            l2 = l2.next;
        }
        tempList = tempList.next;
    }
    if (l1 != null)
        tempList.next = l1;
    if (l2 != null)
        tempList.next = l2;
    return mergedList.next;
}

