    if len(arr) == 0:
        return []
    if len(arr) == 1:
        return [arr]

    l = [] 
    for i in range(len(arr)):
        m = arr[i]

        # Extract lst[i] or m from the list.  remLst is 
        # remaining list 
        remLst = arr[:i] + arr[i+1:]

        # Generating all permutations where m is first 
