    # find the shortest string
    shortest_str = str_list[0]
    for s in str_list:
        if len(s) < len(shortest_str):
            shortest_str = s

    # iterate over all characters in shortest string   
    prefix = ""
    for i in range(len(shortest_str)):
        # if all strings have same character in ith position
        same_char = True
        for s in str_list:
            if s[i] != shortest_str[i]:
                same_char = False
                break

        # add the character to the prefix
        if same_char:
            prefix += shortest_str[i]
        else:
            break

