class TwoThreeTree:
    def __init__(self):
        self.root = None

    # Insert a node
    def insert(self, val):
        if self.root is None:
            self.root = TreeNode(val)
        else:
            self._insert(val, self.root)

    def _insert(self, val, node):
        if val < node.data:
            if node.left:
                self._insert(val, node.left)
            else:
                node.left = TreeNode(val)
        elif not node.middle or val < node.middle.data:
            if node.middle:
                self._insert(val, node.middle)
            else:
                node.middle = TreeNode(val)
        else:
            if node.right:
                self._insert(val, node.right)
            else:
                node.right = TreeNode(val)

