def max_product_three(nums):
    max_product = float('-inf')
    for i in range(len(nums)-2):
        for j in range(i+1, len(nums)-1):
            for k in range(j+1, len(nums)):
                max_product = max(max_product, nums[i]*nums[j]*nums[k])
    return max_product

