import numpy as np

def max_product_three(nums):
    nums = np.array(nums)
    three_largest_indices = np.argsort(nums)[-3:]
    return np.prod(nums[three_largest_indices])

def isValidPermutation(arr):
    n = len(arr)
    s = set()

    for i in range(n):
        if arr[i] < 0 or arr[i] > n - 1:
            return False
        if arr[i] in s:
            return False
        s.add(arr[i])

