def classify(phrase):
    words = phrase.split()
    negative_words = ["not", "unable", "no", "unlikely", "deny", "fail", "worst", "limited"]

    num_negative_words = 0
    for word in words:
        if word in negative_words:
            num_negative_words += 1

    if num_negative_words > (len(words) / 2):
        return "negative"
    else:
        return "positive"

