public class CityWeatherFragment extends Fragment {
    private RequestQueue requestQueue;
    private TextView textView;

    @Override
    public View onCreateView(LayoutInflater inflater, ViewGroup container, Bundle savedInstanceState) {
        View view = inflater.inflate(R.layout.city_weather_fragment, container, false);

        textView = view.findViewById(R.id.text_view);
        requestQueue = Volley.newRequestQueue(getActivity());
        jsonParse();

        return view;
    }

    private void jsonParse() {
        String url = "http://api.openweathermap.org/data/2.5/box/city?bbox=12,32,15,37,10";

        JsonObjectRequest request = new JsonObjectRequest(Request.Method.GET, url, null,
                new Response.Listener<JSONObject>() {
                    @Override
                    public void onResponse(JSONObject response) {
                        try {
                            JSONArray list = response.getJSONArray("list");
                            for (int i = 0; i < list.length(); i++) {
                                JSONObject city = list.getJSONObject(i);
                                String name = city.getString("name");
                                JSONObject main = city.getJSONObject("main");
                                int temp = main.getInt("temp");
                                textView.append(name + ": " + temp + "°C\n");
                            }
                        } catch (JSONException e) {
                            e.printStackTrace();
                        }
                    }
                }, new Response.ErrorListener() {
            @Override
            public void onErrorResponse(VolleyError error) {
                error.printStackTrace();
            }
        });

        requestQueue.add(request);
    }
}

