def isBST(arr):
    if len(arr) == 0:
        return True
    elif len(arr) == 1:
        return True
    else:
        root = arr[0]
        left_subtree = [i for i in arr if i < root]
        right_subtree = [i for i in arr if i > root]
        return (all(x < root for x in left_subtree)
                and all(x > root for x in right_subtree))
        and isBST(left_subtree)
        and isBST(right_subtree)

