def count_occurrences(arr, x): 
    n = len(arr) 
    result = 0 
    # first occurrence 
    idx = first(arr, 0, n-1, x, n) 

    # If x doesn't exist in arr then return 
    if idx == -1: 
        return result 
    # else count the number of occurrences of x 
    result = 1
    right = idx + 1
    while right < n and arr[right] == x : 
        result += 1
        right += 1

    left = idx - 1

    while left >= 0 and arr[left] == x: 
        result += 1
        left -= 1
    return result 

def first(arr, low, high, x, n): 
    if high >= low: 
        mid = low + (high - low) // 2
        if (mid == 0 or x > arr[mid-1]) and arr[mid] == x:
            return mid 
        elif x > arr[mid]: 
            return first(arr, (mid + 1), high, x, n) 
        else: 
            return first(arr, low, (mid - 1), x, n) 

    return -1

