using namespace std; 

string numToWord(int num) 
{ 
    // strings to return 
    string one[] = { "", "one ", "two ", "three ", 
                     "four ", "five ", "six ", 
                     "seven ", "eight ", "nine ", 
                     "ten ", "eleven ", "twelve ", 
                     "thirteen ", "fourteen ", 
                     "fifteen ", "sixteen ", 
                     "seventeen ", "eighteen ", 
                     "nineteen " }; 

    // strings to return if the number  
    // is a multiple of 10 
    string multipleOfTen[] = { "", "ten ", "twenty ", 
                               "thirty ", "forty ", "fifty ", 
                               "sixty ", "seventy ",  
                               "eighty ", "ninety " }; 

    // add minus before the number 
    if (num < 0) 
    { 
        return "minus " + numToWord(-num); 
    } 

    // base case 
    if (num == 0) 
    { 
        return "zero "; 
    } 

    // if the number is a multiple of 10 
    if (num % 10 == 0) 
    { 
        return multipleOfTen[num / 10] +  
               numToWord(num % 10); 
    } 

    // checks for first two digits of the number 
    else if (num < 20) 
    { 
        return one[num] + numToWord(num % 10); 
    } 

    // for number having more than two  
    // digits and less than 100 
    else 
    { 
        return multipleOfTen[num / 10] + 
               one[num % 10] + numToWord(num % 10); 
    } 
} 

