def isAnagram(str1, str2):
    str1 = str1.lower()
    str2 = str2.lower()

    freq = {}

    for s in str1:
        if s not in freq:
            freq[s] = 1
        else:
            freq[s] += 1

    for s in str2:
        if s not in freq:
            return False
        else:
            freq[s] -= 1

    for count in freq.values():
        if count != 0:
            return False
    return True

