def min_cost(destinations, distances):
 # initialize cost table
 cost_table = [[-1 for j in range(len(destinations))] for i in range(len(destinations))]

 # populate cost_table with distances
 for i in range(len(destinations)):
 for j in range(len(destinations)):
 cost_table[i][j] = distances[i][j]

 # dynamic programming loop
 for k in range(len(destinations)):
 for i in range(len(destinations)):
 for j in range(len(destinations)):
 cost_table[i][j] = min(cost_table[i][j], cost_table[i][k] + cost_table[k][j])

 # output
