function extractNumbers(str) {
  let numbers = []
  let numberString = ''
  for (let char of str) {
    if (isNaN(char) && numberString) {
      //push the number to the array
      numbers.push(Number(numberString));
      //reset the numberString
      numberString = '';
    } else if (!isNaN(char)) {
      numberString += char;
    }
  }
  //add the last number
  if (numberString) {
    numbers.push(Number(numberString));
  }

  return numbers;
}

