def longest_subsequence(x, y): 
    n, m = len(x), len(y)

    dp = [[0]*(m+1) for j in range(n+1)] 

    for i in range(1, n+1): 
        for j in range(1, m+1): 

            # if the current char is equal
            if x[i-1] == y[j-1]: 
                dp[i][j] = 1 + dp[i-1][j-1] 
            else: 

                dp[i][j] = max(dp[i][j-1], dp[i-1][j]) 


    return dp[n][m]

