public class CalculateSalesIncrease {

 public static void calculateIncreaseInSales (DataStore store, 
                                             startPeriod, 
                                             endPeriod) {

  int totalSalesStartPeriod = 0;
  int totalSalesEndPeriod = 0;

  for (Sale sale : store.list()) {
      if (sale.date.before(startPeriod) || 
          sale.date.after(endPeriod)) {
          continue;
      }

      if (sale.date.after(startPeriod) && 
          sale.date.before(endPeriod)) {
          totalSalesEndPeriod += sale.amount;
      } else {
          totalSalesStartPeriod += sale.amount;
      }
  }

  int increaseInSales = totalSalesEndPeriod - totalSalesStartPeriod;
  System.out.println("Increase in sales over the period is: " + 
                     increaseInSales);
 }
}

