def knapSack(weights, values, maxWeight): 
    W = maxWeight + 1 # size of the Lookup table 
    n = len(weights)
    lookup = [[0 for x in range(W)] for x in range(n + 1)] 

    # Build the Lookup table in bottom up manner 
    for i in range(n + 1): 
        for w in range(W): 
            if i == 0 or w == 0: 
                lookup[i][w] = 0
            elif weights[i-1] <= w: 
                lookup[i][w] = max(values[i-1] + lookup[i-1][w-weights[i-1]], lookup[i-1][w]) 
            else: 
                lookup[i][w] = lookup[i-1][w] 

    res = lookup[n][maxWeight] 
    return res

