def huffman_encoding(data):
    # construct the frequency dictionary
    freq_dict = {}
    for c in data:
        if c not in freq_dict:
            freq_dict[c] = 0

        freq_dict[c] += 1

    # create a min heap
    min_heap = []
    for key in freq_dict:
        min_heap.append((freq_dict[key], key))

    # create the huffman tree
    while len(min_heap) > 1:
        freq1, char1 = heapq.heappop(min_heap)
        freq2, char2 = heapq.heappop(min_heap)

        # merge them into one node
        min_heap.append((freq1 + freq2, (char1, char2)))

    # assign encoding
    encoding = {}
    def assign_code_helper(heap_node, code):
        if len(heap_node) == 1:
            return None
        else:
            char1, char2 = heap_node[1]
            if isinstance(char1, str):
                encoding[char1] = code + '0'
            else:
                assign_code_helper(char1, code+'0')

            if isinstance(char2, str):
                encoding[char2] = code + '1'
            else:
                assign_code_helper(char2, code+'1')

    assign_code_helper(min_heap[0], '')

    # compress the string
    output = ''
    for c in data: 
        output += encoding[c]

    return output, encoding

