// parses a given URL and returns a Map of URL query parameters
function parseQueryParams (url) {
 const params = new Map();
 const queryString = url.split('?')[1];
 if (queryString) {
   queryString.split('&').forEach(param => {
     let [ key, value ] = param.split('=');
     params.set(key, value);
   })
 }
 return params;
}

// constructUrl:
// constructs a new URL from a base URL and a map of query parameters
function constructUrl (baseUrl, params) {
 let constructedUrl = baseUrl;
 for (let [key, value] of params) {
   constructedUrl += `${key}=${value}&`;
 }

 return constructedUrl;
}

module.exports = {
 parseQueryParams,
 constructUrl
