 };

// Function to convert a Roman numeral string to decimal
let romanToDecimal = function(str) {
  // Split string into individual characters
  let splitStr = str.split("");
  // Initialize result
  let result = 0;
// Loop over string
for (let i = 0; i < splitStr.length; i++) {
  let currentVal = romanToDec[splitStr[i]];
  if (i+1 < splitStr.length) {
    let nextVal = romanToDec[splitStr[i+1]];
    // Check if value of current character is greater than or
    // equal to value of next character
    // If it is, then add this value to the result
    if (currentVal >= nextVal) {
        result += currentVal;
    } 
    // If the value of current character is less than value of
    // next character, then subtract this value from the result
    else {
        result -= currentVal;
    }
  } else {
    // If there are no characters left in the string to compare
    // with, then add the value of current character to the result
    result += currentVal;
  }
}
return result;
};

