void deleteNode(Node *head, int key) {
    Node *currNode = head;
    Node *prevNode;

    if (currNode != NULL && currNode->data == key) {
        // deleting the head
        prevNode->next = currNode->next;
        delete currNode;
        return;       
    }

    while (currNode != NULL && currNode->data != key) {
        prevNode = currNode;
        currNode = currNode->next;
    }

    if (currNode == NULL) // key not found
        return;

    prevNode->next = currNode->next;
    delete currNode;     
}

