// calculate Levenshtein distance
const editDistance = (a, b) => {
 let m = a.length;
 let n = b.length;
 let dp = new Array(m+1).fill(null).map(() => new Array(n+1).fill(0));
 for (let i = 1; i <= m; i++) {
 dp[i][0] = i;
 }
 for (let j = 1; j <= n; j++) {
 dp[0][j] = j;
 }
 for (let i = 1; i <= m; i++) {
 for (let j = 1; j <= n; j++) {
 if (a[i-1] === b[j-1]) {
 dp[i][j] = dp[i-1][j-1];
 } else {
 dp[i][j] = Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1;
 }
 }
 }
 return dp[m][n];
};

