def get_fibonacci(position):
    """
    Get the Fibonacci number of a given position.

    Parameters:
        position (int): Position in the Fibonacci sequence to be calculated

    Returns:
        int: Fibonacci number at the given position
    """
    if position == 0:
        return 0
    if position == 1 or position == 2:
        return 1
    else:
        return get_fibonacci(position-1) + get_fibonacci(position-2)

