class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if self.is_empty():
            return None
        return self.items.pop()

    def peek(self):
        if self.is_empty():
            return None
        return self.items[-1]

    def is_empty(self):
        return self.items == []

def optimize_function(x):
    return 3*x**2 + 8*x + 7

def objective_function(x):
    return optimize_function(x)

def optimize():
    optimal_x = 0
    min_val = objective_function(optimal_x)

    for x in range(1, 1000):
        current_val = objective_function(x)
        if current_val < min_val:
            min_val = current_val
            optimal_x = x

    return optimal_x

