def permutations(arr):
  results = []
  if len(arr) == 1:
    results.append(arr)
    return results
  else:
    for el in arr:
      remaining = [e for e in arr if e != el]
      sub_perms = permutations(remaining)
      for perm in sub_perms:
        results.append([el]+perm)
    return results

