def find_frequent_words(text):
    words = text.split()
    count = {}
    for word in words:
        if word not in count:
            count[word] = 0
        count[word] += 1
    freq_words = sorted(count.items(), key=lambda x: x[1], reverse=True)[:5]
    return [word[0] for word in freq_words]

