    # Initializing priorities
    priority = {"high": [], "medium": [], "low": []}

    # Performing the search
    results = search(name)

    # Assigning each result to the appropriate priority
    for result in results:
        if result.is_important:
            priority["high"].append(result)
        elif result.is_somewhat_important:
            priority["medium"].append(result)
        else:
            priority["low"].append(result)

    # Returning the results in order of priority
    return priority["high"] + priority["medium"] + priority["low"]

