func main() {
 kmMatrix := [][]int{
  {0, 2, 8, 3},
  {6, 0, 4, 7},
  {3, 7, 0, 9},
  {2, 4, 5, 0},
 }

// create a visited array of size N
 visited := make([]bool, len(kmMatrix))

// function to find the route with the minimum distance
 fmt.Println("Optimized route:", optimizedRoute(kmMatrix, visited, 0))
}

func optimizedRoute(kmMatrix [][]int, visited []bool, start int) int {
 // declare a minimum distance int
 minKm := 999

 // declare a best route int
 bestRoute := 0

// loop over the kmMatrix to find the minimum distance
 for i := 0; i < len(visited); i++ {
  //if the current node has not been visited and the current distance is less than the minimum distance
  if kmMatrix[start][i] > 0 && !visited[i] {
   //mark the current node as visited 
   visited[i] = true

   //recursively call the optimizedRoute function to find other legs of the route
   temp := kmMatrix[start][i] + optimizedRoute(kmMatrix, visited, i)

   //if the total distance is less than the minimum distance, set the minimum distance and the best route to current values
   if minKm > temp {
    minKm = temp
    bestRoute = i
   }

   //mark the current node as unvisited
   visited[i] = false
  }
 }

 // return the best route + the start distance
 return kmMatrix[start][bestRoute] + minKm
}

