import heapq as hq

def huffman_encoding(data):
  freq_dict = {x: data.count(x) for x in set(data)}
  heap = [[freq, [symbol, ""]] for symbol, freq in freq_dict.items()]
  hq.heapify(heap)
  while len(heap) > 1:
    low = hq.heappop(heap)
    high = hq.heappop(heap)

    for pair in low[1:]:
      pair[1] = '0' + pair[1]
    for pair in high[1:]:
      pair[1] = '1' + pair[1]
    hq.heappush(heap, [low[0] + high[0]] + low[1:] + high[1:])  

  code_dict = dict(hq.heappop(heap)[1:])
  encoded_data = ""
  for symbol in data:
    encoded_data += code_dict[symbol]
  return encoded_data, code_dict

