int editDistance(string m, string n) { 
    int dp[m.length()+1][n.length()+1]; 

    for (int i = 0; i <= m.length(); i++) { 
        for (int j = 0; j <= n.length(); j++) { 
            if (i == 0) 
                dp[i][j] = j;  

            else if (j == 0) 
                dp[i][j] = i;  

            else if (m[i-1] == n[j-1]) 
                dp[i][j] = dp[i-1][j-1]; 

            else
                dp[i][j] = 1 + min(dp[i][j-1],  
                                    dp[i-1][j],  
                                    dp[i-1][j-1]); 
        } 
    } 

    return dp[m.length()][n.length()]; 
} 

