public class StringReverser {
  public static String reverseString(String s) {
    char[] sChars = s.toCharArray();
    int low = 0;
    int high = s.length() - 1;

    while (low < high) {
      char temp = sChars[low];
      sChars[low] = sChars[high];
      sChars[high] = temp;
      low++;
      high--;
    }

    return new String(sChars);
  }

}

