function detectRedundantParentheses(str) {
    let stack = [];
    for (let i = 0; i < str.length; i++) {
        let char = str.charAt(i);
        if (char == '(') {
            stack.push(char);
        } 
        else if (char == ')') {
            if (stack.length <= 0) {
                return true;
            }
            stack.pop();
        }
    }
    return false;
}

