import java.util.*;
import java.net.*;
import java.io.*;

public class WebCrawler {
    // Set of discovered URLs
    private static Set<String> discoveredURLs = new HashSet<>();

    public static void main(String[] args) throws IOException {
        // Read in the root URL
        String root = args[0];
        // Add the root URL to the set of discovered URLs
        discoveredURLs.add(root);
        // Start crawling from the root URL
        crawl(root);

        // Print out the discovered URLs
        for (String url : discoveredURLs) {
           System.out.println(url);
    	}
    }

    private static void crawl(String url) throws IOException {
        // Parse the URL
        URL link = new URL(url);
        // Open a connection to the URL
        HttpURLConnection connection = (HttpURLConnection) link.openConnection();
        connection.setRequestMethod("GET");  

        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            // Get the body of the request
            BufferedReader in =
                    new BufferedReader(new InputStreamReader( connection.getInputStream()));
            String inputLine;
            StringBuilder content = new StringBuilder();
            while ((inputLine = in.readLine()) != null) {
                content.append(inputLine);
            }

            // Search the body for any links
            String regex = "href=\"([^\"]*)\"";
            Pattern pattern = Pattern.compile(regex);
            Matcher matcher = pattern.matcher(content);
            while (matcher.find()) {
                // Add the newly discovered URL to the set
                String newURL = matcher.group(1);
                if (!discoveredURLs.contains(newURL)) {
                    discoveredURLs.add(newURL);
                    // Recursively call crawl on the new URL
                    crawl(newURL);
                }
            }
        }
    }
}

