 list = list->next;
 }
 return NULL;
}

// Function for inserting a node into a list.
struct node *insert(struct node **list, int value) {
 struct node *node = create_node(value);
 node->next = *list;
 *list = node;
 return node;
}

// Function for deleting a node from a list.
struct node *delete(struct node **list, int value) {
 struct node *prev = NULL;
 struct node *node = search(*list, value);
 if (node == NULL)
 return NULL;

 // head node
 if (node == *list){
 *list = (*list)->next;
 return node;
 }

 //node is not head
 prev = *list;
 while (prev->next != node)
 prev = prev->next;
 prev->next = node->next;
 return node;
 }

// Function for printing all elements in a list.
void print_list(struct node *list) {
 while (list != NULL) {
 printf("%d ", list->value);
 list = list->next;
 }
 printf("\n");
}

