int findMode(int arr[], int n)
{
    int max_count = 0;
    int mode = 0;

    int count[n];
    int i;

    // Initialize count array with all 0
    for (i = 0; i < n; i++)
        count[i] = 0;

    for (i = 0; i < n; i++) {
        count[arr[i]]++;

        if (count[arr[i]] > max_count) {
            mode = arr[i];
            max_count = count[arr[i]];
        }
    }

    return mode;
}

def quick_sort(arr):
    if len(arr) < 2:
        return arr
    else:
        pivot = arr[0]
        less = [i for i in arr[1:] if i <= pivot]
        greater = [i for i in arr[1:] if i > pivot]
        return quick_sort(less) + [pivot] + quick_sort(greater)

