// Gives smallest prime number greater than n 
int nextPrime(int n) 
{ 
    // Base case 
    if (n <= 1) 
        return 2; 

    int prime = n; 
    bool found = false; 

    // Loop continuously 
    while (!found) { 
        prime++; 

        if (isPrime(prime)) 
            found = true; 
    } 

    return prime; 
} 

// Function to check primality 
bool isPrime(int n) 
{ 
    // Corner cases 
    if (n <= 1) 
        return false; 
    if (n <= 3) 
        return true; 

    // Check divisibility by 2 and 3 
    if (n % 2 == 0 || n % 3 == 0) 
        return false; 

    // Look for divisibility by each number from 5 to sqrt(n) 
    for (int i = 5; i * i <= n; i = i + 6) 
        if (n % i == 0 || n % (i + 2) == 0) 
            return false; 

    return true; 
} 

