public class BubbleSort 
{ 
	// Function to sort array
	public static int[] bubbleSort(int[] arr) 
	{ 
		int n = arr.length; 
		for (int i = 0; i < n-1; i++) 
			for (int j = 0; j < n-i-1; j++) 
				if (arr[j] > arr[j+1]) 
				{
					// Swap the elements 
					int temp = arr[j];
					arr[j] = arr[j+1];
					arr[j+1] = temp; 
				} 
		return arr; 
	} 

	// Driver code
	public static void main(String args[]) 
	{ 
		// Input array
		int[] arr = {5, 2, 1, 3, 4};

		// Sort using Bubble Sort
		arr = bubbleSort(arr);

		// Print sorted array
		for (int i=0; i<arr.length; ++i) 
			System.out.print(arr[i] + " "); 
		System.out.println(); 
	} 
}

