function findShortestPath(grid, start, end) {
  //Create an empty queue
  let queue = [];

  //Mark the start node as visited and add it to the queue
  start.visited = true;
  queue.push(start);

  //While the queue is not empty
  while (queue.length) {

    //Remove the first node
    let node = queue.shift();

    //If the node is the end node return the node
    if (node === end) {
      return node;
    }

    //Get the neighbours of the current node
    let neighbours = getNeighbours(grid, node);

    //Loop over the neighbours
    for (let neighbour of neighbours) {
      //Mark the neighbour as visited and add it to the queue
      if (!neighbour.visited) {
        neighbour.visited = true;
        queue.push(neighbour);
      }
    }
  }
  //Return null if no path is found
  return null;
}

function getNeighbours(grid, node) {
  let x = node.x;
  let y = node.y;

  let neighbours = [];

  //Check left
  if (x > 0) {
    neighbours.push(grid[y][x - 1]);
  }
  //Check right
  if (x < grid[y].length - 1) {
    neighbours.push(grid[y][x + 1]);
  }
  //Check bottom
  if (y > 0) {
    neighbours.push(grid[y - 1][x]);
  }
  //Check top
  if (y < grid.length - 1) {
    neighbours.push(grid[y + 1][x]);
  }

  return neighbours;
}

