bool isPrime(int n){ 
  for (int i = 2; i <= n/2; i++) 
    if (n % i == 0) 
      return false; 
  return true; 
} 

int main() 
{ 
  int n = 100; 
  cout << "All Prime numbers from 1 to " << n << " are: "; 
  for (int i = 2; i <= n; i++) { 
    if (isPrime(i)) 
      cout << i << " "; 
  } 
  cout << endl; 
  return 0; 
}

