public class Main {
  public static void main(String[] args) {
    String input = "Black Widoe";
    List<String> canonicals = Arrays.asList("Black Widow", "Hulk");

    String canonical = findClosestCanonical(input, canonicals);

    System.out.println("Input: " + input);
    System.out.println("Closest canonical: " + canonical);
  }

  public static String findClosestCanonical(String input, List<String> canonicals) {
    String closestCanonical = null;
    int minDistance = Integer.MAX_VALUE;

    for (String canonical : canonicals) {
      int distance = LevenshteinDistance.computeLevenshteinDistance(input, canonical);
      if (distance < minDistance) {
        minDistance = distance;
        closestCanonical = canonical;
      }
    }
    return closestCanonical;
  }
}

