def hasPathSum(root, target): 

    # Return true if we run out of tree and sum is as expected 
    if root is None: 
        return (target == 0) 

    # Otherwise check both subtrees 
    ans = 0
    subSum = target - root.data 

    # If we reach a leaf node and sum becomes 0, then 
    # return True 
    if(subSum == 0 and root.left == None and root.right == None): 
        return True 

    if root.left is not None: 
        ans = ans or hasPathSum(root.left, subSum) 
    if root.right is not None: 
        ans = ans or hasPathSum(root.right, subSum) 

    return ans

