string ROT13(string input) {
    string output = "";
    for (int i = 0; i < input.length(); i++) {
        char c = input[i];
        if (c >= 'a' && c <= 'z') {
            c += 13;
            if (c > 'z')
                c -= 26;
        } else if (c >= 'A' && c <= 'Z') {
            c += 13;
            if (c > 'Z')
                c -= 26;
        }
        output += c;
    }
    return output;
}

int main() {
    string input = "Hello World";
    string output = ROT13(input);
    cout << output << endl; // Output: Uryyb Jbeyq
    return 0;
}

