fn analyze_nums(nums: Vec<i32>) {
 let sum = 0;
 for n in &nums {
  sum += n;
 }
 let mean = sum as f32 / nums.len() as f32;

 let mut sorted = nums.clone();
 sorted.sort();

 let mut idx = 0;
 if sorted.len() % 2 == 0 {
  let mid_left = sorted[sorted.len() / 2 - 1];
  let mid_right = sorted[sorted.len() / 2];
  idx = (mid_left + mid_right) / 2;
 } else {
  idx = sorted[(sorted.len() - 1) / 2];
 }
 let median = sorted[idx];

 let mut mode = Vec::new();
 let mut count = 1;
 let mut max_count = 1;
 for n in 1..sorted.len() {
  if sorted[n] == sorted[n-1] {
   count += 1;
  } else {
   count = 1;
  }
  if count > max_count {
   max_count = count;
   mode = vec![sorted[n]];
  } else if count == max_count {
   mode.push(sorted[n]);
  }
 }

 println!("Mean: {} Median: {} Mode: {:?}", mean, median, mode);
}

fn main() {
 let numbers = vec![1, 2, 3, 4, 5];
 analyze_nums(numbers);
}

