public class QuickSort {
    public static void quickSort(int[] arr, int left, int right) {
        if (left < right) {
            int pivotIndex = pickPivotIndex(arr, left, right);		
            // Swap pivot with the rightmost element
            int temp = arr[right];
            arr[right] = arr[pivotIndex];
            arr[pivotIndex] = temp;		
            // Perform partitioning
            pivotIndex = partition(arr, left, right);		
            // Sort elements before and after partition
            quickSort(arr, left, pivotIndex - 1);
            quickSort(arr, pivotIndex + 1, right);
        }
    }

    public static int partition(int[] arr, int left, int right) {
        int pivotValue = arr[right];
        // Keep track of the bonds of the unpartitioned elements
        int smallPartitionIndex = left;
        int largePartitionIndex = right;
        // Iterate over the unpartitioned elements
        while (smallPartitionIndex < largePartitionIndex) {
            // If element is smaller than pivot, swap it at the right side of the smaller partition
            if (arr[smallPartitionIndex] <= pivotValue) {
                smallPartitionIndex++;
            } else {
                // If element is greater than pivot, swap it at the left side of the larger partition
                int tmp = arr[smallPartitionIndex];
                arr[smallPartitionIndex] = arr[largePartitionIndex];
                arr[largePartitionIndex] = tmp;
                largePartitionIndex--;
            }
        }
        // Place the pivot element at the middle of the two partitions
        int tmp = arr[smallPartitionIndex];
        arr[smallPartitionIndex] = arr[right];
        arr[right] = tmp;
        // Return pivot's current index
        return smallPartitionIndex;
    }

    // Pick the most middle element in the range as pivot
    private static int pickPivotIndex(int[] arr, int left, int right) {
        int middleIndex = left + (right - left) / 2;
        return middleIndex;
    }

    public static void main(String[] args) {
        int[] arr = { -12, 7, 0, 56, 13, 79, -8 };
        quickSort(arr, 0, arr.length - 1);
        for (int x : arr)
            System.out.print(x + " ");
    }
}

