void insertionSort(int arr[], int n) {
 int i, key, j;
 for (i = 1; i < n; i++) {
 key = arr[i];
 j = i - 1;

// Move elements of arr[0..i-1], that are
// greater than key, to one position ahead
// of their current position
 while (j >= 0 && arr[j] > key) {
 arr[j + 1] = arr[j];
 j = j - 1;
 }
 arr[j + 1] = key;
 }
}

def compress(string):
    if len(string) <= 2:
        return string

    result = ""
    i = 0
    while i < len(string):
        result += string[i]
        count = 1
        while i < len(string) - 1 and string[i] == string[i + 1]:
            count += 1
            i += 1
        if count > 2:
            result += str(count)
        i += 1
    return result

