import java.util.HashMap;

public class DNASequence {

 public static void main(String[] args) {
 String dnaSequence = "ACGTACGTAAGTTCCA";

 int k = 4;
 HashMap<String, Integer> patternCounts = getFrequent4mers(dnaSequence, k);

 System.out.println("Most frequent 4-mers are: ");
 for(HashMap.Entry<String, Integer> entry : patternCounts.entrySet()) {
 System.out.println(entry.getKey()+": "+entry.getValue());
 }
 }

 public static HashMap<String, Integer> getFrequent4mers(String dnaSequence, int k) {

 // Create an empty hash map for storing the k-mers as key and their counts as value
 HashMap<String, Integer> patternCounts = new HashMap<>();

 // Traverse the given sequence for extracting k-mers
 for(int i=0; i+k <= dnaSequence.length(); i++) {
 String pattern = dnaSequence.substring(i, i+k);
 int count = 1;

 // Check if the pattern is already seen
 if(patternCounts.containsKey(pattern)){
 count = patternCounts.get(pattern) + 1;
 }

 // Update the pattern count
 patternCounts.put(pattern, count);
 }

 return patternCounts;
 }

}

