    max_factor = -1

    # The largest prime factor of any number cannot be greater than sqrt(number) 
    for i in range(2, int(math.sqrt(number)) + 1): 
        # If i is a factor of number 
        if number % i == 0: 
            # Check if it is prime, if yes then update the max_factor 
            if is_prime(i): 
                max_factor = i 

    # If at the end max_factor is still -1, it means the number itself is prime. 
