def optimize(num_generations):
 # generate a population with randomly generated solutions
 population = [generate_solution() for _ in range(25)] # 25 is size of population

 for _ in range(num_generations):
  # Calculate fitness of population
  population_fitness = [fitness(*solution) for solution in population]

  # Find the best solution in the population
  best_solution_index = population_fitness.index(min(population_fitness))

  # Create a new population by crossover, and mutation
  new_population = [mutate(*crossover(*random.sample(population, 2))) for _ in range(25)]

  # Replace worst solutions in the population with best solutions from new population
  population[-5:] = new_population[-5:]

  # If the best solution from the new population is better than current best solution
  # replace it with the best solution from the new population
  if new_population[best_solution_index][0] < population[best_solution_index][0]:
   population[best_solution_index] = new_population[best_solution_index]

 # return best solution
 return min(population_fitness), population[best_solution_index]

if __name__ == '__main__':
