vector<double> noiseReduction(vector<double> signal)
{
    int n = signal.size();
    vector<double> output(n);

    // Traverse the input signal and find local maxima
    for (int i = 1; i < n-1; i++)
    {
        // If local maxima
        if (signal[i] > signal[i-1] && signal[i] > signal[i+1])
            output[i] = signal[i];
        else
            output[i] = 0;
    }

    return output;
}

