def merge_sorted_lists(head_a, head_b):
    # Create a new linked list.
    new_list = Node(None)
    tail = new_list

    current_a = head_a
    current_b = head_b

    while current_a is not None or current_b is not None:
        if current_a is None:
            tail.next = current_b
            current_b = current_b.next
        elif current_b is None:
            tail.next = current_a
            current_a = current_a.next
        elif current_a.data <= current_b.data:
            tail.next = current_a
            current_a = current_a.next
        else:
            tail.next = current_b
            current_b = current_b.next
        tail = tail.next

    return new_list.next

public static ArrayList<Integer> longestIncreasingSub(int[] array) {
 ArrayList<Integer> result = new ArrayList<Integer>();
 int j = 0;
 int maxLen = 1;

 //iterate array
 for (int i = 0; i < array.length - 1; i++) {
 //look for increasing trends
 if (array[i] < array[i + 1]) {
 j++;
 } else {
 //if end of increasing trend is found
 //compare length with current max
 if (j > maxLen) {
 result = new ArrayList<Integer>();
 //add the increasing trend into result
 for (int k = i - j + 1; k <= i; k++) {
 result.add(array[k]);
 }
 //update max length
 maxLen = j;
 j = 0;
 }
 }
 }
 //check and add the last increasing trend
 if (j > maxLen) {
 for (int k = array.length - j; k < array.length; k++) {
 result.add(array[k]);
 }
 }
 return result;
}

