const typeDefs = `
type Post {
 id: ID!
 title: String!
 content: String!
 author: User!
}

type User {
 id: ID!
 name: String!
 posts: [Post!]!
}

type Query {
 posts(authorName: String): [Post!]!
 user(name: String): User
}

type Mutation {
 createPost(title: String!, content: String!, authorName: String!): Post!
 updatePost(id: ID!, title: String, content: String): Post!
 deletePost(id: ID!): Post
}
`

const resolvers = {
 Query: {
 posts(_, { authorName }) {
 return posts.filter(f => authorName ? f.author.name === authorName : true);
 },
 user(_, { name }) {
 return users.find(f => f.name === name);
 }
 },
 Post: {
 author(p) {
 return users.find(f => f.id === p.author);
 }
 },
 User: {
 posts(u) {
 return posts.filter(f => f.author.id === u.id);
 }
 },
 Mutation: {
 createPost(_, { title, content, authorName }) {
 const author = users.find(f => f.name === authorName);
 const post = {
 id: generateId(),
 title,
 content,
 author: author.id,
 };
 posts.push(post);
 return post;
 },
 updatePost(_, { id, title, content }) {
 const postIndex = posts.findIndex(f => f.id === id);
 const post = posts[postIndex];
 if (title) post.title = title;
 if (content) post.content = content;
 return post;
 },
 deletePost(_, { id }) {
 const postIndex = posts.findIndex(f => f.id === id);
 return posts.splice(postIndex, 1)[0];
 }
 }
};

const server = new GraphQLServer({ typeDefs, resolvers });
server.start(() => console.log('Server is running on localhost:4000'));

