#define SIZE 2 

int main() 
{
	int A[SIZE][SIZE] = { {1, 2},
                      {3, 4} };

	int B[SIZE][SIZE] = { {1, 2},
                      {3, 4} };

	int C[SIZE][SIZE]; 

	int i, j, k; 

	#pragma omp parallel for shared(A,B,C) private(i,j,k)
	for (i = 0; i < SIZE; i++) { 
		for (j = 0; j < SIZE; j++) { 
			C[i][j] = 0; 
			for (k = 0; k < SIZE; k++) 
				C[i][j] += A[i][k]*B[k][j]; 
		} 
	} 

	for (i = 0; i < SIZE; i++) { 
		for (j = 0; j < SIZE; j++) 
			printf("%d ", C[i][j]); 

		printf("\n"); 
	} 
	return 0; 
}

