function longestSubstringWithoutDuplicates(s) {
    let longestSubstring = "";
    let currentSubstring = "";
    let seen = {};

    for (let i = 0; i < s.length; i++) {
        let c = s[i];

        if (seen[c]) {
            currentSubstring = "";
            seen = {};
        }

        currentSubstring += c;
        seen[c] = true;

        if (currentSubstring.length > longestSubstring.length) {
            longestSubstring = currentSubstring;
        }
    }

