public class Stack {
 private int[] data;
 private int top;

 public Stack(int size) {
  data = new int[size];
  top = -1;
 }

 public void push(int x) {
  if (top == data.length - 1) {
   System.out.println("Stack overflow");
   return;
  }
  data[++top] = x;
 }

 public int pop() {
  if (top == -1) {
   System.out.println("Stack underflow");
   return 0;
  }
  return data[top--];
 }

 public boolean isEmpty() {
  return (top == -1);
 }

 public void display() {
  if (top == -1) {
   System.out.println("Stack is empty");
   return;
  }
  for (int i = 0; i <= top; i++) {
   System.out.println(data[i] + "\t");
  }
  System.out.println();
 }

}

