   PreparedStatement stmt = dbConnection.prepareStatement("SELECT * FROM Customers");
   return stmt.executeQuery();
  }

  // Retrieve customer by ID
  public ResultSet getCustomerById(int id) throws SQLException {
   PreparedStatement stmt = dbConnection.prepareStatement("SELECT * FROM Customers WHERE id = ?");
   stmt.setInt(1, id);
   return stmt.executeQuery(); 
  }

  // Create customer
  public int createCustomer(String name, String address) throws SQLException {
   PreparedStatement stmt = dbConnection.prepareStatement("INSERT INTO Customers (name, address) VALUES (?, ?)");
   stmt.setString(1, name);
   stmt.setString(2, address);
   return stmt.executeUpdate();
  }

  // Update customer
  public int updateCustomer(int id, String name, String address) throws SQLException {
   PreparedStatement stmt = dbConnection.prepareStatement("UPDATE Customers SET name = ?, address = ? WHERE id = ?");
   stmt.setString(1, name);
   stmt.setString(2, address);
   stmt.setInt(3, id);
   return stmt.executeUpdate();
  }

  // Delete customer
  public int deleteCustomer(int id) throws SQLException {
   PreparedStatement stmt = dbConnection.prepareStatement("DELETE FROM Customers WHERE id = ?");
   stmt.setInt(1, id);
   return stmt.executeUpdate();
  }

}

