public class MaximumSubarraySum {
    // Function to find maximum subarray sum using divide-and-conquer approach 
    public static int maxSubarraySum(int[] arr, int left, int right) 
    { 
        // base case, only one element 
        if (left == right) { 
            return arr[left]; 
        } 

        // find mid point 
        int mid = (left + right) / 2; 

        /* return maximum of following three possible cases 
        a) maximum subarray sum in left half 
        b) maximum subarray sum in right half 
        c) maximum subarray sum such that the subarray crosses the midpoint */
        return Math.max( 
            maxSubarraySum(arr, left, mid), 
            maxSubarraySum(arr, mid + 1, right), 
            maxCrossingSum(arr, left, mid, right)); 
    } 

    // finds the maximum possible sum in subarray  
    // that crosses mid point 
    public static int maxCrossingSum(int[] arr, int l, int m, int h) 
    { 
        // Include elements on left of mid. 
        int sum = 0; 
        int left_sum = Integer.MIN_VALUE; 
        for (int i = m; i >= l; i--) { 
            sum = sum + arr[i]; 
            if (sum > left_sum) 
                left_sum = sum; 
        } 

        // Include elements on right of mid 
        sum = 0; 
        int right_sum = Integer.MIN_VALUE; 
        for (int i = m + 1; i <= h; i++) { 
            sum = sum + arr[i]; 
            if (sum > right_sum) 
                right_sum = sum; 
        } 
        // Return sum of elements on left and right of mid 
        return left_sum + right_sum; 
    } 

    // Driver Program 
    public static void main(String[] args) 
    { 
        int[] arr = {2, -3, 4, 1, -5, 7, -10}; 
        int n = arr.length; 
        int max_sum = maxSubarraySum(arr, 0, n - 1); 
        System.out.println("Maximum Subarray Sum="+ max_sum); 
    } 
}

def editDistance(str1, str2): 
    m = len(str1)
    n = len(str2)

    dp = [[0 for x in range(n+1)] for x in range(m+1)] 

    for i in range(m+1): 
        for j in range(n+1): 

            if i == 0: 
                dp[i][j] = j 
            elif j == 0: 
                dp[i][j] = i 
            elif str1[i-1] == str2[j-1]: 
                dp[i][j] = dp[i-1][j-1] 
            else: 
                dp[i][j] = 1 + min(dp[i][j-1],    # Insert 
                                   dp[i-1][j],    # Remove 
                                   dp[i-1][j-1])  # Replace

    return dp[m][n]

