// Function to find the shortest path 
// from the source cell to destination cell 
std::vector<std::pair<int, int> > shortestPath(int srcX, int srcY, 
									int destX, int destY, 
									int rows, int cols) 
{ 
	// Use a 2D array to track the visited cells 
	// so that it is easy to print the paths at the end 
	bool visit[rows][cols]; 
	for (int i = 0; i < rows; i++) 
		for (int j = 0; j < cols; j++) 
			visit[i][j] = false; 

	// Coutner to keep trace of the length of path 
	int pathLen = 0; 

	// Use a 2D vector to track the path structure 
	std::vector<std::vector<std::pair<int, int> >> Path; 

	// Define a source vector and push the source coordinate 
	std::vector<std::pair<int, int> > Source; 
	Source.push_back(make_pair(srcX, srcY)); 
	Path.push_back(Source); 
	visit[srcX][srcY] = true; 

	while (Path.size() != 0) 
	{ 
		std::vector<std::pair<int, int> > temp = Path[0]; 
		Path.erase(Path.begin()); 

		// Take out the final coordiante of the current vector 
		// to find the possible neighbours 
		std::pair<int, int> curr = temp[temp.size() - 1]; 

		// Check if the current coordinate is equal to the destination 
		// coordinate, if yes then return the path matrix 
		if (curr.first == destX && curr.second == destY) 
			return temp; 

		// Define 4 directions 
		int dirX[] = {1, 0, -1, 0}; 
		int dirY[] = {0, -1, 0, 1}; 

		// Traverse through the possible neighbours 
		for (int i = 0; i < 4; i++) 
		{ 
			int newX = curr.first + dirX[i]; 
			int newY = curr.second + dirY[i]; 

			//If the neighbour is unvisited and in-bounds 
			if (newX >= 0 && newX < rows && 
				newY >= 0 && newY < cols && 
				!visit[newX][newY]) 
			{ 
                // Push the neighbour cell to the current path vector
				temp.push_back(make_pair(newX, newY)); 

				// Mark the new neighbour as visited 
				visit[newX][newY] = true; 

				// Push the new row vector to the set of all possible paths 
				Path.push_back(temp); 

				// Remove the last element of the 
				// current path vector 
				temp.pop_back(); 
			} 
		} 
	} 
	return Path[0]; 
}

