def generate_tree_structure(json_data):
    tree = {}
    def generate_tree(tree,data,level):
        for key,value in data.items():
            if isinstance(value, dict):
                tree[key] = []
                generate_tree(tree[key], value, level+1)
            elif isinstance(value, list):
                i = 0
                for item in value:
                    if isinstance(item, dict):
                        tree[f"{key}_{i}"] = []
                        generate_tree(tree[f"{key}_{i}"], item, level+1)
                    else:
                        tree[f"{key}_{i}"] = value
                    i+=1
            else:
                tree[key] = value
    generate_tree(tree, json_data, 0)
    return tree

