    for word in text.split(" "):
        if word in words_freq_dict:
            words_freq_dict[word] += 1
        else:
            words_freq_dict[word] = 1

    sorted_words_freq_dict = sorted(words_freq_dict.items(), key=lambda item: item[1], reverse=True)
