// Function to find nth Fibonacci number 
int Fibonacci(int n) 
{ 
    int f1 = 0, f2 = 1, next; 

    if (n == 0) 
        return f1; 

    for (int i = 2; i <= n; i++) {
        next = f2 + f1; 
        f1 = f2; 
        f2 = next; 
    } 
    return f2; 
} 

