// Function to calculate nth Fibonacci number
int fibonacci(int n) {
  int first = 0, second = 1, next, c;

  if (n == 0)
    return first;

  for (c = 2; c <= n; c++)
  {
    next = first + second;
    first = second;
    second = next;
  }

  return second;
}

