import numpy as np

def solve(board):
    board = np.array(board)
    zero_locations = np.where(board == 0)

    for row, col in zip(*zero_locations):
        for guess in range(1, 10):
            if valid_guess(board, row, col, guess):
                board[row][col] = guess
                if solve(board):
                    return board
                else:
                    board[row][col] = 0

    # No empty space left
    if np.all(board):
        return board

    # Guess not valid
    return False

def valid_guess(board, row, col, guess):
    col_valid = not guess in board[row, :]
    row_valid = not guess in board[:, col]
    box_valid = not guess in get_box(board, row, col)
    return col_valid and row_valid and box_valid

def get_box(board, row, col):
    y_start = (row // 3) * 3
    x_start = (col // 3) * 3
    return board[y_start:y_start + 3, x_start:x_start + 3].flatten()

