use std::sync::{Mutex, Arc};
use std::net::TcpListener;

fn main() {
 let listener = TcpListener::bind("127.0.0.1:7878").unwrap();
 println!("Chat server is running!");

 // create a message queue
 let messages = Arc::new(Mutex::new(Vec::new()));

 for stream in listener.incoming() {
 let messages = Arc::clone(&messages);
 std::thread::spawn(move || {
 handle_client(stream.unwrap(), messages);
 });
 }
}

fn handle_client(mut stream: std::net::TcpStream, messages: Arc<Mutex<Vec<String>>>) { // Mutex<Vec<String>>
 loop {
 // read from stream
 let mut msg= String::new();
 stream.read_to_string(&mut msg).unwrap();

 // store the message in queue
 let mut queue = messages.lock().unwrap();
 queue.push(msg);

 // send back the messages in queue
 drop(queue);
 let mut response = String::new();
 let queue = messages.lock().unwrap();
 for m in queue.iter() {
 response.push_str(&m);
 response.push_str("\n");
 }

 stream.write(response.as_bytes()).unwrap();
 }
}

