def isPrime(num):
    # edge cases
    if num <= 1:
        return False
    if num == 2:
        return True

    # check if num is a multiple of 2
    if num % 2 == 0:
        return False

    # check for numbers from 3 up to num-1
    for i in range(3, num):
        if num % i == 0:
            return False
    return True

