public class TwoNonOverlapSubarr { 
    public static void maxTwoNonOverlapSubarr(int[] list) { 

        int size = list.length; 
        int max_sum = Integer.MIN_VALUE; 
        int max_left_index = 0; 
        int max_right_index = 0; 

        // If single element 
        if (size == 1)  
        { 
            max_sum = list[0]; 
            max_left_index = 0; 
            max_right_index = 0; 
        } 

        // If two elements 
        if (size == 2) 
        {   
            if (list[0] > list[1]) 
            { 
                max_sum = list[0]; 
                max_left_index = 0; 
                max_right_index = 0; 
            } 
            else
            { 
                max_sum = list[1]; 
                max_left_index = 1; 
                max_right_index = 1; 
            } 
        } 

        // If more than 2 elements 
        if (size > 2)  
        { 
            int left_subarr_sum = 0; 
            int right_subarr_sum = 0; 

            // 2 Loops to fix right and left  
            // indices of subarray 
            for (int i = 0; i < size - 1; i++)  
            { 
                // Reset left_subarr_sum for 
                // new left index 
                left_subarr_sum = 0; 

                for (int j = i; j >= 0; j--)  
                { 
                    left_subarr_sum += list[j]; 

                    // Reset right_subarr_sum for 
                    // new right index 
                    right_subarr_sum = 0; 

                    for (int k = i + 1; k < size; k++)  
                    { 
                        right_subarr_sum += list[k]; 

                        // Updating maximum  
                        // sum if reqd. 
                        if (left_subarr_sum + right_subarr_sum >  
                        max_sum) 
                        { 
                            max_sum = left_subarr_sum +  
                                    right_subarr_sum; 

                            max_left_index = j; 
                            max_right_index = k; 
                        } 
                    } 
                } 
            } 
        } 

        System.out.println("The two non-overlapping " +  
                      "subarrays with largest sum are: "); 

        // Print the maximum sum sub arrays 
        for (int i = max_left_index; i <= max_right_index; i++)  
        { 
            System.out.print(list[i] + " "); 
        } 

        System.out.println(); 

        // Print the maximum sum 
        System.out.println("Maximum sum is " + max_sum); 
    } 
}

