def rot13(message):  
    # Create anEncrypted Message string  
    encoded = ""

    # Loop over each character and apply ROT13 logic  
    for ch in message:
        if ch.isalpha():
            if (ch.isupper()):
                encoded += chr((ord(ch) - 65 + 13) % 26 + 65)
            else:
                encoded += chr((ord(ch) - 97 + 13) % 26 + 97)
        else: 
            encoded += ch

    return encoded

