func binarySearch<T: Comparable>(array: [T], element: T) -> Int? {

  var low = 0
  var high = array.count - 1

  while low <= high {
    let mid = low + (high - low) / 2
    let midElement = array[mid]

    if midElement == element {
      return mid
    } else if midElement < element {
      low = mid + 1
    } else {
      high = mid - 1
    }
  }

  return nil
}

