char *removeChar(char *str, char ch)
{
    int pos;
    for (pos = 0; str[pos] != '\0'; pos++) {
        if (str[pos] == ch) {
            int i;
            for (i = pos; str[i] != '\0'; i++) { 
                str[i] = str[i + 1]; 
