public class Node {
    int key;
    Node left, right;

    public Node(int item) {
        key = item;
        left = right = null;
    }
}

public class LowestCommonAncestor {

    public Node lowestCommonAncestor(Node left, Node right) {
        if (left == null || right == null) 
            return null;

        if (left.key == right.key) 
            return left;

        Node current = left;

        while(current != null) {            
            if (isAncestor(current, right)) 
                return current; 

            current = current.parent; 
        } 
        return null; 
    }

    boolean isAncestor(Node root, Node node) {  
        if (root == null) 
            return false; 

        if (root == node) 
            return true; 

        return isAncestor(root.left, node) 
            || isAncestor(root.right, node); 
    } 
}

