def evaluateExpression(expr):
    if expr == "":
        return 0
    stack = []
    i = 0
    while i < len(expr):
        op = expr[i]
        if op in "+-*/":
            val2 = stack.pop()
            val1 = stack.pop()
            if op == "+":
                stack.append(val1 + val2)
            elif op == "-":
                stack.append(val1 - val2)
            elif op == "*":
                stack.append(val1 * val2)
            else:
                stack.append(val1 / val2)
        else:
            stack.append(int(op))
        i += 1
    return stack[0]

