// Function to partition the array on the basis of a pivot element
int Partition(int array[], int low, int high)
{
    int pivot = array[high];
    int i = low - 1; // index of the smaller elements

    // iterate through array
    for (int j = low; j < high; j++)
    {
        // If current element is smaller than or equal to pivot
        if (array[j] <= pivot)
        {
            i++; // increment index
            // swapping of elements
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }

    // swap pivot with the i+1 th element
    int temp = array[i+1];
    array[i+1] = array[high];
    array[high] = temp;

    // return the partition index 
    return i+1;
}

// Function to sort an array using quick sort
void QuickSort(int array[], int low, int high)
{
    // base condition
    if (low < high)
    {
        /* Partition index returned by Partition()
           partitionIndex is now at right place */
        int partitionIndex = Partition(array, low, high);

        // now sort the left and right halves
        QuickSort(array, low, partitionIndex - 1);
        QuickSort(array, partitionIndex + 1, high);
    }
}

// Print an array
void PrintArray(int array[], int size)
{
    for (int i = 0; i < size; i++)
        std::cout << array[i] << " "; 
    std::cout << std::endl;
}

// Driver code
int main()
{
    int array[] = { 4, 6, 3, 8, 3, 5 };

    int size = sizeof(array) / sizeof(array[0]);

    std::cout << "Given array: ";
    PrintArray(array, size);

    QuickSort(array, 0, size - 1);

    std::cout << "Sorted array: ";
    PrintArray(array, size);

    return 0;
}

