function stringPermutations(str) {
  if (str.length <= 1) {
    return [str];
  }

  let perms = [];

  for (let i = 0; i < str.length; i++) {
    let char = str[i];

    // remove the char from string
    let subStr = str.substring(0, i) + str.substring(i + 1);

    // get subpermutations
    let subPerms = stringPermutations(subStr);

    // append current char to every subpermutation
    for (let j = 0; j < subPerms.length; j++) {
      perms.push(char + subPerms[j]);
    }
  }

  return perms;
}

def pascals_triangle(n):
    '''Prints a pascals triangle of size n'''
    lines = []
    for i in range(1, n+1):
        line = [1] * i
        for j in range(1, i-1):
            line[j] = lines[i-2][j-1] + lines[i-2][j]
        lines.append(line)

    for line in lines:
        print(' '.join(map(str, line)))

