def shortest_distance(dict, source, dest):
    n = len(dict)
    visited = [False] * n 

    distance = [float('inf')] * n

    distance[dict.index(source)] = 0

    for i in range(n): 
        min_index = -1
        for j in range(n):
            if visited[j] == False and (min_index == -1 or distance[j] < distance[min_index]):
                min_index = j 
        visited[min_index] = True

        for k in range(n):
            if(dict[min_index] == dict[k]): 
                continue
            if visited[k] == False and (abs(min_index - k) == 1 or k-min_index == len(dict)-1):
               if(distance[min_index] + 1 < distance[k]):
                   distance[k] = distance[min_index] + 1
    return distance[dict.index(dest)]

