int getIndexOfMax(int arr[], int size) {
 // check for empty array
 if (size == 0)
 return -1;

 // initial index of max element
 int maxInd = 0;

 // start from first element
 for (int i = 1; i < size; ++i) {
 // find position of largest element
 if (arr[i] > arr[maxInd])
 maxInd = i;
 }

 return maxInd;
}

