class NaiveBayes:
    def fit(self, X, y):
        # Create three dictionaries to store feature counts
        self.feature_pos_counts = create_feature_dict(X, y, 1)
        self.feature_neg_counts = create_feature_dict(X, y, 0)
        self.class_counts = count_classes(y)

    def predict(self, x_test):
        predictions = []

        for x in x_test:
            pos_prob, neg_prob = self.get_pos_and_neg_prob(x)
            predictions.append(1 if pos_prob > neg_prob else 0)

        return predictions

    def get_pos_and_neg_prob(self, x):
        pos_prob = self.class_counts[1] / len(y)
        neg_prob = self.class_counts[0] / len(y)

        for feature_index in range(len(x)):
            feature_value = x[feature_index]
            pos_prob *= self.feature_pos_prob(feature_index, feature_value)
            neg_prob *= self.feature_neg_prob(feature_index, feature_value)

        return pos_prob, neg_prob

