public class APIcall
{
    public static object GetAPIdata(string APIUrl)
    {
        HttpWebRequest APIRequest = 
            (HttpWebRequest)WebRequest.Create(APIUrl);
        APIRequest.Method = "GET";
        APIRequest.ContentType = "text/html; charset=utf-8";

        HttpWebResponse APIResponse = 
            (HttpWebResponse)APIRequest.GetResponse();
        Stream APIStream = APIResponse.GetResponseStream();
        StreamReader APIReader = new StreamReader(APIStream);
        string APIdata = APIReader.ReadToEnd();
        APIResponse.Close();
        APIReader.Close();

        return APIdata;
    }
}

