using namespace std;

int main() 
{ 
    int array[2][2] = {{1, 2}, {3, 4}}; 
    int det = array[0][0]*array[1][1] - array[1][0]*array[0][1]; 

    // Finding the inverse using "Cramer's Rule" 
    int inv[2][2] = {{array[1][1]/det, -array[0][1]/det}, 
                      {-array[1][0]/det, array[0][0]/det}}; 

    // Printing the inverse matrix 
    cout << "Inverse of the matrix is: " << endl; 
    for (int i = 0; i < 2; i++) 
    { 
        for (int j = 0; j < 2; j++) 
        { 
            cout << inv[i][j] << " "; 
        }
        cout << endl; 
    }

    return 0; 
}

