   <RecipeForm onCreate={createRecipe} />
   {recipes.map((recipe, index) =>
    <Recipe 
     key={index}
     index={index}
     recipe={recipe}
     onEdit={editRecipe}
     onDelete={deleteRecipe}
    />
   )}
  </React.Fragment>
 );

};

