// Function to merge two sorted arrays in ascending order
vector<int> mergeSortedLists(vector<int> list1, vector<int> list2){
    vector<int> res(list1.size() + list2.size());

    int i = 0, j = 0, k = 0;

    while(i < list1.size() && j < list2.size()){
        if(list1[i] < list2[j])
            res[k++] = list1[i++];
        else
            res[k++] = list2[j++];
    }

    while(i < list1.size()){
        res[k++] = list1[i++];
    }

    while(j < list2.size()){
        res[k++] = list2[j++];
    }

    return res;
}

