func findLCS(s1 string, s2 string) string {
    lcs := ""
    row := len(s1) + 1
    column := len(s2) + 1
    table := make([][]int, row)
    for k := range table {
        table[k] = make([]int, column)
    }
    maxim := 0
    for i := 1; i < row; i++ {
        for j := 1; j < column; j++ {
            if s1[i - 1] == s2[j - 1] {
                table[i][j] = table[i - 1][j - 1] + 1
                if table[i][j] > maxim {
                    maxim = table[i][j]
                    lcs = s1[i - maxim:i]
                }
            }
        }
    }
    return lcs
}

