def aStarSearch(grid, start, end):
 startNode = Node(None, start)
 endNode = Node(None, end)

 openList = []
 closedList = []

 openList.append(startNode)

 while len(openList) > 0:
 currentNode = openList[0]

 currentIndex = 0
 for index, item in enumerate(openList):
 if item.f < currentNode.f:
 currentNode = item
 currentIndex = index

 openList.pop(currentIndex)
 closedList.append(currentNode)

 if currentNode == endNode:
 path = []
 current = currentNode
 while current is not None:
 path.append(current.position)
 current = current.parent
 return path[::-1]

 children = []
 for newPosition in childrenPositions(currentNode.position):
 if isValidPosition(grid, newPosition):
 newNode = Node(currentNode, newPosition)
 children.append(newNode)

 for child in children:

 for closedChild in closedList:
 if child == closedChild:
 continue

 child.g = currentNode.g + 1
 child.h = heuristic(child.position, endNode.position)
 child.f = child.g + child.h

 for openNode in openList:

 if child == openNode and child.g > openNode.g:
 continue

 openList.append(child)

def isValidPosition(grid, position):
 if position[0] < 0 or position[1] < 0 or position[0] > len(grid) or position[1] > len(grid) or grid[position[0]][position[1]]:
 return False
 return True

def heuristic(position, end):
 return  abs(end[0] - position[0]) + abs(end[1] - position[1])

def childrenPositions(position):
 children = []

 xPos, yPos = position

 positions = [[xPos - 1, yPos], [xPos + 1, yPos], [xPos, yPos - 1], [xPos, yPos + 1]]

 for pos in positions:
 if len(pos) < 2 or pos[0] < 0 or pos[1] < 0 or pos[0] > len(grid) or pos[1] > len(grid):
 continue

 children.append(pos)

 return children

