def searchMatrix(matrix, target): 
    if not matrix: 
        return False 
    row_len, col_len = len(matrix), len(matrix[0]) 
    row, col = 0, col_len-1 
    while row < row_len and col >= 0 : 
        if matrix[row][col] == target : 
            return True 
        elif matrix[row][col] < target : 
            row += 1 
        else: 
            col -= 1 
    return False

