function sort(arr) {
  let temp;
  let swapped;

  // Repeat until no elements have been swapped
  do {
    swapped = false;

    // Iterate over the array
    for (let i = 0; i < arr.length-1; i++) {
      // Compare each pair of adjacent elements
      if (arr[i] > arr[i+1]) {
        // Swap them if the current element is greater than the next
        temp = arr[i];
        arr[i] = arr[i+1];
        arr[i+1] = temp;

        swapped = true;
      }
    }
  }
  while (swapped);

  // Return the sorted array
  return arr;
}

