def longest_palindrome_substring(input_string):
    substr_len = longest_substr = 1

    if len(input_string) > 1: 
        for i in range(len(input_string)): 

            #odd-length palindromes 
            low = i - 1
            high = i + 1
            while low >= 0 and high < len(input_string) and input_string[low] == input_string[high]: 
                if high - low + 1 > longest_substr: 
                    longest_substr = high - low + 1
                    substr_len = longest_substr 
                low -= 1
                high += 1

            #even-length palindromes 
            low = i -1
            high = i 
            while low >= 0 and high < len(input_string) and input_string[low] == input_string[high]: 
                if high - low + 1 > longest_substr: 
