def find_prime_numbers(N):
  prime_numbers = []

  #Loop till the given N
  for i in range(2, N+1):
    is_prime = True

    #check if the current number is divisible  
    #by any number less than it
    for j in range(2, i):
      if i % j == 0:
        is_prime = False
        break

    #append the number to prime_numbers if it is prime
    if is_prime:
      prime_numbers.append(i)

  return prime_numbers

