def build_clusters(data):
    clusters = []

    while len(data) > 0:
        current_element = data[0]
        cluster = []
        data.remove(current_element)

        for i in data:
            if abs(i[0] - current_element[0]) + abs(i[1] - current_element[1]) + abs(i[2] - current_element[2]) <= 1:
                cluster.append(i)
                data.remove(i)

        clusters.append(cluster)

    return clusters

