import java.util.LinkedList; 

class GFG { 

 // Function to find middle element a linked list 
 static int getMiddle(LinkedList ll) 
 { 
 if (ll.isEmpty()) 
 return -1; 

 int slow_ptr = ll.get(0); 
 int fast_ptr = ll.get(0); 

 while (fast_ptr != ll.getLast() 
 && fast_ptr.next != ll.getLast()) { 
 fast_ptr = fast_ptr.next.next; 
 slow_ptr = slow_ptr.next; 
 } 

 // if there are even elements in list 
 // then return second middle element 
 if (fast_ptr == ll.getLast()) 
 return slow_ptr.next; 

 return slow_ptr; 
 } 

