function findWords(chars) {
    //create empty set
    let words = new Set();
    //call recursive function with empty string and characters array
    findWordsHelper(words, "", chars);
    return words;
}

function findWordsHelper(words, currentWord, chars) {
    //base condition
    if(chars.length === 0) {
        words.add(currentWord);
        return;
    }

    //iterate over character array
    for(let i = 0; i < chars.length; i++) {
        //create new character array with removed character at position i
        let newChars = chars.slice(0, i).concat(chars.slice(i+1));

        //call recursive function with current word plus removed character and new character array
        findWordsHelper(words, currentWord + chars[i], newChars); 
    }
}

