public class Stack
{
    private int top;
    private int capacity;
    private int array[];

    public Stack(int capacity)
    {
        this.capacity = capacity;
        array = new int[capacity];
        top = -1;
    }

    public boolean isFull()
    {
        return (top == capacity - 1);
    }

    public boolean isEmpty()
    {
        return (top == -1);
    }

    public void push(int item)
    {
        if (isFull())
        {
            System.out.println("Stack is Full!");
            return;
        }
        array[++top] = item;
    }

    public int pop()
    {
        if (isEmpty())
        {
            System.out.println("Stack is Empty!");
            return -1;
        }
        return array[top--];
    }

}

def evaluate_expression(expression):
    stack = []
    for char in expression:
        if char.isdigit():
            stack.append(int(char))
        else:
            num1 = stack.pop()
            num2 = stack.pop()
            if char is '+':
                res = num1 + num2
            elif char is '-':
                res = num2 - num1
            elif char is '*':
                res = num1 * num2
            elif char is '/':
                res = num2 / num1
            stack.append(res)
    return stack.pop()

