def find_shortest_path(start_vertex, end_vertex, graph):
  # Establish a shortest-paths data structure
  shortest_paths = {vertex: {'cost': float("inf"), 'prev': None} for vertex in graph}

  # Set the start vertex's cost to 0
  shortest_paths[start_vertex] = {"cost": 0, "prev": None}

  # Loop through the graph
  while shortest_paths:
    # Find an unvisited vertex with the smallest cost
    vertex, cost = min(
      {(vertex, cost) for vertex, cost in shortest_paths.items()},
      key=lambda x: x[1]['cost']
    )

    # If the end is found, break out of the loop
    if vertex == end_vertex:
        break

    # Update the costs for adjacent vertices
    for neighbor, edge_cost in graph[vertex].items():
        new_cost = cost['cost'] + edge_cost
        if new_cost < shortest_paths[neighbor]['cost']:
            shortest_paths[neighbor]['cost'] = new_cost
            shortest_paths[neighbor]['prev'] = vertex

    # Remove the visited vertex
    del shortest_paths[vertex]

  # Reconstruct the path
  path = []
  while end_vertex is not None:
    path.append(end_vertex)
    end_vertex = shortest_paths[end_vertex]['prev']

  # Reverse the path
  return path[::-1]

