class BalancedParantheses {
    public static bool IsBalanced(string input) {
        // Create stack
        var stack = new Stack<char>();

        // Push opening brackets
        foreach (var c in input)
            if (c == '(' || c == '{' || c == '[') {
                stack.Push(c);
            }

        // Check matching closing brackets
        foreach (var c in input) {
            if (c == ')' || c == '}' || c == ']') {
                if(stack.Count == 0) {
                    return false;
                }

                char top = stack.Pop();

                if (! IsMatch(top, c)) {
                    return false;
                }
            }
        }

        // Stack should be empty if parentheses matched
        return stack.Count == 0;
    }

    // Returns true if the characters match
    private static bool IsMatch(char open, char close) {
        return open == '(' && close == ')' ||
               open == '{' && close == '}' ||
               open == '[' && close == ']';
    }
}

