public static void sort(int[] array) {
 //Loop through the array
 for (int i = 0; i < array.length; i++) {
 //Store the current element
 int min = array[i];
 int min_index = i;

 //Loop through the unsorted section of the array
 for (int j = i+1; j < array.length; j++) {
 //If the current element is less than the min
 if (array[j] < min) {
 //Store index of the current element
 min = array[j];
 min_index = j;
 }
 }

 //Swap the element with the lowest element
 int temp = array[i];
 array[i] = min;
 array[min_index] = temp;
 }
}

