"""
Determine the maximum subarray of a given array
"""
def max_subarray(arr): 
    max_so_far = 0;   
    max_ending_here = 0; 

    for i in range(len(arr)):
        # if max_ending_here > 0, elements are increasing
        if  max_ending_here + arr[i] > 0:
            # if elements are increasing, add element to max_ending_here
            max_ending_here += arr[i]
        else:
            # if elements are decreasing, reset max_ending_here
            max_ending_here = 0

        # if max_ending_here > max_so_far, update max_so_far
        if max_so_far < max_ending_here:
            max_so_far = max_ending_here

    return max_so_far

