public void removeDuplicates(LinkedList list) { 
    Node currentElement = list.head; 
    Node nextElement; 

    // Loop through the list 
    while (currentElement != null && currentElement.next != null) { 
        nextElement = currentElement; 

        // Loop through all remaining elements 
        while (nextElement.next != null) { 
            // If currentElement's data is equal to nextElement's data 
            if (currentElement.data ==nextElement.next.data) { 
                nextElement.next=nextElement.next.next;
            } else {
                // Else, move nextElement to the next node
                nextElement = nextElement.next;
            } 
        } 

        // Move currentElement to the next node 
        currentElement = currentElement.next; 
    } 
}

def binarySearch(arr, x): 
    low = 0
    high = len(arr) - 1
    while low <= high: 
        mid = (high + low) // 2
        if arr[mid] < x: 
            low = mid + 1
        elif arr[mid] > x: 
            high = mid - 1
        else: 
            return mid 
    return -1

