public static boolean binarySearch(int[] array, int target) {
    int left = 0;
    int right = array.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2; 
        int midVal = array[mid];
        if (midVal == target) {
            return true;
        }
        else if (midVal < target) {
            left = mid + 1;
        }
        else {
            right = mid - 1;
        }
    }
    return false;
}

