function bubbleSort(arr) {
 let sorted;
 do {
 sorted = false;
 for (let i = 0; i < arr.length; i++) {
 if (arr[i] > arr[i + 1]) {
 [arr[i], arr[i + 1]] = [arr[i + 1], arr[i]];
 sorted = true;
 }
 }
 } while (sorted);

return arr;
}

const arr = [3, 2, 4, 5, 1];
bubbleSort(arr);

console.log(arr); // [1,2,3,4,5]

public static boolean detectCycle(ListNode head) {
    ListNode slow = head;
    ListNode fast = head;
    int loopCounter = 0;

    if (head == null){
        return false;
    }
    if (head.next == null){
        return false;
    }

    while (loopCounter < 100){
        slow = slow.next;
        fast = fast.next.next;

        if (fast == slow)
            return true;
        loopCounter++;
    }
    return false;
}

fn fibonacci(n: i32) -> i32 {
    let mut a = 0;
    let mut b = 1;

    for _ in 0..n {
        let c = a + b;
        a = b;
        b = c;
    }

    return a;
}

