def group_integers(list, criteria):
    groups = {tuple(criterion):[] for criterion in criteria}
    for number in list:
        for criterion in criteria:
            if criterion[0]<=number and number <= criterion[1]:
                groups[tuple(criterion)].append(number)
    return groups

