def quick_sort(arr):
  if len(arr) < 2:
    return arr

  left, equal, right = [], [], []
  pivot = arr[0]

  for value in arr:
    if value < pivot:
      left.append(value)
    elif value > pivot:
      right.append(value)
    else:
      equal.append(value)

  return quick_sort(left) + equal + quick_sort(right)

