// Optimized prime number algorithm

// Step 1: Initialize the prime list
primeList = []

// Step 2: Iterate from 2 to the given number
for i in range(2, n):

    // Step 3: Set prime flag to true
    isPrime = true;

    // Step 4: Iterate from 2 to sqrt(i)
    for j in range(2, int(i**0.5) + 1):

        // Step 5: If any factor is found then set prime flag to false
        if i % j == 0:
            isPrime = false;
            break;

    // Step 6: Based on prime flag append the number in the list
    if isPrime:
        primeList.append(i);

// Step 7: Return the prime list 
return primeList;

