def encrypt_substitution_cipher(s):
    cipher = {'A':'X', 'B':'D', 'C':'V', 'D':'U', 'E':'G', 'F':'Q', 'G':'K', 
              'H':'A', 'I':'W', 'J':'P', 'K':'Z', 'L':'R', 'M':'B', 'N':'Y', 
              'O':'C', 'P':'F', 'Q':'O', 'R':'N', 'S':'T', 'T':'J', 'U':'H', 
              'V':'E', 'W':'L', 'X':'S', 'Y':'M', 'Z':'I'}
    s = s.upper()
    encrypted_string = ""
    for char in s:
        if char in cipher:
            encrypted_string += cipher[char]
        else:
            encrypted_string += char
    return encrypted_string

