public static int findGCD(int x, int y) {
 if (x == 0 || y == 0) {
 return 0;
 }

// base case
 if (x == y) {
 return x;
 }

// swap if necessary so x < y
 if (x > y) {
 int temp = x;
 x = y;
 y = temp;
 }

// GCD(x, y) = GCD(x, y-x)
 return findGCD(x, y-x);
}

