public static bool ContainsUniqueCharacters(string input)
{
    // Check if the input string is null or empty
    if (string.IsNullOrEmpty(input))
    {
        return false;
    }

    // Create a set to store unique characters
    var uniqueCharacters = new HashSet<char>();

    // Loop through the input string
    foreach (char c in input)
    {
        // If the character is already in the set, the string doesn't contain unique characters
        if (uniqueCharacters.Contains(c))
        {
            return false;
        }

        // Otherwise, add the character to the set
        uniqueCharacters.Add(c);
    }

    // The input string contains unique characters
    return true;
}

