 let longest = '';
 for (let i = 0; i < phrase1.length; i++) {
 for (let j = 0; j < phrase2.length; j++) {
 let substring = '';
 while (phrase1[i+substring.length] === phrase2[j+substring.length]) {
 substring += phrase1[i+substring.length];
 if (substring.length > longest.length) {
 longest = substring;
 }
 if (i+substring.length > phrase1.length || j+substring.length > phrase2.length) {
 break;
 }
 }
 }
