function oneDifference(str1, str2) {
  // check the lengths, if they are more than 1 character off, return false
  if (Math.abs(str1.length - str2.length) > 1) {
    return false;
  }

  // loop through each character in the strings, looking for one difference
  let diffCount = 0;
  for (let i = 0; i < str1.length; i++) {
    if (str1[i] !== str2[i]) {
      // if the difference count is already > 0, there must be more than one difference so return false
      if (diffCount > 0) {
        return false;
      } else {
        diffCount++;
      }
    }
  }

  // there can be only one difference, if we reach this far, we passed
  return true;
}

