def least_common_ancestor(root, node1, node2):

    # If nodes are either side of root, root is LCM
    if (node1.data < root.data and node2.data > root.data)  or (node2.data < root.data and node1.data > root.data):
        return root

    # If both nodes are smaller than root, LCM lies in left subtree
    elif node1.data < root.data and node2.data < root.data:
        return least_common_ancestor(root.left, node1, node2)

    # If both nodes are greater than root, LCM lies in right subtree
    elif node1.data > root.data and node2.data > root.data:
        return least_common_ancestor(root.right, node1, node2)

