    var reversedArr = [];

    // iterate over the length of the given array
    for (var i=arr.length -1; i >= 0; i--) {
        // add the element at the index of i to the beginning of the new array
        reversedArr.unshift(arr[i]);
    }

    return reversedArr;

}

class HashTable: 
    def __init__(self, size): 
        self.table = [None]*size 
        self.num_elements = 0

    def hashCode(self, key): 
        key_bytes = key.encode() 
        hash_code = sum(key_bytes) 
        return hash_code 

    def compress(self, hash_code): 
        compressor = hash_code % len(self.table) 
        return compressor 

    def assign(self, key, value): 
        array_index = self.compress(self.hashCode(key))
        current_array_value = self.table[array_index]  
        if current_array_value is None:
            self.table[array_index] = [key, value] 
            self.num_elements += 1 

        if current_array_value[0] == key:
            self.table[array_index] = [key, value] 

    def retrieve(self, key): 
        array_index = self.compress(self.hashCode(key)) 
        possible_return_value = self.table[array_index]             
        if possible_return_value is None: 
            return None 
        if possible_return_value[0] == key: 
            return possible_return_value[1]

