def findElement(arr, target):
    if arr is None or len(arr) == 0:
        return False
    num_rows = len(arr)
    num_cols = len(arr[0])
    row = 0
    col = num_cols - 1
    while row < num_rows and col >= 0:
        if target == arr[row][col]:
            return True
        elif target < arr[row][col]:
            col -= 1
        else:
            row += 1
    return False

