def longestCommonPrefix(stringArray):
    if len(stringArray) == 0:
        return ""
    minString = min(stringArray, key=len)
    for i in range(1, len(minString) + 1):
        substring = minString[:i]
        for j in range(1, len(stringArray)):
            if stringArray[j].find(substring) != 0:
                return minString[:i-1]
    return minString

