void insertionSort(int[] arr) {
    int n = arr.length;
    int temp, i, j;
    for (i = 1; i < n; i++) {
        j = i - 1;
        temp = arr[i];
        while (j >= 0 && arr[j] > temp) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = temp;
    }
}

