    # If the number is less than 2, it is not a prime 
    if num < 2: 
        return False 

    # Check if the number is divisble by any number from 2 to 
    # the square root of the number 
    for i in range(2, int(sqrt(num)) + 1): 
        if num % i == 0: 
            return False

    return True

