public static int BinarySearch(int[] array, int target)
{
 int left = 0;
 int right = array.Length - 1;

 while (left <= right)
 {
 int midpoint = left + (right - left) / 2;

 if (array[midpoint] == target)
 {
 return midpoint;
 }
 else if (array[midpoint] < target)
 {
 left = midpoint + 1;
 }
 else
 {
 right = midpoint - 1;
 }
 }

 return -1;
}

