public static String findMostFrequentWord(String[] words) {
    if(words == null || words.length == 0)
        return null;

    HashMap<String, Integer> wordCount = new HashMap<>();

    for (String str: words) {
        if (wordCount.containsKey(str)) {
            int count = wordCount.get(str);
            wordCount.put(str, ++count);
        } else {
            wordCount.put(str, 1);
        }
    }

    int highestFrequency = 0;
    String mostFrequentWord = "";
    for (Map.Entry<String, Integer> e : wordCount.entrySet()) {
        if (e.getValue() > highestFrequency) {
            highestFrequency = e.getValue();
            mostFrequentWord = e.getKey();
        }
    }

    return mostFrequentWord;
}

