def square_root(num):
    if num < 0:
        return "Error"

    # Initialise roots
    low = 0
    high = num

    # Using binary search algorithm
    while low <= high:
       mid = (low + high)//2
       mid_sqr = mid * mid

       if mid_sqr == num:
           return mid

       elif mid_sqr < num:
           low = mid + 1

       elif mid_sqr > num:
           high = mid - 1

    # If root is not a perfect square
    return mid

