import React, {useState, useEffect} from 'react';

const Table = ({data}) => { 
// state variables
  const [page, setPage] = useState(1);
  const [sortColumn, setSortColumn] = useState(null);
  const [sortOrder, setSortOrder] = useState('asc');

// table headers
  const headers = [
    { name: 'id', label: 'ID' },
    { name: 'firstName', label: 'First Name' },
    { name: 'lastName', label: 'Last Name' },
  ];

// table body data
  const getTableData = () => { 
    let items = data;

    if (sortColumn) {
      items = items.sort((a, b) => {
        let order = 1;
        if (sortOrder === 'desc') order = -1;
        if (a[sortColumn] < b[sortColumn]) return -1 * order;
        if (a[sortColumn] > b[sortColumn]) return 1 * order;
        return 0;
      });
    }

    return items;
  };

  const handleSort = (name) => {
    let newOrder;
    if (name === sortColumn) {
      newOrder = (sortOrder === 'asc') ? 'desc' : 'asc';
    } else {
      newOrder = 'asc';
    }
    setSortColumn(name);
    setSortOrder(newOrder);
  };

// render header
  const renderHeader = () => (
    <thead>
      <tr>
        {headers.map(item => {
          let className = '';
          if (item.name === sortColumn) {
            className = (sortOrder === 'asc') ? 'ascending' : 'descending';
          };
          return (
            <th key={item.name} className={className} onClick={() => handleSort(item.name)}>
              {item.label}
            </th>
          )
        })}
      </tr>
    </thead>
  )

// render body
  const renderBody = () => (
    <tbody>
      {getTableData().map((row, index) => {
        const {id, firstName, lastName} = row;
        return (
          <tr key={index}>
          <td>{id}</td>
          <td>{firstName}</td>
          <td>{lastName}</td>
          </tr>
        );
      })}
    </tbody>
  );

// render pagination
  const renderPagination = () => (
    <nav>
      <ul>
      <li>Page { page } of { Math.ceil(data.length / 10)}</li>
        <li><a href="/#">Next</a></li>
      </ul>
    </nav>
  );

  return (
    <div>
      <div id="table">
      <table>
        {renderHeader()}
        {renderBody()}
      </table>
      </div>
      {renderPagination()}
    </div>
  );
};

