// function to convert binary tree  
// to doubly linked list 
Node* Bintree2listUtil(Node* root)  
{  
    // Base case  
    if (root == NULL) 
        return root;  

    // Convert the left subtree and link to root  
    if (root->left != NULL)  
    {  
        // Convert the left subtree  
        Node* left = Bintree2listUtil(root->left);  

        // Find inorder predecessor. After this loop, left  
        // will point to the inorder predecessor  
        for (; left->right!=NULL; left=left->right);  

        // Make root as next of the predecessor  
        left->right = root;  

        // Make predecssor as previous of root  
        root->left = left;  
    }  

    // Convert the right subtree and link to root  
    if (root->right!=NULL)  
    {  
        // Convert the right subtree  
        Node* right = Bintree2listUtil(root->right);  

        // Find inorder successor. After this loop, right  
        // will point to the inorder successor  
        for (; right->left!=NULL; right = right->left);  

        // Make root as previous of successor  
        right->left = root;  

        // Make successor as next of root  
        root->right = right;  
    }  

    return root;  
}

"""
Create a function which will take two strings as input and edit them to make them into anagrams of each other.
"""

def make_anagrams(s1, s2):

  # convert strings to lists
  s1 = list(s1)
  s2 = list(s2)

  # count characters in strings
  counts1 = {}
  counts2 = {}
  for c in s1:
      if c in counts1:
          counts1[c] += 1
      else:
          counts1[c] = 1
  for c in s2:
      if c in counts2:
          counts2[c] += 1
      else:
          counts2[c] = 1

  # remove common characters
  for c in counts1.keys():
      if c in counts2:
          min_cnt = min(counts1[c], counts2[c])
          s1 = [c for c in s1 if c != c] * min_cnt
          s2 = [c for c in s2 if c != c] * min_cnt
          del counts1[c]
          del counts2[c]

  # add extra characters to the second string
  s2 += [c for c in counts1.keys()] * counts1[c]

  # add extra characters to the first string
  s1 += [c for c in counts2.keys()] * counts2[c]

  s1 = ''.join(s1)
  s2 = ''.join(s2)

  return s1, s2

