const sortAsc = arr => {
    // loop through the array
    for (let i = 0; i < arr.length; i++) {
        // loop through the subarray from start to current element
        for (let j = 0; j < i; j++) {
            // if current element is less than previous element, 
            //  swap them
            if (arr[i] < arr[j]) {
                let temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
        }
    }
    return arr;
};

