def isSafe(board, row, col, num): 
    # check if 'num' is not already placed in current row 
    for i in range(9): 
        if board[row][i] == num: 
            return False

    # check if 'num' is not already placed in current column 
    for i in range(9): 
        if board[i][col] == num: 
            return False

    # 3x3 matrix 
    row_start = row - row % 3
    col_start = col - col % 3

    for i in range(row_start, row_start + 3): 
        for j in range(col_start, col_start + 3): 
            if board[i][j] == num: 
                return False

    return True

def solveSudoku(board): 
    row, col = findUnassignedLocation(board) 

    # base case: if all cells are assigned 
    if row == -1 and col == -1: 
        return True

    for num in range(1, 10): 

        # check if safe to assign 'num' to current cell 
        if isSafe(board, row, col, num): 
            board[row][col] = num 

            # recursively try fill in the rest 
            if solveSudoku(board): 
                return True

            # failure, unmake & try again 
            board[row][col] = 0

    # this triggers backtracking         
    return False

def findUnassignedLocation(board): 
    for row in range(9): 
        for col in range(9): 
            if board[row][col] == 0: 
                return (row, col) 

    return (-1, -1)

