const heapSort = arr => {
  const maxHeapify = (arr, idx, max) => {
    let largest = idx;
    let leftIdx = 2 * idx + 1;
    let rightIdx = 2 * idx + 2;

    if (leftIdx < max && arr[leftIdx] > arr[largest]) {
      largest = leftIdx;
    }

    if (rightIdx < max && arr[rightIdx] > arr[largest]) {
      largest = rightIdx;
    }

    if (idx !== largest) {
      [arr[idx], arr[largest]] = [arr[largest], arr[idx]];
      maxHeapify(arr, largest, max);
    }
  };

  const heap = (arr, length) => {
    for (let i = Math.floor(length / 2); i >= 0; i--) {
      maxHeapify(arr, i, length);
    }

    for (let j = length - 1; j > 0; j--) {
      [arr[j], arr[0]] = [arr[0], arr[j]];
      maxHeapify(arr, 0, j);
    }
    return arr;
  };

  return heap(arr, arr.length);
};

