public static int[] closestPair(int[] a1, int[] a2) {
    int minDiff = Integer.MAX_VALUE;
    int minX = -1;
    int minY = -1;

    int i = 0; 
    int j = 0;
    while (i < a1.length && j < a2.length) {
        int diff = Math.abs(a1[i] - a2[j]);
        if (diff < minDiff) {
            minDiff = diff;
            minX = a1[i];
            minY = a2[j];
        }
        if (a1[i] > a2[j]) 
            j++;
        else 
            i++;
    }

    return new int[]{minX, minY};
}

