public class TransactionHandler {
  // List of all transactions
  List<Transaction> transactions;

  // Constructor
  public TransactionHandler(List<Transaction> transactions) {
    this.transactions = transactions;
  }

  public Map<Integer, List<Transaction>> groupByCustomerId() {
    // Create a map to store the transactions by customer id
    Map<Integer, List<Transaction>> transactionMap = new HashMap<>();

    // Iterate over the transactions and group them by customer id
    for (Transaction transaction : transactions) {
      // Get the customer id of this transaction
      int customerId = transaction.getCustomerId();

      // Check if the customer id is already present in the map
      if (!transactionMap.containsKey(customerId)) {
        // If not, create a new list to store the transactions
        transactionMap.put(customerId, new ArrayList<Transaction>());
      }

      // Add the transaction to the list
      transactionMap.get(customerId).add(transaction);
    }

    return transactionMap;
  }

}

