def find_element_recursive(arr, element):
  if len(arr) == 0:
    return -1

  mid = len(arr) // 2

  if arr[mid] == element:
    return mid
  elif element < arr[mid]:
    return find_element_recursive(arr[:mid], element)
  else:
    return find_element_recursive(arr[mid + 1:], element)

