public class MazeSolver 
{ 
    public void solveMaze(int[,] maze) 
    { 
        if (maze[0, 0] == 0) 
        { 
            Console.WriteLine("No Solution"); 
            return; 
        } 

        // Initializing a matrix 
        // to keep track of visited cells. 
        int[,] solution = new int[maze.GetLength(0), 
                            maze.GetLength(1)]; 

        if (SolveMazeUtil(maze, 0, 0, solution) == false) 
            Console.Writeline("No Solution"); 
        else
            printSolution(solution); 
    } 

    // A recursive utility function 
    // to solve the Maze problem 
    private bool SolveMazeUtil(int[,] maze, int x, 
                            int y, int[,] solution) 
    { 
        // If (x, y is goal) 
        if (x == maze.GetLength(0) - 1 && y == maze.GetLength(1) - 1) 
        { 
            solution[x, y] = 1; 
            return true; 
        } 

        // Check if maze[x, y] is valid 
        if (isValid(maze, x, y) == true) 
        { 
            // mark x, y as part of solution path 
            solution[x, y] = 1; 

            // Move forward in x direction 
            if (SolveMazeUtil(maze, x + 1, y, solution)) 
                return true; 

            // If moving in x direction 
            // does not give solution 
            // then Move down in y direction 
            if (SolveMazeUtil(maze, x, y + 1, solution)) 
                return true; 

            // If none of the above movements 
            // work then BACKTRACK: 
            // un-mark x, y as part of the path 
            solution[x, y] = 0; 
            return false; 
        } 

        return false; 
    } 

    private bool isValid(int[,] maze, int x, int y) 
    { 
        if (x >= 0 && x < maze.GetLength(0) && y >= 0 && 
            y < maze.GetLength(1) && maze[x, y] == 1) 
            return true; 

        return false; 
    } 

    // Function to print the solution matrix 
    private void printSolution(int[,] solution) 
    { 
        for (int i = 0; i < solution.GetLength(0); i++) 
        { 
            for (int j = 0; j < solution.GetLength(1); j++) 
            { 
                Console.Write(solution[i, j] + " "); 
            } 
            Console.WriteLine(); 
        } 
    } 
}

