def convertIntToBin(num):
	binStr = ''
	bits = 8
	while bits > 0:
		if num&1 == 1:
			binStr = '1' + binStr
		else:
			binStr = '0' + binStr
		num = num >> 1
		bits -= 1
	return binStr

