class ItemDataStructure:
    def __init__(self, max_size):
        self.max_size = max_size
        self.data = [None] * max_size

    def add(self, item):
        if len(self.data) < self.max_size:
            self.data.append(item)
            return True
        else:
            return False

    def remove(self, item_index):
        if item_index >= 0 and item_index < self.max_size:
            del self.data[item_index]
            return True
        else:
            return False

    def search(self, item):
        for i in range(self.max_size):
            if self.data[i] == item:
                return i
        return -1

    def get(self, item_index):
        if item_index >= 0 and item_index < self.max_size:
            return self.data[item_index]
        else:
            return None

