Function longest_common_subsequence(string1, string2) {
  // Create a matrix to store the lengths of longest
  // common subsequences.
  let matrix = new Array(string1.length + 1).fill(0).map(x => new Array(string2.length + 1).fill(0));

  // Loop through and store values in the matrix
  // while comparing two strings
  for (let i = 0; i < string1.length; i++) {
    for (let j = 0; j < string2.length; j++) {
      if (string1[i] == string2[j]) {
        matrix[i+1][j+1] = matrix[i][j] + 1;
      } else {
        matrix[i+1][j+1] = Math.max(matrix[i+1][j], matrix[i][j+1]);
      }
    }
  }

  // Return the longest common subsequence
  return matrix[string1.length][string2.length];
}

