public static boolean isPrime(int n) {
 if (n < 2) {
 return false;
 }
 if (n == 2) {
 return true;
 }
 // check every number from 2 up to n-1
 for (int i = 2; i < n; i++) {
 if (n % i == 0) {
 // n is divisible by i, so it is not prime
 return false;
 }
 }
 // n is not divisible by any number from 2 up to n-1
 return true;
}

