def two_sum(nums, target):
  # Use dictionary to store two sum pairs
  two_sum_dict = {}

  # Iterate over numbers
  for i in range(len(nums)):
    # Calculate the difference between target and current number
    num2 = target - nums[i]

    # Check if the difference is in dictionary
    if num2 in two_sum_dict:
      # Return the two numbers
      return [nums[i], num2]
    else:
      # Add the current number as key to dictionary
      two_sum_dict[nums[i]] = nums[i]

# Call the function
