import java.util.regex.Matcher; 
import java.util.regex.Pattern; 

public class ValidateURL { 
    public static boolean isValid(String url)  
    { 
        String regex = "^(http:\\/\\/www\\.|https:\\/\\/www\\.|http:\\/\\/|https:\\/\\/)?[a-z0-9]+([\\-\\.]{1}[a-z0-9]+)*\\.[a-z]{2,5}(:[0-9]{1,5})?(\\/.*)?$";
        Pattern pattern = Pattern.compile(regex); 

        if (url == null) 
            return false; 

        Matcher matcher = pattern.matcher(url); 
        return matcher.matches(); 
    } 

    public static void main(String[] args)  
    { 

        String url1 = "https://www.example.com"; 
        String url2 = "1234"; 

        if(isValid(url1)) {
            System.out.println("url1 is valid"); 
        }else {
            System.out.println("url1 is invalid"); 
        }

        if(isValid(url2)) {
            System.out.println("url2 is valid"); 
        }else {
            System.out.println("url2 is invalid"); 
        }
    } 
}

