var canvas = document.querySelector('canvas');
var ctx = canvas.getContext('2d');
ctx.canvas.width = 500;
ctx.canvas.height = 500;

// Physics Variables
const GRAVITY = 0.9;
const FRICTION = 0.8;

// Classes
class Ball {
    constructor(x, y, size, color) {
        this.x = x;
        this.y = y;
        this.size = size;
        this.color = color;

        this.dx = 0;
        this.dy = 0;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, 2 * Math.PI);
        ctx.fillStyle = this.color;
        ctx.fill();
    }

    update() {
        this.x += this.dx;
        this.y += this.dy;

        this.dx *= FRICTION;
        this.dy += GRAVITY;
    }
}

// Create a ball
var ball = new Ball(250, 250, 20, "#FF0000");

// Main Loop
function draw() {
    // Clear canvas
    ctx.fillStyle = 'rgba(255, 255, 255, 0.2)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw
    ball.draw();
    ball.update();

    // Request Animation Frame
    requestAnimationFrame(draw);
}
