class Trie {
 constructor() {
 this.root = {};
 this.size = 0;
 }

 insert(word) {
 let node = this.root;
 for (let char of word) {
 if (!node[char]) {
 node[char] = {};
 }
 node = node[char];
 }
 if (!node.end) { 
 node.end = true;
 this.size++;
 }
 }

 search(word) {
 let node = this.root;
 for (let char of word) {
 if (node[char]) {
 node = node[char];
 } else {
 return false;
 }
 }

 return node.end === true;
 }

 startsWith(prefix) {
 let node = this.root;
 for (let char of prefix) {
 if (node[char]) {
 node = node[char];
 } else {
 return false;
 }
 }

 return true;
 }
}

