function isMultipleOf9(num) {
    while (num > 9) {
        // calculate the sum of all digits in the given number 
        let sum = 0;
        while(num > 0) {
            let lastDigit = num % 10;
            sum += lastDigit;
            num = Math.floor(num / 10);
        }
        num = sum;
    }
    // check if the final number is a multiple of 9
    return num === 9;
}

