def sort_list(input_list):

    # If the list has 0 or 1 element, it is already sorted.
    if len(input_list) <= 1:
        return input_list
    else:
        # Get the first element from the list
        pivot = input_list[0]
        # Create a list for the lesser elements
        less = [item for item in input_list[1:] if item <= pivot]
        # Create a list for the greater elements
        greater = [item for item in input_list[1:] if item > pivot]
        # Call the function recursively
        return sort_list(less) + [pivot] + sort_list(greater)

