def knapsack(weights, values, knapsack_weight_limit):
  # create a matrix to store values
  matrix = [[0 for i in range(knapsack_weight_limit + 1)] for j in range(len(weights) + 1)]

  # create a loop to look at each item separately
  for i in range(1, len(weights) + 1):
    for j in range(1, knapsack_weight_limit + 1):
      # if the items weight is more than the knapsack's weight limit,
      # then the value stays the same, otherwise, check if the value 
      # of adding it to the knapsack is greater than the value in the previous
      # row
      if weights[i - 1] > j:
        matrix[i][j] = matrix[i - 1][j]
      else:
        matrix[i][j] = max(matrix[i - 1][j], values[i - 1] + matrix[i - 1][j - weights[i - 1]])

  # return the max value of the matrix
  return matrix[len(weights)][knapsack_weight_limit]

