 const textArray = text.split(' ');
 const passage = [];
 let startWordIndex = Math.floor(Math.random * textArray.length);
 let nextWordIndex = textArray.length;
 // get the next word index based on our current word and order
 for (let i = 0; i < order; i++) {
 nextWordIndex = textArray.indexOf(
 textArray[startWordIndex + i + 1],
 startWordIndex
 );
 }
 // get the range of potential words that might follow
 const potentialWords = textArray.slice(startWordIndex + order, nextWordIndex);
 // generate the next word randomly
 const nextWord = potentialWords[
 Math.floor(Math.random() * potentialWords.length)
 ];
 passage.push(nextWord);
 // keep generating words until we reach a period
 while (nextWord[nextWord.length - 1] !== '.') {
 startWordIndex = textArray.indexOf(
 textArray[startWordIndex + order],
 startWordIndex
 );
 nextWordIndex = textArray.length;
 for (let i = 0; i < order; i++) {
 nextWordIndex = textArray.indexOf(
 textArray[startWordIndex + i + 1],
 startWordIndex
 );
 }
 potentialWords = textArray.slice(startWordIndex + order, nextWordIndex);
