// Merge Sort algorithm
void mergeSort(std::vector<int> &arr1, std::vector<int> &arr2)
{
    int n1 = arr1.size();
    int n2 = arr2.size();

    std::vector<int> merged(n1+n2);
    int i=0, j=0, k=0;

    // merge the two arrays into merged
    while (i < n1 && j < n2)
    {
        if (arr1[i] <= arr2[j])
            merged[k++] = arr1[i++];
        else
            merged[k++] = arr2[j++];
    }

    // add any left elements of arr1
    while (i < n1)
        merged[k++] = arr1[i++];

    // add any left elements of arr2
    while (j < n2)
        merged[k++] = arr2[j++];

    // store the merged arr in arr1 and arr2, then print the sorted array
    arr1 = merged;
    arr2 = merged;

    for (int i=0; i<n1+n2; i++)
        std::cout << merged[i] << " ";
}

