void printPrimeNumbers(int n) 
{
    // From 2 to n iterate and check whether a number is prime or not
    for (int i = 2; i <= n; i++) 
    { 
        int flag = 1; 

        // Check if the current number is divisible by any of the numbers from 2 to n
        for (int j = 2; j < i; j++) 
        { 
