// Function to find the most frequent element 
int mostFrequent(int arr[], int n) 
{ 
    // Sort the array 
    sort(arr, arr + n); 

    int max_count = 1;  // Initialize count 
    int res = arr[0];   // Initialize element 
    int curr_count = 1; 

    for (int i = 1; i < n; i++) 
    { 
        if (arr[i] == arr[i - 1]) 
            curr_count++; 
        else
        { 
            if (curr_count > max_count) 
            { 
                max_count = curr_count; 
                res = arr[i - 1]; 
            } 
            curr_count = 1; 
        } 
    } 

    // If last element is most frequent
    if (curr_count > max_count) 
    { 
        max_count = curr_count; 
        res = arr[n - 1]; 
    } 

    return res; 
} 

