        return 0
    # Initialize count as 0 
    count = 0
    # Loop through all the numbers
    for n in range(2, num):
        is_prime = True
        # Iterate through all the divisors
        for div in range(2, n):
            if div != 0 and n % div == 0:
                # Not prime
                is_prime = False
                break
        if is_prime:
            count += 1
    return count

