def longest_common_subsequence(list1, list2): 
    # Create a 2D matrix to store values 
    memo_matrix = [[0] * (len(list2) + 1) for i in range(len(list1) + 1)] 

    for i in range(1, len(list1)+1): 
        for j in range(1, len(list2)+1): 
            # compare the list1's element with list2's element 
            if list1[i-1] == list2[j-1]: 
                # If a match is found, increment the value of cell
                memo_matrix[i][j] = memo_matrix[i-1][j-1] + 1
            else: 
                # take the max value from either top or left cell
                memo_matrix[i][j] = max(memo_matrix[i][j-1], memo_matrix[i-1][j]) 
    # returns the length of the longest common subsequence
    return memo_matrix[len(list1)][len(list2)]

