public class SnakeGame extends JPanel {
    // Setup for the game
    private int unitWidth = 15;
    private int unitHeight = 15;
    private int boardWidth = 30;
    private int boardHeight = 20;
    private int[][] board = new int[boardWidth][boardHeight];
    private int foodX;
    private int foodY;

    // Array for the snake body
    private int[] snakeX = new int[100];
    private int[] snakeY = new int[100];
    private int snakeLength;
    private int snakeDirection;

    // Timer for game loop
    Timer timer;

    // Constructor
    public SnakeGame() {
        // Set up board
        setPreferredSize(new Dimension(boardWidth * unitWidth, boardHeight * unitHeight));
        setBackground(Color.BLACK);
        setFocusable(true);
        addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                switch (e.getKeyCode()) {
                    case KeyEvent.VK_UP:
                        snakeDirection = 1;
                        break;
                    case KeyEvent.VK_DOWN:
                        snakeDirection = 2;
                        break;
                    case KeyEvent.VK_RIGHT:
                        snakeDirection = 3;
                        break;
                    case KeyEvent.VK_LEFT:
                        snakeDirection = 4;
                        break;
                }
            }
        });
        initGame();
    }

    // Initialize game
    public void initGame() {
        // Set up snake
        snakeLength = 3;
        snakeX[0] = boardWidth / 2;
        snakeY[0] = boardHeight / 2;
        snakeDirection = 3;

        // Set up food
        newFood();

        // Set up UI
        setVisible(true);
        JFrame frame = new JFrame("Snake Game");
        frame.add(this);
        frame.pack();
        frame.setResizable(false);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);

        // Start game loop
        timer = new Timer(100, new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                tick();
            }
        });
        timer.start();
    }

    // Game loop
    public boolean tick() {
        // Move snake
        if (moveSnake()) {
            // Get food
            if (snakeX[0] == foodX && snakeY[0] == foodY) {
                snakeLength++;
                newFood();
            }
            // Update board
            for (int x = 0; x < boardWidth; x++) {
                for (int y = 0; y < boardWidth; y++) {
                    //snake
                    if (x == snakeX[0] && y == snakeY[0])
                        board[x][y] = 1;
                    //food
                    else if (x == foodX && y == foodY)
                        board[x][y] = 2;
                    else
                        board[x][y] = 0;
                }
            }
            repaint();
            return true;
        }
        return false;
    }

    // Generate a new food position
    public void newFood() {
        foodX = (int) (Math.random() * boardWidth);
        foodY = (int) (Math.random() * boardHeight);
    }

    // Move snake
    public boolean moveSnake() {
        // Update tail
        for (int i = snakeLength - 1; i > 0; i--) {
            snakeX[i] = snakeX[i - 1];
            snakeY[i] = snakeY[i - 1];
        }
        // Update head
        switch (snakeDirection) {
            case 1: // Up
                snakeY[0]--;
                break;
            case 2: // Down
                snakeY[0]++;
                break;
            case 3: // Right
                snakeX[0]++;
                break;
            case 4: // Left
                snakeX[0]--;
                break;
        }
        // Check for death
        if (snakeX[0] < 0 || snakeX[0] > boardWidth - 1 || snakeY[0] < 0 || snakeY[0] > boardHeight - 1) {
            return false;
        }
        // Check for self-intersection
        for (int i = 1; i < snakeLength; i++) {
            if (snakeX[0] == snakeX[i] && snakeY[0] == snakeY[i])
                return false;
        }
        return true;
    }

    // Paint GUI
    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        g.setColor(Color.BLUE);
        for (int x = 0; x < boardWidth; x++) {
            for (int y = 0; y < boardHeight; y++) {
                if (board[x][y] == 1)
                    g.fillRect(x * unitWidth, y * unitHeight, unitWidth, unitHeight);
                else if (board[x][y] == 2)
                    g.drawRect(x * unitWidth, y * unitHeight, unitWidth, unitHeight);
            }
        }
    }

    // Main
    public static void main(String[] args) {
        new SnakeGame();
    }
}

