function pascalTriangle(n) {
    let result = [];
    for (let i = 0; i < n; i++) {
        let row = [1];
        for (let j = 0; j <= i; j++) {
            if (j == i) {
                row.push(1);
            } else {
                row.push(result[i - 1][j] + result[i - 1][j + 1]);
            }
        }
        result.push(row);
    }
    return result;
}

