import java.util.*;

public class KruskalMST { 
 // kruskal's algorithm to find MST 
 static int V, e; 
 static int[][] graph; 
 static Edge[] edge; 

 //represent edge of graph 
 static class Edge implements Comparable<Edge> { 
 int src, dest, weight; 

 //compare weight 
 public int compareTo(final Edge o) 
 { 
 return this.weight - o.weight; 
 } 
 }; 

 //find set of vertex i 
 static int find(int[] parent, int i) 
 { 
 if (parent[i] == -1) 
 return i; 
 return find(parent, parent[i]); 
 } 

 //union of two subsets 
 static void union(int[] parent, int x, int y) 
 { 
 int xset = find(parent, x); 
 int yset = find(parent, y); 
 parent[xset] = yset; 
 } 

 //print constructed MST 
 static void KruskalMST() 
 { 
 //sorted edges 
 edge = new Edge[e]; 
 for (int i = 0; i < e; i++) 
 edge[i] = new Edge(); 

 int[] parent = new int[V]; 
 int x, y; 
 // Make subset 
 for (int i = 0; i < V; i++) 
 parent[i] = -1; 

 //step 1: sort all edges in non-decreasing order of their 
 // weight. 
 for (int i = 0; i < e; i++) 
 { 
 graph[i][0] = edge[i].src; 
 graph[i][1] = edge[i].dest; 
 graph[i][2] = edge[i].weight; 
 } 
 for (int i = 0; i < e; i++) 
 for (int j = 0; j < e - 1; j++) 
 { 
 if (graph[j][2] > graph[j + 1][2]) 
 { 
 x = graph[j][0]; 
 y = graph[j][1]; 
 graph[j][0] = graph[j + 1][0]; 
 graph[j][1] = graph[j + 1][1]; 
 graph[j][2] = graph[j + 1][2]; 
 graph[j + 1][0] = x; 
 graph[j + 1][1] = y; 
 graph[j + 1][2] = graph[j][2]; 
 } 
 } 
 for (int i = 0; i < e; i++) 
 { 
 //step 2: pick the smallest edge. Check if it forms 
 // a cycle with the spanning tree formed so far. 
 int subset1 = find(parent, graph[i][0]); 
 int subset2 = find(parent,graph[i][1]); 

 //IF cycle not formed 
 if (subset1 != subset2) 
 { 
 System.out.printf("Edge %d:(%d, %d) Weight: %d \n", 
 i, graph[i][0], graph[i][1], graph[i][2]); 

 union(parent, subset1, subset2); 
 } 
 } 
 } 

 // Driver code 
 public static void main(String[] args) 
 { 
 V = 4; // Number of vertices in graph 
 e = 5; // Number of edges in graph 

 //Graph 
 graph = new int[e][3]; 

 //assign data to graph 
 /*
 int graph[][] = { { 0, 1, 10 }, 
 { 0, 2, 6 }, 
 { 0, 3, 5 }, 
 { 1, 3, 15 }, 
 { 2, 3, 4 } }; 
 */
 graph[0][0] = 0; 
 graph[0][1] = 1; 
 graph[0][2] = 10; 
 graph[1][0] = 0; 
 graph[1][1] = 2; 
 graph[1][2] = 6; 
 graph[2][0] = 0; 
 graph[2][1] = 3; 
 graph[2][2] = 5; 
 graph[3][0] = 1; 
 graph[3][1] = 3; 
