function findMostCommon(arr) {
  let mostCommon;
  let mostCommonCount = 0;
  let countMap = {};

  for (let num of arr) {
    if (!countMap[num]) {
      countMap[num] = 0;
    }

    countMap[num]++;

    if (countMap[num] > mostCommonCount) {
      mostCommonCount = countMap[num];
      mostCommon = num;
    }
  }
  return mostCommon;
}

