/*
 * Iterative program to reverse a singly linked list and return the 
 * pointer to the head node
 */
Node *reverse(Node *head)
{
 Node *prev = nullptr;
 Node *curr = head;
 Node *next;

 while (curr != nullptr)
 {
  next = curr->next;
  curr->next = prev;
  prev = curr;
  curr = next;
 }

 return prev;
}

