function longestCommonSubstring(str1, str2) {
  let s1 = str1.split("");
  let s2 = str2.split("");
  let lcsLength = 0;
  let lcsObject = {};

  for (let i = 0; i < s1.length; i++){
    for (let j = 0; j < s2.length; j++) {
      if (s1[i] == s2[j]) {
        let lcsLengthTillNow = 0;
        let k = i;
        let l = j;
        while (s1[k] == s2[l] && k < s1.length && l < s2.length) {
          lcsLengthTillNow++;
          lcsObject[lcsLengthTillNow] = s1[k];
          k++;
          l++;
        }
        if (lcsLengthTillNow > lcsLength){
          lcsLength = lcsLengthTillNow;
        }
      }
    }
  }
  let lcsString = "";
  let lcsLengthIteration = 0;
  while (lcsLengthIteration < lcsLength) {
  	lcsString += lcsObject[lcsLengthIteration + 1];
    lcsLengthIteration++;
  }
  return lcsString;
}

