def evaluate_expression(exp):
    stack = []
    for token in exp:
        if isinstance(token, int):
            stack.append(token)
        else:
            op2, op1 = stack.pop(), stack.pop()
            if token == '+':
                stack.append(op1 + op2)
            elif token == '-':
                stack.append(op1 - op2)
            elif token == '*':
                stack.append(op1 * op2)
            elif token == '/':
                stack.append(op1 / op2)

    return stack.pop()

