int getMinCoins(int amount, vector<int> coins) {
 // Initialize the array to infinity (INT_MAX)
 int DP[amount+1] = {INT_MAX};

 // Set the base case:
 DP[0] = 0;

 for (int i=1; i<=amount; i++) {
  for (int coin: coins) {
  // The minimum number of coins is the minimum of the subproblems plus one
  if (coin <= i) {
  DP[i] = min(DP[i], DP[i-coin] + 1);
  }
  }
 }
 return DP[amount];
}

