func maze(matrix [][]int) {
	m := len(matrix) 
	n := len(matrix[0]) 

	// mark blocks to find the path 
	mark := make([][]bool, m)
	for i := 0; i < m; i++ {
		mark[i] = make([]bool, n)
	}

	// check the source and destination to the maze 
	source := []int{3, 0} 
	dest := []int{0, 3}

	// if possible to reach destination 
	if solveMazeUtil(matrix, source, dest, mark) { 
		fmt.Println("Solution Found") 
	} else { 
		fmt.Println("No Solution Found") 
	} 

	return
} 

func solveMazeUtil(matrix [][]int, source []int, dest []int, mark [][]bool) bool { 
	m := len(matrix) 
	n := len(matrix[0]) 

	if source[0] == dest[0] && source[1] == dest[1] { 
		mark[source[0]][source[1]] = true
		return true 
	}

	//Check if the selected block is valid or not
	if (source[0] < 0 || source[0] >= m || 
		source[1] < 0 || source[1] >= n || 
		matrix[source[0]][source[1]] == 1 || 
		mark[source[0]][source[1]] == true) { 
		return false 
	} 

	// Mark the block 
	mark[source[0]][source[1]] = true

	// Move right 
	if solveMazeUtil(matrix, []int{source[0] + 1, source[1]}, dest, mark) { 
		return true 
	} 

	//Move left 
	if solveMazeUtil(matrix, []int{source[0], source[1] - 1}, dest, mark) { 
		return true 
	} 

	//Move up
	if solveMazeUtil(matrix, []int{source[0] - 1, source[1]}, dest, mark) { 
		return true 
	}

	//Move down
	if solveMazeUtil(matrix, []int{source[0], source[1] + 1}, dest, mark) {
		return true 
	}	

	return false
}

