        // Create a count array to store all characters 
        // and their count 
        int[] count = new int[256]; 

        // Initialize count array index 
        for (int i = 0; i < str.length(); i++) { 
            count[str.charAt(i)]++; 
        } 

        // Find the index of the max value in count array 
        int max = 0; 
        char result = ' '; 
        for (int i = 0; i < str.length(); i++) { 
            if (max < count[str.charAt(i)]) { 
                max = count[str.charAt(i)]; 
                result = str.charAt(i); 
            } 
        } 

