def binomial_coefficient(n, k):
    if k == 0 or k == n:
        return 1
    numerator = 1
    for i in range(n - k + 1, n + 1):
        numerator *= i

    denominator = 1
    for i in range(1, k + 1):
        denominator *= i

    return numerator / denominator

