public class DataStructure {
    int[] array;
    int count;

    public void insert(int data) {
        if (count == array.length) {
            int[] temp = new int[count * 2]; // Double the array length if needed
            System.arraycopy(array, 0, temp, 0, count);
            array = temp;
        }
        array[count] = data;
        count++;
    }

    public void delete(int data) {

        int location = 0;

        // Find the data to delete
        for (int i = 0; i < count; i++) {
            if (array[i] == data) {
                location = i;
                break;
            }
        }

        // Shift elements to the left after the element to delete
        for (int i = location; i < count - 1; i++) {
            array[i] = array[i + 1];
        }
        count--;
    }
}

