def number_of_ways(amount, coins):
    dp = [[0 for x in range(amount+1)] for x in range(len(coins))] 

    for i in range(len(dp)): 
        dp[i][0] = 1

    for i in range(len(dp)): 
        for j in range(1, amount + 1): 
            if coins[i] > j: 
                if i - 1 < 0: 
                    dp[i][j] = 0
                else: 
                    dp[i][j] = dp[i - 1][j] 
            else: 
                if i - 1 < 0: 
                    dp[i][j] = 1
                else: 
                    dp[i][j] = dp[i][j - coins[i]] + dp[i - 1][j] 

    return dp[len(coins) - 1][amount] 

