def construct_polynomial(input_str):
    parts = input_str.split("+")

    coefficients = []
    for part in parts:
        try:
            coefficient = int(part)
        except:
            coefficient = 1

        coefficients.append(coefficient)


    def polynomial(x):
        output = 0
        for i, coeff in enumerate(coefficients):
            output += coeff * x**i
        return output

    return polynomial

