const lowestCommonAncestor = (root , n1, n2) => {
 if(!root) return null;

 if (root.data == n1 || root.data == n2) return root;

 let left = lowestCommonAncestor(root.left, n1, n2);
 let right = lowestCommonAncestor(root.right, n1, n2);

 // If both of the above calls return Non-null, then one key
 // is present in once subtree and other is present in other,
 // So this node is the LCA
 if (left && right) return root;

 // Otherwise check if left subtree or right subtree is LCA
 return (left != null) ? left : right;
}

#include <stdio.h>

struct Heap {
 int size;
 int capacity;
 int *arr;
};

struct Heap * createHeap(int capacity) {
 struct Heap *h = (struct Heap *)malloc(sizeof(struct Heap));
 h->size = 0;
 h->capacity = capacity;
 h->arr = (int *)malloc(sizeof(int) * h->capacity);
 return h;
}

void minHeapify(struct Heap *h, int i) {
 int l = 2 * i + 1;
 int r = 2 * i + 2;
 int smallest = i;
 if (l < h->size && h->arr[l] < h->arr[smallest])
 smallest = l;
 if (r < h->size && h->arr[r] < h->arr[smallest])
 smallest = r;
 if (smallest != i) {
 int temp = h->arr[smallest];
 h->arr[smallest] = h->arr[i];
 h->arr[i] = temp;
 minHeapify(h, smallest);
 }
}

void buildHeap(struct Heap *h, int arr[], int n) {
 int i;
 if (h == NULL)
 return;
 while (n > h->capacity) {
 h->capacity *= 2;
 h->arr = (int *)realloc(h->arr, sizeof(int) * (h->capacity));
 }
 for (i = 0; i < n; i++)
 h->arr[i] = arr[i];
 h->size = n;
 for (int i = (n - 1) / 2; i >= 0; --i)
 minHeapify(h, i);
}

int main()
{
 int arr[] = {8, 7, 6, 5, 4, 3, 2, 1};
 int n = sizeof(arr) / sizeof(arr[0]);
 struct Heap *h = createHeap(n);
 buildHeap(h, arr, n);
 return 0;
}

