class MyString {
    Node *head;

    MyString() {
        head = NULL;
    }

    MyString(String str) {
        head = NULL;
        for (int i=str.length()-1; i>=0; --i) {
            insertAtHead(str[i]);
        }
    }

    void insertAtHead(char ch) {
        Node *new_node = new Node(ch);
        new_node->next = head;
        if (head != NULL) {
            head->prev = new_node;
        }
        head = new_node;
