def LIS(arr):
    n = len(arr)
    lis = [1]*n

    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i] and lis[i]< lis[j] + 1 :
                lis[i] = lis[j]+1

    longest = 0
    for i in range(n):
        longest = max(longest,lis[i])

    return longest

