def kthSmallestElement(arr, k):
    priority_queue = []
    # insert elements one by one
    for el in arr:
        heapq.heappush(priority_queue, el) 

    # pop first k-1 elements from the queue
    for _ in range(k-1):
        heapq.heappop(priority_queue)

    # get the k-th smallest element
    return heapq.heappop(priority_queue)

