    j = 0
    max_len = 0
    window_chars = {}

    for i in range(len(string)): 
        window_chars[string[i]] = window_chars.get(string[i],0) + 1

        while len(window_chars) > k: 
            window_chars[string[j]] -= 1
            if window_chars[string[j]] == 0: 
                del window_chars[string[j]] 
