// Backtracking Algorithm
solveSudoku(board, n) {  
    // step 1: Find a cell with no value
    let r = -1, c = -1;
    for (let i=0; i<n; i++) { 
        for (let j=0; j<n; j++) { 
            if (board[i][j] == 0) { 
                r = i; 
                c = j; 
                break; 
            } 
        } 
        if (r != -1) { 
            break; 
        } 
    } 

    //step 2: No unassigned position is found, puzzle solved
    if (r == -1 && c == -1) { 
        return true; 
    } 

    //step 3: Try all numbers from 1 to n
    for (let num = 1; num <=n; num++) {
        if (canPlace(board, r, c, num)) { 
            // Assign it
            board[r][c] = num; 

            // Move forward and check next row and col
            if (solveSudoku(board, n)) { 
                return true; 
            } else { 

                // failure, unmake & try again
                board[r][c] = 0;
            } 
        } 
    } 
    return false; 
}

