"""
Implement the Bubble Sort algorithm for sorting an array of integers
"""

def bubble_sort(lst):
    # iterate over the list
    for i in range(len(lst)):
        # bubbles the highest number to the end
        for j in range(len(lst)-1):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
    return lst

