using namespace std; 

void dfs(vector<vector<int>>& A, int i, int j) {
    A[i][j] = 0; 

    if (i+1 < A.size() && A[i+1][j] == 1) { 
        dfs(A, i+1, j); 
    }
    if (i-1 >= 0 && A[i-1][j] == 1) { 
        dfs(A, i-1, j); 
    }
    if (j+1 < A[i].size() && A[i][j+1] == 1) { 
        dfs(A, i, j+1); 
    }
    if (j-1 >= 0 && A[i][j-1] == 1) { 
        dfs(A, i, j-1); 
    } 
} 

int countIslands(vector<vector<int>>& A) { 
    int count = 0;

    for (int i = 0; i < A.size(); i++) { 
        for (int j = 0; j < A[0].size(); j++) { 
            if (A[i][j] == 1) { 
                dfs(A, i, j); 
                ++count; 
            } 
        } 
    } 
    return count;
}

