        mid = len(arr)//2
        L = arr[:mid] 
        R = arr[mid:] 

        while len(L) > 1 and len(R) > 1:
            if L[0] < R[0]: 
                arr[0] = L[0] 
                L.pop(0)
            else: 
                arr[0] = R[0] 
                R.pop(0)
            arr.pop(0)

