def detect_fraud(transactions):
    # Record normal spending patterns
    normal_spend_hist = {}
    for transaction in transactions:
        account_num = transaction["account_num"]
        amount = transaction["amount"]
        if account_num not in normal_spend_hist:
            normal_spend_hist[account_num] = []
        normal_spend_hist[account_num].append(amount)

    # Iterate through transactions to identify outliers
    for transaction in transactions:
        account_num = transaction["account_num"]
        amount = transaction["amount"]
        if amount > 3 * mean(normal_spend_hist[account_num]):
            # flag as potential fraud
            potential_fraud = transaction

    return potential_fraud

