import java.util.Arrays; 
import java.util.Comparator; 

public class ClosestPair {

 // comparator class to compare two points on x-coordinate
 public static class xCompare implements Comparator<Point> 
 { 
     public int compare(Point p, Point q) 
     { 
         if (p.x < q.x) return -1; 
         if (p.x == q.x) return 0; 
         return 1; 
     } 
 } 

 // distance between two points (euclidean distance)
 public static double dist(Point p1, Point p2) 
 { 
     return Math.sqrt((p1.x - p2.x)*(p1.x - p2.x) + (p1.y - p2.y)*(p1.y - p2.y)); 
 } 

 // finds closest pair of points in a two-dimensional plane
 public static Point[] findClosestPoints(Point[] points) 
 { 
     int i, j;
     int n = points.length; 

     // sort point according x-coordinates 
     Arrays.sort(points, new xCompare()); 

     // start with two points 
     double min_dist = dist(points[0], points[1]); 
     Point[] closest = new Point[2]; 
     closest[0] = points[0]; 
     closest[1] = points[1]; 

     // pick two points one after another and 
     // calculate their distance
     i = 0; 
     for (j = 1; j < n; j++) 
     { 
         double d = dist(points[i], points[j]); 

         // update min_dist and closest points 
         if (d < min_dist) 
         { 
             min_dist = d; 
             closest[0] = points[i]; 
             closest[1] = points[j]; 
         } 
     } 

     // return closest pair 
     return closest; 
 } 

 public static void main(String[] args) 
 { 
