def prime_numbers_in_range(start, end):
    prime_numbers = []
    for num in range(start, end + 1):
        if num > 1:
            is_prime = True
            for i in range(2, num):
                if num % i == 0:
                    is_prime = False
            if is_prime:
                prime_numbers.append(num)
