}

public class Stack {
  private Object[] arr;
  private int top;

  public Stack(int size) {
   this.arr = new Object[size];
   this.top = -1;
  }

  public Object pop() {
   if (this.top < 0) {
    // Stack is empty
    return null;
   }

   Object value = this.arr[this.top];
   this.top--;
   return value;
  }

  public void push(Object item) {
   this.top++;
   this.arr[this.top] = item;
  }

  public Object peek() {
   if (this.top < 0) {
    // Stack is empty
    return null;
   }

   return this.arr[this.top];
  }
}

def eval_str(str):
    stack = []
    for token in str.split():
        # process tokens
        if token == "+":
            op2 = stack.pop()
            op1 = stack.pop()
            stack.append(op1 + op2)
        elif token == "-":
            op2 = stack.pop()
            op1 = stack.pop()
            stack.append(op1 - op2)
        elif token == "*":
            op2 = stack.pop()
            op1 = stack.pop()
            stack.append(op1 * op2)
        elif token == "/":
            op2 = stack.pop()
            op1 = stack.pop()
            stack.append(op1 / op2)
        else:
            stack.append(int(token))

    return stack.pop()

