#define MAX_TABLE_SIZE 100

// Data structure to store a hash table entry
typedef struct
{
 char key[50];
 int value;
} HashEntry;

// Hash table
HashEntry *hashTable[MAX_TABLE_SIZE]; 

// calculate hash from given string
unsigned int hash(char *str)
{
 unsigned int hash = 0;
 while (*str)
 hash += *str++;
 hash %= MAX_TABLE_SIZE;
 return hash;
}

// insert a key-value pair into a hash table
void insert(char *key, int value)
{
 // obtain hash code from key
 unsigned int pos = hash(key);

 // create entry
 HashEntry *entry = (HashEntry*) malloc(sizeof(HashEntry));

 // set values
 strcpy(entry->key, key);
 entry->value = value;

 // insert into the table
 hashTable[pos] = entry;
}

// search for a key in hash table and return its corresponding value
int search(char *key)
{
 // obtain hash code from key
 unsigned int pos = hash(key);

 // return corresponding value from table
 return hashTable[pos]->value;
}

// delete entry from hash table
void delete(char *key)
{
 // obtain hash code from key
 unsigned int pos = hash(key);

 // remove entry from table
 free(hashTable[pos]);
}

