public class Palindrome {

  static void findPalindrome(String str) {
    int n = str.length();
    ArrayList<String> allPalindrome = new ArrayList<String>();
    for (int i = 0; i < n; i++) {
      String palindrome = Character.toString(str.charAt(i));
      allPalindrome.add(palindrome);
      for (int j = i + 1; j < n; j++) {
        palindrome += Character.toString(str.charAt(j));
        if (palindrome.equals(reverseString(palindrome))) {
          allPalindrome.add(palindrome);
        }
      }
    }
    for (int i = 0; i < allPalindrome.size(); i++) {
      System.out.print(allPalindrome.get(i) + " ");
    }
  }

  static String reverseString(String str) {
    String reverse = "";
    for (int i = str.length() - 1; i >= 0; i--) {
      reverse = reverse + str.charAt(i);
    }
    return reverse;
  }

  public static void main(String[] args) {
    String str = "malaysia";
    findPalindrome(str);
  }
}

