def check_strings_recursive(str1, str2):
    """
    Check if the two input strings are equal or not using recursion
    """
    # Base cases
    if not str1 and not str2:
        return True
    if not str1 or not str2:
        return False

    if str1[0] != str2[0]:
        return False

    # Recursive part
    remaining_str1 = str1[1:]
    remaining_str2 = str2[1:]
    return check_strings_recursive(remaining_str1, remaining_str2)

