public static String longestSubstring(String input) {
    // This will hold the longest substring found
    String longestSubstring = "";

    // This will track the current substring
    String currentSubstring = "";

    // This will keep track of seen characters in a hash set (no duplicates)
    Set<Character> seenCharacters = new HashSet<>();

    // Loop through the input string
    for (int i = 0; i < input.length(); i++) {
        char currentChar = input.charAt(i);

        // If the character has already been seen
        // Reset the currentSubstring
        if (seenCharacters.contains(currentChar)) {
            longestSubstring = currentSubstring.length() > longestSubstring.length() ? currentSubstring : longestSubstring;

            seenCharacters.clear();
            currentSubstring = "";
        }

        // If the character hasn't been seen, add it to the seen characters
        // and add it to the current substring
        seenCharacters.add(currentChar);
        currentSubstring += currentChar;
    }

    // Check if the current substring is longer than the longestSubstring
    longestSubstring = currentSubstring.length() > longestSubstring.length() ? currentSubstring : longestSubstring;

    return longestSubstring;
}

