// Function to find the minimum value 
// in the given array 
int minValue(int array[], int n) 
{ 
    // Initialize the minimum element 
    int minimum = array[0]; 

    // Run the loop till the end of array 
    for (int i = 1; i < n; i++) 
    { 
        // Compare the current element with 
        // the minimum element 
        if (array[i] < minimum) 
            minimum = array[i]; 
    } 

    // Return the minimum element 
    return minimum; 
} 

