def create_expression_tree(string):
    stack = []
    for char in string:
        if char not in "+-/*":
            stack.append(Node(char))
        else:
            node = Node(char)
            node.right = stack.pop() 
            node.left = stack.pop()
            stack.append(node)
    return stack.pop()

