public static String caesarCipher(String sentence, int key) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < sentence.length(); i++) {
        char ch = sentence.charAt(i);
        if (Character.isLetter(ch)) {
            char c = (char) (ch + key);
            if (Character.isUpperCase(ch) && c > 'Z'
                    || Character.isLowerCase(ch) && c > 'z') {
                c = (char) (ch - (26 - key));
            }
            sb.append(c);
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

