void printPascalTriangle(int N) 
{ 
A triangle can be printed like this
    // Iterate through rows 
    for (int line = 1; line <= N; line++) 
    { 

        // Initialize character  
        // which we will use to print  
        int C = 1; 

        // Print space in triangle pattern 
        for (int i = 1; i <= (N - line); i++)  
            cout << "  "; 

        // Print value in triangle pattern 
        for (int i = 1; i <= line; i++)  
        { 
            // Print character "C" 
            cout << C << "   "; 
        } 

        // Update value of "C" 
        // in next iteration 
        C = C * (line - i) / i;  

