    public static void sort(int[] input) {
        quickSort(input, 0, input.length - 1);
    }

    private static void quickSort(int[] input, int low, int high) {

        int pivotIndex = partition(input, low, high);

        if (low < pivotIndex) {
            quickSort(input, low, pivotIndex - 1);
        }

        if (pivotIndex < high) {
            quickSort(input, pivotIndex + 1, high);
        }
    }

    private static int partition(int[] input, int low, int high) {
        int pivotValue = input[high];
        int j = low;
        int i = low;

        while (i < high) {
            if (input[i] <= pivotValue) {
                int temporaryValue = input[i];
                input[i] = input[j];
                input[j] = temporaryValue;
                j++;
            }
            i++;
        }

        int temp = input[j];
        input[j] = input[high];
        input[high] = temp;

        return j;
    }
