def shortestPath(start, end, graph): 

    # use a queue to store paths
    queue = []
    queue.append([start])

    # use a set to store visited vertices
    visited = set()

    while queue: 
        # get the first path from the queue 
        path = queue.pop(0)

        # get the last node from the path
        node = path[-1]

        # path found
        if node == end:
            return path
        # traverse to all the nearest nodes
        for neighbour in graph[node]:
            if neighbour not in visited:
                newPath = list(path)
                newPath.append(neighbour)
                queue.append(newPath)

                # mark as visited
                visited.add(neighbour)

    return None

