function lcm(num1, num2) {
    let div = 2;
    let lcm = 1;

    while (num1 >= div || num2 >= div) {
        if (num1 % div === 0 && num2 % div === 0) {
            lcm = lcm * div;
            num1 = num1 / div;
            num2 = num2 / div;
        } else if (num1 % div === 0) {
            lcm = lcm * div;
            num1 = num1 / div;
        } else if (num2 % div === 0) {
            lcm = lcm * div;
            num2 = num2 / div;
        } else {
            div++;
        }
    }

    return lcm;
}

