def sort_array(arr):
    if not arr:
        return arr
    else:
        pivot = arr[-1]
        left_arr = []
        right_arr = []
        for value in arr[:-1]:
            if value >= pivot:
                right_arr.append(value)
            else:
                left_arr.append(value)
        return merge_sort(left_arr) + [pivot] + merge_sort(right_arr)

def merge_sort(arr):
    # Base case
    if len(arr) <= 1:
        return arr

    # Recursive case
    first_half = merge_sort(arr[:(len(arr)//2)])
    second_half = merge_sort(arr[(len(arr)//2):])

    # Merge
    result = []
    i, j = 0, 0
    while (i < len(first_half)) and (j < len(second_half)):
        if first_half[i] < second_half[j]:
            result.append(first_half[i])
            i += 1
        else:
            result.append(second_half[j])
            j += 1
    while i < len(first_half):
        result.append(first_half[i])
        i += 1
    while j < len(second_half):
        result.append(second_half[j])
        j += 1

    return result

