// Returns a String of given length with random alphanumeric characters
fn random_string(length: usize) -> String {
 let alphanumeric: String = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789".into();
 let mut result = String::with_capacity(length);

 let mut rng = thread_rng();
 for _ in 0..length {
  let index: usize = rng.gen_range(0, alphanumeric.len());
  result.push(alphanumeric.chars().nth(index).unwrap());
 }

 return result;
}

