function alphabeticalSort(arr) {
  // Iterate over the array and compare each item
  for (let i = 0; i < arr.length; i++) {
    for (let j = i +1; j < arr.length; j++) {
      // Sort in alphabetical order
      if (arr[i] > arr[j]) {
        // Swap the two items
        let temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
      }
    }
  }
  return arr;
}

