# using Exponential Smoothing
import numpy as np 
def exponential_smoothing(data, alpha):
    forecast = np.zeros(data.shape[0] + 3)
    forecast[0] = data[0]
    for i in range(1, data.shape[0]):
        forecast[i] = alpha * data[i-1] + (1-alpha) * forecast[i-1]
    for i in range(data.shape[0], data.shape[0]+3):
        forecast[i] = alpha * forecast[i-1] + (1-alpha) * forecast[i-2]
    return forecast

