}

// Function to search a given node in a linked list
int search(struct Node* head, int data)
{
 // Iterate over the linked list and search for the given node
 while (head != NULL)
 {
  if (head->data == data)
  {
   return 1;
  }

  head = head->next; 
 }

 return 0;
}

