def findMode(arr):
    mode_dict = dict()
    for num in arr:
        if num not in mode_dict:
            mode_dict[num] = 1
        else:
            mode_dict[num] += 1
    max_count = 0
    mode = 0
    for key, value in mode_dict.items():
        if value > max_count:
            max_count = value
            mode = key

    return mode

