public static String getLargestPalindrome(String myString) {
    int maxLength = 0;
    String returnStr = "";
    String temp;

    //Loop through each character in the string
    for (int i = 0; i < myString.length(); i++) {
        //Loop through each possible substring starting at the current index
        for (int j = i + 1; j <= myString.length(); j++) {
            temp = myString.substring(i, j);
            //Check if substring is a palindrome
            if (isPalindrome(temp)) {
                //Check if length is bigger than current record
                if (temp.length() > maxLength) {
                    returnStr = temp;
                    maxLength = temp.length();
                }
            }
        }
    }

    return returnStr;
}

