function levenshteinDistance(str1, str2) {
    let m = str1.length;
    let n = str2.length;
    let dp = new Array(m + 1).fill().map(() => new Array(n + 1)); 

    for (let i = 0; i <= m; i++) 
        dp[i][0] = i; 

    for (let j = 0; j <= n; j++) 
        dp[0][j] = j;

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) { 
            if (str1[i - 1] == str2[j - 1]) 
                dp[i][j] = dp[i - 1][j - 1]; 
            else 
                dp[i][j] = 1 + Math.min(dp[i][j - 1],  
                                       dp[i - 1][j],  
                                       dp[i - 1][j - 1]); 
        } 
    } 
    return dp[m][n];
}

