def LCS(str1, str2):
    m = len(str1)
    n = len(str2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m):
        for j in range(n):
            if str1[i] == str2[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i][j + 1], dp[i + 1][j])
    longest = ""
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if i == 1 or j == 1:
                if dp[i][j] > 0:
                    longest += str1[i-1]
            elif dp[i][j] > dp[i-1][j-1]:
                if dp[i][j] > 0:
                    longest += str1[i-1]
    return longest

