def getLCS(s1, s2):
    n = len(s1)
    m = len(s2)
    # Create 2D array to store results of subproblems
    L = [[0 for i in range(m+1)] for j in range(n+1)]
    LCS = ""
    for i in range(1, n+1):
        for j in range(1, m+1): 
            if s1[i-1] == s2[j-1]:
                L[i][j] = L[i-1][j-1]+1
            else:
                L[i][j] = max(L[i-1][j], L[i][j-1])
    # Longest Common Subsequence
    index = L[n][m]
    # Create string
    while index > 0:
        if s1[n-1] == s2[m-1]:
            LCS += s1[n-1] 
            n-=1
            m-=1
            index -= 1
        elif L[n-1][m] > L[n][m-1]:
            n-=1
        else:
            m -= 1
    return LCS

