def caesar_cipher(string, shift):
    cipher = ''
    for char in string:
        if char.isalpha():
            code = ord(char)
            code += shift

            if char.isupper():
                if code > ord('Z'):
                    code -= 26
                elif code < ord('A'):
                    code += 26
            elif char.islower():
                if code > ord('z'):
                    code -= 26
                elif code < ord('a'):
                    code += 26

            cipher += chr(code)
        else:
            cipher += char

    return cipher

