def detect_pattern(stream):
    if len(stream) <= 1:
        return "Unknown"

    # Initialize count variable
    count = 0

    # Iterate over the stream
    for i in range(len(stream)-1):
        # Count the number of increasing or decreasing pairs in the stream
        if stream[i+1] == stream[i] + 1:
            count += 1
        elif stream[i+1] == stream[i] - 1:
            count -= 1

    # Return appropriate result
    if count > 0:
        return "Increasing"
    elif count < 0:
        return "Decreasing"
    else:
        return "Unknown"

