def sort_list(nums, desc=False):
  ascending = True
  if desc:
    ascending = False

  for i in range(len(nums) - 1):
    min_idx = i
    for j in range(i+1, len(nums)):
      if ascending:
        if nums[j] < nums[min_idx]:
          min_idx = j
      else:
        if nums[j] > nums[min_idx]:
          min_idx = j
    nums[min_idx], nums[i] = nums[i], nums[min_idx] 
  return nums

