def find_longest_inc_sequence(arr):
    # This function finds the longest consecutive increasing sequence in an array of integers.
    max_length = 1
    current_length = 1
    # Start from the second element in the array
    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            current_length += 1
            if max_length < current_length:
                max_length = current_length
        else:
            # If the current number is not greater than the previous number, reset the current length
            current_length = 1
    return max_length

