bool validatePassword(char *password){
    int digitCount = 0;
    int upperCaseCount = 0;
    int lowerCaseCount = 0;
    int otherCount = 0;
    int i;

    for (i = 0; password[i] != '\0';i++)
    {
        char currentChar = password[i];

        if(isdigit(currentChar)){
            digitCount++;
        } else if(isupper(currentChar)){
            upperCaseCount++;
        } else if(islower(currentChar)){
            lowerCaseCount++;
        } else {
            otherCount++;
        }
    }

    if(digitCount >= 1 && upperCaseCount >= 1 && lowerCaseCount >= 1 && otherCount >= 1){
        return true;
    }

    return false;
}

