int maxSubArray(int arr[], int n) 
{ 
    // Initialize maximum sum 
    int maxSum = arr[0]; 

    // Consider all subarrays one by one 
    for (int i = 0; i < n; i++) 
    { 
        // Initialize current sum 
        int currSum = arr[i]; 

        // Check all subarrays that start with arr[i] 
        for (int j = i+1; j < n; j++) 
        { 
            // Add current element to currSum 
            currSum += arr[j]; 

            // Update maximum sum 
            maxSum = max(maxSum, currSum); 
        } 
    } 

    return maxSum; 
} 

