function reverseList(head) { 
    let prev = null; 
    let current = head; 
    let next = null;  
    while (current != null) { 
        // Store next 
        next = current.next; 

        // Reverse current node's pointer 
        current.next = prev; 

        // Move pointers one position ahead. 
        prev = current; 
        current = next; 
    } 
    head = prev; 
    return head; 
}

