                board[i][j] = player
                score = minimax(board, 0, False)
                board[i][j] = 0

                if score > best_score:
                    moves = [(i, j)] 
                    best_score = score
                elif score == best_score:
                    moves.append((i,j))

    return random.choice(moves)

# Minimax algorithm
def minimax(board, depth, isMaximizing):

    result = check_results(board) 

    if result is not None:
        if result == 10:
            return -10 + depth
        elif result == -10:
            return 10 - depth
        else:
            return 0

    if isMaximizing: 
        best_score = -1000

        for i in range(3):
            for j in range(3):
                if board[i][j] == 0:
                    board[i][j] = 1
                    score = minimax(board, depth + 1, False)
                    board[i][j] = 0

                    best_score = max(score, best_score)

        return best_score

    else: 
        best_score = 1000

        for i in range(3):
            for j in range(3):
                if board[i][j] == 0:
                    board[i][j] = 2
                    score = minimax(board, depth + 1, True)
                    board[i][j] = 0

                    best_score = min(score, best_score)

        return best_score

# Function to check results
def check_results(board):
    # check rows 
    for i in range(3): 
        if (board[i]==[1,1,1]).all(): 
            return 10 

        if (board[i]==[2,2,2]).all(): 
            return -10 

    # check columns
    for j in range(3): 
        if (board[:,j]==[1,1,1]).all(): 
            return 10 

        if (board[:,j]==[2,2,2]).all(): 
            return -10 

    # check diagonals 
    if (board.diagonal()==[1,1,1]).all(): 
        return 10
    if (board.diagonal()==[2,2,2]).all(): 
        return -10
    if np.fliplr(board).diagonal()==[1,1,1].all(): 
        return 10
    if np.fliplr(board).diagonal()==[2,2,2].all(): 
        return -10

    # check for draw 
    if np.all(board!= 0) == True: 
        return 0

# Main function
