void createCircularList(int arr[], int n) 
{ 
    struct node *head, *p; 
    int i; 

    // Create head node
    head = (struct node *)malloc(sizeof(struct node)); 
    head->data = arr[0]; 
    head->next = head; 
    p = head; 

    // Link remaining nodes
    for (i = 1; i < n; i++) 
    { 
        struct node *temp = (struct node *)malloc(sizeof(struct node)); 
        temp->data = arr[i]; 
        temp->next = head; 

        p->next = temp; 
        p = temp; 
    } 
}

def levenshteinDistance(str1, str2):
    # Create a matrix
    matrix = [[0 for x in range(len(str2) + 1)] for x in range(len(str1) + 1)]

    # Initialize the first row and column of the matrix
    for i in range(len(str1) + 1):
        matrix[i][0] = i
    for j in range(len(str2) + 1):
        matrix[0][j] = j

    # Fill the matrix
    for i in range(1, len(str1) + 1):
        for j in range(1, len(str2) + 1):
            if str1[i-1] == str2[j-1]:
                matrix[i][j] = matrix[i-1][j-1]
            else:
                matrix[i][j] = 1 + min(matrix[i-1][j], matrix[i][j-1], matrix[i-1][j-1])

    # The bottom-right element of the matrix will contain the Levenshtein distance between the two strings
    return matrix[len(str1)][len(str2)]

