public class LongestSubstring { 

    public static int longestSubstring(String s) { 
        // set to store the elements 
        Set<Character> set = new HashSet<>(); 
        int maxLength = 0; 
        int i = 0; 
        int j = 0;

        while (i < s.length() && j < s.length()) { 
            // Check if the character already exists in the set 
            if (! set.contains(s.charAt(j))) { 
                // Add the character to the set 
                set.add(s.charAt(j)); 

                // Increment the 'j' pointer 
                j++; 

                // Update the maxLength whenever required 
                maxLength = Math.max(maxLength, j-i); 
            } 
            else { 
                // Remove the character at the 'i' pointer 
                set.remove(s.charAt(i)); 

                // Increment the 'i' pointer 
                i++; 
            } 
        } 
        return maxLength; 
    } 

    public static void main (String[] args) 
    { 
        String str = "abcabcbb";
        int result = longestSubstring(str); 
        System.out.println("The length of the longest substring without repeating characters is: {:d}".format(result));
    } 
}

