    public Matrix(int[][] inMatrix){
        this.matrix = inMatrix;
    }

    public Matrix multiply(Matrix otherMatrix){
        int rowsA = this.matrix.length;
        int columnsA = this.matrix[0].length;
        int rowsB = otherMatrix.matrix.length;
        int columnsB = otherMatrix.matrix[0].length;

        int[][] result = new int[rowsA][columnsB];

        for(int i=0; i<rowsA; i++){ 
            for(int j=0; j<columnsB; j++){
                for(int k=0; k<columnsA; k++){
                    result[i][j] += this.matrix[i][k] * otherMatrix.matrix[k][j]; 
                }
            }
        }
        return new Matrix(result);
    }
}

