public class Stack {
   private int[] data;
   private int size; 

   public Stack(int size) {
       this.data = new int[size];
       this.size = 0;
   }

   public void push(int element) {
       this.data[this.size] = element;
       this.size += 1;
   }

   public int pop() {
       if (this.size == 0) {
           throw new IllegalStateException("Stack is empty");
       }

       int element = this.data[this.size - 1]; 
       this.size -= 1;
       return element;
   }

   public boolean isEmpty() {
       return this.size == 0;
   }
}

