def longest_common_substring(str1, str2):
    len1 = len(str1)
    len2 = len(str2)

    dp = [[0 for _ in range(len2 + 1)] for _ in range(len1 + 1)]
    max_len = 0
    for i in range(len1):
        for j in range(len2):
            if str1[i] == str2[j]:
