pub fn remove_all_occurrences<T: PartialEq + Clone>(list: &mut LinkedList<T>, element: T) {
    let mut node = list.head_mut();
    while let Some(cur) = node {
        if cur.elem == element {
            let next = cur.next.take();
            list.remove(cur);
            node = next;
        } else {
            node = cur.next.as_mut();
        }
    } 
}

