 String encodedString = "";
 for (int i = 0; i < str.length(); i++) {
 char ch = str.charAt(i);
 if (Character.isLetter(ch)) {
 if (Character.isLowerCase(ch)) {
 char c = (char)(ch + 3);
 if (c > 'z') {
 encodedString += (char)(ch - 23);
 } else {
 encodedString += c;
 }
 } else if (Character.isUpperCase(ch)) {
 char c = (char)(ch + 3);
 if (c > 'Z') {
