// Function to remove a node from a linked list  
 void removeNode(struct Node *head, int key)  
 {  
   // Store head node  
   struct Node* temp = head;  

   // If head node itself holds the key to be deleted  
   if (temp != NULL && temp->data == key)  
   {  
       head = temp->next;   // Changed head  
       free(temp);           // free old head  
       return;  
   }  

   // Search for the key to be deleted, keep track of the  
   // previous node as we need to change 'prev->next'  
   while (temp != NULL && temp->data != key)  
   {  
       prev = temp;  
       temp = temp->next;  
   }  

   // If key was not present in linked list  
   if (temp == NULL) return;  

   // Unlink the node from linked list  
   prev->next = temp->next;  

   free(temp);  // Free memory  
}

def plagiarism_detection(doc1, doc2):
    # Count the total number of characters in both doc1 and doc2
    l1 = len(doc1)
    l2 = len(doc2)

    # Create a dictionary to store the frequency of each word in doc1 and doc2
    freq1 = {}
    freq2 = {}

    # Count the frequency of each word in doc1
    for word in doc1.split():
        if word not in freq1:
            freq1[word] = 1
        else:
            freq1[word] += 1

    # Count the frequency of each word in doc2
    for word in doc2.split():
        if word not in freq2:
            freq2[word] = 1
        else:
            freq2[word] += 1

    # Calculate the similarity score
    score = 0
    for word in freq1:
        if word in freq2:
            if freq1[word] > 0 and freq2[word] > 0:
                score += freq1[word]*freq2[word] 

    # Normalize the score
    if (l1*l2) == 0:
        score = 0
    else:
        score = (2*score) / (l1*l2)

    return score

