def CaesarCipher(text): 
    result = "" 
    for i in range(len(text)): 
        char = text[i] 
        if (char.isupper()): 
            result += chr((ord(char) + 3-65) % 26 + 65)
        else: 
            result += chr((ord(char) + 3 - 97) % 26 + 97) 
    return result

