public static void permute(List<Integer> arr, int l, int r) {
    // Base case
    if (l == r) {
        System.out.println(arr);
    } else {
        for (int i = l; i <= r; i++) {
            // Swap arr[l] and arr[i]
            Collections.swap(arr, l, i);

            // Recursively call permutation on arr, l+1 and r
            permute(arr, l+1, r);

            // Swap arr[l] and arr[i] back 
            Collections.swap(arr, l, i);
        }
    }
}

