function binarySearch(array, value) {
    let start = 0;
    let end = array.length - 1;

    while (start <= end) {
        const middle = Math.floor((start + end) / 2);
        const curValue = array[middle]

        if (curValue === value) { 
            return true;
        } else if (value < curValue) {
            end = middle - 1;
        } else {
            start = middle + 1;
        }
    }
    return false;
}

