"""
A simple implementation of a decision tree classifier
"""

class Node():
    """"A node on a decision tree"""

    def __init__(self, attr_name, class_label):
        self.attr_name = attr_name
        self.class_label = class_label
        self.children = []

    def add_children(self, node_list):
        self.children.extend(node_list)

def classify(instance, root_node):
    """Classify an instance using the decision tree"""
    if root_node.children == []:
        # leaf node
        return root_node.class_label

    else:
        # internal node
        attr_value = instance[root_node.attr_name]
        for node in root_node.children:
            if node.attr_name == attr_value:
                return classify(instance, node)

