import numpy as np

# Representing the board as a 3x3 array. 
# Empty spaces are represented with 0, X with 1 and O with -1
board = np.zeros((3,3))

# Function to check if the game has ended or not
def check(board):
    # Check for horizontal, vertical and diagonal lines
    for i in range(3):
        # Check for horizontal lines
        if np.sum(board[i,:]) == 3 or np.sum(board[i,:]) == -3:
            return board[i,0]
        # Check for vertical lines
        if np.sum(board[:,i]) == 3 or np.sum(board[:,i]) == -3:
            return board[0,i]
    # Check for the left diagonal
    if np.sum(np.diag(board)) == 3 or np.sum(np.diag(board)) == -3:
        return board[1,1]
    # Check for the right diagonal
    if np.sum(np.diag(np.fliplr(board))) == 3 or np.sum(np.diag(np.fliplr(board))) == -3:
        return board[1,1]
    # If none of these conditions are satisfied, the game is not over
    return 0

# Function to get the best move for the AI
def best_move(board, mark):
    # Checking all possible boards
    for i in range(3):
        for j in range(3):
            if board[i,j] == 0:
                board[i,j] = mark    # Making the move
                if check(board) == mark:
                    return (i,j)
                else:
                    board[i,j] = 0    # Resetting the move

# Function to play game
def play(board):
    mark = 1
    # While game is not over
    while(check(board) == 0):
        # Get best move for AI
        (i,j) = best_move(board, mark)
        board[i,j] = mark
        # If game is not over
        if check(board) == 0:
            # Get user input
            x = int(input("Enter row: "))
            y = int(input("Enter col: "))
            # Make user move
            if board[x,y] == 0:
                board[x,y] = -1
            else:
                print("Invalid move")
        else:
            break
        # Flip turn
        mark *= -1
    # Game is over
    print ("Game Over")
    # Print the board
    print(board)
    # Print the winner
    result = check(board)
    if result == 1:
        print("AI wins")
    elif result == -1:
        print("You win")
    else:
        print("Draw")

# Calling the play function
