public class Substring {
    public static String getMaxLengthSubstring(String input) {
        char[] arr = input.toCharArray();
        int st = 0;
        int end = 0;
        int max_len = Integer.MIN_VALUE;
        int cur_len = 1;
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] != arr[i - 1]) {
                cur_len++;
            }
            else {
                cur_len = 1;
            }
            if (cur_len > max_len) {
                max_len = cur_len;
                end = i;
            }
        }
        st = end - max_len + 1;
        return input.substring(st, end + 1);
    }

