public class OptimizeExpression {
  private static final int VAR_NUM = 5;
  private static final int MAX_ITER = 1_000_000;

  // define the expression
  private static int expression(int v1, int v2, int v3, int v4, int v5) {
    return (v1 - 2 * v2 + 3 * v3 - 4 * v4 + 5 * v5) * (v1 + 2 * v2 - 3 * v3 + 4 * v4 - 5 * v5);
  }

  public static void main(String[] args) {
    int max = Integer.MIN_VALUE;
    int[] maxX = new int[VAR_NUM];

    // try every possible combination of the 5 variables
    for (int v1 = 0; v1 < VAR_NUM; v1++) {
      for (int v2 = 0; v2 < VAR_NUM; v2++) {
        for (int v3 = 0; v3 < VAR_NUM; v3++) {
          for (int v4 = 0; v4 < VAR_NUM; v4++) {
            for (int v5 = 0; v5 < VAR_NUM; v5++) {
              int result = expression(v1, v2, v3, v4, v5);
              if (result > max) {
                max = result;
                maxX[0] = v1;
                maxX[1] = v2;
                maxX[2] = v3;
                maxX[3] = v4;
                maxX[4] = v5;
              }
            }
          }
        }
