 }

 // Function to insert a new element to the heap
 public void insert(int element) {
  if (heapSize == heap.length - 1) {
   throw new IndexOutOfBoundsException("Overflow Exception");
  }
  heap[++heapSize] = element;
  int current = heapSize;
  while (current > 1 && heap[current] < heap[parent(current)]) {
   swap(current, parent(current));
   current = parent(current);
  }
 }

 // Function to remove the minimum element from the heap
 public int remove() {
  if (isEmpty()) {
   throw new NoSuchElementException("Underflow Exception");
  }
  int keyItem = heap[1];
  delete(1);
  return keyItem;
 }

 // Function to remove an element from the heap
 public int delete(int position) {
  if (isEmpty()) {
   throw new NoSuchElementException("Underflow Exception");
  }
  int keyItem = heap[position];
  heap[position] = heap[heapSize--];
  heapify(position);
  return keyItem;
 }

 private void heapify(int position) {
  if (isLeaf(position))
   return;

  if (heap[position] > heap[leftChild(position)]
   || heap[position] > heap[rightChild(position)]) {

   if (heap[rightChild(position)]>=heap[leftChild(position)]) {
    swap(position, leftChild(position));
    heapify(leftChild(position));
   }else {
    swap(position, rightChild(position));
    heapify(rightChild(position));
   }
  }
 }

 // Function to check if heap is empty
 public boolean isEmpty() {
  return heapSize == 0;
 }

 // Function to check if heap is full
 public boolean isFull() {
  return heapSize == heap.length;
 }

 // Function to check if a node is leaf
 private boolean isLeaf(int position) {
  if (position > (heapSize / 2) && position <= heapSize) {
   return true;
  }
  return false;
 }

 // Function to get left child of node
 private int leftChild(int position) {
  return position * 2;
 }

 // Function to get right child of node
 private int rightChild(int position) {
  return (position * 2) + 1;
 }

 // Function to get parent of node
 private int parent(int position) {
  return position / 2;
 }

 // Function to swap two nodes
 private void swap(int fpos, int spos) {
  int tmp;
  tmp = heap[fpos];
  heap[fpos] = heap[spos];
  heap[spos] = tmp;
 }
}

