class Board { 
    // 3x3 board 
    char board[][]; 

    public Board() { 
        board = new char[3][3]; 

        // Setting the board with empty values 
        // Initially the board should be  
        // empty when created 
        for (int i = 0; i < 3; i++) { 
            for (int j = 0; j < 3; j++) { 
                board[i][j] = '_'; 
            } 
        } 
    } 

    // Function to print board at any  
    // instance 
    public void printBoard() 
    { 
        System.out.println("-------------"); 
        for (int i = 0; i < 3; i++) { 
            System.out.print("| "); 
            for (int j = 0; j < 3; j++) { 
                System.out.print(board[i][j] + " | "); 
            } 
            System.out.println(); 
            System.out.println("-------------"); 
        } 
    } 

    // Main logic to check whether  
    // any of the players wins 
    public boolean checkWin(char val) 
    { 

        // Checking if any of the  
        // row has same value 
        for (int i = 0; i < 3; i++) { 
            if (board[i][0] == val 
                && board[i][1] == val 
                && board[i][2] == val) { 

                return true; 
            } 
        } 

        // Checking if any of the 
        // column has same value. 
        for (int i = 0; i < 3; i++) { 
            if (board[0][i] == val 
                && board[1][i] == val 
                && board[2][i] == val) { 

                return true; 
            } 
        } 

        // Checking left-right diagonal 
        if (board[0][0] == val 
            && board[1][1] == val 
            && board[2][2] == val) { 
            return true; 
        } 

        // Checking right-left diagonal 
        if (board[2][0] == val 
            && board[1][1] == val 
            && board[0][2] == val) { 
            return true; 
        } 
        return false; 
    } 
} 

