def prime_factors(n): 
    # Create list to store prime factors 
    prime_factors = []

    # Store all prime factors of n 
    for i in range(2, n+1): 
        # Check if i is divisible by any 
        # number between 2 and i 
        for j in range(2, i): 
            if(i % j == 0): 
                break

        # If i is Prime factor
        if(j == i-1): 
            prime_factors.append(i)

    return prime_factors

