struct LRU<Key: Hashable, Value: Hashable> {

    // Items in an LRU Cache
    private var items: [Key: Value] = [:]
    private var keys: [Key] = []

    // Maximum amount of items 
    private let size: Int

    // Initializes an LRU Cache
    init(size: Int) {
        self.size = size
    }

    // Add a new item to the cache
    mutating func add(key: Key, value: Value) {
        items[key] = value
        keys.append(key)
        if(keys.count > size) {
            keys.removeFirst()
        }
    }

    // Get item from the cache
    func get(key: Key) -> Value? {
        guard let index = keys.firstIndex(of: key) else {
            return nil
        }

        keys.remove(at: index)
        keys.append(key)
        return items[key]
    }
}

