    for row in range(9):
        for col in range(9):
            if grid[row][col] == 0: 
                for n in range(1,10): 
                    if possible(grid, row, col, n): 
                        grid[row][col] = n 
                        if solveSudokuProblem(grid): 
                            return True
                        else: 
                            grid[row][col] = 0  
                return False
    return True

