void removeDuplicates(int arr[], int n) 
{ 
    // Pick elements one by one 
    for (int i = 0; i < n; i++) { 

        // Compare the picked element  
        // with rest of the elements 
        for (int j = i + 1; j < n; j++) { 
            if (arr[i] == arr[j]) { 

                // If any element is found  
                // which is duplicate to  
                // the picked element,  
                // then remove it 
                for (int k = j; k < n; k++)  
                    arr[k] = arr[k + 1];                 
                n--;  
                j--; 
            } 
        } 
    } 
}

