def game(player1, player2):

    #Players rotate turns
    turns = iter(player1, player2)

    #Iterate over each of the pawns
    for pawn1, pawn2 in zip(player1, player2):
        current_turn = next(turns)

        while !pawn1.position == 5 or !pawn2.position == 5:
            if current_turn == player1:
                pawn1.move()
            else:
                pawn2.move()
            #Switches turns
            current_turn = next(turns)

    #In order to win the player must have three pawns in finish line
    if player1.status == 3:
        return "Player 1 wins!"
    else:
        return "Player 2 wins!"

