int Search(int arr[], int n, int x) 
{ 
    int l=0, h=n-1; 
    while (l <= h) { 
        int mid = (l + h)/2; 
        if (x == arr[mid]) 
            return mid; 
        if (x < arr[mid]) 
            h = mid - 1; 
        else
            l = mid + 1; 
    } 
    return -1; 
