public int getLargestPrimeFactor(int n) {
  int largestPrimeFactor = 0;
  int divisor = 2;
  while (n > 1) {
   if (n % divisor == 0) {
    largestPrimeFactor = divisor;
    n = n / divisor;
   } else {
    divisor++;
   }
  }
  return largestPrimeFactor;
