public class Main {
  public static boolean isPalindrome(int n) {
    int reversed = 0;
    int original = n;

    while (n != 0) {
      int remainder = n % 10;
      reversed = reversed * 10 +  remainder;
      n /= 10;
    }

    return original == reversed;
  }

  public static void main(String[] args) {
    int n = 1221;
    System.out.println(isPalindrome(n));
  }
}

