import java.util.Arrays;

public class bstHeight {

    static int bstHeight(int arr[], int n)
    {
        if (n == 0)
            return 0;

        Arrays.sort(arr);
        int height = 0;
        int i = 0;
        int j = n - 1;

        while (i <= j)
        {
            int mid = (i + j) / 2;

            if (mid < j && arr[mid + 1] == arr[mid])
                i = mid + 1;
            else if (mid > i && arr[mid] == arr[mid - 1])
                j = mid - 1;
            else
            {
                if (mid == n - 1 || arr[mid + 1] > arr[mid])
                    return ++height;

                i = mid + 1;
            }
            height++;
        }
        return 0;
    }

    public static void main(String[] args)
    {
        int arr[] = { 1, 2, 3, 4, 5 };
        int n = arr.length;
        System.out.println("Height: "
                           + bstHeight(arr, n));
    }
}

