// A generic optimizer function
template<typename Iter, typename CostFn, typename ImproveFn>
std::vector<typename Iter::value_type> optimize(Iter start, Iter end, CostFn costFn, ImproveFn improveFn)
{
    // Calculate the initial cost
    typename Iter::value_type current_cost = costFn(start, end);
    typename Iter::value_type best = *start;

    // Iterate until no improvement
    while (improveFn(start, end))
    {
        typename Iter::value_type new_cost = costFn(start, end);

        if (new_cost < current_cost)
        {
            best = *start;
            current_cost = new_cost;
        }
    }

    return best;
}

