std::vector<int> generatePrimeNumbers(int n) 
{ 
    std::vector<int> res; 
    int count = 0; 
    int prime = 2; 

    while (count < n) 
    {  
        bool isPrime = true; 
        for (int i = 2; i < prime; i++) 
            if (prime % i == 0) { 
                isPrime = false; 
                break; 
            } 

        // If prime is prime then insert into result 
        if (isPrime) { 
            res.push_back(prime); 
            count++; 
        } 

        prime++; 
    } 

    return res; 
}

