        }
    }

    static Dictionary<string, List<int>> ClassifyData(int[] data, string[] label)
    {
        var results = new Dictionary<string, List<int>>();

        for (int i = 0; i < label.Length; i ++)
        {
            if(results.ContainsKey(label[i]))
            {
                results[label[i]].Add(data[i]);
            }
            else
            {
                results.Add(label[i], new List<int>() { data[i]});
            }
        }

        return results;
    }
