def factorial(n):
    """Calculates the factorial of a number using memoization"""

    # Create a cache
    cache = {}

    if n == 0:
        return 1

    # Check for cached values
    if n in cache:
        return cache[n]

    result = n * factorial(n - 1)

    # Update the cache
    cache[n] = result

    return result

