def rec_combinations(arr):
  if len(arr) == 1:
    return arr[0]

  combinations = []
  for index, elem in enumerate(arr):
    combos = rec_combinations(arr[:index] + arr[index+1:])
    if isinstance(combos[0], list):
      for combo in combos:
        combination = [elem] + combo
        combinations.append(combination)
    else:
      combinations.append([elem] + combos)

  return combinations

