public class MergeSort {

 // Merges two subarrays of inputNumbers
 // First subarray is arr[l..m]
 // Second subarray is arr[m+1..r]
 void merge(int inputNumbers[], int l, int m, int r) {
 // Find sizes of two subarrays to be merged
 int n1 = m - l + 1;
 int n2 = r - m;

 // Create temp arrays
 int leftArray[] = new int [n1];
 int rightArray[] = new int [n2];

 // Copy data to temp arrays
 for (int i=0; i<n1; ++i)
 leftArray[i] = inputNumbers[l + i];
 for (int j=0; j<n2; ++j) 
 rightArray[j] = inputNumbers[m + 1+ j];

 // Initial indexes of first and second subarrays 
 int i = 0, j = 0; 

 // Initial index of merged subarry array
 int k = l; 
 while (i < n1 && j < n2) 
 { 
 if (leftArray[i] <= rightArray[j]) 
 { 
 inputNumbers[k] = leftArray[i]; 
 i++; 
 } 
 else
 { 
 inputNumbers[k] = rightArray[j]; 
 j++; 
 } 
 k++; 
 } 

 // Copy remaining elements of leftArray[] if any 
 while (i < n1) 
 { 
 inputNumbers[k] = leftArray[i]; 
 i++; 
 k++; 
 } 

 // Copy remaining elements of rightArray[] if any 
 while (j < n2) 
 { 
 inputNumbers[k] = rightArray[j]; 
 j++; 
 k++; 
 } 
 } 

 // Main function that sorts arr[l..r] using 
 // merge() 
 void sort(int inputNumbers[], int l, int r) 
 { 
 if (l < r) 
 { 
 // Find the middle point 
 int m = (l+r)/2; 

 // Sort first and second halves 
 sort(inputNumbers, l, m); 
 sort(inputNumbers , m+1, r); 

 // Merge the sorted halves 
 merge(inputNumbers, l, m, r); 
 } 
 } 

