        elif char in operators:
            # If the character is an operator, add it to the stack
            stack.append(char)
        else:
            # If the character is a bracket, pop the last operator from the stack and add it to the output
            postfix += stack.pop()
    # Return the postfix expression
    return postfix

def grad_descent(f, grad_f, x0, learning_rate, tol, num_iter):

    # Set the initial point
    x = x0

    # Iterate until the maximum number of iterations
    for i in range(num_iter):
        g = grad_f(x)
        x -= learning_rate * g

        if np.linalg.norm(g) < tol:
            return x, i

    return x, num_iter

