def is_anagram(string1, string2):
    # Check length of strings
    if len(string1) != len(string2):
        return False

    # Count the frequencies of each letter
    count_string1 = {}
    count_string2 = {}
    for c1 in string1:
        if c1 not in count_string1:
            count_string1[c1] = 1
        else:
            count_string1[c1] += 1
    for c2 in string2:
        if c2 not in count_string2:
            count_string2[c2] = 1
        else:
            count_string2[c2] += 1

    # Compare the two frequency dicts
    for key in count_string1:
        if key not in count_string2 or count_string2[key] != count_string1[key]:
            return False

    return True

