def calculator(nums):
    result = nums[0] 
    for i in range(1, len(nums)): 
        if nums[i] == '+': 
            result += nums[i + 1] 
        elif nums[i] == '-': 
            result -= nums[i + 1] 
        elif nums[i] == '*': 
            result *= nums[i + 1] 
        else: 
            result /= nums[i + 1] 
    return result 

def optimizeCalculator(nums):
    result = calculator(nums[:2])
    i = 2
    while i < len(nums):
        if nums[i-1] == '*':
            result = calculator([result, '*', nums[i] * nums[i+1]])
            i += 2
        elif nums[i-1] == '/':
            result = calculator([result, '/', nums[i] / nums[i+1]])
            i += 2
        else:
            result = calculator([result, nums[i], nums[i+1]])
            i += 2
    return result

