            int randomNum = randomGen.nextInt(5);
            switch (randomNum) {
                case 0:
                    generatedPassword += lowerCaseChars[randomGen.nextInt(25)];
                    break;
                case 1:
                    generatedPassword += upperCaseChars[randomGen.nextInt(25)];
                    break;
                case 2:
                    generatedPassword += numbers[randomGen.nextInt(9)];
                    break;
                case 3:
                    generatedPassword += specialChar[randomGen.nextInt(7)];
                    break;
                default:
                    generatedPassword += lowerCaseChars[randomGen.nextInt(26)];
            }
        }

        //Validate the password constraints
        int numLowerCase = 0;
        int numUpperCase = 0;
        int numSpecialChar = 0;
        int numNum = 0;

        for (int i = 0; i < generatedPassword.length(); i++) {
            char temp = generatedPassword.charAt(i);
            if (Character.isUpperCase(temp)) {
                numUpperCase++;
            } else if (Character.isLowerCase(temp)) {
                numLowerCase++;
            } else if (Character.isDigit(temp)) {
                numNum++;
            } else {
                numSpecialChar++;
            }
        }

        // If the constraints are not fulfilled, generate password again
        if (numLowerCase < numLowerCase || numUpperCase < numUpperCase ||
            numSpecialChar < numSpecial || numNum < numNumbers) {
            generatedPassword = generatePassword(length, numNumbers, numUpperCase, numLowerCase, numSpecial);
        }

        return generatedPassword;
    }
}

