def quicksort(list, left, right):
    if left < right:
        pivot_index = partition(list, left, right)
        quicksort(list, left, pivot_index)
        quicksort(list, pivot_index + 1, right)

def partition(list, left, right):
    pivot = list[left]
    i = left
    j = right

    while i < j:
        while i <= right and list[i] <= pivot:
            i += 1
        while list[j] > pivot:
            j -= 1
        if i < j:
            list[i], list[j] = list[j], list[i]

    list[left], list[j] = list[j], list[left]

    return j

