#include <vector>
#include <string>
#include <iostream>

classRecentStringQueue 
{
private:
    size_t mMaxSize;
    std::vector<std::string> mRecentString;
public:
    RecentStringQueue(size_t maxSize) : mMaxSize(maxSize) { }
    void add(const std::string& str);
    bool compare(const std::string& str);
};

void RecentStringQueue::add(const std::string& str)
{
    if (mRecentString.size() == mMaxSize) {
        mRecentString.erase(mRecentString.begin());
    }
    mRecentString.push_back(str);
}

bool RecentStringQueue::compare(const std::string& str)
{
    bool isSame = false;
    int index = mRecentString.size() - 1;
    while (index >= 0 && mRecentString[index] == str) {
        isSame = true;
        index--;
    }
    return isSame;
}

int main()
{
    RecentStringQueue rsq(5);
    std::string str;
    do
    {
        std::cout << "> ";
        std::cin >> str;
        rsq.add(str);
        if (!rsq.compare(str))
        {
            std::cout << "String entered twice consecutively!\n";
            break;
        }
    } while (true);
    return 0;
}

