function mergeLinkedLists(head1, head2) {
    let merged, temp;

    //if one of the lists is empty return the other
    if (head1 === null) return head2;
    if (head2 === null) return head1;

    //compare the values of the two lists
    if (head1.val < head2.val) {
        merged = head1;
        head1 = head1.next;
    } else {
        merged = head2;
        head2 = head2.next;
    }

    //assign temp to the current location in the new list
    temp = merged;

    // traverse both the lists and add elemenents in sorted order
    while(head1 !== null && head2 !== null) {
        if (head1.val < head2.val) {
            temp.next = head1;
            head1 = head1.next;
        } else {
            temp.next = head2;
            head2 = head2.next;
        }
        temp = temp.next;  
    }

    // add the rest of the list
    if (head1 !== null) temp.next = head1;
    else temp.next = head2;

    return merged;
 }

