def pascalTriangle(rows): 
    triangle = []

    for i in range(rows): 
        row = [] 
        for j in range(i + 1): 
            if j == 0 or j == i: 
                row.append(1) 
            else: 
                row.append(triangle[i-1][j-1] + triangle[i-1][j]) 
        triangle.append(row) 

    # Convert Pascal's Triangle to string
    result = ""
    for row in triangle:
        result += str(row) + '\n'

