function longestPalindrome(str) {

let longest = '';

for (let i = 0; i < str.length; i++) {
  let start = i;
  let end = str.lastIndexOf(str[i]);

  while (end !== start) {
    let subStr = str.slice(start, end + 1);
    let isPalindrome = checkPalindrome(subStr);
    if (isPalindrome && longest.length < subStr.length) longest = subStr;
    end = str.substring(0, end).lastIndexOf(str[i]);
  }
}

// check if string is palindrome
function checkPalindrome(str) {
  let halfway = Math.floor(str.length / 2);
  let firstHalf = str.slice(0, halfway);
  let secondHalf = str
    .slice(str.length - 1 - halfway + 1)
    .split('')
    .reverse()
    .join('');

  if (firstHalf === secondHalf) return true;
  else return false;
}

return longest;
}

