std::vector<std::pair<int, int> > tasks;

int selectMaxTasks(int i) {
    if (i >= tasks.size())
        return 0;

    int includeTask = 1 + selectMaxTasks(highestTaskCompatible(i));
    int excludeTask = selectMaxTasks(i+1);
    return std::max(includeTask,excludeTask);
}

int highestTaskCompatible(int i) {
    int best = -1;
    int end = tasks[i].second;
    for (int j = i+1; j <  tasks.size(); j++) {
        if (tasks[j].first >= end) {
            best = j;
            break;
        }
    }
    return best;
}

