bool areAnagrams(char* s1, char* s2)
{
    int length1 = strlen(s1);
    int length2 = strlen(s2);

    // Return false if both strings of different lengths
    if (length1 != length2)
        return false;

    // Initialize occurrence of each character as 0 in frequency array
    int frequency[256] = {0};

    // Count occurrences of each character of first string 
    // by increasing frequency array value
    for (int i = 0; i < length1; i++)
        frequency[s1[i]]++;

    // Decrease frequency array for each character of second string
    for (int j = 0; j < length2; j++)
        frequency[s2[j]]--;

    // Check if all frequencies are 0
    for (int j = 0; j < 256; j++)
        if (frequency[j] != 0)
            return false;

    return true;
}

