public class BinarySearch {

 // Function to perform binary search
 public static <T extends Comparable<T>> int binarySearch(final T[] arr, final T searchElement) {

  // left index
  int leftIndex = 0;

  // right index
  int rightIndex = arr.length - 1;

  while (leftIndex <= rightIndex) {

   // middle index
   int middleIndex = (rightIndex + leftIndex) / 2;

   // Condition to determine searchElement matches middle element 
   if (searchElement.compareTo(arr[middleIndex]) == 0) {
    return middleIndex;
   }

   // Condition to determine searchElement is less than middle element
   if (searchElement.compareTo(arr[middleIndex]) < 0) {
    rightIndex = middleIndex - 1;
   }

   // Condition to determine searchElement is greater than middle element
   else {
    leftIndex = middleIndex + 1;
   }
  }

  return -1;
 }

}

