int knapsack(int capacity, int weight[], int value[], int numOfItems) 
{ 
   int dp[capacity+1]; 

   // Build table K[][] in bottom 
   // up manner 
   for (int i = 0; i <= capacity; i++) 
   {  
       dp[i] = 0; 

       for (int j = 0; j < numOfItems; j++) 
         if (weight[j] <= i) 
            dp[i] = max(dp[i], dp[i - weight[j]] + value[j]); 
   } 

   return dp[capacity]; 
}

