def knapsack(items, maxWeight):
    # Create a two-dimensional array to store the maximum value
    # that can be achieved with the given weights and items
    dp = [[0 for weight in range(maxWeight + 1)] for item in range(len(items) + 1)]

    # Fill the array for all items
    for item in range(1, len(items) + 1):
        for weight in range(1, maxWeight + 1):
            if items[item-1][1] <= weight:
                dp[item][weight] = max(items[item-1][0] + dp[item-1][weight-items[item-1][1]], dp[item-1][weight])
            else:
                dp[item][weight] = dp[item-1][weight]

    return dp[len(items)][maxWeight]

