def caesar_encode(message, key): 
    encoded_message = ""

    for char in message: 
        if char.isupper(): 
            char = chr((ord(char) + key - 65) % 26 + 65) 
        else: 
            char = chr((ord(char) + key - 97) % 26 + 97) 
        encoded_message += char

    return encoded_message

