def can_split_to_equal_sum(arr):
    total_sum = sum(arr)
    if total_sum % 2 == 1:
        return False

    target_sum = total_sum // 2
    seen_sums = set()
    current_sum = 0
    for num in arr:
        current_sum += num
        if current_sum == target_sum:
            return True
        if (current_sum - target_sum) in seen_sums:
            return True
        seen_sums.add(current_sum)
    return False

