def distinct_palindromic_subsequences(str):
    n = len(str)
    dp = [[0]*n for _ in range(n)]

    for gap in range(n):
        i = 0
        for j in range(gap, n):
            if i == j:
                dp[i][j] = 1
            elif str[i] == str[j]: 
                dp[i][j] = dp[i+1][j-1] + 2
            else: 
                dp[i][j] = max(dp[i+1][j], 
                                dp[i][j-1]) 
            i += 1
    return dp[0][n-1]

