    // Base case 
    if (node1 == null && node2 == null) {
        return true;
    }

    if (node1 == null || node2 == null) {
        return false;
    }

    // If the data of both nodes is same and left and right subtrees of both nodes are identical 
    if (node1.value == node2.value 
            && areIdentical(node1.left, node2.left) 
            && areIdentical(node1.right, node2.right)) { 
