def simpson(f, a, b, n):
    h = (b-a)/n
    s = f(a) + f(b)
    for i in range(1, n):
        if i % 2 == 0:
            s += 2*f(a + i*h)
        else:
            s += 4*f(a + i*h)
    return (h/3)*s

