def longest_increasing_subsequence(arr):
    max_length = 1
    n = len(arr)

    # Initaialize memoization table 
    LIS = [1 for x in range(n)] 

    # Computelongest increasing subsequence  
    for i in range (1 , n): 
        for j in range(0 , i): 
            if arr[i] > arr[j] and LIS[i] < LIS[j] + 1 : 
                LIS[i] = LIS[j] + 1

