public class ShuntingYardAlgorithm {

    public static int evaluateExpression(String expression) {

        Stack<String> stack = new Stack<>();
        Queue<String> queue = new LinkedList<>();
        String[] elements = expression.split(" ");

        StringBuilder currentNumber = new StringBuilder(); 
        for (String element : elements) {
            switch(element) {
                case "(":
                    stack.push(element);
                    break;
                case "+": 
                case "-":
                case "*":
                case "/":
                    while(!stack.isEmpty() && precedence(stack.peek()) >= precedence(element)) {
                        queue.add(stack.pop());
                    }
                    stack.push(element);
                    break;
                case ")":
                    String poped;
                    while(!stack.isEmpty() && !(poped = stack.pop()).equals("(")) {
                        queue.add(poped);
                    }
                    break;
                default:
                    queue.add(element);
            }
        }

        while(!stack.isEmpty()) {
            queue.add(stack.pop());
        }

        int result = 0;
        while (!queue.isEmpty()) {
            String element = queue.poll();
            switch (element) {
                case "+":
                    result = Integer.parseInt(queue.poll()) + result; 
                    break;
                case "-":
                    result = result - Integer.parseInt(queue.poll());
                    break;
                case "*":
                    result = Integer.parseInt(queue.poll()) * result;
                    break;
                case "/":
                    result = result / Integer.parseInt(queue.poll());
                    break;
                default:
                    result = Integer.parseInt(element);
            }
        }

        return result;
    }

    public static int precedence(String str) {
        if (str.equals("(")) {
            return 0;
        } else if (str.equals("+") || str.equals("-")) {
            return 1;
        }else {
            return 2;
        }
    }

    public static void main(String[] args) {
        String expression = "( 1 + 2 ) * 3";
        int result = evaluateExpression(expression);
        System.out.println("Result of the expression: " + result);
    }
}

