def min_edit_distance(string1, string2):
 m = len(string1)+1
 n = len(string2)+1
 dist = [[0]*n for i in range(m)]
 for i in range(m):
 dist[i][0] = i
 for j in range(n): 
 dist[0][j] = j
 for i in range(1,m): 
 for j in range(1,n): 
 if string1[i-1] == string2[j-1]: 
 dist[i][j] = dist[i-1][j-1] 
 else: 
 dist[i][j] = 1 + min(dist[i][j-1], 
 dist[i-1][j], 
 dist[i-1][j-1]) 
 return dist[m-1][n-1]

