func longestSubStringWithoutRepeatingChars(s string) string {
	charIdx := make(map[byte]int)
	start := 0
	maxLen := 0
	var longestSubStr string

	for i, c := range s {
		prevIdx, ok := charIdx[byte(c)]
		if ok && prevIdx >= start {
			start = prevIdx + 1
		}
		currLen := i - start + 1
		if currLen > maxLen {
			longestSubStr = s[start:i+1]
			maxLen = currLen
		}
		charIdx[byte(c)] = i
	}
	return longestSubStr
}

