public int[] removeDuplicates(int[] arr){
    Set<Integer> set = new HashSet<>();
    for(int i=0; i<arr.length; i++){
        set.add(arr[i]);
    }
    int[] uniqueElements = new int[set.size()];
    int j = 0;
    for (Integer element : set) {
        uniqueElements[j++] = element;
    }
    return uniqueElements;
}

