#include<float.h> 

double calcArea(double x) 
{ 
    return x * x; 
} 

double gradientDescent(double initial, double step) 
{ 
    double error, x0, x1; 
    x0 = initial; 

    do { 
        x1 = x0 - step * (2 * x0); 
        error = calcArea(x1) - calcArea(x0); 
        x0 = x1; 
    } 
    while (error > DBL_EPSILON); 

    return x1; 
} 

int main() 
{ 
    double initial = 6.0; 
    double step = 0.001; 

    double area = calcArea(gradientDescent(initial, step)); 
    std::cout << "Area of square: "
              << area << std::endl; 
    return 0; 
}

