// Function to generate a set of unique random numbers.
int *uniqueRandoms(int numCount)
{
    int *unique_nums = malloc(sizeof(int) * numCount);
    int i, index, r;
    for (i = 0; i < numCount; i++)
    {
        do
        {
            r = rand();
            for(index = 0; index < i; index++)
            {
                if(r == unique_nums[index])
                    break;
            }
        } while (index != i);

        unique_nums[i] = r;
    }
    return unique_nums;
}

