public static void countVowelsAndConsonants(String s) 
{ 
    // Initializing counters 
    int count_vowels = 0; 
    int count_consonants = 0; 

    // Converting the entered string into lowercase 
    s = s.toLowerCase(); 

    // Converting the string into a character array 
    char c[] = s.toCharArray(); 

    // Checking for Vowels 
    for (int i = 0; i < s.length(); i++) 
    { 
        //Checking whether a character is a vowel 
        if (c[i]=='a' || c[i]=='e' || c[i]=='i' 
            || c[i]=='o' || c[i]=='u') 
        { 
            //Increasing the number of vowels 
            count_vowels++; 
        } 
        else if((c[i]>='a'&& c[i]<='z')) 
        { 
            //Increasing the number of consonants
            count_consonants++; 
        } 
    } 

    //Printing the number of vowels and consonants 
    System.out.println("Number of vowels : " + count_vowels); 
    System.out.println("Number of consonants : " + count_consonants); 
}

