public bool IsValidCreditCardNumber(string cardNumber)
{
    // Check for empty string
    if (string.IsNullOrEmpty(cardNumber))
    {
        return false;
    }

    // Check for non-zero string
    if (cardNumber.StartsWith("0000000000") || cardNumber.StartsWith("1111111111") || cardNumber.StartsWith("2222222222") || cardNumber.StartsWith("3333333333") || cardNumber.StartsWith("4444444444") || cardNumber.StartsWith("5555555555") || cardNumber.StartsWith("6666666666") || cardNumber.StartsWith("7777777777") || cardNumber.StartsWith("8888888888") || cardNumber.StartsWith("9999999999"))
    {
        return false;
    }

    // Luhn Algorithm
    int sumOfDigits = cardNumber
                        .Where((e) => e >= '0' && e <= '9')
                        .Reverse()
                        .Select((e, i) => ((int)e - 48) * (i % 2 == 0 ? 1 : 2))
                        .Sum((e) => e / 10 + e % 10);

    return sumOfDigits % 10 == 0;
}

