public class SubsequenceFinder { 

    public static string FindShortestSubsequence(string str) 
    { 
        int n = str.Length; 

        string[,] outmatrix = new string[n, n]; 

        // Filling the output matrix. 
        // l --> Length of substring 
        for (int l = 1; l <= n; l++) { 
            for (int i = 0; i <= n - l; i++) { 
                int j = i + l - 1; 

                if (l == 1) 
                    outmatrix[i, j] = str[i].ToString(); 

                else if (str[i] == str[j]) 
                    outmatrix[i, j] = str[i] + outmatrix[i + 1, j - 1]; 

                else { 
                    string s1 = outmatrix[i + 1, j]; 
                    string s2 = outmatrix[i, j - 1]; 

                    outmatrix[i, j] = 
                        s1.Length<s2.Length?s1:s2; 
                } 
            } 
        } 

        return outmatrix[0,n - 1]; 
    } 

}

