def compress(s):
 # Make a dictionary to keep track of characters and their counts
 d = {}

 for c in s:
 if c not in d:
 d[c] = 1
 else:
 d[c] += 1

 # Create a new string by replacing similar sequences
 # with numbers
 result = ''
 for c, count in d.items():
 result += c + str(count)

 return result

