"""
Return the maximum possible sum of some of its k consecutive numbers of a given array
"""

function max_sum_k_consecutive(arr, k) {
    let max_sum = 0,
        sum = 0;
    for (let i = 0; i < arr.length - k + 1; i++) {
        sum = 0;
        for (let j = i; j < i + k; j++) {
            sum += arr[j];
        }
        if (sum > max_sum) {
            max_sum = sum;
        }
    }
    return max_sum;

}

