// Recursive function to return gcd
int gcd(int a, int b) 
{ 
    // base case
    if (a == 0) 
        return b; 
    if (b == 0) 
        return a; 

    // if both a and b are even 
    if (a % 2 == 0 && b % 2 == 0) 
        return 2 * gcd(a >> 1, b >> 1); 

    // if both a and b are odd 
    if (a % 2 != 0 && b % 2 != 0) 
        return gcd(a, b); 

    // if a is even and b is odd 
    if (a % 2 == 0) 
        return gcd(a >> 1, b); 

    // if a is odd and b is even 
    else
        return gcd(a, b >> 1); 
} 

