public class MainActivity extends AppCompatActivity  {

 private SensorManager sManager;
 private Sensor mSensor;

 @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);    
        sManager = (SensorManager) getSystemService(SENSOR_SERVICE);  
        mSensor = sManager.getDefaultSensor(Sensor.TYPE_ACCELEROMETER);  
        sManager.registerListener(this, mSensor, SensorManager.SENSOR_DELAY_NORMAL);  
    }

    @Override  
    public void onSensorChanged(SensorEvent event) {  
        if (event.sensor.getType() == Sensor.TYPE_ACCELEROMETER) {  
            getAccelerometer(event);  
        }  
    }  

 // Method that shows the notification on device shake
    private void showNotification() {
        // Create an Intent for an action.
        Intent intent = new Intent(this, MainActivity.class);

        //Create a pending intent to provide the action
        PendingIntent pendingIntent =
        PendingIntent.getActivity(this, 0, intent, 0);

        //Create a notification
        NotificationCompat.Builder builder = new 
        NotificationCompat.Builder(this)
            .setSmallIcon(R.drawable.ic_notifications_black_24dp)
            .setContentTitle("Alert!")
            .setContentText("Device shaken")
            .setContentIntent(pendingIntent);

        NotificationManager manager = 
        (NotificationManager) getSystemService(NOTIFICATION_SERVICE);

        //Send the notification
        manager.notify(0, builder.build());
    }

    // Method to detect device shake
    private void getAccelerometer(SensorEvent event) {
        float[] values = event.values;
        float x = values[0];
        float y = values[1];
        float z = values[2];

        float gX = x / SensorManager.GRAVITY_EARTH;
        float gY = y / SensorManager.GRAVITY_EARTH;
        float gZ = z / SensorManager.GRAVITY_EARTH;

        double gForce = Math.sqrt(Math.pow(gX, 2) + 
        Math.pow(gY, 2) + Math.pow(gZ, 2));

        if (gForce > 3.0) {
            showNotification();
        }
    }
}

