class StateSelector extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            selectedState: '',
            selectedCounty: ''
        }
    }

    //Populates the state selector dropdown
    renderStateOptions() {
        const states = {};
        this.props.data.forEach((d) => {
            if (!states.hasOwnProperty(d.state)) {
                states[d.state] = true;
            }
        });

        let stateOptions =  Object.keys(states).map((state) => (
            <option key={state} value={state}>{state}</option>
            ));

        //Adds an initial option allowing no selection
        stateOptions.unshift(<option key="none" disabled>--Select State--</option>);
        return stateOptions;
    }

    //Populates the county selector dropdown based on the selected state
    renderCountyOptions() {
        const { data, selectedState } = this.state;
        let countyOptions = data
            .filter(s => s.state == selectedState)
            .map(c => (
            <option key={c.county} value={c.county}>{c.county}</option>
            ));

        //Adds an initial option allowing no selection
        countyOptions.unshift(<option key="none" disabled>--Select County--</option>);
        return countyOptions;
    }

    render() {
        return (
            <div>
                <select onChange={e => this.setState({selectedState: e.target.value})}>
                {this.renderStateOptions()}
                </select>
                <select onChange={e => this.setState({selectedCounty: e.target.value})}>
                {this.renderCountyOptions()}
                </select>
            </div>
        );
    }
}

