def wordExists(board, word):
    for i in range(len(board)):
        for j in range(len(board[i])):
            if dfs(board, word, i, j):
                return True

    return False

def dfs(board, word, i, j):
    if len(word) == 0: # all the characters of the world are checked
            return True

    if i < 0 or i >= len(board) or j < 0 or j >= len(board[i]) or word[0] != board[i][j]:
        return False

    tmp = board[i][j]
    board[i][j] = '#'

    # explore neighbor cells in 8 directions
    res = dfs(board, word[1:], i+1, j) or dfs(board, word[1:], i-1, j) or \
            dfs(board, word[1:], i, j+1) or dfs(board, word[1:], i, j-1) or \
            dfs(board, word[1:], i+1, j+1) or dfs(board, word[1:], i+1, j-1) or \
            dfs(board, word[1:], i-1, j+1) or dfs(board, word[1:], i-1, j-1)

    board[i][j] = tmp
    return res

