public class Palindrome {

    public static boolean isPalindrome(String s) {
        // Check if string is empty or null
        if (s == null || s.length() == 0) {
            return true;
        }

        int n = s.length();

        // Iterate through each character of the string
        for (int i = 0; i < n / 2; i++) {
            if (s.charAt(i) != s.charAt(n - i - 1)) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        String s = "madam";
        System.out.println("Is '" + s + "' a palindrome? : " + isPalindrome(s));
    }
}

public class Strings {

 public static boolean isSameCharacters(String str1, String str2) {
   // Remove all white spaces
   str1 = str1.replaceAll("\\s+","");
   str2 = str2.replaceAll("\\s+","");

   // Check if both strings are equal in length
   if (str1.length() != str2.length()) {
    return false;
   }

   // Compare both strings character by character
   for (int i = 0; i < str1.length(); i++) {
    if (str1.charAt(i) != str2.charAt(i)) {
     return false;
    }
   }

   // Strings are equal
   return true;
 }

 public static void main(String[] args) {
   String str1 = "hello world";
   String str2 = "eworld hello";

   // Check if the strings have the same characters
   if (isSameCharacters(str1, str2)) {
