string caesarCypherEncrypt(string text, int key) {
    string result = "";

    for (int i = 0; i < text.length(); i++) {
        if (isalpha(text[i])) {
            if (isupper(text[i])) {
                result += char(int(text[i] + key - 65) % 26 + 65);
            } else {
                result += char(int(text[i] + key - 97) % 26 + 97);
            }
        }
    }

    return result;
}

