  const { clickRate } = props;

  useEffect(() => {
    let interval = setInterval(() => {
      setPercent((percent) => {
        if (percent + clickRate <= 100) {
          return percent + clickRate;
        } else {
          clearInterval(interval);
          return 100;
        }
      });
    }, 1000);

