//function to draw histogram
function drawHistogram(data, min, max) {
    const barWidth = (canvas.width / data.length) * 0.8;
    const barOffset = (canvas.width - (barWidth * data.length)) / 2;

    for (let i = 0; i < data.length; i++) {
        //calculate height of each bar
        const height = (canvas.height * data[i]) / (max - min);

        //draw each bar
        context.fillStyle = "black";
        context.fillRect(
            barOffset + (i * barWidth),
            canvas.height - height,
            barWidth,
            height
        );
    }
}

