public void deleteNode (Node head, Node toDelete) {
 if (head == null || toDelete == null) {
  return;
 }

 // Delete if the node to delete is the first Node
 if (head == toDelete) {
  head = toDelete.next;
  return;
 }

 // Find the previous node
 Node prevNode = head;
 while (prevNode.next != toDelete) {
  prevNode = prevNode.next;
 }

 // Delete the node and link the previous node to the next
 prevNode.next = toDelete.next;
}

