struct Node{
    int key;
    struct Node *left, *right;
};

// Function to find the first common ancestor of two nodes
Node* findCommonAncestor(Node* root, int key1, int key2){
    if(root == NULL || root->key == key1 || root->key == key2){
        return root;
    }

    Node* left = findCommonAncestor(root->left, key1, key2);
    Node* right = findCommonAncestor(root->right, key1, key2);

    if(left && right){
        return root;
    }
    return left? left : right;
}

