// C++ program to check if a tree is
// a valid Binary Search Tree
#include <stdio.h>
#include <stdlib.h>

/* A binary tree node has key, pointer
   to left child and a pointer to right
   child */
struct Node
{
    int key;
    struct Node *left, *right;
};

/* Returns true if given tree is a binary
search tree (efficient version) */
bool isBST(struct Node* node)
{
    // Base case
    if (node == NULL)
        return true;

    // if left node exist then check its key
    // against root's key
    if (node->left != NULL and
        node->left->key > node->key)
        return false;

    // if right node exist then check its key
    // against root's key
    if (node->right != NULL and
        node->right->key < node->key)
        return false;

    // check recursively for every node.
    return isBST(node->left) &&
            isBST(node->right);
}

/* Helper function that allocates a new node
with the given data and NULL left and right
pointers. */
struct Node* newNode(int data)
{
    struct Node* node = (struct Node*)
                        malloc(sizeof(struct Node));
    node->key = data;
    node->left = NULL;
    node->right = NULL;
    return (node);
}

/* Driver program to test above functions*/
int main()
{
    struct Node *root = newNode(4);
    root->left = newNode(2);
    root->right = newNode(5);
    root->left->left = newNode(1);
    root->left->right = newNode(3);

    if (isBST(root))
        printf("Is BST");
    else
        printf("Not a BST");

    return 0;
}

