        continue;
      }

      // Get HTML content of the page
      try {
        URL url = new URL(currentLink);
        InputStream is = url.openStream();
        BufferedReader br = new BufferedReader(new InputStreamReader(is));

        String line = "";
        while ((line = br.readLine()) != null) {
          // Get all text from current link
          content.append(line); 

          // Get HTML links from current link 
          collectInternalLinks(line, currentLink);
        }

        visited.add(currentLink);
      } catch (MalformedURLException | IOException e) {
        e.printStackTrace();
      }
    }

    return content.toString();
  }

  // Collect internal links from visited page 
  private void collectInternalLinks(String line, String currentLink) {
    // Regular expression for extracting links
    Pattern pattern = Pattern.compile("(<a.*?href=\").*?((\\\"\\s|\\\").*>|\").*?(</a>)");
    Matcher matcher = pattern.matcher(line);

    while (matcher.find()) {
      // Check if the link already exists in links queue or already visited 
      if (!links.contains(matcher.group(1)) 
        && !visited.contains(matcher.group(1))) {
        // If link relative, then convert it to absolute 
        // and add to links queue
        if (matcher.group(1).startsWith("/")) {
          String absoluteLink = currentLink + matcher.group(1);
          links.add(absoluteLink);
        } else {
          links.add(matcher.group(1));
        }
      }
    }
  } 
}

