def pearsonCorrelation(series1: Seq[Double], series2: Seq[Double]):
 // Find the mean of each series
 mean1 = series1.sum / series1.length
 mean2 = series2.sum / series2.length

 // Calculate the deviation from the mean for each series
 deviations1 = series1.map(x => x - mean1)
 deviations2 = series2.map(x => x - mean2)

 // Find the covariance between the two series
 covariance = deviations1.zip(deviations2).map { case (x1, x2) => x1 * x2 }.sum

 // Find the standard deviations of each series
 stdDev1 = math.sqrt(deviations1.map(x => x * x).sum)
 stdDev2 = math.sqrt(deviations2.map(x => x * x).sum)

 // Calculate the Pearson Correlation
 correlation = covariance / (stdDev1 * stdDev2)
 return correlation

