public boolean oneAway(String s1, String s2) { 
    int l1 = s1.length(); 
    int l2 = s2.length(); 

    // If difference between length is > 1 then strings can't be one away 
    if (Math.abs(l1-l2) > 1) 
        return false; 

    int count = 0; // Count to store count of isEdited 
    int i = 0, j = 0; 
    // Check characters in both strings if same than no edits else increment count 
    while (i < l1 && j < l2) { 
        // If current character doesn't match 
        if (s1.charAt(i) != s2.charAt(j)) { 
            if (count == 1) 
                return false; 

            // If characters are not same but length is same, we 
            // can replace the current character in S1 
            if (l1 == l2) 
                i++; 
            count++; 
        } else { // If characters match 
            i++; 
            j++;
        } 
    } 

    // If last character is extra in any string 
    if (i < l1 || j < l2) 
        count++; 

    return count == 1; 
}

