import numpy as np

def cost__func(x, y):
	return np.square(x-3) + np.square(y-3)

def optimize_cost(cost_func, x_start, y_start):
	best_value = cost_func(x_start, y_start)
	best_x = x_start
	best_y = y_start

	for x in range(-100,100):
		for y in range(-100,100):
			cost = cost_func(x, y)

			if(cost < best_value):
				best_value = cost
				best_x = x
				best_y = y

	return best_x, best_y

