public class IntSet {
    // Array to store integers
    int[] arr = new int[10];

    // Variable for current size of the set
    int size = 0;

    // Function to add an integer to the set
    public boolean add(int x) {
        // Check if x is already present
        if (contains(x)) {
            return false;
        }
        // Increase size and add x to the array
        arr[size] = x;
        size++;
        return true;
    }

    // Function to remove an integer from the set
    public boolean remove(int x) {
        // Find the index of x in the array
        int index = find(x);
        // If x is not found, return false
        if (index == -1) {
            return false;
        }
        // Shift all the elements after x one place left
        for (int i = index; i < size - 1; i++) {
            arr[i] = arr[i + 1];
        }
        // Decrease size
        size--;
        return true;
    }

    // Function to check if integer is present or not
    public boolean contains(int x) {
        return find(x) != -1;
    }

    // Helpder function to find the index of an integer in the array
    private int find(int x) {
        for (int i = 0; i < size; i++) {
            if (arr[i] == x) {
                return i;
            }
        }
        return -1;
    }
}

