function evaluateExpression(expression) {
    let evaluatedExpression;
    if (expression.length === 1) {
        evaluatedExpression = expression;
    } else {
        let firstCompositeExpression = evaluateExpression(expression.slice(0, expression.indexOf(')')));
        let outsideTerms = expression.match(/(?:[^\s()]+|\([^\s)]+/g);
        let operator = outsideTerms[1];
        let secondCompositeExpression = evaluateExpression(expression.slice(expression.indexOf(')') + 1));
        if (operator === "or") {
            evaluatedExpression = firstCompositeExpression || secondCompositeExpression;
        } else if (operator === "and") {
            evaluatedExpression = firstCompositeExpression && secondCompositeExpression;
        }
    }
    return evaluatedExpression;
}

