function greedyBinPack(items) {
 let bin = [];
 let binCapacity = 1;

 for (let i = 0; i < items.length; i++) {
 let item = items[i];
 let isAddedToBin = false;

 for (let j = 0; j < bin.length; j++) {
 let currentBinCapacity = bin[j];
 if (currentBinCapacity + item <= binCapacity) {
 bin[j] += item;
 isAddedToBin = true;
 break;
 }
 }

 if (!isAddedToBin) {
 bin.push(item)
 }
 }

 return bin;
}

