function sort(arr) {
    for (let i = 0; i < arr.length; i++) {
        // Find the minimum element in unsorted array
        let minIdx = i;
        for (let j = i+1; j < arr.length; j++) {
            if (arr[minIdx] > arr[j]) {
                minIdx = j;
            }
        }

        // Swap the found minimum element with the first element
        let temp = arr[minIdx];
        arr[minIdx] = arr[i];
        arr[i] = temp;
    }
    return arr;
}

