void Stack::push(int x) {
    if (top >= 20) {
        cout << "Stack Overflow";
        return;
    }
    arr[++top] = x;
}

int Stack::pop() {
    if (top < 0) {
        cout << "Stack Underflow";
        return 0;
    }

    int a = arr[top--];
    return a;
}

