function longestCommonSubarray(arr1, arr2) {
    var maxLength = 0;
    var length  = 0;
    var start_subarray = 0;

    // traverse the first array 
    for (var i = 0; i < arr1.length; i++) {
        // traverse the second array
        for (var j = 0; j < arr2.length; j++) {
            length = 0;
            while (arr1[i+length] == arr2[j+length]) {
                length++;

                // update the maximum length at each iteration
                if (length > maxLength) {
                    maxLength = length;
                    start_subarray = i;
                }
            }
        }
    }
    return arr1.slice(start_subarray, start_subarray + maxLength);
}

