import random

class Agent():
    def __init__(self, maze):
        self.maze = maze
        self.visited = []

    def find_exit(self):
        self.visited.append(self.maze.start_position)

        while True:
            current_position = self.visited[-1]
            valid_moves = self.maze.valid_moves(current_position)
            if self.maze.is_exit(current_position):
                break
            else:
                valid_moves.remove(self.visited[-2])
                move = random.choice(valid_moves)
