import com.itextpdf.text.pdf.PdfWriter;
import com.itextpdf.tool.xml.XMLWorkerHelper;

public class PDFServlet extends HttpServlet {

 @Override
 protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
  final String htmlContent = req.getParameter("html");
  ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
  try {
   Document document = new Document();
   PdfWriter.getInstance(document, byteArrayOutputStream);

   // open document
   document.open();

   // convert html content into PDF
   XMLWorkerHelper.getInstance().parseXHtml(PdfWriter.getInstance(document, byteArrayOutputStream), document,
     new ByteArrayInputStream(htmlContent.getBytes()));

   // close document
   document.close();

   // download pdf file
   resp.reset();
   resp.setContentType("application/pdf");
   resp.setContentLength(byteArrayOutputStream.size());
   resp.setHeader("Content-disposition", "inline; filename=file.pdf");

   OutputStream outputStream = resp.getOutputStream();
   outputStream.write(byteArrayOutputStream.toByteArray());
   outputStream.flush();
   outputStream.close();

  } catch (DocumentException e) {
   e.printStackTrace();
  } finally {
   byteArrayOutputStream.flush();
   byteArrayOutputStream.close();
  }
 }
}

