def find_anagrams(words):
    """This function finds all the anagrams in a list of words."""
    anagrams = []
    seen = set()
    for word in words:
        # sort characters in word
        sorted_word = ''.join(sorted(word))
        if sorted_word not in seen:
            # first occurance of this sorted word
            seen.add(sorted_word)
            # append itself as first anagram
            anagrams.append([word])
        else:
            # add to list of anagrams
            for i in range(len(anagrams)):
                if ''.join(sorted(anagrams[i][0])) == sorted_word:
                    anagrams[i].append(word)
                    break
    return anagrams

