def rot13_encode(string): 
    encoded_string = '' 
    for i in range(len(string)): 
        c = string[i] 
        if  'A' <= c <= 'Z': 
            encoded_string += chr((ord(c) + 13 - 65) % 26 + 65) 
        elif  'a' <= c <= 'z': 
            encoded_string += chr((ord(c) + 13 - 97) % 26 + 97) 
        else:
            encoded_string += string[i]  
    return encoded_string

