const cosineSimilarity = (str1, str2) => {

 // Tokenize the strings
 const tokens1 = str1.split(' ');
 const tokens2 = str2.split(' ');

 // Get the unique tokens
 const uniqueTokens = Array.from(new Set([...tokens1, ...tokens2]));

 // Get the token counts
 const tokenCounts1 = uniqueTokens.map(token => tokens1.filter(x => x === token).length);
 const tokenCounts2 = uniqueTokens.map(token => tokens2.filter(x => x === token).length);

 // Calculate the dot product of the token counts
 let dotProduct = 0;
 for (let i=0; i<uniqueTokens.length; i++) {
  dotProduct += tokenCounts1[i] * tokenCounts2[i];
 } 

 // Calculate the magnitudes
 const norm1 = Math.sqrt(tokenCounts1.reduce((acc, count) => acc + Math.pow(count, 2), 0));
 const norm2 = Math.sqrt(tokenCounts2.reduce((acc, count) => acc + Math.pow(count, 2), 0));

 // Calculate and return the cosine similarity
 return dotProduct / (norm1 * norm2);
};

