public static int countPrimes(int min, int max) {
    int count = 0;

    for (int num = min; num <= max; num++) {
        boolean isPrime = true;

        for (int i = 2; i < num; i++) {
            if (num % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            count++;
        }
    }

    return count;
}

