class Autocomplete {
  constructor() {
    this.root = {};
  }

  insert(word) {
    let node = this.root;
    for (let char of word) {
      if (node[char] == null) {
        node[char] = {};
      }
      node = node[char];
    }
    node.$ = word;
  }

  searchFor(term) {
    let results = [];
    let node = this.root;
    for (let char of term) {
      if (node[char] == null) return results;
      node = node[char];
    }
    this.fetchWords(node, results);
    return results;
  }

  fetchWords(node, arr) {
    for (let char in node) {
      if (char === '$') {
        arr.push(node.$);
      } else {
        this.fetchWords(node[char], arr);
      }
    }
  }
}

