public class ReverseDigits {

 public static int reverseDigits(int num) {
  int result = 0;

  while (num > 0) {
   int lastDigit = num % 10;
   result = result * 10 + lastDigit;
   num = num / 10;
  }

  return result;
 }

 public static void main(String[] args) {
  System.out.println(reverseDigits(5432));
 } 
}

