def compress_string(string): 
    prev_char = '' 
    result = '' 
    count = 0  
    for char in string: 
        if char != prev_char: 
            if count != 0:
                result += str(count) 
            result += char 
            count = 0 
        count += 1  

    if count != 0:
            result += str(count)
    return result

