def first_fit(process_sizes, memory_slot_sizes):
  result = []
  for process_size in process_sizes:
    for slot_index, slot_size in enumerate(memory_slot_sizes):
      if slot_size >= process_size:
        result.append((slot_index, process_size))
        memory_slot_sizes[slot_index] -= process_size
        break
  return result

def quickSort(arr): 
  if len(arr) <= 1:
    return arr
  pivot = arr[len(arr) // 2]
  left = [x for x in arr if x < pivot]
  middle = [x for x in arr if x == pivot]
  right = [x for x in arr if x > pivot]
  return quickSort(left) + middle + quickSort(right)

