def sort_array(arr):
    # Bubble Sort

    arr_len = len(arr)

    # Iterate through all elements in the given array
    for i in range(arr_len):

        # Iterate through all elements until the sorted part of the array at the end
        for j in range(0, arr_len-i-1):

            # Swap the element if it is greater than the next element
            if arr[j] > arr[j+1] :
                arr[j], arr[j+1] = arr[j+1], arr[j]

