public class HuffmanTree {
    public static HuffmanNode createTree(Map<Character, Integer> freq) { 
        PriorityQueue<HuffmanNode> pq = new PriorityQueue<>(); 
        for (Character c : freq.keySet()) { 
            pq.add(new HuffmanNode(c, freq.get(c), null, null));
        } 

        while (pq.size() > 1) { 
            HuffmanNode left = pq.poll(); 
            HuffmanNode right = pq.poll(); 
            int sum = left.freq + right.freq; 
            pq.add(new HuffmanNode('\0', sum, left, right)); 
        } 
        return pq.poll(); 
    } 

}

// Algorithm to calculate the Euclidean distance between two points
