def knapsack_problem(items, capacity):
    dp = [[0 for i in range(capacity + 1)] for i in range(len(items))]
    for item in range(len(items)):
        for cap in range(capacity + 1):
            if items[item][1] <= cap:
                dp[item][cap] = max(items[item][0] + dp[item - 1][cap - items[item][1]], dp[item - 1][cap])
            else:
                dp[item][cap] = dp[item-1][cap]
    return dp[len(items)-1][capacity]

