// Check if a given element is visible or not
function checkVisibility(id) {
  // Read the HTML file
  const data = fs.readFileSync('./index.html', 'utf8');

  // Search for the given element
  const regex = new RegExp(`[id="${id}"]`);

  // Return true if the element is visible, false otherwise
  return regex.test(data) && !data.includes(`[id="${id}"][style="visibility: hidden"]`);
}

// Toggle the visibility of a given element
function toggleVisibility(id) {
  // Read the HTML file
  let data = fs.readFileSync('./index.html', 'utf8');

  // Check if element is visible
  const isVisible = checkVisibility(id);

  // If element is visible, add the hidden style attribute
  if (isVisible) {
    const style = `style="visibility: hidden"`;
    data = data.replace(`[id="${id}"]`, `[id="${id}"][${style}]`);
  // Otherwise, remove the hidden style attribute
  } else {
    data = data.replace(`[id="${id}"][style="visibility: hidden"]`, `[id="${id}"]`);
  }

  // Write the updated HTML file
  fs.writeFileSync('./index.html', data);
}

