function trimString(str) {
    let leftTrimIndex = 0;
    while (str[leftTrimIndex] === ' ') {
        leftTrimIndex++;
    }

    let rightTrimIndex = str.length;
    while (str[rightTrimIndex - 1] === ' ') {
        rightTrimIndex--;
    }

    return str.substring(leftTrimIndex, rightTrimIndex);
}

