function longestPalindromicSubstring(string) { 
  let longest = '';
  for (let i = 0; i < string.length; i++) {
    for (let j = 0; j < 2; j++) { 
      let left = i;
      let right = i + j;
      while (string[left] && string[left] === string[right]) { 
        left--;
        right++; 
      }
      if (right - left - 1 > longest.length) {
        longest = string.slice(left + 1, right);
      }
    }
  }
  return longest;
}

