#include <stdio.h> 

int findCombinations(int n, int k) 
{ 
	// dp[i][j] stores number of 
	int dp[n + 1][k + 1]; 

	// Base case: 
	// if given sum is 0 
	for (int i = 0; i <= n; i++) 
		dp[i][0] = 1; 

	// if current number of elements is 0 
	for (int i = 1; i <= k; i++) 
		dp[0][i] = 0; 

	// Recursively fill entries of dp[][] 
	// from i = 1 to n and j = 1 to k 
	for (int i = 1; i <= n; i++) { 
		for (int j = 1; j <= k; j++) { 
			if (j >= i) 
				dp[i][j] = dp[i - 1][j] + dp[i][j - i]; 
			else
				dp[i][j] = dp[i - 1][j]; 
		} 
	} 

	// No of combinations of size n and sum k is 
	// dp[n][k] 
	return dp[n][k]; 
} 

int main() 
{ 
	int n = 4, k = 7; 
	printf("%d", findCombinations(n, k)); 
	return 0; 
}

