    intervals.sort() 
    max_overlaps = 0 
    overlap = 0 
    for i in range(1,len(intervals)):
        if intervals[i][0] < intervals[i-1][1]: 
            overlap += 1 
            if overlap > max_overlaps: 
                max_overlaps = overlap 
        else: 
            overlap = 0 
    return max_overlaps + 1

