public class Probability {

    public static double calculateProbability(int n, int x) {
        int denominator = 1;
        //Calculating the denominator
        for (int i = n; i > 0; i--) {
            denominator *= i;
        }
        int numerator = 1;
        //Calculating the numerator
        for (int i = x; i > 0; i--) {
            numerator *= i;
        }
        //Calculating the probability
        double probability = (double) numerator / (double) denominator;
        return probability;
    }

    public static void main(String[] args) {
        //Flipping a coin 5 times
        int n = 5;
        //Number of heads
        int x = 3;
        System.out.println("Probability of getting 3 heads when a coin is flipped 5 times: "+calculateProbability(n, x));
    }
}

def AStar(start, goal, grid):
    openSet = {start}
    closedSet = set()
    cameFrom = {}

    gScore = {start: 0}
    fScore = {start: heuristic(start, goal)}

    while openSet:
        current = find_minimum(openSet, fScore)
        if current == goal:
            return reconstruct_path(cameFrom, current)
        openSet.remove(current)
        closedSet.add(current)

        for neighbor in get_neighbors(grid, current):
            if neighbor in closedSet:
                continue
            if neighbor not in openSet:
                openSet.add(neighbor)
            tentative_gScore = gScore[current] + 1

            if neighbor in gScore and tentative_gScore > gScore[neighbor]:
                continue

            cameFrom[neighbor] = current
            gScore[neighbor] = tentative_gScore
            fScore[neighbor] = gScore[neighbor] + heuristic(neighbor, goal)

    return "Failure"

