class Node {
    int data; // Data
    Node* next; // Pointer to the next node
 public:
    Node(int d) {
        data = d;
        next = NULL;
    }
    ~Node() {}
    // Setters
    void setData(int d) { data = d; }
    void setNext(Node* n) { next = n; }
    // Getters
    int getData() { return data; }
    Node* getNext() { return next; }
};

void push(Node** head_ref, int data) {
    Node* new_node = new Node(data);
