int findCombinations(int n, int k) 
{ 
    int C[n + 1][k + 1]; 
    int i, j; 

    // Calculating values of nC0 and nCn 
    for (i = 0; i <= n; i++) 
    { 
        C[i][0] = 1; 
        C[i][i] = 1; 
    } 

    // Calculating values of nCk from (nCk-1) 
    for (i = 2; i <= n; i++) 
        for (j = 1; j < i; j++) 
            C[i][j] = C[i - 1][j - 1] + C[i - 1][j]; 

    return C[n][k]; 
}

