def combinations_with_repetitions(my_array, k):
    # Edge case 
    if k == 0:
        return 0 

    # Base case 
    if k == 1:
        return len(my_array)

    # General case
    count = 0
    for i in range(len(my_array)):
        # Calculate combinations with repetitions for the remaining elements 
        count += combinations_with_repetitions(my_array[i+1:], k-1)
    return count

