def maximum_sum_non_adjacent_elements(arr):
    if len(arr) <= 2:
        return max(arr)

    even_sum = arr[0]
    odd_sum = max(arr[0], arr[1])

    for i in range(2, len(arr)):
        if i % 2 == 0:
            even_sum = max(odd_sum, even_sum + arr[i])
        else:
            odd_sum = max(even_sum, odd_sum + arr[i])

