public class PrimeSum {
    public int sumPrimes(int n) 
    { 
        boolean[] prime = new boolean[n + 1]; 
        Arrays.fill(prime, true); 

        for (int p = 2; p * p <= n; p++) { 
            if (prime[p] == true) { 
                for (int i = p * p; i <= n; i += p) 
                    prime[i] = false; 
            } 
        } 

        int sum = 0; 
        for (int p = 2; p <= n; p++) { 
            if (prime[p]) 
                sum += p; 
        } 

        return sum; 
    } 

    public static void main(String args[]) 
    { 
        int n = 10;
        System.out.println(sumPrimes(n)); 
    } 
}

