function searchSortedArray(arr, value) {
 let left = 0;
 let right = arr.length - 1;
 while (left <= right) {
  let mid = Math.floor((left + right) / 2);
  if (arr[mid] == value) {
   return mid;
  } else if (arr[mid] > value) {
   right = mid - 1;
  } else {
   left = mid + 1;
