// Function to find the kth smallest element in an unsorted array
int kthSmallest(int arr[], int left, int right, int k) 
{ 
    // If left is greater than right 
    if (left > right) 
        return -1; 

    // Find the mid element 
    int mid = (left + right) / 2; 

    // Check if the mid element is the kth smallest 
    if (arr[mid] == k) 
        return k; 

    // If the kth smallest is less than the mid element 
    else if (arr[mid] > k) 
        return kthSmallest(arr, left, mid-1, k); 

    // If the kth smallest is greater than the mid element 
    else
        return kthSmallest(arr, mid+1, right, k); 
}

