// Function to sort a stack in incrementing order
void sortStack(std::stack<int>& s) {
 // create an empty temporary stack
 std::stack<int> temp;

 // while input stack is not empty
 while (!s.empty()) {
  // pop an element from s
  int x = s.top();
  s.pop();

  // while temporary stack is not empty and top 
  // of stack is greater than x 
  while (!temp.empty() && temp.top() > x) {
   // pop from temporary stack and push 
   // it to the input stack 
   s.push(temp.top());
   temp.pop();
  }

  // push x to temporary stack
  temp.push(x);
 }

 // copy the elements from temp stack to orig stack
 while (!temp.empty()) {
  s.push(temp.top());
  temp.pop();
 }
}

