def findKSmallest(left, right, k):
    res = []
    i, j = 0, 0

    while i < len(left) and j < len(right) and len(res) < k:
        if left[i] <= right[j]:
            res.append(left[i])
            i += 1
        else:
            res.append(right[j])
            j += 1

    while i < len(left) and len(res) < k:
        res.append(left[i])  
        i += 1

    while j < len(right) and len(res) < k:
        res.append(right[j])  
        j += 1

    return res

fn is_palindrome(head: Option<Box<ListNode>>) -> bool {
    let mut slow = &head;
    let mut fast = &head;

    // Find middle of the list
    while let Some(ref node) = fast {
        fast = &node.next;
        if let Some(ref node) = fast {
            fast = &node.next;
            slow = &slow.as_ref().unwrap().next;
        }
    }

    // Reverse the list after middle
    let mut prev_node = None;
    let mut current_node = slow.take();
    while let Some(mut node) = current_node {
        current_node = node.next.take();
        node.next = prev_node;
        prev_node = Some(node);
    }

    // Compare the list from start to middle and from middle to end
    let mut left = &head;
    let mut right = &prev_node;
    while let (Some(ref l), Some(ref r)) = (left, right) {
        if l.val != r.val {
            return false;
        }
        left = &l.next;
        right = &r.next;
    }
    true
}

