def is_anagram(str_1, str_2):
    # check the lengths are equal
    if len(str_1) != len(str_2):
        return False

    # create a frequency dictionary for characters in str_1
    char_frequency = {}
    for ch in str_1:
        if ch in char_frequency:
            char_frequency[ch] += 1
        else:
            char_frequency[ch] = 1

    # check if the characters in str_2 have matching frequency
    for ch in str_2:
        if ch not in char_frequency or char_frequency[ch] == 0:
            return False
        else:
            char_frequency[ch] -= 1

    # all characters match
    return True

