class Heap(object): 
    def __init__(self): 
        self.heap_list = [] 
        self.length = 0

    def insert(self, item): 
        self.heap_list.append(item) 
        self.length += 1 
        self.heapify_up(self.length-1) 

    def heapify_up(self, index): 
        parent = (index-1) // 2 
        # Check max heap property
        if index > 0 and self.heap_list[index] > self.heap_list[parent]: 
            self.swap(index, parent) 
            self.heapify_up(parent) 

    def swap(self, i, j): 
        self.heap_list[i], self.heap_list[j] = self.heap_list[j], self.heap_list[i]

public class Sort { 

    // Function to sort an array of integers in ascending order 
    public static void sortAscending(int arr[]) { 
        int n = arr.length; 

        // One by one move boundary of unsorted subarray 
        for (int i = 0; i < n - 1; i++) { 
            // Find the minimum element in unsorted array 
            int min_idx = i; 
            for (int j = i + 1; j < n; j++) 
                if (arr[j] < arr[min_idx]) 
                    min_idx = j; 

            // Swap the found minimum element with the first 
            // element 
            int temp = arr[min_idx]; 
            arr[min_idx] = arr[i]; 
            arr[i] = temp; 
        } 
    } 

}

