fn rotate_array(arr: &[i32], k: i32) -> Vec<i32> {
 let mut result: Vec<i32> = Vec::new();
 let len = arr.len();
 let k = k % len;

 for i in 0..len {
 let idx = (i + k) % len;
 result.push(arr[idx]);
 }

 return result;
}

