function quickSort(arr) {
    if (arr.length <= 1){
        return arr;
      } 
    else {
        let pivot = arr[0];
        let left = [];
        let right = [];
        for (let i = 1; i < arr.length; i++){
            if (arr[i] < pivot){
                left.push(arr[i]);
            } 
            else {
                right.push(arr[i]);
            }
        }

        let sortedLeft = quickSort(left);
        let sortedRight = quickSort(right);
        let sortedArray = [].concat(sortedLeft, pivot, sortedRight);
        return sortedArray;
    }
}

