def rule_based_classification(data):
  # Create a set of rules for categorization
  rules = {
    'feature1': {'min': 0, 'max': 5},
    'feature2': {'value': [1, 2, 'X']}
  }
  predictions = []
  # Iterate through the data
  for sample in data:
    # Assume the sample belongs to the "low" category
    prediction = "low"
    # Iterate through the rules
    for feature, rule in rules.items():
      if isinstance(rule['value'], list):
        # If the value isn't in the list, then it doesn't belong to that category
        if sample[feature] not in rule['value']:
          prediction = "high"
      else:
        # If the value isn't in the given range, then it doesn't belong to that category
        if not (rule['min'] <= sample[feature] <= rule['max']):
          prediction = "high"
    # Append the prediction to the predictions list
    predictions.append(prediction)
  return predictions

