// Function for computing least squares
std::pair<double, double> leastSquares(std::vector<double> x, std::vector<double> y)
{
 int n = x.size();

 // Calculate sums
 double sumX = sum(x);
 double sumY = sum(y);
 double sumXY = 0;
 double sumX2 = 0;
 for(int i = 0; i < n; i++)
 {
  sumXY += (x[i]*y[i]);
  sumX2 += (x[i]*x[i]);
 }

 // Calculate slope and y-intercept
 double slope = (n*sumXY - sumX*sumY) / (n*sumX2 - sumX*sumX);
 double intercept = (sumY - slope*sumX) / n;

 return std::make_pair(slope, intercept);
}

