 let mut j = 0;
 while i < arr1.len() && j < arr2.len() {
 if arr1[i] > arr2[j] {
 merged.push(arr2[j]);
 j += 1;
 } else {
 merged.push(arr1[i]);
 i += 1;
 }
 }
 while i < arr1.len() {
 merged.push(arr1[i]);
 i += 1;
 }
 while j < arr2.len() {
