public class SecondMostFrequentCharacter{
    public static char getSecondMostFrequentCharacter(String str){
        int max = 0;
        int secondMax = 0;
        char maxChar = ' ';
        char secondMaxChar = ' ';

        char[] arr = str.toCharArray();

        for(int i = 0; i < arr.length; i++){
            int count = 1;
            for(int j = i+1; j < arr.length; j++){
                if(arr[i] == arr[j])
                    count += 1;
            }

            if(count > max){
                secondMax = max;
                max = count;
                secondMaxChar = maxChar;
                maxChar = arr[i];
            }
            else if(count > secondMax){
                secondMax = count;
                secondMaxChar = arr[i];
            }
        }
        return secondMaxChar;
    }

    public static void main(String args[]){
        String str = "abbacccceeeee";
        System.out.println(getSecondMostFrequentCharacter(str)); // Output: c 
    }
}

