 private static class ClientThread extends Thread {
 Socket client;
 Set<String> userNames;

 ClientThread(Socket client, Set<String> userNames) {
 this.client = client;
 this.userNames = userNames;
 }

 @Override
 public void run() {

 String name = "";

 try (Scanner in = new Scanner(client.getInputStream());
PrintStream out = new PrintStream(client.getOutputStream())) {

 // read name until we get a valid one
 while (true) {
 out.println("Enter your name: ");
 name = in.nextLine().trim();

 if (name.isEmpty())
 continue;

 if (userNames.contains(name)) {
 out.println("Name already in use, please choose another");
 }
 else
 break;
 }

 out.println("Welcome " + name + "!");
 userNames.add(name);

 out.println("Now Online: " + userNames);

 String message = "";

 // read messages from the user
 while (true) {
 message = in.nextLine();

 if (message.equalsIgnoreCase("exit"))
 break;

 // broadcast the message
 for (PrintStream clientout : clients) {
 clientout.println(name + ": " + message);
 }
 }

 userNames.remove(name);
 out.println(" now offline.. ");

 for (PrintStream clientout : clients) {
