def spiralize(array):
    """Returns the spiral version of a two-dimensional array."""
    spiral_array = []
    while array:
        # Add top row
        spiral_array += array.pop(0)
        # Add right column
        if array:
            for row in array:
                spiral_array.append(row.pop(-1))
        # Add bottom row
        if array:
            spiral_array += array.pop().reverse()
        # Add left column
        if array:
            for row in array.reverse():
                spiral_array.append(row.pop(0))
    return spiral_array

