public class LongestPalindrome {

  public static void main(String[] args) {
    String input = "abcbad";

    // Find the longest palindrome
    String output = "";

    boolean[] used = new boolean[input.length()];

    // Iterate through the input string
    for (int i=input.length()-1; i>=0; i--) {
      // Check for existing palindromes
      if (isPalindrome(input, used, i)) {
        output = input.substring(0, i+1);
        break;
      }

      // Maintain an array to keep track of the used characters
      used[i] = true;
    }

    // Print the longest palindrome
    System.out.print(output);
  }

  // Check if the string is a palindrome
  public static boolean isPalindrome(String input, boolean[] used, int endIndex) {
    int startIndex = 0;

    while (startIndex < endIndex) {
      if (input.charAt(startIndex) != input.charAt(endIndex)) {
        return false;
      }

      if (!used[startIndex]) {
        startIndex++;
      }

      if (!used[endIndex]) {
        endIndex--;
      }
    }

    return true;
  }

}

