class Game:
    def __init__(self):
        self.board = [' '] * 9 # list of spaces (each space is indexed 0-8)
        self.player = 'X'

    def put_marker(self, marker, pos):
        self.board[pos] = marker

    def swap_player(self):
        if self.player == 'X':
            self.player = 'O'
        else:
            self.player = 'X'

    def check_winner(self):
        win_cond = [(0,1,2), (3,4,5), (6,7,8), (0,3,6),(1,4,7), (2,5,8), (0,4,8), (2,4,6)]
        for cond in win_cond:
            if self.board[cond[0]] == self.board[cond[1]] == self.board[cond[2]] == self.player:
                return True
        return False

    def check_tie(self):
        used_spaces = 0
        for i in self.board:
            if i == 'X' or i == 'O':
                used_spaces += 1
        if used_spaces == 9:
            return True
        return False

    def display(self):
        print(" {} | {} | {} ".format(self.board[6], self.board[7], self.board[8]))
        print("---|---|---")
        print(" {} | {} | {} ".format(self.board[3], self.board[4], self.board[5]))
        print("---|---|---")
        print(" {} | {} | {} ".format(self.board[0], self.board[1], self.board[2]))

    def play(self):
        self.display()
        while True:
            pos = int(input("Enter position (1-9): "))-1
            self.put_marker(self.player, pos)
            if self.check_winner() == True:
                self.display()
                print("{} won!".format(self.player))
                break
            elif self.check_tie() == True:
                self.display()
                print("It's a tie")
                break
            self.swap_player()
            self.display()

