use std::cmp::min;

fn find_closest_match(input_str: &str, str_list: &[&str]) -> &str {
 let mut min_dist = std::usize::MAX;
 let mut closest_match = "";

 for s in str_list {
  let dist = levenshtein_distance(input_str, s);
  if dist < min_dist {
   closest_match = s;
   min_dist = dist;
  }
 }

 return closest_match;
}


fn levenshtein_distance(s1: &str, s2: &str) -> usize {
 let n = s1.len();
 let m = s2.len();
 let mut dp = vec![vec![0; m + 1]; n + 1];

 for i in 0..=n {
  dp[i][0] = i;
 }
 for j in 0..=m {
  dp[0][j] = j;
 }

 for i in 1..=n {
  for j in 1..=m {
   dp[i][j] = min(dp[i - 1][j] + 1, dp[i][j - 1] + 1);

   if s1.chars().nth(i - 1) == s2.chars().nth(j - 1) {
    dp[i][j] = min(dp[i][j], dp[i - 1][j - 1]);
   } else {
    dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + 1);
   }
  }
 }

 return dp[n][m];
}

