// Function to determine if a given word is a palindrome
bool isPalindrome(char str[])
{
    // pointer to start of the string
    char* start = str;

	// pointer to end of the string    
    char* end = start + strlen(str) - 1;

    while (end > start) {
        // compare characters while moving pointers
        // towards each other
        if (*start++ != *end--)
            return false;
    }
    return true;
}

