function convertToWords(num) {
    let ones = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 
        'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve', 'thirteen', 
        'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
    let tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 
        'eighty', 'ninety'];
    let words = "";

    if (num == 0) {
        return ones[num];
    } else if (num < 0) {
        words += "minus";
    }

    let divider = num;
    let counter = 0;

    while (divider > 0) {
        let modulus = divider % 10;
        divider = Math.floor(divider / 10);

        if (counter == 0) {
            words += ones[modulus];
        } else if (counter == 1) {
            words = tens[modulus] + " " + words;
        } else if (counter == 2) {
            words = ones[modulus] + " hundred " + words;
        }

        counter++;
    }

    return words;
}

