def run_query(query):
    headers = {
    'Content-Type': 'application/json',
    }
    auth = (WATSON_USERNAME, WATSON_PASSWORD)

    data = {
        'text': query,
        'features': {
            'entities': {
                'sentiment': True,
            },
            'keywords': {
                'sentiment': True,
            },
            'intents': True
        }
    }

    response = requests.post(
        WATSON_ENDPOINT,
        headers=headers,
        auth=auth,
        data=json.dumps(data))

    response_data = response.json()
    intent = response_data['intents'][0]['intent']
    entities = response_data['entities']
    keywords = response_data['keywords']
    return intent, entities, keywords

