    print('Entities:')
    for entity in entities:
        print(f'\t{entity["text"]}: {entity["type"]}')
    print('Keywords:')
    for keyword in keywords:
        print(f'\t{keyword["text"]}: {keyword["sentiment"]["label"]}')

