function intToRoman(P) { 
  // storing roman values of digits from 0-9    
  var roman_values = ["", "I", "II", "III", "IV", "V",  
                      "VI", "VII", "VIII", "IX"]; 

  // converting to roman 
  var thousands = Math.floor(P / 1000); 
  var hundreds = Math.floor((P % 1000) / 100); 
  var tens = Math.floor(((P % 1000) % 100) / 10); 
  var ones = Math.floor(((P % 1000) % 100) % 10); 

  let romanNumber = 'M'.repeat(thousands) + roman_values[hundreds] +  
                            roman_values[tens] + roman_values[ones]; 

  // Return result 
  return romanNumber; 
} 

