def maxdistance(x): 
    # Initialize max distance 
    max_distance = 0

    for i in range(0, len(x)):
        for j in range(i + 1, len(x)):
            # Find the current distance between two elements
            d = abs(x[i] - x[j])
            # Update the maximum distance 
            if max_distance < d: 
                max_distance = d

    return max_distance

function bubbleSort(arr) {
    var len = arr.length;
    for (var i = 0; i < len; i++) {
        for (var j = 0; j < len; j++) {
            if (arr[j] > arr[j + 1]) {
                var temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
    return arr;
}

