import java.util.ArrayList;
import java.util.Collections;

public class PalindromeChecker {
    public static void main(String args[]) {
        int min_range = 1000; // minimum number of range
        int max_range = 2000; // maximum number of range
        ArrayList<Integer> palindrome_nos = new ArrayList<Integer>(); //List to store palindrome numbers

        for (int i = min_range;i <= max_range;i++)
        {
            String no = Integer.toString(i); // convert to string
            String reverse = ""; // empty string

            // reverse the string to check for palindrome number
            for (int j = no.length()-1;j >= 0;j--)
            {
                reverse = reverse + no.charAt(j);
            }

            // check if reverse equals original
            if (reverse.equals(no))
            {
                palindrome_nos.add(i); // add to list
            }
        }

        if (palindrome_nos.size()!= 0) 
        {
            System.out.println("The largest palindrome no from the given range is:" );
            System.out.println(Collections.max(palindrome_nos));
        }
        else
        {
            System.out.println("No palindrome numbers found in the given range!");
        }
    }
}

