def quickSort(list): 
    if len(list) <= 1:
        return list
    pivot = list[0]
    lessThanPivot = [i for i in list[1:] if i < pivot]
    greaterThanPivot = [i for i in list[1:] if i > pivot]
    return quickSort(lessThanPivot) + [pivot] + quickSort(greaterThanPivot)

