def find_shortest_route(matrix, start, end):
    queue = collections.deque([[start]])
    visited = set()

    while queue:
        path = queue.popleft()
        node = path[-1]

        if node == end: 
            return path

        for next_node in matrix[node]:
            if next_node not in visited:
                queue.append(path + [next_node])
                visited.add(next_node)

    return []

