    public static String palindromeString(String str)
    {
        // Find the required answer
        String ans = str; 
        int n = str.length();


        // Append first half of the string
        // in reverse order
        for (int i = n-1; i >= 0; i--)
            ans += str.charAt(i);

        return ans;
    }  

