package main

import (
    "fmt"
    "encoding/json"
    "io/ioutil"
)

type ToDo struct {
    Tasks []string
}

func NewToDo() ToDo {
    return ToDo{Tasks: []string{}}
}

func (t ToDo) Create(task string) {
    t.Tasks = append(t.Tasks, task)
}

func (t ToDo) Delete(task string) {
    for i, t := range t.Tasks {
        if t == task {
            t.Tasks = append(t.Tasks[:i], t.Tasks[i+1:]...)
            break
        }
    }
}

func (t ToDo) List() []string {
return t.Tasks
}

func (t ToDo) Save() error {
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }

    err = ioutil.WriteFile("todos.json", b, 0644)
    if err != nil {
        return err
    }

    return nil
}

func (t *ToDo) Load() error {
    b, err := ioutil.ReadFile("todos.json")
    if err != nil {
        return err
    }

    err = json.Unmarshal(b, &t)
    if err != nil {
        return err
    }

    return nil
}

func main() {
    t := NewToDo()
    t.Create("Learn Go")
    t.Create("Learn React")
    fmt.Println(t.List())
    t.Delete("Learn Go")
    fmt.Println(t.List())
    err := t.Save()
    if err != nil {
        fmt.Println("Error saving todos:", err)
    }

    t2 := NewToDo()
    err = t2.Load()
    if err != nil {
        fmt.Println("Error loading todos:", err)
    }
    fmt.Println(t2.List())
}

