import math

def closest_pair(set1, set2):
    min_dist = float("inf")
    for (x1,y1) in set1:
        for (x2, y2) in set2:
            dist = math.sqrt((x2-x1)**2 + (y2-y1)**2)

            if dist < min_dist:
                min_dist = dist
                closest_pair = (x1, y1), (x2, y2)

    return min_dist, closest_pair

