class Heap: 
    def __init__(self): 
        self.heap_list = [] 

    def insert(self, num): 
        self.heap_list.append(num) 
        self.heapify() 

    def heapify(self): 
        count = len(self.heap_list) - 1
        last_parent = (count - 1)//2
        for i in range(last_parent, -1, -1): 
            self.swap_down(i) 

    def swap_down(self, i): 
        lc = self.left_child(i) 
        rc = self.right_child(i)
        if lc > len(self.heap_list) - 1: 
            return

        if rc > len(self.heap_list) - 1: 
            max_index = lc 
        else: 
            if self.heap_list[lc] > self.heap_list[rc]:  
                max_index = lc 
            else: 
                max_index = rc 

        if self.heap_list[i] < self.heap_list[max_index]: 
            self.swap(i, max_index) 
            self.swap_down(max_index)

