// Function to sort array using insertion sort
void insertionSort(int arr[], int n)
{
    int i, j, k;
    for (i = 1; i < n; i++) {
        k = arr[i];
        j = i - 1;

        while (j >= 0 && arr[j] > k) {
            arr[j + 1] = arr[j];
            j = j - 1;
        }
        arr[j + 1] = k;
    }
}

// Driver code
int main()
{
    int arr[] = {7, 4, 5, 9, 8, 2};
    int n = sizeof(arr) / sizeof(arr[0]);

    insertionSort(arr, n);

