def find_number_index(lst, target):
    lower_bound = 0
    upper_bound = len(lst) - 1
    while lower_bound <= upper_bound:
        mid = (lower_bound + upper_bound) // 2
        if lst[mid] == target:
            return mid
        elif lst[mid] > target:
            upper_bound = mid - 1
        else:
            lower_bound = mid + 1
    return -1

