int power(int x, int y) 
{ 
    if (y == 0) 
        return 1; 
    else if (y % 2 == 0) 
        return power(x, y / 2) * power(x, y / 2); 
    else
        return x * power(x, y / 2) * power(x, y / 2); 
} 

int order(int x) 
{ 
    int n = 0; 
    while (x > 0) 
    { 
        n++; 
        x = x / 10; 
    } 
    return n; 
} 

bool Arm(int x, int n) 
{ 
    int sum = 0, t = x; 
    while (t > 0) 
    { 
        int r = t % 10; 
        sum += power(r, n); 
        t = t / 10; 
    } 

    return (sum == x); 
} 

