def shorten_sentence(sentence):
  words = sentence.split()
  new_words = []
  for word in words:
    if len(word) > 4:
      new_words.append(re.sub(r'(?!^)[A-Za-z]', '', word))
    else:
      new_words.append(word)

  return ' '.join(new_words)  

