// Function to determine the number of days between two dates
int getNumDaysBetween(std::string date1, std::string date2) { 
    // Convert given dates in proper format
    std::tm d1 = {};
    std::istringstream(date1) >> std::get_time(&d1, "%m/%d/%Y");

    std::tm d2 = {};
    std::istringstream(date2) >> std::get_time(&d2, "%m/%d/%Y");

    // Find time difference
    time_t seconds_since_epoch = std::difftime(mktime(&d2), mktime(&d1));
    int days_between_dates = seconds_since_epoch / (60 * 60 * 24);

    return days_between_dates;
}

