def calculate_frequency(sentence):
	# creating an empty dictionary
    freq = {}
	# splitting the sentence into words
    words = sentence.split()

	# iterating over each word
    for word in words:
		# check if the word is already present in the dictionary
        if word not in freq:
			# if not present initializing it to 1
            freq[word] = 1
        else:
			# if present, increment it by 1
            freq[word]+=1

	#return the result
    return freq

