// A function to implement selection sort
void selectionSort(int arr[], int n)
{
    // pos_min is short for position of min
    int pos_min, temp;

    // bBucl through all founds
    for (int i=0; i < n-1; i++)
    {
        // Set pos_min to this position
        pos_min = i;

        // Check the rest of the elements
        for (int j=i+1; j < n; j++)
        {
            // If this element is less, then it is the new minimum
            if (arr[j] < arr[pos_min])
                   pos_min=j;
        }

        // If the minimum_position is different than the current position,swap them
        if (pos_min != i)
        {
             temp = arr[i];
             arr[i] = arr[pos_min];
             arr[pos_min] = temp;
        }
    }
}

