object MergeSort {
  def merge(a: Array[Int], b: Array[Int]): Array[Int] = {
    val c = Array.ofDim[Int](a.length + b.length)
    var i = 0
    var j = 0
    for (k <- 0 until c.length) {
      if (i == a.length || j == b.length)
        if (i == a.length) c(k) = b(j)
        else c(k) = a(i)
      else if (a(i) < b(j)) {
        c(k) = a(i)
        i += 1
      } else {
        c(k) = b(j)
        j += 1
      }
    }
    c
  }
}

