def two_sum(arr, target):
    # check to make sure the list is long enough to have a solution
    if len(arr) < 2:
        return False

    # create a dictionary to store processed numbers
    processed = {}
    for i in range(0, len(arr)):
        # compute the difference with the target and the current number
        difference = target-arr[i]
        if difference in processed:
            # if we have seen the difference before, solution is found
            return (processed[difference], i)
        else:
            # if not, add the current number to the processed list
            processed[arr[i]] = i

public class MinHeap {
 private int[] heap;
 private int size;

 public MinHeap (int capacity) {
  this.heap = new int[capacity];
  this.size = 0;
 }

 public void add (int item) {
  if (size >= heap.length) {
   throw new IllegalStateException("Heap is full!");
  }
  heap[size] = item;
  size++;
  bubbleUp();
 }

 public int remove () {
  if (size == 0) {
   throw new IllegalStateException("Heap is empty!");
  }
  int min = heap[0];
  heap[0] = heap[size - 1];
  size--;
  bubbleDown();
  return min;
 }

 private void bubbleUp () {
  int index = size - 1;
  while (hasParent(index) && parent(index) > heap[index]) {
   swap(index, parentIndex(index));
   index = parentIndex(index);
  }
 }

 private void bubbleDown () {
  int index = 0;
  while (hasLeftChild(index)) {
   int smallerChildIndex = leftChildIndex(index);
   if (hasRightChild(index) && rightChild(index) < leftChild(index)) {
    smallerChildIndex = rightChildIndex(index);
   }
   if (heap[index] < heap[smallerChildIndex]) {
    break;
   } else {
    swap(index, smallerChildIndex);
   }
   index = smallerChildIndex;
  }
 }

 private boolean hasParent (int i) {
  return i > 0;
 }

 private int parent (int i) {
  return heap[parentIndex(i)];
 }

 private int parentIndex (int i) {
  return (i - 1) / 2;
 }

 private int leftChildIndex (int i) {
  return (i * 2) + 1;
 }

 private int rightChildIndex (int i) {
  return (i * 2) + 2;
 }

 private boolean hasLeftChild (int i) {
  return leftChildIndex(i) < size;
 }

 private boolean hasRightChild (int i) {
  return rightChildIndex(i) < size;
 }

 private int leftChild (int i) {
  return heap[leftChildIndex(i)];
 }

 private int rightChild (int i) {
  return heap[rightChildIndex(i)];
 }

 private void swap (int index1, int index2) {
  int temp = heap[index1];
  heap[index1] = heap[index2];
  heap[index2] = temp;
 }
}

def is_safe(board, row, col): 
    """Check if it is safe to place a queen at board[row][col]"""

    # Check this row on left side 
    for i in range(col): 
        if board[row][i] == 1: 
            return False

    # Check upper diagonal on left side 
    for i,j in zip(range(row,-1,-1), range(col,-1,-1)): 
        if board[i][j] == 1: 
            return False

    # Check lower diagonal on left side 
    for i,j in zip(range(row,N,1), range(col,-1,-1)): 
        if board[i][j] == 1: 
            return False        
    return True

def place_queen(board, col):
    """Use backtracking to find all possible solutions of N Queen problem""" 
    # If all queens are placed 
    if col == N:
        return True

    # Consider this column and attempt to place this queen in all rows 
    for i in range(N):
        if is_safe(board, i, col)==True: 
            # Place this queen in board[i][col] 
            board[i][col] = 1
            # Recur to place rest of the queens 
            if place_queen(board, col + 1) == True: 
                 return True
            # If placing queen in board[i][col] doesn't lead to a solution 
            board[i][col] = 0 
    # If the queen cannot be placed in any row in this colum col, then return false 
    return False

