func convertRomanNumeral(romanNumeral: String) -> Int {
 let romanValues = ["I": 1, "V": 5, "X": 10, "L":50, "C": 100, "D": 500, "M": 1000];
 var result = 0;

 // Iterate the characters in reverse order
 for i in (0..<romanNumeral.count).reversed() {
 let c = String(romanNumeral[romanNumeral.index(romanNumeral.startIndex, offsetBy: i)]);

// If the current character is larger than or equal to the previous one
 // it should be added, otherwise it should be subtracted
 if i == 0 || romanValues[c]! >= romanValues[String(romanNumeral[romanNumeral.index(romanNumeral.startIndex, offsetBy: i - 1)])]! {
 result += romanValues[c]!;
 } else {
 result -= romanValues[c]!;
 }
 }

return result;
}

