def huffman_encoding(text): 
    # Creating a dictionary of frequencies of characters in text 
    freq_dict = {} 
    for char in text: 
        if char not in freq_dict.keys(): 
            freq_dict[char] = 0
        freq_dict[char] += 1

    # Creating a MinHeap 
    from queue import PriorityQueue 
    minHeap = PriorityQueue() 

    # Adding frequencies of characters to minHeap 
    for key in freq_dict: 
        minHeap.put((freq_dict[key], key))    

    # Building the Huffman tree 
    while (minHeap.qsize()>1): 
        leftChar =  minHeap.get() 
        rightChar = minHeap.get() 
        for char in leftChar[1:] + rightChar[1:]: 
            if char not in freq_dict.keys(): 
                freq_dict[char]=0
            freq_dict[char] +=1 
        minHeap.put((leftChar[0]+rightChar[0], leftChar[1]+rightChar[1])) 

    # Tracing the code (binary) 
    code = "" 
    while (minHeap.qsize()): 
        tinyheap = minHeap.get() 
        char = tinyheap[1] 
        freq = tinyheap[0] 
        code += ("1"+char[0]+"0"*(len(char)-1)) 
        c = 0
        for ch in char: 
            freq_dict[ch] = ("1"+code[::-1][c:c+len(char)][::-1]) 
            c += len(char) 

    # Inserting in dictionary 
    huffmanCode = {} 
    for key in freq_dict: 
        huffmanCode[key] = freq_dict[key] 

    return huffmanCode

