def sort(sequence): 
    length = len(sequence) 
    for i in range(length): 
        min_idx = i 
        for j in range(i+1, length): 
            if sequence[min_idx] > sequence[j]: 
                min_idx = j 
        sequence[i], sequence[min_idx] = sequence[min_idx], sequence[i] 

    return sequence 

