def is_anagram(s1, s2): 
    if len(s1) != len(s2): 
        return False 

    s1_dict = {} 
    for letter in s1: 
        if letter in s1_dict: 
            s1_dict[letter] += 1
        else: 
            s1_dict[letter] = 1

    s2_dict = {} 
    for letter in s2: 
        if letter in s2_dict: 
            s2_dict[letter] += 1 
        else: 
            s2_dict[letter] = 1

    if s1_dict == s2_dict: 
        return True 
    return False

