// Function to print prime numbers 
void printPrime(int limit) 
{ 
	bool isPrime; 

	for (int i = 2; i <= limit; i++) 
	{ 
		isPrime = true; 

		for (int j = 2; j*j <= i; j++) 
		{ 
			if (i % j == 0) 
			{ 
				isPrime = false; 
				break; 
			} 
		} 

		// Print the number if prime 
		if (isPrime) 
			cout << i << " "; 
	} 
} 

