int maxSubArraySum(int arr[], int n) 
{ 
    int max_so_far = arr[0]; 
    int curr_max = arr[0]; 

    for (int i = 1; i < n; i++) 
    { 
        curr_max = max(arr[i], curr_max+arr[i]); 
        max_so_far = max(max_so_far, curr_max); 
    } 
    return max_so_far; 
} 

int main() 
{ 
    int arr [] = {2, 3, -2, 4, -3}; 
    int n = sizeof(arr)/sizeof(arr[0]); 
    int max_sum = maxSubArraySum(arr, n); 
    cout << "Maximum sum of the subarray is: " << max_sum << endl; 
    return 0; 
}

public class Node {
    int data;
    Node left;
    Node right;

    public Node(int data){
        this.data = data;
        left = null;
        right = null;
    }
}

public Node findFirstCommonAncestor(Node root, int node1, int node2){
    if(root == null){
        return null;
    }

    if(root.data == node1 || root.data == node2){
        return root;
    }

    Node leftResult = findFirstCommonAncestor(root.left, node1, node2);
    Node rightResult = findFirstCommonAncestor(root.right, node1, node2);

    if(leftResult != null && rightResult != null){
        return root;
    }
    if(leftResult != null){
        return leftResult;
    }
    return rightResult;
}

