    let barWidth = size/CGFloat(values.count)
    let margin = barWidth/2
    var startX = CGFloat(0)
    for value in values {
        let barHeight = size * CGFloat(value) / CGFloat(maxValue)
        let x = startX + margin
        let y = height - barHeight
        let rect = CGRect(x: x, y: y, width: barWidth, height: barHeight)
        drawBar(rect: rect, context: context)
        startX = startX + barWidth
    }
