// A function to check if parentheses are balanced 
function areParenthesesBalanced(str) { 
 let stack = []; 
 let open = { '{':'}', '[':']', '(':')' };
 let closed = { '}':true, ']':true, ')':true }; 

 for (let i = 0; i < str.length; i++) { 
 let item = str[i]; 
 if (open[item]) { 
 stack.push(item); 
 } else if (closed[item]) { 
 if (open[stack.pop()] !== item) return false; 
 } 
 } 
 return stack.length === 0; 
}

def fibonacci(n):
