import React from 'react';
import {render} from 'react-dom';
import {createStore} from 'redux';
import {Provider, connect} from 'react-redux';

// Actions
const ADD_TODO = 'ADD_TODO';
const REMOVE_TODO = 'REMOVE_TODO';
const TOGGLE_TODO = 'TOGGLE_TODO';

// Action Creators
const addTodo = (text) => ({
 type: ADD_TODO,
 text
});

const removeTodo = (index) => ({
 type: REMOVE_TODO,
 index
});

const toggleTodo = (index) => ({
 type: TOGGLE_TODO,
 index
});

// Reducer
const reducer = (state = [], action) => {
 switch (action.type) {
  case ADD_TODO:
   return [...state, {text: action.text, completed: false}];
  case REMOVE_TODO:
   return state.filter((todo, index) => index !== action.index);
  case TOGGLE_TODO:
   return state.map((todo, index) =>
    index === action.index ? {...todo, completed: !todo.completed} : todo
   );
  default:
   return state;
 }
};

// Store
const store = createStore(reducer);

// Presentational Components: todos
const Todos = (props) => (
 <ul>
  {props.todos.map((todo, index) => (
   <li key={index}>
    <span style={{textDecoration: todo.completed ? 'line-through' : ''}}>
     {todo.text}
    </span>
    <button onClick={() => props.removeTodo(index)}>X</button>
    <button onClick={() => props.toggleTodo(index)}>Toggle</button>
   </li>
  ))}
  <li>
   <input
    type='text'
    placeholder='Add new todo'
    onKeyDown={(e) => {
     if (e.keyCode === 13) {
      props.addTodo(e.target.value);
      e.target.value = '';
     }
    }}
   />
  </li>
 </ul>
);

// Container Components
const mapStateToProps = (state) => ({
 todos: state
});

const mapDispatchToProps = (dispatch) => ({
 addTodo: (text) => dispatch(addTodo(text)),
 removeTodo: (index) => dispatch(removeTodo(index)),
 toggleTodo: (index) => dispatch(toggleTodo(index))
});

const TodosContainer = connect(mapStateToProps, mapDispatchToProps)(Todos);

// App
const App = () => (
 <Provider store={store}>
  <TodosContainer />
 </Provider>
);

render(<App />, document.getElementById('root'));

