Function to compare two strings and list all the differences
"""

def compare_strings(str1,str2):
    differences = []
    if len(str1) < len(str2):
        min_length = len(str1)
    else:
        min_length = len(str2)

    for i in range(min_length):
        if str1[i] != str2[i]:
            differences.append([i, str1[i], str2[i]])

    if len(str1) != len(str2):
        differences.append([len(str1),"",""] if len(str1) > len(str2) else [len(str2),"",""]) 

    return differences

