{ 
    int x = 5, y = 3; 
    printf("Before Swap\nx = %d\ny = %d\n", x, y); 

    // Calling swap function 
    swapWithoutTemp(&x, &y); 

    printf("After Swap\nx = %d\ny = %d", x, y); 

    return 0; 
}

