def countPrimes(n):
    if n <= 1:
        return 0

    count = 0
    for i in range(2, n):
        for j in range(2, i):
            if i % j == 0:
                break
        else:
            count += 1
    return count

import java.util.Stack;

public class EquationParser {

 public double parse(String equation) {
 equation = equation.replaceAll(" ", "");
 Stack<Character> operatorStack = new Stack<>();
 Stack<Double> operandStack = new Stack<>();
 int start = 0;
 for (int i = 0; i < equation.length(); i++) {
 char c = equation.charAt(i);
 if (c == '+' || c == '-' || c == '*' || c == '/' || c == '(' || c == ')') {
 String operand = equation.substring(start, i);
 // push the previous operand onto the stack if it isn't empty
 if (!operand.isEmpty()) {
 operandStack.push(Double.parseDouble(operand));
 }
 // push the current operator onto the stack
 operatorStack.push(c);
 start = i+1;
 }
 }
 // push the last operand onto the stack
 String operand = equation.substring(start);
 if (!operand.isEmpty()) {
 operandStack.push(Double.parseDouble(operand));
 }
 // evaluate the equation
 while (!operatorStack.isEmpty()) {
 double operand1 = operandStack.pop();
 double operand2 = operandStack.pop();
 char operator = operatorStack.pop();
 double result = 0;
 switch (operator) {
 case '+':
 result = operand1 + operand2;
 break;
 case '-':
 result = operand1 - operand2;
 break;
 case '*':
 result = operand1 * operand2;
 break;
 case '/':
 result = operand1 / operand2;
 break;

 }
 operandStack.push(result);
 }
 return operandStack.peek();
 }

