void printFibonacciSeriesReverse(int n) 
{ 
    int t1 = 0, t2 = 1, nextTerm = 0; 

    cout << "The Fibonacci Series in reverse is: \n"; 

    int arr[n]; 

    // Store the Fibonacci numbers in an array 
    for (int i = 1; i <= n; ++i) { 
        if (i == 1) { 
            arr[i - 1] = t1; 
            continue; 
        } 
        if (i == 2) { 
            arr[i - 1] = t2; 
            continue; 
        } 
        nextTerm = t1 + t2; 
        t1 = t2; 
        t2 = nextTerm; 

        arr[i - 1] = nextTerm; 
    } 

    // Print the numbers from the array in reverse order 
    for (int i = n - 1; i >= 0; --i) 
        cout << arr[i] << " ";
} 

int main() 
{ 
    int n;
    cout<<"Enter the number of terms you want: ";
    cin>>n; 
    printFibonacciSeriesReverse(n); 
    return 0; 
}

