    for i in range(len(words) -1):
        w1 = words[i]
    if w1 in markov:
        markov[w1].append(words[i+1])
    else:
        markov[w1] = [words[i+1]]

    current_word = words[0]
    output = current_word
    for i in range(20):
        if current_word in markov:
            next_word = random.choice(markov[current_word])
            output += ' ' + next_word
            current_word = next_word
        else:
            current_word = random.choice(words)
            output += ' ' + current_word
    return output

