import java.nio.ByteBuffer;
import java.nio.IntBuffer;

public class ServoMotorControl {

 private UsbManager mUsbManager;
 private UsbDevice mServoMotorDevice;

 private static final int REQUEST_CONTROL_MSG_SET_POSITION = 0x10;
 private static final int REQUEST_CONTROL_MSG_ENABLE = 0x11;
 private static final int REQUEST_CONTROL_MSG_DISABLE = 0x12;

 public ServoMotorControl(UsbManager usbManager) {
  mUsbManager = usbManager;
 }

 public void open() {
  mServoMotorDevice = mUsbManager.getDeviceList().values().stream()
    .filter(u -> u.getVendorId() == 1234 && u.getProductId() == 5678)
    .findFirst()
    .orElse(null);
 }

 public void close() {
  mServoMotorDevice.close();
 }

 public void setPosition(int pos) {
  ByteBuffer buffer = ByteBuffer.allocate(4);
  buffer.putInt(pos);
  mServoMotorDevice.controlTransfer(
   UsbConstants.USB_DIR_OUT | UsbConstants.USB_TYPE_VENDOR,
   REQUEST_CONTROL_MSG_SET_POSITION, 0, 0, buffer.array(), 4, 1000);
 }

 public void enable() {
  mServoMotorDevice.controlTransfer(
   UsbConstants.USB_DIR_OUT | UsbConstants.USB_TYPE_VENDOR,
   REQUEST_CONTROL_MSG_ENABLE, 0, 0, null, 0, 1000);
 }

 public void disable() {
  mServoMotorDevice.controlTransfer(
   UsbConstants.USB_DIR_OUT | UsbConstants.USB_TYPE_VENDOR,
   REQUEST_CONTROL_MSG_DISABLE, 0, 0, null, 0, 1000);
 }

}

