         if char.isupper():
             if char_code > ord('Z'): 
                 char_code -= 26 
             elif char_code < ord('A'): 
                 char_code += 26 
         elif char.islower(): 
             if char_code > ord('z'): 
                 char_code -= 26 
             elif char_code < ord('a'): 
