def find_roots(a, b, c):
    discriminant = b ** 2 - 4 * a * c  
    if(discriminant > 0):
        root1 = (-b + sqrt(discriminant)) / (2 * a)
        root2 = (-b - sqrt(discriminant)) / (2 * a)
        return root1, root2
    elif(discriminant == 0):
        return -b / (2 * a)
    else:
        return "No real roots"

