import java.util.*;

class BFS{

    // Stores visited nodes
    public static Set<Integer> visited;

    public static void bfs(int src, ArrayList<ArrayList<Integer>> graph, int V)  
    {
        // To store the nodes to be traversed
        Queue<Integer> queue = new LinkedList<>();    

        // Adding the source node to the queue
        queue.add(src);

        // Adding the source to the visited set
        visited.add(src);

        // Traversing the queue
        while(!queue.isEmpty()) {
            // Pop the first element from the queue
            Integer node = queue.poll();

            // Get all the adjoining nodes from the graph
            ArrayList<Integer> neighbors = graph.get(node);

            // Traverse all the neighboring nodes
            for (Integer neighbor: neighbors) {
                // Add neighbors to the queue if not visited
                if (!visited.contains(neighbor)) {
                    queue.add(neighbor);
                    visited.add(neighbor);
                }
            }
        }
    }
}

