def generate_prime_nums(n):
    #create an empty list
    prime_nums = []

    # create first prime number
    current_num = 2

    # Keep looping until given number of prime numbers is achieved
    while len(prime_nums) < n:
        isPrime = True
        for num in range(2, current_num):
            if current_num % num == 0:
                isPrime = False
                break
        if isPrime:
            prime_nums.append(current_num)
        current_num += 1
    return prime_nums

