def leastCommonAncestor(root, p, q): 
	if root is None: 
		return None
	if root == p or root == q: 
		return root 
	left_lca = leastCommonAncestor(root.left, p, q) 
	right_lca = leastCommonAncestor(root.right, p, q) 
	if left_lca and right_lca: 
		return root 
	else: 
		return left_lca if left_lca is not None else right_lca

