def closestPair(points):
    minDist = float("inf")
    p1, p2 = None, None
    for p in points:
        for q in points:
            if (p == q): continue
            dist = ((p[0] - q[0])**2 + (p[1] - q[1])**2)**(1/2)
            if (dist < minDist): 
                minDist, p1, p2 = dist, p, q
    return [p1, p2]

