def find_shortest_path(grid):
    start = (0, 0)
    end = (-1, -1)

    # find start and end location
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 'A':
                start = (i, j)
            elif grid[i][j] == 'B':
                end = (i, j)

    queue = [start]
    numRows = len(grid)
    numCols = len(grid[0])
    visited = [[False for _ in range(numCols)] for _ in range(numRows)]

    # mark the location of walls
    for i in range(numRows):
        for j in range(numCols):
            if grid[i][j] == 'X':
                visited[i][j] = True

    while len(queue):

        current = queue[0]
        queue.pop(0) 
        row, col = current

        # check if current is the end
        if current == end:
            break

        # mark the current as visited
        visited[row][col] = True

        # explore paths in all directions
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for rowChange, colChange in directions:
            updatedRow = row + rowChange
            updatedCol = col + colChange

            if (0 <= updatedRow < numRows) and (0 <= updatedCol < numCols):
                if visited[updatedRow][updatedCol] == False:
                    queue.append((updatedRow, updatedCol))

    # get the shortest path
    shortest = [[0 for _ in range(numCols)] for _ in range(numRows)]
    previous = [[(-1, -1) for _ in range(numCols)] for _ in range(numRows)]
    for i in range(numRows):
        for j in range(numCols):
            if grid[i][j] == 'X':
                shortest[i][j] = -1 
            elif (i, j) == start:
                shortest[i][j] = 0
            else:
                shortest[i][j] = float("inf") 

    # get the length of each path from start to end
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while len(queue):
        current = queue[0]
        queue.pop(0)
        row, col = current

        for (rowChange, colChange) in directions:
            updatedRow = row + rowChange
            updatedCol = col + colChange

            if (0 <= updatedRow < numRows) and (0 <= updatedCol < numCols):
                val = 1 + shortest[row][col]
                if val < shortest[updatedRow][updatedCol]:
                    shortest[updatedRow][updatedCol] = val
                    previous[updatedRow][updatedCol] = current
                    queue.append((updatedRow, updatedCol))

    # traverse through the shortest path found
    path = []
    current = end
    while current != start:
        path.append(current)
        current = previous[current[0]][current[1]]

    return list(reversed(path))

