// Recursive C program to find gcd of two numbers 
int gcd(int A, int B) 
{ 
	// base case 
	if (A == 0) 
		return B; 
	if (B == 0) 
		return A; 

	// A is greater 
	if (A > B) 
		return gcd(A-B, B); 
	else
		return gcd(A, B-A); 
}

