function longestIncreasingArray(nums) {
 let maxLen = 0;
 let curLen = 1;
 let lastNum = nums[0];

 // Loop through all elements
 for (let i = 1; i < nums.length; i++) {
 if (nums[i] > lastNum) {
 // Increase the length of current sequence
 curLen++;
 } else {
 // Reset current length
 curLen = 1;
 }

 // Update the maximum length
 maxLen = Math.max(maxLen, curLen);

 // Set the lastNum
 lastNum = nums[i];
 }

 return maxLen;
}

