def permutations(string): 
    if len(string) == 0: 
        return [] 

    if len(string) == 1: 
        return [string] 

    perm_list = [] 

    for i in range(len(string)): 
       m = string[i] 
       rem_string = string[:i] + string[i+1:] 

       for perm in permutations(rem_string): 
           perm_list.append([m] + perm) 

    return perm_list

