public class StringCompare {

 public static double jaccardSimilarity(String str1, String str2) {

  int len1 = str1.length();
  int len2 = str2.length();

  // Count the intersection of the strings
  int intersection = 0;
  for (int i = 0; i < len1; i++) {
   for (int j = 0; j < len2; j++) {
    if (str1.charAt(i) == str2.charAt(j)) {
     intersection++;
     break;
    }
   }
  }

  // Calculate the Jaccard Similarity
  return (double)intersection/(len1 + len2 - intersection);
 }

 public static void main(String[] args) {
  String str1 = "book";
  String str2 = "cook";

  double similarity = jaccardSimilarity(str1, str2);
  System.out.println("The similarity score of the strings is: " + similarity);
 }
}

