def find_median(arr1, arr2):
    merged_arr = []
    i, j = 0, 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            merged_arr.append(arr1[i])
            i += 1
        else:
            merged_arr.append(arr2[j])
            j += 1

    while i < len(arr1):
        merged_arr.append(arr1[i])
        i += 1
    while j < len(arr2):
        merged_arr.append(arr2[j])
        j += 1

    length = len(merged_arr)
    if length % 2 == 0:
        median = (merged_arr[length // 2] + merged_arr[length // 2 - 1]) / 2
    else:
        median = merged_arr[length // 2]

    return median

def isBalanced(root): 

    if root is None: 
        return True

    lh = height(root.left) 
    rh = height(root.right) 

    if abs(lh-rh) <= 1 and isBalanced(root.left) is True and isBalanced(root.right) is True: 
        return True 

    return False 

