"""
A program that attempts to solve the least common multiple (LCM) problem.
"""

def lcm(a, b):
    if a == 0 or b == 0:
        return 0 
    else:
        num1, num2 = a, b
        while num1 != num2:
            if num1 > num2:
                num1 -= num2
            else:
                num2 -= num1
        lcm = a*b / num1
        return lcm

