import numpy as np
def winning_move(board):
    #Check Rows
    for i in range(3):
        if np.all(board[i] == "O"): 
            for index, x in enumerate(board[i]):
                if x == 0:
                    return (i, index)
        if np.all(board[i] == "X"): 
            for index, x in enumerate(board[i]):
                if x == 0:
                    return (i, index)

    #Check Columns
    for i in range(3):
        col = board[:,i]
        if np.all(col == "O"): 
            for index, x in enumerate(col):
                if x == 0:
                    return (index, i)
        if np.all(col == "X"): 
            for index, x in enumerate(col):
                if x == 0:
                    return (index, i)

    #Check Diagonals 
    diag1 = board.diagonal()
    if np.all(diag1 == "O"): 
        for index, x in enumerate(diag1):
            if x == 0:
                return (index, index)
    if np.all(diag1 == "X"): 
        for index, x in enumerate(diag1):
            if x == 0:
                return (index, index)

    diag2 = np.fliplr(board).diagonal()
    if np.all(diag2 == "O"): 
        for index, x in enumerate(diag2):
            if x == 0:
                return (index, 2-index)
    if np.all(diag2 == "X"): 
        for index, x in enumerate(diag2):
            if x == 0:
                return (index, 2-index)

    #No winning move found
    return (-1,-1)

