def minCoinChange(coins, amount):
   # base case
    if amount == 0:
        return 0

    # Initialize result
    res = float("inf") 

    # Try every coin that has smaller value
    # than amount
    for i in range(len(coins)):
        if coins[i] <= amount:
            sub_res = minCoinChange(coins, amount - coins[i])

            # Check for INT_MAX to avoid overflow 
            # and see if result can minimized
            if sub_res != float("inf") and  sub_res + 1 < res:
                res = sub_res + 1

    return res

