public class QuadraticEquation {

    public static void main(String[] args) 
    {
        Scanner sc = new Scanner(System.in);

        System.out.print("Enter the coefficient of x^2:");
        double a = sc.nextDouble();

        System.out.print("Enter the coefficient of x:");
        double b = sc.nextDouble();

        System.out.print("Enter the constant:");
        double c = sc.nextDouble();

        double root1, root2;
        double determinant = b * b - 4 * a * c;

        if(determinant > 0)
        {
            root1 = (-b + Math.sqrt(determinant)) / (2*a);
            root2 = (-b - Math.sqrt(determinant)) / (2*a);

            System.out.format("The roots of the equation are: %.2f and %.2f", root1 , root2);
        }
        else if(determinant == 0)
        {
            root1 = root2 = -b / (2 * a);
            System.out.format("The root of the equation is: %.2f", root1);
        }
        else
        {
            double realPart = -b / (2 *a);
            double imaginaryPart = Math.sqrt(-determinant) / (2 * a);
            System.out.format("The roots of the equation are: %.2f + %.2fi and %.2f - %.2fi", realPart, imaginaryPart, realPart, imaginaryPart);
        }
    }
}

