    number2 = sc.nextInt();
    System.out.println("Enter an operator (+, -, *, /): ");
    char operator = sc.next().charAt(0);
    double result;

    switch (operator) {
      case '+':
        result = number1 + number2;
        break;
      case '-':
        result = number1 - number2;
        break;
      case '*':
        result = number1 * number2;
        break;
      case '/':
        result = number1 / number2;
        break;
      default:
        System.out.printf("You have entered wrong operator");
        return;
    }

    System.out.println(number1 + " " + operator + " " + number2 + " = " + result);

  }
}

