def count_valid_solutions(lower, upper):
    count = 0
    for n in range(lower, upper+1):
        solutions = 0
        for i in range(1, n+1):
            # check if i is valid solution
            if n % i == 0:
                solutions += 1
        # check if solutions is even
        if solutions % 2 == 0:
            count += 1
    return count

