class DataTable extends Component {
 constructor(props) {
 super(props);
 this.state = {
 data: props.data,
 sortKey: null,
 reverse: false
 }
 }

 handleSort = (key) => {
 let reverse = this.state.sortKey === key && !this.state.reverse;
 this.setState({
 sortKey: key,
 reverse
 });
 }

 render() {
 let data = [...this.state.data]; // Deep copy of data
 let {sortKey, reverse} = this.state;

 data.sort((a, b) => {
 let sortVal = 0;
 if (a[sortKey] < b[sortKey]) {
 sortVal = reverse ? 1 : -1;
 }
 else if (a[sortKey] > b[sortKey]) {
 sortVal = reverse ? -1 : 1;
 }

 return sortVal;
 });

 return (
 <div className="DataTable">
 <table>
 <thead>
 <tr>
 <th onClick={() => this.handleSort('name')}>Name</th>
 <th onClick={() => this.handleSort('age')}>Age</th>
 </tr>
 </thead>
 <tbody>
 {data.map(item => (
 <tr key={item.name}>
 <td>{item.name}</td>
 <td>{item.age}</td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 );
 }
