    for i in range(3):
        if board[i * 3] == board[i * 3 + 1] == board[i * 3 + 2] and board[i * 3] != ' ':
            return True

    # Check columns
    for i in range(3):
        if board[i] == board[i + 3] == board[i + 6] and board[i] != ' ':
