function camelCase(str) {
    let splitStr = str.split('_');
    let camelCaseStr = splitStr[0];

    for(let i = 1; i < splitStr.length; i++) {
        let firstLetter = splitStr[i].slice(0,1);
        let remainingLetters = splitStr[i].slice(1);
        camelCaseStr += firstLetter.toUpperCase()+remainingLetters;
    }
    return camelCaseStr;
}

