public class NumberOfSubstrings { 

    // Function to find number of distinct substrings 
    // containing given set of characters 
    public static int findSubstrings(String str) 
    { 
        int dist_count = 0; 

        // create an array of size 256, to store 
        // occurrence of characters in string 
        int[] count = new int[256]; 

        // update occurrence of characters in string 
        for (int i = 0; i < str.length(); i++) { 
            char charAt = str.charAt(i); 

            // if character has occurred before,  
            // then increase count[] by 1 
            if (count[charAt] == 1) 
                dist_count++; 

            // update count[] array 
            count[charAt]++; 
        } 

        return (str.length() * (str.length() + 1) / 2 - dist_count); 
    } 

    public static void main(String args[]) 
    { 
        String str = "geeksogeeks"; 
        System.out.println(findSubstrings(str)); 
    } 
}

