def mostFrequent(arr): 
    # insert all elements in a dictionary
    freq = {} 
    for i in arr: 
        if i in freq: 
            freq[i] += 1
        else: 
            freq[i] = 1
    # traversing dictionary and finding  
    # the most frequent element 
    max_count = 0
    res = -1
    for i, j in freq.items(): 
        if j > max_count : 
            res = i 
            max_count = j
    # return result
    return res 

