    public void increaseKey(int i, int key) {
        int temp = heap[i];  
        heap[i] = key;  

        while (i > 0 && heap[parent(i)] < heap[i]) {
            swap(heap, i, parent(i)); 
            i = parent(i); 
        }
    }
    private void swap(int[] arr, int i, int j) {  
        int tmp = arr[i];  
        arr[i] = arr[j];  
        arr[j] = tmp;  
    }
    private int parent(int i) {
        return (i - 1) / 2;  
    }
