// Function to find the inorder predecessor of given node in a binary tree 
node* inOrderPredecessor(node* root, node* n) 
{ 
    if (n->left != NULL) 
        return maxValueNode(n->left); 

    node * predecessor = NULL; 

    while (root != NULL) { 
        if (n->data > root->data) 
        { 
            predecessor = root;
            root = root->right; 
        } 
        else if (n->data < root->data) 
            root = root->left; 
        else
            break; 
    } 
    return predecessor; 
}

