class Node {
 var data: Int
 var left: Node?
 var right: Node?

 init(data: Int) {
   self.data = data
   self.left = nil
   self.right = nil
 }
}

func insert(node: Node?, elem: Int) -> Node? {
 if node == nil {
   return Node(data: elem)
 }
 if elem < node!.data {
  node!.left = insert(node: node?.left, elem: elem)
 } else if elem > node!.data {
  node!.right = insert(node: node?.right, elem: elem)
 }
 return node
}

