public class Combinations {

    // Function to generate all possible combinations of  
    // the numbers below N  
    public static void combinations(int N)  
    {  
        // String to store a given number  
        String str = "";  

        // Call a recursive function to generate  
        // all combinations of the given numbers  
        generate(N, 0, str);  
    }  

    // Recursive function to generate all combinations 
    // of the given numbers  
    public static void generate(int N, int start, String str)  
    {  
        if (start == N)  
        {  
            // Print the generated combination  
            System.out.println(str);  
            return;  
        }

        // Iterate from start to N  
        for (int i = start+1; i < N; i++)  
        {  
            // Append the current number  
            // to the previous generated  
            // combination  
            str += i;  

            // Call the recursive function  
            generate(N, i, str);  

            // Remove the last appended number 
            // from the string  
            str = str.substring(0, str.length()-1);  
        }  
    } 
}

