class PolynomialAdd 
{ 
    // Prints the polynomial addition 
    public static void polyAdd(int[] poly1,  
                          int[] poly2, int m, int n) 
    { 
        int[] polySum = new int[m > n ? m : n]; 

        // Adding corresponding terms 
        int i = 0 , j = 0; 
        while (i < m && j < n) 
        { 
            polySum[i] = poly1[i] + poly2[j]; 
            i++ ; j++ ; 
        } 

        // Adding remaining terms of 
        // larger polynomial 
        while (i < m) 
        { 
            polySum[i] = poly1[i]; 
            i++; 
        } 
        while (j < n) 
        { 
            polySum[j] = poly2[j]; 
            j++; 
        } 

        // Printing summarised polynomial 
        Console.Write("\nSum Polynomial: "); 
        for (i = 0; i < polySum.Length; i++) 
            Console.Write(polySum[i] + " "); 
    } 

    public static void Main(string[] args) 
    { 
        int[] poly1 = {3, 2, 4}; 
        int[] poly2 = {2, 3, 4, 5}; 
        int m = poly1.Length; 
        int n = poly2.Length; 
        polyAdd(poly1, poly2, m, n); 
    } 
}

