// Function to insert a new node at the beginning 
// of the linked list 
void push(Node **head, int newData) 
{ 
    // Allocate the new node in the heap 
    Node* new_node = new Node(); 

    // Put the data in the new node 
    new_node->data = newData; 

    // Make the next of the new node to be the head 
    new_node->next = *head; 

    // Make the new node as head 
    *head = new_node; 
} 

// Function to return the size of the linked list 
int get_size(Node **head) 
{ 
    int count = 0; 
    Node* temp = *head; 
    while (temp != nullptr) { 
        count++; 
        temp = temp->next; 
    } 
    return count; 
} 

// Function to print the linked List 
void print_list(Node **head) 
{ 
    Node *temp = *head; 
    while (temp != nullptr) { 
        cout << temp->data << " "; 
        temp = temp->next; 
    } 
} 

