def evalExpression(exp): 

    # Array to store the operands. 
    operand = [] 

    # Traversing the expression. 
    for i in range(len(exp)): 
        if exp[i] == '*' or exp[i] == '+': 
            op1 = operand.pop() 
            op2 = operand.pop() 
            result = eval(op1 + exp[i] + op2) 
            operand.append(str(result)) 
