int getMincoins(int coins[], int n, int sum) 
{ 
    int minCoins[sum+1]; 

    minCoins[0] = 0; 

    for(int amount = 1; amount <= sum; amount++)  { 
        minCoins[amount] = INT_MAX; 
        for (int i = 0; i < n; i++) { 
            if (coins[i] <= amount) { 
                int x = minCoins[amount - coins[i]]; 
                if (x != INT_MAX && x + 1 < minCoins[amount]) 
                    minCoins[amount] = x + 1; 
            } 
        } 
    } 
    return minCoins[sum]; 
}

