public class PrintCombinations {
    // Function to print all the combinations of size k
    static void combinationUtil(String str, String data[], int start, 
                        int end, int index, int k) 
    { 
        // Current combination is ready to be printed, 
        // print it 
        if (index == k) { 
            for (int j = 0; j < k; j++) 
                System.out.print(data[j] + " "); 
            System.out.println(""); 
            return; 
        } 

        // replace index with all possible elements. The 
        // condition "end-i+1 >= r-index" makes sure that 
        // including one element at index will make a 
        // combination with remaining elements at remaining 
        // positions 
        for (int i = start; i <= end && end - i + 1 >= k - index; i++) { 
            data[index] = str.substring(i, i + 3); 
            combinationUtil(str, data, i + 1, end, index + 1, k); 
        } 
    } 

    // Function to print all possible combinations of size k 
    static void printAllKLength(String str, int k) 
    { 
        int n = str.length(); 
        // Allocate memory 
        String data[] = new String[k]; 

        // Call the recursie function 
        combinationUtil(str, data, 0, n - 1, 0, k); 
    } 

}

