def is_valid_isbn(isbn):
    # remove all whitespace and hyphens
    isbn = isbn.replace(' ', '').replace('-', '')

    # length should be 10 characters
    if len(isbn) != 10:
        return False

    # check that the characters are all digits
    for c in isbn:
        if not c.isdigit():
            return False

    # calculate the checksum
    check = 0
    for i, d in enumerate(isbn):
        check += int(d) * (i + 1)
    if check % 11 == 0:
        return True

    return False

def longestCommonSubsequence(word1, word2): 
    m = len(word1) 
    n = len(word2)

    dp = [[None]*(n + 1) for i in range(m + 1)] 

    for i in range(m + 1): 
        for j in range(n + 1): 
            if i == 0 or j == 0 : 
                dp[i][j] = 0
            elif word1[i-1] == word2[j-1]: 
                dp[i][j] = dp[i-1][j-1]+1
            else: 
                dp[i][j] = max(dp[i-1][j] , dp[i][j-1]) 
    return dp[m][n]

