def is_anagram(s1, s2):
    s1 = s1.lower()
    s2 = s2.lower()
    s1_freq = {}
    s2_freq = {}

    # Find character frequency in both strings
    for char in s1:
        if char in s1_freq: 
            s1_freq[char] += 1
        else:
            s1_freq[char] = 1
    for char in s2:
        if char in s2_freq: 
            s2_freq[char] += 1
        else:
            s2_freq[char] = 1

    # Compare characters in both strings
    for key in s1_freq:
        if key not in s2_freq or s2_freq[key] != s1_freq[key]:
            return False
    for key in s2_freq:
        if key not in s1_freq or s1_freq[key] != s2_freq[key]:
            return False
    return True

