def merge_lists(head1,head2): 
    '''merge two sorted linked lists into one sorted linked list'''
    # Base case
    if head1 is None: 
        return head2 
    if head2 is None: 
        return head1 

    # Start with the head node of the merged list
    merged_head = None
    if head1.data <= head2.data: 
        merged_head = head1 
        head1 = head1.next
    else: 
        merged_head = head2 
        head2 = head2.next

    # Create the pointer to traverse and return the head
    merged_ptr = merged_head 

    # Merge the two sorted linked lists 
    while head1 is not None and head2 is not None: 
        if head1.data <= head2.data: 
            merged_ptr.next = head1 
            head1 = head1.next
        else: 
            merged_ptr.next = head2 
            head2 = head2.next
        merged_ptr = merged_ptr.next

    # Append the remaining nodes of the nonempty list
    if head1 is not None: 
        merged_ptr.next = head1 
    else: 
        merged_ptr.next = head2 

    return merged_head

