function encodeString(string) {
    // Declare a variable to store the encoded result
    let encodedString = '';

    // Iterate over every character in the string
    for (let i = 0; i < string.length; i++) {
        // Get the corresponding ASCII value of each character
        let ascii = string.charCodeAt(i);

        // Add the value to the encoded string
        encodedString += ascii.toString();
