function reverseStack(stack) {
    let tmpStack1 = [];
    let tmpStack2 = [];

    // Push all elements from stack to tmpStack1
    while (stack.length > 0) {
        tmpStack1.push(stack.pop());
    }

    // Push all elements from tmpStack1 to tmpStack2
    while (tmpStack1.length > 0) {
        tmpStack2.push(tmpStack1.pop());
    }

    // Push all elements from tmpStack2 to stack
    while (tmpStack2.length > 0) {
        stack.push(tmpStack2.pop());
    }
}

