def dfs(maze, start, end):
 path = []
 visited = set()

 # Helper function to determine if a cell is valid
  def is_valid(row, col):
   if row < 0 or row >= len(maze) or col < 0 or col >= len(maze[0]):
    return False
   else:
    return not maze[row][col]

 # Helper recursive function 
  def find_path(row, col):
   if (row, col) == end:
    return True
   else: 
    if is_valid(row, col) and (row, col) not in visited:
     visited.add((row, col))
     if find_path(row + 1, col):
      path.append('S')
      return True
     elif find_path(row - 1, col):
      path.append('N')
      return True
     elif find_path(row, col + 1):
      path.append('E')
      return True
     elif find_path(row, col - 1):
      path.append('W')
      return True
     visited.remove((row, col))
   return False

 # Start the actual dfs 
 find_path(start[0], start[1])
 path.reverse()
 return path

