function reverseEngineer(node) {
 // base Case 
 if (!node) {
  return;
 }

 var html = '';
 if (node.nodeType === 1) { // if it is an element node
  // generate the opening tag
  html = `<${node.nodeName}`;

  // add attributes
  for (let attribute of node.attributes) {
   html += ` ${attribute.name}="${attribute.value}"`;
  }
  html += '>';
 }

 if (node.nodeType === 3) { // if it is textNode
  html += node.textContent;
 }

 for (let childNode of node.childNodes) {
  // recursion
  html += reverseEngineer(childNode);
 }

 if (node.nodeType === 1) { // if it is an element node
  html += `</${node.nodeName}>`;
 }

 return html;
}

