public static boolean isValidCardNumber(String number) {
    int[] digits = new int[number.length()];

    for(int i = 0; i < number.length(); i++) {
        digits[i] = Integer.parseInt(number.substring(i, i+1));
    }

    int sum = 0;
    for(int i = digits.length - 2; i > -1; i = i - 2) {
        sum += digits[i];
    }

    for(int i = digits.length - 1; i > -1; i = i - 2) {
        int doubleDigit = digits[i] * 2;
        if(doubleDigit > 9) {
            doubleDigit = doubleDigit - 9;
        }
        sum += doubleDigit;
    }

    if(sum % 10 == 0) {
        return true;
    }

    return false;
}

