public class RotateArray {

 public static void rotate(int[][] array) {
 // transpose the array
 for (int i = 0; i < array.length; i++) {
 for (int j = i; j < array[i].length; j++) {
 int tmp = array[i][j];
 array[i][j] = array[j][i];
 array[j][i] = tmp;
 }
 }

 // reverse the columns
 for (int j = 0; j < array[0].length; j++) {
 for (int i = 0, k = array.length - 1; i < k; i++, k--) {
 int tmp = array[i][j];
 array[i][j] = array[k][j];
 array[k][j] = tmp;
 }
 }
 }

