def find_shortest_path(maze):
    '''This function will find the shortest path through a given maze'''
    rows = len(maze)
    cols = len(maze[0])

    dis = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if maze[i][j] == 1:
                dis[i][j] = float('inf')

    dis[0][0] = 0
    for i in range(rows):
        for j in range(cols):
            if i > 0:
                dis[i][j] = min(dis[i][j], dis[i-1][j] + 1)
            if j > 0:
                dis[i][j] = min(dis[i][j], dis[i][j-1] + 1)

    return dis[rows-1][cols-1]

