public boolean isPalindrome(LinkedListNode head) {

  LinkedListNode fast = head;
  LinkedListNode slow = head;

  Stack<Integer> stack = new Stack<Integer>();

  while (fast != null && fast.next != null) {
    stack.push(slow.val);
    slow = slow.next;
    fast = fast.next.next;
  }

  if (fast != null) { 
    slow = slow.next;
  }

  while (slow != null) {
    if (slow.val != stack.pop()) {
      return false;
    }

    slow = slow.next;
  }

  return true;
}

def binarySearch(arr, number):
    left = 0
    right = len(arr) - 1
    while left <= right:
        mid = (left + right)//2
        if arr[mid] == number:
            return mid
        elif arr[mid] < number:
            left = mid + 1
        else:
            right = mid - 1
    return -1

