// The Edge class represents an edge from vertex u to vertex v with weight w.
struct Edge {
 int u, v, w;
};

// The Graph class represents an directed graph consisting of 
// n vertices and m edges.
class Graph {
 private:
 vector<Edge> edges;  // Vector of edges
 int n, m;            // Number of vertices and edges
 public:

 Graph(int n, int m) : n(n), m(m) {
 edges.resize(m);
 }

 void addEdge(int i, int u, int v, int w) {
 edges[i] = {u, v, w};
 }

 int bellmanFord(int s, int t) {
 vector<int> dist(n, 10000);
 dist[s] = 0;

 // Relax each edge n-1 times
 for (int i = 0; i < n-1; ++i) {
 for (int j = 0; j < m; ++j) {
 int u = edges[j].u, 
 v = edges[j].v, 
 w = edges[j].w;

 dist[v] = min(dist[v], dist[u] + w); 
 }
 }

 // Check for negative cycles
 for (int j = 0; j < m; ++j) {
 int u = edges[j].u, 
 v = edges[j].v, 
 w = edges[j].w;

 if (dist[v] > dist[u] + w)
 return -1;
 }

 return dist[t];
 }
};

