// Function to find the length of the Longest Common Subsequence
int LCSLength(string s1, string s2, int m, int n)
{
    // If either of the strings is empty, return 0
    if (m == 0 || n == 0)
        return 0;

    // If last characters of the strings match
    if (s1[m-1] == s2[n-1])
        return 1 + LCSLength(s1, s2, m - 1, n - 1);
    else
    {
        // Return maximum of the two possible paths
        int op1 = LCSLength(s1, s2, m, n - 1);
        int op2 = LCSLength(s1, s2, m - 1, n);
        return max(op1, op2);
    }
}

