    { 
        // Create a list of integers 
        List<int> list = new List<int>(); 

        // To Store the current length of 
        // the longest substring 
        int max = 0; 

        // To Store the longest substring 
        string maxSubstring = ""; 

        // To Store the current substring 
        string currentSubstring = ""; 

        for (int i = 0; i < str.Length; i++) 
        { 
            // If the character is already present 
            if (list.Contains(str[i])) 
            { 
                // Update max 
                max = Math.Max(max, list.Count()); 

                // Store currentSubstring into maxSubstring 
                // if max is updated 
                if (max > list.Count()) 
                    maxSubstring = currentSubstring; 

                // Clear list and currentSubstring 
                list.Clear(); 
                list.Add(str[i]); 
                currentSubstring = "" + str[i]; 
            } 

            // If character is not present 
            else
            { 
                list.Add(str[i]); 
                currentSubstring += str[i]; 
            } 
        } 

        // Update last time 
        max = Math.Max(max, list.Count()); 
        if (max > list.Count()) 
            maxSubstring = currentSubstring; 

        return max; 
    }

