import java.util.ArrayList;
import java.util.List;

public class PriorityQueue { 

	List<Integer> queue = new ArrayList<Integer>(); 

	public void enqueue(int data, int priority) 
	{ 
		// Create a new node with given data 
		Node newNode = new Node(data, priority); 

		// Append the new node to the end of the queue 
		queue.add(newNode.data); 

		// Traverse the list and move the node ahead 
		// of all nodes with higher priority 
		int i = queue.size()-1; 
		while (i != 0 && queue.get(i) > queue.get(i - 1)) 
		{ 
			// Swap the data 
			int temp = queue.get(i); 
			queue.set(i, queue.get(i - 1)); 
			queue.set(i - 1, temp); 

			// move the index to smaller index 
			i--; 
		} 
	} 

	// Function to remove an element from queue 
	public void dequeue() 
	{ 
		if (queue.size() == 0) 
		{ 
			System.out.println("Underflow"); 
		} 

		// Return the dequeued element 
		int rem = queue.remove(0); 
		System.out.println("Removed element: " + rem); 
	} 

	public void peek() 
	{ 
		if (queue.size() == 0) 
		{ 
			System.out.println("Underflow"); 
			return ; 
		} 

	 	// Return the element at the front 
		int front = queue.get(0); 
		System.out.println("Element at the front : " + front); 
	} 
}

