// Alpha-beta pruning algorithm 
function alphaBetaPruning(state, depth, alpha, beta, maximizer){       
    if (depth == 0 || isTerminalState(state)){
        return evaluate(state);
    } 

    if (maximizer == true){     
        let v = -Infinity;

        for (let move of possibleMoves(state)){

            const nextState = makeMove(state, move, maximizer);
            v = max(v, alphaBetaPruning(nextState, depth - 1, alpha, beta, false)); 
            alpha = max(alpha, v); 

            if (beta <= alpha){
                break; 
            }   
        }
        return v; 
    }
    else{ 
        let v = Infinity;

        for (let move of possibleMoves(state)){

            const nextState = makeMove(state, move, maximizer);             
            v = min(v, alphaBetaPruning(nextState, depth - 1, alpha, beta, true)); 
            beta = min(beta, v); 

            if (beta <= alpha){
                break; 
            }   
        } 
        return v; 
    }
}

def merge_sort(nums):
    if len(nums) == 1:
        return nums
    mid = len(nums) // 2
    left = merge_sort(nums[:mid])
    right = merge_sort(nums[mid:])
    return merge(left, right)

