def compress_text(text):
    output_txt = ""
    current_c = ""
    current_count = 0

    for c in text:
        if c == current_c:
            current_count += 1
        else:
            if current_count > 0:
                output_txt += str(current_count) + current_c
            current_c = c
            current_count = 1

    if current_count > 0:
        output_txt += str(current_count) + current_c

    return output_txt

