def rock_paper_scissors_prediction(game_history):
    paper_count = 0 
    rock_count = 0
    scissors_count = 0
    prediction = "rock"

    for history in game_history:
        if history == "paper":
            paper_count += 1
        elif history == "rock":
            rock_count += 1
        else:
            scissors_count += 1

    if paper_count > rock_count and paper_count > scissors_count:
        prediction = "scissors"
    elif rock_count > paper_count and rock_count > scissors_count:
        prediction = "paper"
    else:
        prediction = "rock"

    return prediction

