// Create an Automata class
class Automata {
  constructor(x, y, matrix) {
    this.x = x;
    this.y = y;
    this.matrix = matrix; 
  }

  update() {
    // Rules for the automata
    for (let x = 0; x < this.x; x++) {
      for (let y = 0; y < this.y; y++) {
        if (this.matrix[x][y].s === "Fire") {
          // If the cell around is Tree, that Tree catch Fire
          let treeCellAround = this.getCellAround(x, y);
          treeCellAround.forEach(cell => {
            if (this.matrix[cell.x][cell.y].s === "Tree") {
              this.matrix[cell.x][cell.y].s = "Fire";
            }
          });
        }
      }
    }
  }

  getCellAround(x, y) {
    const cellAround = [
      { x: x - 1, y: y - 1 },
      { x: x - 1, y: y },
      { x: x - 1, y: y + 1 },
      { x: x, y: y - 1 },
      { x: x, y: y + 1 },
      { x: x + 1, y: y - 1 },
      { x: x + 1, y: y },
      { x: x + 1, y: y + 1 }
    ];
    return cellAround;
  }
}

