} 

// Finds two closest points and returns the distance between them 
double two_closest(point points[], int n) 
{ 
    double min_dist = DBL_MAX; // Initialize minimum distance 

    for (int i = 0; i < n; ++i) 
    { 
        for (int j = i + 1; j < n; ++j) 
        { 
            double d = dist(points[i], points[j]); 

            if (d < min_dist && d!= 0) 
                min_dist = d; 
        } 
    } 

    return min_dist; 
} 

