public class MorseCode {
    public static String convertMorseCode(String morseCode) {
        StringBuilder plainText = new StringBuilder("");
        Hashtable<String, String> codes = new Hashtable<String, String>();
        codes.put(".-", "A");
        codes.put("-...", "B");
        codes.put("-.-.", "C");
        codes.put("-..", "D");
        codes.put(".", "E");
        codes.put("..-.", "F");
        codes.put("--.", "G");
        codes.put("....", "H");
        codes.put("..", "I");
        codes.put(".---", "J");
        codes.put("-.-", "K");
        codes.put(".-..", "L");
        codes.put("--", "M");
        codes.put("-.", "N");
        codes.put("---", "O");
        codes.put(".--.", "P");
        codes.put("--.-", "Q");
        codes.put(".-.", "R");
        codes.put("...", "S");
        codes.put("-", "T");
        codes.put("..-", "U");
        codes.put("...-", "V");
        codes.put(".--", "W");
        codes.put("-..-", "X");
        codes.put("-.--", "Y");
        codes.put("--..", "Z");

        String[] letters = morseCode.split(" ");
        for (int i = 0; i < letters.length; i++) {
            plainText.append(codes.get(letters[i]));
        }
        return plainText.toString();
    }
}

