import java.util.HashMap;

public class AnagramChecker {
  // method to check if two strings are anagrams
  public static boolean isAnagram(String str1, String str2) {
    // check for null
    if (str1 == null || str2 == null) {
      return false;
    }

    // remove spaces and convert to same case
    str1 = str1.replaceAll("\\s", "").toLowerCase();
    str2 = str2.replaceAll("\\s", "").toLowerCase();

    // length of strings should be same
    if (str1.length() != str2.length()) {
      return false;
    }

    // create a hash map to store the characters
    HashMap<Character, Integer> map = new HashMap<>();

    // iterate through first string and add to map
    for (int i = 0; i < str1.length(); i++) {
      char c = str1.charAt(i);
      if (map.containsKey(c)) {
        int count = map.get(c);
        count++;
        map.put(c, count);
      } else {
        map.put(c, 1);
      }
    }

    // iterate through second string and check if in map
    for (int i = 0; i < str2.length(); i++) {
      char c = str2.charAt(i);
      if (map.containsKey(c)) {
        int count = map.get(c);
        if (count == 0) {
          return false;
        }
        count--;
        map.put(c, count);
      } else {
        return false;
      }
    }

    // if both strings match, it is an anagram
    return true;
  }

  public static void main(String[] args) {
    String str1 = "Carthorse";
    String str2 = "Orchestra";
    if (isAnagram(str1, str2)) {
      System.out.println("The strings are anagrams");
    } else {
      System.out.println("The strings are NOT anagrams");
    }
  }
}

