    """
    Find the maximum sum of non-adjacent elements from given array.

    Args:
        arr (list): a list of integer elements.

    Returns:
        int: maximum sum of non-adjacent elements.
    """
    if not arr:
        return 0
    elif len(arr) == 1:
        return arr[0]
    else:
        max_sum = 0
        for i in range(len(arr)):
            if i == 0:
                max_sum = arr[i]
            elif i == 1:
