const graph = {
  A: {B: 5, C: 4}, 
  B: {A: 5, C: 6, D: 3}, 
  C: {A: 4, B: 6, D: 8, E: 8}, 
  D: {B: 3, C: 8, E: 3}, 
  E: {C: 8, D: 3}
 };

 // Function to find the minimum distance between nodes
 const findMinDistance = (graph, startNode, endNode) => {
   // Initialize a set of visited nodes
   const visited = {};
   for (let key in graph) {
     visited[key] = false;
   }

   // Initialize the minimum distance with infinity
   let minDistance = Number.MAX_VALUE;

   // Use Breadth-First Search to traverse the graph
   const queue = [startNode];
   while(queue.length > 0) {
     const node = queue.shift();
     if (node === endNode) {
       return minDistance;
     }
     for (let neighbor in graph[node]) {
       if (!visited[neighbor]) {
         visited[neighbor] = true;
         minDistance = Math.min(minDistance, graph[node][neighbor]);
         queue.push(neighbor);
       }
     }
   }

   return -1;
 }

 // Use the function to find the minimum distance between nodes
