def find_target_sum(S, T):
 # Use a dictionary to store information about the numbers
 # and their complement that need to be summed to
 # get the target T.
 info = {}

 # Iterate through the set of numbers.
 for n in S:
  # Calculate complement.
  c = T - n

  # Check if complement exists in dictionary.
  if c in info:
   # Return the two numbers that sum to the target.
   return (n, c)
  else:
   # Store the number and its complement
   # in the dictionary.
   info[n] = c

 # No two numbers that sum to the target found.
 return None

