namespace EncryptionLibrary
{
    public static class Encryption
    {
        // Encrypts the given string with Aes algorithm 
        public static string Encrypt(string plainText, string key, string iv)
        {
            // Check arguments. 
            if (plainText == null || plainText.Length <= 0)
                throw new ArgumentNullException("plainText");
            if (key == null || key.Length <= 0)
                throw new ArgumentNullException("key");
            if (iv == null || iv.Length <= 0)
                throw new ArgumentNullException("key");
            byte[] encrypted;

            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = Convert.FromBase64String(key);
                aesAlg.IV = Convert.FromBase64String(iv);

                // Create an encryptor to perform the stream transform.
                ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);

                // Create the streams used for encryption.
                using (var msEncrypt = new MemoryStream())
                {
                    using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                    {
                        using (var swEncrypt = new StreamWriter(csEncrypt))
                        {
                            //Write all data to the stream.
                            swEncrypt.Write(plainText);
                        }
                        encrypted = msEncrypt.ToArray();
                    }
                }
            }

            return Convert.ToBase64String(encrypted);
        }

        // Decrypts a given string with the Aes algorithm
        public static string Decrypt(string cipherText, string key, string iv)
        {
            // Check arguments. 
            if (cipherText == null || cipherText.Length <= 0)
                throw new ArgumentNullException("cipherText");
            if (key == null || key.Length <= 0)
                throw new ArgumentNullException("key");
            if (iv == null || iv.Length <= 0)
                throw new ArgumentNullException("key");

            // Declare the string used to hold 
            // the decrypted text. 
            string plaintext = null;

            using (Aes aesAlg = Aes.Create())
            {
                aesAlg.Key = Convert.FromBase64String(key);
                aesAlg.IV = Convert.FromBase64String(iv);

                // Create a decryptor to perform the stream transform.
                ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

                // Create the streams used for decryption. 
                using (var msDecrypt = new MemoryStream(Convert.FromBase64String(cipherText)))
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                    {
                        using (var srDecrypt = new StreamReader(csDecrypt))
                        {
                            // Read the decrypted bytes from the decrypting stream 
                            // and place them in a string.
                            plaintext = srDecrypt.ReadToEnd();
                        }
                    }
                }

            }

            return plaintext;
        }
    }
}

function createPagination(currentPage, totalPages) {
  let pagination = document.createElement("div");

  // Go to previous page
  let prev = document.createElement("a");
  prev.classList.add('page-link');
  prev.innerHTML = '<';
  if (currentPage > 1) {
    prev.href = '#page' + (currentPage - 1).toString();
    prev.addEventListener('click', (e) => {
      e.preventDefault();
      createPagination(currentPage - 1, totalPages);
    });
  }
  pagination.appendChild(prev);

  // Render page links
  for (let i = 1; i <= totalPages; i++) {
    let a = document.createElement('a');
    a.classList.add('page-link');
    a.innerHTML = i;
    if (i === currentPage) {
      a.classList.add('active');
    } else {
      a.href = '#page' + i;
      a.addEventListener('click', (e) => {
        e.preventDefault();
        createPagination(i, totalPages);
    });
    }
    pagination.appendChild(a);
  }

  // Go to next page
  let next = document.createElement("a");
  next.classList.add('page-link');
  next.innerHTML = '>';
  if (currentPage < totalPages) {
    next.href = '#page' + (currentPage + 1).toString();
    next.addEventListener('click', (e) => {
      e.preventDefault();
      createPagination(currentPage + 1, totalPages);
    });
  }
  pagination.appendChild(next);

  // Render the pagination
  let container = document.querySelector('.pagination');
  container.innerHTML = '';
  container.appendChild(pagination);
}

