public static int longestCommonSubstring(String s, String t) {
   int m = s.length();
   int n = t.length();
   int[][] dp = new int[m + 1][n + 1];
   int result = 0;

   for (int i = 0; i <= m; i++) {
      for (int j = 0; j <= n; j++) {
         if (i == 0 || j == 0) {
            dp[i][j] = 0;
         }
         else if (s.charAt(i - 1) == t.charAt(j - 1)) {
            dp[i][j] = dp[i - 1][j - 1] + 1;
            result = Math.max(result, dp[i][j]);
         }
         else {
            dp[i][j] = 0;
         }
      }
   }
   return result;
}

