fn quick_sort(arr: &mut [i32]) {
    if arr.len() < 2 {
        return;
    }

    let mut pivotIndex = arr.len() / 2;
    let mut pivot = arr[pivotIndex];

    // Partition
    let mut leftIndex = 0;
    let mut rightIndex = arr.len() - 1;

    while leftIndex < rightIndex {
        while arr[leftIndex] < pivot {
            leftIndex += 1;
        }
        while arr[rightIndex] > pivot {
            rightIndex -= 1;
        }

        let temp = arr[leftIndex];
        arr[leftIndex] = arr[rightIndex];
        arr[rightIndex] = temp;

        leftIndex += 1;
        rightIndex -= 1;
    }

    // Recure
    quick_sort(&mut arr[0..rightIndex]);
    quick_sort(&mut arr[leftIndex..arr.len()]);
}

