public class LinkedListToArray {

 public static int[] linkedListToArray(ListNode head) {
  ListNode currentNode = head;
  int count = 0;

  // get the length of the list
  while (currentNode != null) {
   currentNode = currentNode.next;
   count++;
  }

  // create the array and initialize it with 0
  int[] array = new int[count];

  // inititalize the current node to head again
  currentNode = head;

  // copy the values from linked list to array
  for (int i = 0; i < count; i++) {
   array[i] = currentNode.val;
   currentNode = currentNode.next;
  }

  return array;
 }

 public static void main(String[] args) {
  // create a linked list manually
  ListNode head = new ListNode(7);
  ListNode second = new ListNode(14);
  ListNode third = new ListNode(21);

  head.next = second;
  second.next = third;

  int[] array = linkedListToArray(head);

  System.out.println(Arrays.toString(array));
 }
