    """
    Given a list of words and a list of letters and a target word length,
    find all the words which can be formed using the given letter list and the target word length.
    """
    valid_words = []
    for word in words:
        valid = True
        if len(word) == target_word_length:
            for c in word:
                if c not in letters:
                    valid = False
            if valid:
                valid_words.append(word)
    return valid_words

