def most_frequent_element(list):
    # Create a dictionary to store element-frequency pairs
    frequency_dict = {}
    # Loop through the list and count the frequency of each element
    for element in list:
        if element in frequency_dict.keys():
            frequency_dict[element] += 1
        else:
            frequency_dict[element] = 1
    # Find the maximum frequency
    max_frequency = max(frequency_dict.values())
    # Find the elements with the maximum frequency
    max_elements = []
    for element, freq in frequency_dict.items():
        if freq == max_frequency:
            max_elements.append(element)

    return max_elements

