def longest_common_substring(str1, str2):
    len1 = len(str1)
    len2 = len(str2)

    lcs_arr = [[0 for x in range(len2 + 1)] for x in range(len1 + 1)]

    longest = 0

    for i in range(len1):
        for j in range(len2):
            if str1[i] == str2[j]:
                lcs_arr[i+1][j+1] = lcs_arr[i][j] + 1
                if lcs_arr[i+1][j+1] > longest:
                    longest = lcs_arr[i+1][j+1]

    return str1[i+1 - longest:i+1]

