class Dijkstra:
    def __init__(self, graph, start_node):
        self.graph = graph
        self.start_node = start_node
        self.dist = {}
        self.prev = {}

    def calculate_distance(self):
        for v in self.graph:
            self.dist[v] = float('inf')
            self.prev[v] = None

        self.dist[self.start_node] = 0

        processed_nodes = set()

        while processed_nodes != set(self.graph.keys()):
            u = min(self.dist, key=lambda k: self.dist[k] if k not in processed_nodes else float('inf')) 

            processed_nodes.add(u)

            for v in self.graph[u]:
                alt = self.dist[u] + self.graph[u][v]
                if alt < self.dist[v]:
                    self.dist[v] = alt
                    self.prev[v] = u

        return self.dist, self.prev

def quicksort(arr):
  if len(arr) <= 1:
    return arr
  pivot = arr[len(arr) // 2]
  left = [x for x in arr if x < pivot]
  middle = [x for x in arr if x == pivot]
  right = [x for x in arr if x > pivot]
  return quicksort(left) + middle + quicksort(right)

