            temp = arr[i][j] 
            arr[i][j] = arr[N - 1 - j][i] 
            arr[N - 1 - j][i] = arr[N - 1 - i][N - 1 - j] 
            arr[N - 1 - i][N - 1 - j] = arr[j][N - 1 - i] 
            arr[j][N - 1 - i] = temp 
