function numberToWords(number){
    let numberInWords = "";
    let Ones = ["", "one ", "two ", "three ", "four ", "five ", "six ", "seven ", "eight ", "nine "];
    let Teens = ["ten ", "eleven ", "twelve ", "thirteen ", "fourteen ", "fifteen ", "sixteen ", "seventeen ", "eighteen ", "nineteen "];
    let Tens = ["", "", "twenty ", "thirty ", "forty ", "fifty ", "sixty ", "seventy ", "eighty ", "ninety "];

    if (number === 0) {
        numberInWords += "zero";
    }
    else {
        let hundreds = Math.floor(number / 100);
        numberInWords += hundreds ? `${Ones[hundreds]}hundred ` : "";

        const tens = number % 100;

        if (tens < 10) {
            numberInWords += `${Ones[tens]}`;
        }
        else if (tens >= 10 && tens < 20) {
            numberInWords += `${Teens[tens - 10]}`;
        }
        else {
            let tensAndOnes = Math.floor(tens / 10);
            numberInWords += `${Tens[tensAndOnes]}`;
            let ones = tens % 10;
            numberInWords += `${Ones[ones]}`;
        }
    }
    return numberInWords;
}

