import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class FaultTolerantStreaming {
 private static final String CHECKPOINT_FILE = "checkpoint.txt";

 private ScheduledExecutorService scheduler;
 private List<String> data = new ArrayList<>();

 public void start() {
 scheduler = Executors.newSingleThreadScheduledExecutor();

 // Load the checkpoint
 loadCheckpoint();

 // Schedule checkpointing
 scheduler.scheduleAtFixedRate(this::checkpoint, 5, 5, TimeUnit.SECONDS);
 }

 private void loadCheckpoint() {
 File file = new File(CHECKPOINT_FILE);

 if (file.exists()) {
 try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
 String line;

 while ((line = reader.readLine()) != null) {
 data.add(line);
 }
 } catch (IOException e) {
 e.printStackTrace();
 }
 }
 }

 private void checkpoint() {
 try (BufferedWriter writer = new BufferedWriter(new FileWriter(CHECKPOINT_FILE))) {
 for (String d : data) {
 writer.write(d);
 writer.newLine();
 }
 } catch (IOException e) {
 e.printStackTrace();
 }
 }

 public void processData(String d) {
 // Do some data processing
 data.add(d);
 }

 public void stop() {
 scheduler.shutdown();
 }
}

