def perceptron(x, y, weights, bias):
    output = 0
    for i in range(len(x)):
        output += x[i] * weights[i]
    output += bias
    if output * y > 0:
        return weights, bias
    else:
        for i in range(len(x)):
            weights[i] += y * x[i]
        bias += y
        return weights, bias

