def add_equation(equation):
    equation = equation.replace(' ', '') #remove spaces
    #split equation into left and right sides
    left, right = equation.split('=')
    left_terms = left.split('+') #split left side into terms
    right_terms = right.split('+') #split right side into terms

    #create two dictionaries to store coefficients and constants
    coeff_left = {}
    coeff_right = {}
    constants_left = 0
    constants_right = 0

    #store left side coefficients and constants
    for term in left_terms:
        if 'x' in term:
            var, coeff = term.split('x') #split coefficient and variable
            coeff_left['x'] = int(coeff)
        elif 'y' in term:
            var, coeff = term.split('y') #split coefficient and variable
            coeff_left['y'] = int(coeff)
        else:
            constants_left = int(term)

    #store right side coefficients and constants
    for term in right_terms:
        if 'x' in term:
            var, coeff = term.split('x') #split coefficient and variable
            coeff_right['x'] = int(coeff)
        elif 'y' in term:
            var, coeff = term.split('y') #split coefficient and variable
            coeff_right['y'] = int(coeff)
        else:
            constants_right = int(term)

    #add coefficients of same variable
    if 'x' in coeff_left and 'x' in coeff_right:
        coeff_left['x'] += coeff_right['x']
    if 'y' in coeff_left and 'y' in coeff_right:
        coeff_left['y'] += coeff_right['y']
    #add constants
    constants_left += constants_right

    #construct new equation 
    equation_left = ''
    for key, coeff in coeff_left.items():
        if coeff > 0:
            equation_left += '+'
        equation_left += str(coeff) + key     

    return equation_left + '=' + str(constants_left)

