struct Node 
{ 
    int data; 
    struct Node* next; 
}; 

// function to insert a given node at a given position  
// in a linked list 
void insertNode(struct Node** head_ref, int new_data, int pos) 
{ 
    // if linked list is empty 
    if (*head_ref == NULL) 
        return; 

    // allocating new node 
    Node* new_node = new Node(); 

    // put in the data  
    new_node->data = new_data; 

    // if position is 0 
    if (pos == 0) 
    { 
        // set new node's next node to head node 
        new_node->next = (*head_ref); 

        // set head to point to new node 
        (*head_ref) = new_node; 
        return; 
    } 

    // find previous node of the node to be inserted 
    Node* temp = *head_ref; 
    for (int i=0; temp!=NULL && i<pos-1; i++) 
         temp = temp->next; 

    // if position is more than number of nodes 
    if (temp == NULL) 
        return; 

    // link the new node with the next node 
    new_node->next = temp->next; 

    // make new node as next next node of previous node 
    temp->next = new_node; 
}

