function findPermutations(str) {
  if (str.length <= 1) {
    return str;
  }

  let permutations = [];
  for (let i = 0; i < str.length; i++) {
    let current = str[i];
    let remaining = str.slice(0, i) + str.slice(i + 1);
    for (let permutation of findPermutations(remaining)) {
      permutations.push(current + permutation)
    }
  }
  return permutations;
}

