class Node { 
    constructor(character, frequency) { 
        this.character = character; 
        this.frequency = frequency; 
        this.left = null; 
        this.right = null; 
    } 
} 

class PriorityQueue { 
    constructor() 
    { 
        this.characterFrequency = []; 
    } 

    enqueueCharacter(node) 
    { 
        this.characterFrequency.push(node); 
        this.characterFrequency.sort((a, b) => a.frequency - b.frequency); 
    } 

    dequeueCharacter() 
    { 
        return this.characterFrequency.shift(); 
    } 
} 

function encodeData(text) { 
    const characterFrequency = {}; 
    for (const char of text) { 
        characterFrequency[char] 
        ? characterFrequency[char] 
        += 1 
        : characterFrequency[char] = 1; 
    } 

    const priorityQueue = new PriorityQueue(); 

    const keys = Object.keys(characterFrequency); 

    for (const key of keys) { 
        const node = new Node(key, characterFrequency[key]); 
        priorityQueue.enqueueCharacter(node); 
    } 

    while (priorityQueue.characterFrequency.length !== 1) { 
        const left = priorityQueue.dequeueCharacter(); 
        const right = priorityQueue.dequeueCharacter(); 

        const node = new Node(null, left.frequency + right.frequency); 
        node.left = left; 
        node.right = right; 
        priorityQueue.enqueueCharacter(node); 
    } 

    const huffmanCode = {}; 
    const codes = tripleTraversal(priorityQueue.dequeueCharacter(), '', huffmanCode); 

    let codedData = ''; 
    for (const char of text) { 
        codedData += codes[char]; 
    } 
    return codedData; 
} 

function tripleTraversal(root, mask, huffmanCode) { 
    if (root.left !== null && root.right !== null) { 
        tripleTraversal(root.left, `${mask}0`, huffmanCode); 
        tripleTraversal(root.right, `${mask}1`, huffmanCode); 
    } else if (root.character !== null) 
        huffmanCode[root.character] = `${mask}`; 
    return huffmanCode; 
}

