def orderings(n):
    """This function prints all possible orderings of the numbers 1 through n"""
    if n == 0:
        return [[]]
    sub_orderings = orderings(n-1)
    result = []
    for sub_order in sub_orderings:
        for i in range(len(sub_order)+1):
            result.append(sub_order[:i] + [n] + sub_order[i:])
    return result

