function fibonacci(n) {
    let first = 0;
    let second = 1;
    let next; 
    let count = 2;
    if (n === 0) {
        return first;
    } else if (n === 1) {
        return second;
    } else {
        while (count++ < n) {
            next = first + second;
            first = second;
            second = next;
        }
        return next;
    }
}

