  palindromes = []

# iterate all possible substrings
  for i in range(len(string) + 1):
    for j in range(i + 1, len(string) + 1):
      substring = string[i:j]
      # check for palindrome
      if substring == substring[::-1]: 
        palindromes.append(substring)

