namespace PasswordValidation
{
    class Program
    {
        static void Main(string[] args)
        {
            ValidatePassword("Test@123"); // Valid
            ValidatePassword("badpassword"); // Invalid
        }

        // Method to validate a password string
        static void ValidatePassword(string password) 
        {
            int minLength = 8;

            // Check if the password length is valid
            if(password.Length < minLength) {
                Console.WriteLine("Invalid password: Must be at least " + minLength + " characters long");
                return;
            }

            // Flag to keep track if any conditions have been met
            bool validityFlag = false;

            // Check if the password contains a capital letter
            foreach(char c in password) {
                if(Char.IsUpper(c)) {
                    validityFlag = true;
                    break;
                }
            }

            // Check if the password contains a number
            foreach(char c in password) {
                if(Char.IsNumber(c)) {
                    validityFlag = true;
                    break;
                }
            }

            // Check if the password contains a special character
            string specialCharacters = @"!#$%&'()*+,-./:;<=>?@[\]^_`{|}~";
            foreach(char c in password) {
                if(specialCharacters.IndexOf(c) >= 0) {
                    validityFlag = true;
                    break;
                }
            }

            // Print out the result
            if(validityFlag) {
                Console.WriteLine("Valid password");
            }
            else {
                Console.WriteLine("Invalid password: Must contain at least one upper case letter, one number and one special character");
            }
        }
    }
}

