func insertComment(db *sql.DB) http.HandlerFunc {
 return func(w http.ResponseWriter, r *http.Request) {
  // 1. Decode JSON request
  var comment Comment
  err := json.NewDecoder(r.Body).Decode(&comment)
  if err != nil {
   http.Error(w, http.StatusText(400), 400)
    return
  }

  // 2. Insert comment into database
  sqlStatement := `INSERT INTO comments (message) VALUES ($1) returning id`
  id := 0
  err = db.QueryRow(sqlStatement, comment.Message).Scan(&id)
  if err != nil {
   http.Error(w, http.StatusText(500), 500)
    return
  }
  fmt.Println("new comment ID is:", id)

  // 3. Return response
  comment.ID = id
  json.NewEncoder(w).Encode(comment)
 }
}

func getComments(db *sql.DB) http.HandlerFunc {
 return func(w http.ResponseWriter, r *http.Request) {
  // 1. Retrieve comments from the database
  sqlStatement := `SELECT * FROM comments`
  rows, err := db.Query(sqlStatement)
  if err != nil {
   http.Error(w, http.StatusText(500), 500)
   return
  }
  defer rows.Close()

  // 2. Initialize an array for the comments
  comments := []Comment{}

  // 3. Iterate through the comments
  for rows.Next() {
   var comment Comment
   if err := rows.Scan(&comment.ID, &comment.Message); err != nil {
    http.Error(w, http.StatusText(500), 500)
     return
   }
   comments = append(comments, comment)
  }

  // 4. Return response
  json.NewEncoder(w).Encode(comments)
 }
}

