def median_of_two_sorted_arrays(array1, array2):
    combined_arrays = sorted(array1 + array2)
    if len(combined_arrays) % 2 == 0:
        mid_index = len(combined_arrays) // 2 
        median = (combined_arrays[mid_index - 1] + combined_arrays[mid_index])/2
    else:
        mid_index = (len(combined_arrays) - 1) // 2 
        median = combined_arrays[mid_index]
    return median

