def multiply(a, b):
    carry = 0
    result = 0

    for i in range(8 * 4): # size of int * bits in bytes
        bit1 = (a & (1 << i)) >> i

        bit2 = (b & (1 << i)) >> i

        if (bit1 == 1 and bit2 == 1):
            if carry == 1:
                result |= 1 << i
            else:
                carry = 1

        if (bit1 == 0 and bit2 == 0):
            if carry == 0:
                continue
            else:
                result |= 1 << i
                carry = 0

        if (bit1 == 0 and bit2 == 1) or (bit1 == 1 and bit2 == 0):
            if carry == 0:
                result |= 1 << i
            else:
                carry = 1

    return result

