def classify_string(string):
    vowels = set(list("aeiou"))
    consonants = set(list("bcdfghjklmnpqrstvwxyz"))

    num_vowels = 0
    num_consonants = 0

    for char in string:
        if char.lower() in vowels:
            num_vowels += 1
        elif char.lower() in consonants:
            num_consonants += 1

    if num_vowels > num_consonants:
        return "vowel-heavy"
    elif num_consonants > num_vowels:
        return "consonant-heavy"
    else:
        return "neither"

