def getNumberOfIslands(grid):
    num_islands = 0

    for row in range(len(grid)):
        for col in range(len(grid[0])):
            if grid[row][col] == '1':
                num_islands += dfs(grid, row, col)

    return num_islands

def dfs(grid, row, col):
    if row < 0 or col < 0 or row >= len(grid) or col >= len(grid[0]) or  grid[row][col] == '0':
        return 0

    grid[row][col] = '0'

    dfs(grid, row - 1 , col)
    dfs(grid, row + 1 , col)
    dfs(grid, row, col - 1)
    dfs(grid, row, col + 1)

    return 1

