#define ROW 5
#define COL 5

// function to get the minimum cost of the path from
// 0,0 to m,n in the matrix
int minCostPath(int cost[ROW][COL], int m, int n)
{
	if (n < 0 || m < 0)
		return INT_MAX;
	else if (m == 0 && n == 0)
		return cost[m][n];
	else
		return cost[m][n] + min( minCostPath(cost, m-1, n-1),
							minCostPath(cost, m-1, n),
							minCostPath(cost, m, n-1) );
}

