def is_parentheses_balanced(string):
    """Checks if the parentheses in a string are balanced.

    Args:
        string (str): Input string.

    Returns:
        bool: True if parentheses are balanced, False otherwise.
    """

    stack = []

    for ch in string:
        if ch == "(":
            stack.append(ch)
        elif ch == ")":
            if len(stack) > 0:
               stack.pop()
            else:
                return False

    return len(stack) == 0

