	public static boolean isArmstrongNumber(int num) {
		int originalNum, remainder, result = 0;
		originalNum = num;

		while (originalNum != 0)
		{
			remainder = originalNum % 10;
			result  = result + (remainder * remainder * remainder);
			originalNum = originalNum/10;
		}

		return num == result;
	}

