int searchString(char *string, char *chars)
{
    int i, j;

    // Iterate over characters of string
    for(i = 0; i < strlen(string); i++)
    {
        // Flag for found character
        int found = 0;

        // Iterate over characters of chars array
        for(j = 0; j < strlen(chars); j++)
        {
            if(string[i] == chars[j])
            {
                found = 1;
                break;
            }
        }

        // If a character is not found then return false
        if(!found)
            return 0;
    }

