def merge_sorted_lists(lst1, lst2):
    i1 = 0
    i2 = 0

    merged_list = []

    while i1 < len(lst1) and i2 < len(lst2):
        if lst1[i1] < lst2[i2]:
            merged_list.append(lst1[i1])
            i1 += 1
        else:
            merged_list.append(lst2[i2])
            i2 += 1

    if i1 < len(lst1):
        merged_list.extend(lst1[i1:])
    else:
        merged_list.extend(lst2[i2:])

    return merged_list

