#include <vector>

bool IsValid(std::vector<std::vector<int>> &board, int row, int col, int num) 
{ 
    // Check row
    for (int j = 0; j < board[0].size(); j++) 
        if (board[row][j] == num) 
            return false; 

    // Check column 
    for (int i = 0; i < board.size(); i++) 
        if (board[i][col] == num) 
            return false; 

    // Check grid
    int start_row = row - row%3, start_col = col - col%3; 
    for (int i = start_row; i < start_row+3; i++) 
        for (int j = start_col; j < start_col+3; j++) 
            if (board[i][j] == num) 
                return false; 

    return true; 
} 

bool SolveSudoku(std::vector<std::vector<int>> &board, int n) 
{ 
    int row = -1; 
    int col = -1; 
    bool is_empty = false; 

    for (int i = 0; i < n; i++) 
    { 
        for (int j = 0; j < n; j++) 
        { 
            if (board[i][j] == 0) 
            { 
                row = i; 
                col = j; 
                is_empty = true; 
                break; 
            } 
        } 
        if (is_empty) 
            break; 
    } 
    if (!is_empty) 
        return true; 

    for (int num = 1; num <= n; num++) 
    { 
        if (IsValid(board, row, col, num)) 
        { 
            board[row][col] = num; 
            if (SolveSudoku(board, n)) 
                return true; 
            else
                board[row][col] = 0;
        } 
    } 
    return false; 
} 

int SolveSudoku(std::vector<std::vector<int>> &board, int n) 
{ 
    if (SolveSudoku(board, n) == false)  
        return 0; 

    return 1; 
}

