public int[,] MultiplyMatrix(int[,] A, int[,] B) 
{ 
  // Get the size of both the matrices 
  int rowA = A.GetLength(0); 
  int columnA = A.GetLength(1); 
  int rowB = B.GetLength(0); 
  int columnB = B.GetLength(1); 

   // Initalize a new matrix 
  int[,] C = new int[rowA, columnB]; 

   // Check if number of rows of first matrix matches 
   // number of columns of second matrix 
  if (columnA != rowB) 
  { 
    Console.WriteLine("Matrix multiplication not possible"); 
    return null; 
  } 

   // Multiply and store in matrix C 
  for (int i = 0; i < rowA; i++) 
    for (int j = 0; j < columnB; j++) 
      for (int k = 0; k < columnA; k++) 
        C[i, j] += A[i, k] * B[k, j]; 

  return C; 
}

