def isSubtree(s, t):
  #Base case 
  if (s is None): 
    return False

  if (isSameTree(s, t)): 
    return True

  # If the tree with root as current node doesn't match then try left and right subtrees one by one 
  return isSubtree(s.left, t) or isSubtree(s.right, t)

# Helper Function to check if a tree is same as
# another tree 
def isSameTree(s, t): 
    # Base Case 
    if (s is None and t is None): 
        return True

    # Check if the data of both roots is same and data of 
    # left and right subtrees are also same 
    if (s is not None and t is not None): 
        return (s.data == t.data and isSameTree(s.left, t.left) and isSameTree(s.right, t.right)) 

    # Return False if neither of above conditions is true 
