// Iterates over an array and swaps values if they're out of order until they are sorted

// Ascending order
function bubbleSortAsc(arr) {
  let length = arr.length;
  let i, j, temp;

  for (i = 0; i < length; i++) {
    for (j = 0; j < length; j++) {
      if (arr[j] > arr[j+1]) {
        temp = arr[j];
        arr[j] = arr[j+1];
        arr[j+1] = temp;
      }
    }
  }
  return arr;
}

// Descendding order
function bubbleSortDesc(arr) { 
  let length = arr.length;
  let i, j, temp;

  for (i = 0; i < length; i++) {
    for (j = 0; j < length; j++) {
      if (arr[j] < arr[j+1]) {
        temp = arr[j];
        arr[j] = arr[j+1];
        arr[j+1] = temp;
      }
    }
  }
  return arr;
}

