  root = insert(student, root); 
 } 

 private BSTNode insert(Student student, BSTNode node) {  
  if (node == null) { 
   node = new BSTNode(student); 
  }
  else { 
   if (node.student.name.compareTo(student.name) > 0) {
    node.left = insert(student, node.left); 
   }
   else if (node.student.name.compareTo(student.name) < 0){ 
    node.right = insert(student, node.right); 
   }
  }
  return node; 
 } 
}

