public class LongestCommonSubstring { 

    static String findLCSubStr(String X, String Y, int m, int n) 
    { 
        // Create a table to store lengths of  
        // longest common suffixes of substrings.  
        int LCSuff[][] = new int[m + 1][n + 1]; 

        // To store the length of  
        // longest common substring 
        int len = 0;  

        // To store the index  
        // of the cell which contains 
        // the maximum value. 
        int row = 0, col = 0;  

        /* Following steps build LCSuff[m+1][n+1]  
        in bottom up fashion. */
        for (int i = 0; i <= m; i++) 
        { 
            for (int j = 0; j <= n; j++) 
            { 
                if (i == 0 || j == 0) 
                    LCSuff[i][j] = 0; 

                else if (X.charAt(i - 1) ==  
                         Y.charAt(j - 1)) 
                { 
                    LCSuff[i][j] = LCSuff[i - 1][j - 1] + 1; 
                    if (len < LCSuff[i][j]) 
                    { 
                        len = LCSuff[i][j]; 
                        row = i; 
                        col = j; 
                    } 
                }  
                else LCSuff[i][j] = 0; 
            } 
        } 

        // if true, then no common substring 
        // exists 
        if (len == 0) 
            return ""; 

        // allocate space for the longest common substring 
        String resultStr = "";  

        // traverse up diagonally from the (row, col) 
        // cell until LCSuff[row][col] != 0 
        while (LCSuff[row][col] != 0) 
        { 
            resultStr = X.charAt(row - 1) + resultStr;  
            --len; 

            // move diagonally up to previous cell 
            row--; 
            col--; 
        }  

        return resultStr; 
    }  

    // Driver Code 
    public static void main(String[] args) 
    { 
        String X = "ABCABCAB"; 
        String Y = "AABCA"; 

        int m = X.length(); 
        int n = Y.length(); 

        System.out.println("Length of Longest Common Substring is "
                       + findLCSubStr(X, Y, m, n)); 
    } 
}

