// A linked list node 
struct Node 
{ 
	int data; 
	struct Node *next; 
}; 

// Merge two sorted linked lists and return the result 
struct Node* mergeList(struct Node* list1, struct Node* list2) 
{ 
	struct Node *list3; 

	// Checks if one of the list is empty 
	if (list1 == NULL) 
		return list2; 
	if (list2 == NULL) 
		return list1; 

	// Full check which node has a lower value 
	if (list1->data <= list2->data) 
	{ 
		list3 = list1; 
		list3->next = mergeList(list1->next, list2); 
	} 
	else
	{ 
		list3 = list2; 
		list3->next = mergeList(list1, list2->next); 
	} 
	return list3; 
} 

// Function to insert a node at the beginning of the linked list 
void push(struct Node** head_ref, int new_data) 
{ 
	// Memory allocation for new node 
	struct Node* new_node = (struct Node*)malloc(sizeof(struct Node)); 

	// Inserting data in the new node 
	new_node->data = new_data; 

	// Pointing the head to given nodes' next 
	new_node->next = (*head_ref); 

	// Make head point to the new node 
	(*head_ref) = new_node; 
} 

// Function to print nodes in a given linked list 
void printList(struct Node *node) 
{ 
	while (node != NULL) 
	{ 
		printf("%d ", node->data); 
		node = node->next; 
	} 
} 

