function reverseArrayInPlace(arr) {
    let startIndex = 0;
    let lastIndex = arr.length - 1;

    while (startIndex < lastIndex) {
        let temp = arr[startIndex];
        arr[startIndex] = arr[lastIndex];
        arr[lastIndex] = temp;
        startIndex += 1;
        lastIndex -= 1;
    }

    return arr;
}

