public static int findLongestIncreasingSubarray(int[] array) {
    int maxLength = 0;
    int curLength = 0;
    for (int i=0; i<array.length-1; i++) {
        if (array[i] < array[i+1]) { // increasing subarray
            curLength++;
            maxLength = Math.max(maxLength, curLength);
        } else { // decreasing subarray
            curLength = 0;
        }
    }
    return maxLength + 1;
}

