            'up': (0, -1),
            'down': (0, 1)
        }
        # Return the appropriate direction vector
        return direction_vectors.get(direction)

    def render_board(self):
        # Render the board state
        print('+' + '-'*len(self.board[0]) + '+')
        for row in self.board:
            print('|' + ''.join(map(self.render_cell, row)) + '|')
        print('+' + '-'*len(self.board[0]) + '+')

    def render_cell(self, cell):
        # Render the cell state
        if cell == 0:
            return ' '
        elif cell == 1:
            return 'S'
        elif cell == 2:
            return 'F'

