public class GeneratePassword {

    public static String generatePassword() {
        // Define possible characters
        String upperCaseLetters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
        String lowerCaseLetters = "abcdefghijklmnopqrstuvwxyz";
        String numbers = "0123456789";
        String specialCharacters = " !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";
        // Generate random length
        Random random = new Random();
        int length = random.nextInt((12 - 8) + 1) + 8;
        // Generate random password
        String password = "";
        for (int i = 0; i < length; i++) {
            int randomCharacterIndex = random.nextInt(4);
            if (randomCharacterIndex == 0) {
                password += upperCaseLetters.charAt(random.nextInt(upperCaseLetters.length()));
            } else if (randomCharacterIndex == 1) {
                password += lowerCaseLetters.charAt(random.nextInt(lowerCaseLetters.length()));
            } else if (randomCharacterIndex == 2) {
                password += numbers.charAt(random.nextInt(numbers.length()));
            } else {
                password += specialCharacters.charAt(random.nextInt(specialCharacters.length()));
            }
        }
        return password;
    }
}

