def isValidBooleanExpression(expr):
    # Check if string is empty
    if not expr:
        return False

    # Create two empty stacks for operatorsand operands
    operand_stack = []
    operator_stack = []

    # Iterate through the string
    for char in expr:

        # If a number then push it onto the operand stack
        if char.isdigit():
            operand_stack.append(char)

        # If an operator (or parenthesis) then push it onto the operator stack
        elif char in ['+', '-', '*', '^', '(', ')']:
            operator_stack.append(char)

    # all characters must have been either
    # operator or operand thus, stacks must be empty
    if not operator_stack or not operand_stack:
        return False

    return True

