def summarize(text):
    # tokenize the text
    words = nltk.word_tokenize(text)

    # calculate the word frequency
    word_frequencies = {}
    for word in words:
        if word not in word_frequencies:
            word_frequencies[word] = 0
        word_frequencies[word] += 1

    # create the frequency table
    max_frequency = max(word_frequencies.values())
    words_frequency = {word: freq/max_frequency for word, freq in word_frequencies.items()}

    # calculate the sentence score
    sentence_scores = {}
    for sent in nltk.sent_tokenize(text):
        for word in nltk.word_tokenize(sent):
            if word in words_frequency:
                if sent not in sentence_scores:
                    sentence_scores[sent] = 0
                sentence_scores[sent] += words_frequency[word]

    # output the summary
    summary_sentences=[sent for sent in sentence_scores.keys() if sentence_scores[sent] > 0.2]
    summary = ' '.join(summary_sentences)

    return summary

