def find_max_sum(input_list, size):
    total_sum = 0
    start = 0
    end = size
    index = 0
    while start < len(input_list) and end <= len(input_list):
        for i in range(start, end):
            total_sum += input_list[i]
        if total_sum > index:
            index = total_sum
            start = end
            end += size
        else:
            start = end 
            end += size
    return index

