public class SortArrayOfIntegersByFrequency { 

    static void sortByFrequency(int arr[], int n) 
    { 
        // Array of size n 
        int temp[][] = new int[n][2]; 

        // Take elements of arr[] one by one 
        for (int i = 0; i < n; i++) { 
            // Create key with array element as data 
            // and its frequency as index 
            int key = arr[i]; 
            temp[key][0] = key; 

            // Increment the frequency of the 
            // created key by 1 
            ++temp[key][1]; 
        } 

        // Sort the array temp[][] according to 
        // frequency of elements. 
        Arrays.sort(temp, 
            new Comparator<int[]>() { 
                @Override public int compare(int[] o1, 
                                  int o2[]) 
                { 
                    //returning the result of 
                    //comparison between 
                    //o1[1] and o2[1] 
                    return o2[1] - o1[1]; 
                } 
            }); 

        // Store the elements of temp[][] 
        // back to arr[][] 
        for (int i = 0; i < n; i++) { 
            arr[i] = temp[i][0]; 
        } 

        // Print the rearranged array 
        for (int i = 0; i < n; i++) 
            System.out.print(arr[i] + " "); 
    } 

    // Driver method 
    public static void main(String args[]) 
    { 
        int arr[] = {2, 3, 3, 3, 3, 3, 8, 8, 1}; 
        int n = arr.length; 
        sortByFrequency(arr, n); 
    } 
}

