public void sortList(Node head) 
{ 
    Node listStart = null; 
    Node listEnd = null; 

    Node currentNode = head; 

    // Traverse the given list and  
    // move/insert each node to the  
    // sorted list like insertion sort 
    while (currentNode != null)  
    { 
        // Store the next pointer of the currentNode 
        Node next = currentNode.next; 

        // If the head of the sorted list is null, 
        // make the currentNode as head 
        if (listStart == null) 
        { 
            listStart = currentNode; 
            listEnd = currentNode; 
        } 
        else
        { 
            // If the currentNode data ('data') 
            // is less than or equal the data 
            // of listStart node, insert currentNode 
            // at the beginning of the sorted list 
            if (currentNode.data <= listStart.data)  
            { 
               currentNode.next = listStart; 
               listStart = currentNode; 
            } 

            // If the currentNode data is greater 
            // than the data of listEnd node, 
            // insert currentNode at the end 
            // of the sorted list 
            else if (currentNode.data >= listEnd.data)  
            { 
               listEnd.next = currentNode; 
               listEnd = currentNode; 
            } 
            else
            { 
                // Find out the appropriate position 
                // of the currentNode in the sorted list 
                // and insert currentNode into it's position 
                Node position = listStart; 
                while (position.next != null && position.next.data < currentNode.data ) 
                { 
                    position = position.next; 
                } 

                currentNode.next = position.next; 
                position.next = currentNode; 
            } 
        } 
        // Update the currentNode 
        currentNode = next; 
    } 

    head = listStart; 
}

