class KFrequentWords {
    private HashMap<String, Integer> words;
    private int k;

    public KFrequentWords(int k) {
        this.words = new HashMap<>();
        this.k = k;
    }

    public void add(String word) {
        if (words.containsKey(word)) {
            words.put(word, words.get(word) + 1);
        }
        else {
            words.put(word, 1);
        }
    }

    public List<String> getKMostFrequent() {
        List<String> result = new ArrayList<>();
        PriorityQueue<Map.Entry<String, Integer>> maxHeap = new PriorityQueue<>(
          (entry1, entry2) -> entry2.getValue() - entry1.getValue());

        // add all words to the max heap
        maxHeap.addAll(words.entrySet());

        // get the most frequent k words
        while (result.size() < k && !maxHeap.isEmpty()) {
            result.add(maxHeap.poll().getKey());
        }

        return result;
    }
}

