// Function to generate all prime numbers between 1 and n
std::vector<int> primes(int n) {
 // Vector to store prime numbers
 std::vector<int> primes;

 // Loop from 1 to n
 for (int i=1; i<=n; i++) {
  bool is_prime = true;

  // Check if i is divisible by any number between 2 and i
  for (int j=2; j<i; j++) {
   if (i%j == 0) {
    is_prime = false;
    break;
   }
  }

  // If i is prime, add it to the vector
  if (is_prime)
   primes.push_back(i);
 }

 return primes;
} 

