def find_median(arr):
    s_arr = sorted(arr) 
    median = -1
    # Return -1 if array length is 0
    if len(s_arr) == 0:
        return -1
    # if array length is even
    elif len(s_arr) % 2 == 0:
        median = (s_arr[int(len(s_arr)/2)] + s_arr[int((len(s_arr)/2) - 1)]) / 2
    # If array length is odd 
    else:
        median = s_arr[int(len(s_arr)/2)]
    return median

