public class RemoveDuplicates {

    public static int[] removeDuplicates(int[] arr) {
        if (arr.length == 0 || arr.length == 1) {
            return arr;
        }

        int[] temp = new int[arr.length];
        int j = 0;
        for (int i=0; i < arr.length - 1; i++) {
            if (arr[i] != arr[i+1]) {
                temp[j++] = arr[i];
            }
        }
        temp[j++] = arr[arr.length - 1];

        int[] result = new int[j];
        for (int k=0; k < j; k++) {
            result[k] = temp[k];
        }

        return result;
    }

    public static void main(String[] args) {
        int[] arr = {5, 2, 4, 2, 5, 8, 6};
        int[] result = removeDuplicates(arr);
        for (int i=0; i < result.length; i++) {
            System.out.print(result[i]+" ");
        }
    }
}

def int_to_text(num):
    # store numbers less than ten as strings
    nums = {
        0: "zero", 1: "one", 2: "two", 3: "three", 4: "four",
        5: "five", 6: "six", 7: "seven", 8: "eight", 9: "nine"
    }
    # if the number is greater than ten, add the appropriate suffix
    suffixes = {
        10: "teen", 20: "twenty", 30: "thirty",
        40: "forty", 50: "fifty", 60: "sixty",
        70: "seventy", 80: "eighty", 90: "ninety"
    }
    # store the number as a string
    num_string = ""

    # if the number is less than 10, use the pre-defined string
    if num < 10:
        num_string = nums[num]
    # if the number is greater than 10, add the appropriate suffix
    elif num > 10 and num < 100:
        num_string = suffixes[(num // 10) * 10]
        if num % 10 != 0:
            num_string += "-" + nums[num % 10]

    return num_string

