// Function to sort array in ascending order
void sortAscending(int arr[], int size)
{
  int i, j;

  for (i = 0; i < (size - 1); i++)
  {
    // Find the index of the minimum value in the array
    int min = i;

    for (j = (i + 1); j < size; j++)
    {
      if (arr[j] < arr[min])
      {
        min = j;
      }
    }

    // Swap the values
    int temp = arr[i];

    arr[i] = arr[min];
    arr[min] = temp;
  }
}

