extension String {
 func toTitleCase() -> String {
 guard !self.isEmpty else { return self }

 var output = self
 let words = output.components(separatedBy: " ")

 for (index, word) in words.enumerated() {
 let firstLetter = word[word.startIndex..<word.index(word.startIndex, offsetBy: 1)]
 words[index] = firstLetter.capitalized + word[word.index(word.startIndex, offsetBy: 1)...]
 }

 output = words.joined(separator: " ")

 return output
 }
}

