def bubble_sort(list):
    sorted = False

    while not sorted:
        sorted = True
        for i in range(len(list) - 1):
            if list[i] > list[i + 1]:
                sorted = False
                list[i], list[i + 1] = list[i + 1], list[i]

    return list

