 type Mutation {
 updateBook(id: Int!, title: String, author: String): Book
 }
 type Book {
 title: String
 author: String
 id: Int
 }
`;

// The resolvers
const resolvers = {
 Query: {
 book: (parents, args) => {
 return books.find(book => book.id == args.id)
 }
 },
 Mutation: {
 updateBook: (parents, args) => {
 const updatedBook = {
 title: args.title,
 author: args.author,
 id: args.id
 };
 books.push(updatedBook);
 return updatedBook;
 }
 }
};

// Put together a schema
const server = new ApolloServer({
 typeDefs,
 resolvers
});

