def is_perfect_square(x):
    res = False
    if x > 0:
        if x % 4 == 0:
            i = 1
            while i <= x/2:
                if i*i == x:
                    res = True
                i += 1
        else:
            i = 2
            while i <= x/2:
                if i*i == x:
                    res = True
                i += 2
    return res

