public class AverageTemp {

    public static void main(String[] args) {
        ArrayList<CityTemperature> temperatures = new ArrayList<>();
        temperatures.add(new CityTemperature("New York", 43));
        temperatures.add(new CityTemperature("Tokyo", 55));
        temperatures.add(new CityTemperature("Paris", 49));

        double totalTemp = 0;
        for (CityTemperature cityTemp : temperatures) {
            totalTemp += cityTemp.temperature;
        }

        double averageTemp = totalTemp / temperatures.size(); 
        System.out.println("Average Temperature: " + averageTemp);
    }

    static class CityTemperature {
        String city;
        double temperature;

        CityTemperature(String city, double temperature) {
            this.city = city;
            this.temperature = temperature;
        }
    }

}

