def is_anagram(str1, str2):
    # Create two empty dictionaries
    str1_count = {}
    str2_count = {}

    # Iterate over all characters in both strings
    for char in str1:
        if char in str1_count:
            str1_count[char] += 1
        else:
            str1_count[char] = 1
    for char in str2:
        if char in str2_count:
            str2_count[char] += 1
        else:
            str2_count[char] = 1

    # Check if both dictionaries contain same character counts
    if str1_count == str2_count:
        return True
    else:
        return False

