def is_latin_square(array):
    """RETURN True if the supplied 2D array is a Latin square, False otherwise."""
    size = len(array)
    expected_sum = size*(size+1)//2
    # traverse in row-major order
    for row in array:
        if len(row) != size or sum(row) != expected_sum:
            return False
    # traverse in column-major order
    for col in zip(*array):
        if len(col) != size or sum(col) != expected_sum:
            return False
    return True

