import numpy as np

class GridWorld: 
  def __init__(self, grid, rewards, gamma=0.9):
    self.grid = grid
    self.rewards = rewards
    self.height = len(self.grid)
    self.width = len(self.grid[0])
    self.gamma = gamma

  def get_next_state(self, state, action):
    x, y = self.grid[state]
    if action == "up":
      if y == 0:
        new_state = state
      else:
        new_state = (x, y - 1)
    elif action == "down":
      if y == self.height - 1:
        new_state = state
      else:
        new_state = (x, y + 1)
    elif action == "left":
      if x == 0:
        new_state = state
      else:
        new_state = (x - 1, y)
    elif action == "right":
      if x == self.width - 1:
        new_state = state
      else:
        new_state = (x + 1, y)
    return new_state

  def get_reward(self, state):
    return self.rewards[state]

  def get_value_function(self, value_table):
    return np.max(value_table)

  def get_all_states_and_actions(self):
    states = []
    actions = ["up", "down", "left", "right"]
    for i in range(self.height):
      for j in range(self.width):
        states.append((i, j))
    return states, actions

  def get_value_table(self, state, value_table):
    x, y = self.grid[state]
    best_action = ""
    best_value = -99999

    # Compute the value table according to Bellman equation
    for action in ["up", "down", "left", "right"]:
      new_state = self.get_next_state(state, action)
      reward = self.get_reward(new_state)
      value = reward + self.gamma * value_table[new_state]

      # Get the best value and corresponding action for this state
      if value > best_value:
        best_value = value
        best_action = action

    return best_value, best_action

