    """ Function to generate a list of the top 5 most frequent words in a given text"""
    # split input string into words
    words = text.split(' ')
    # create an empty dictionary
    word_freq = {}
    # iterate over word list and count frequencies
    for word in words:
        if word in word_freq:
            word_freq[word] += 1
        else:
            word_freq[word] = 1
    # sort dictionary by value and return the top 5 items
    return sorted(word_freq.items(), key=lambda kv: kv[1], reverse=True)[:5]

