def is_subset(arr1, arr2): 
    # Create a dictionary to store the count of 
    # elements in the first array 
    element_count = {} 
    for element in arr1: 
        if element in element_count: 
            element_count[element] += 1
        else: 
            element_count[element] = 1

    # Iterate through the second array and 
    # check if every element is present in the dictionary
    for element in arr2: 
        if element in element_count: 
            element_count[element] -= 1
            if element_count[element] == 0: 
                del element_count[element]
        else: 
            return False

    # If all the elements have been encountered, 
    # the first array is a subset of the second
    if len(element_count) == 0: 
        return True
    return False

