class MinHeap {
 public:
 MinHeap(std::vector<int> data);
 void insert(int item);
 int extract_min();

 private:
 std::vector<int> heap;
 void heapify(int index);
 void bubble_up(int index);
};

MinHeap::MinHeap(std::vector<int> data) {
 // make heap property true by heapifying all nodes
 for (int i = (data.size() - 1) / 2; i >= 0; i--) {
 heapify(i);
 }
 heap = data;
}

void MinHeap::heapify(int index) {
 int left = 2 * index + 1;
 int right = 2 * index + 2;
 int smallest = index;

 if (left < heap.size() && heap[left] < heap[smallest]) {
 smallest = left;
 }
 if (right < heap.size() && heap[right] < heap[smallest]) {
 smallest = right;
 }

 if (smallest != index) {
 std::swap(heap[index], heap[smallest]);
 heapify(smallest);
 }
}

void MinHeap::bubble_up(int index) {
 int parent = (index - 1) / 2;

 if (index > 0 && heap[parent] > heap[index]) {
 std::swap(heap[index], heap[parent]);
 bubble_up(parent);
 }
}

void MinHeap::insert(int item) {
 heap.push_back(item);
 bubble_up(heap.size() - 1);
}

int MinHeap::extract_min() {
 int min = heap[0];

 std::swap(heap[0], heap[heap.size() - 1]);
 heap.pop_back();

 heapify(0);

 return min;
}

