public int binaryToDecimal(string binaryString) 
{ 
    int dec = 0;
    int number = 1; 

    for (int i = binaryString.Length - 1; i >= 0; i--) 
    { 
        int temp = binaryString[i] - '0'; 
        dec += temp * number; 
        number = number * 2; 
    } 

