function primesInRange(start, end) {
  let primes = [];
  for (let number = start; number <= end; number = number + 1) {
    let isPrime = true;

    for (let div = 2; div <= Math.sqrt(number); div = div + 1) {
      if (number % div === 0) {
        isPrime = false;
        break;
      }
    }

    if (isPrime && number>1) {
      primes.push(number);
    }
  }
  return primes;
}

