public TreeNode reverseEngineeringTree(String[] data) {
 int n = data.length;
 TreeNode root = new TreeNode(data[0], new ArrayList<>());
 TreeNode currNode = root;

 for (int i = 1; i<n; i++) {
 TreeNode newNode = new TreeNode(data[i], new ArrayList<>());
 while (!isDirectChild(currNode, newNode)) 
 currNode = currNode.children.get(currNode.children.size() - 1);
 currNode.children.add(newNode);
 currNode = newNode;
 }

 return root;
}

private boolean isDirectChild(TreeNode parent, TreeNode child) {
 return parent.value.length() + 1 == child.value.length() &&
 child.value.substring(0, parent.value.length()).equals(parent.value);
}

