function lcs(s1, s2) {
 const matrix = Array(s1.length + 1)
 .fill()
 .map(() => Array(s2.length + 1).fill(null));

 // Initialize first column with zeroes
 for (let rowIndex = 0; rowIndex <= s1.length; rowIndex += 1) {
 matrix[rowIndex][0] = 0;
 }

 // Initialize first row with zeroes
 for (let colIndex = 0; colIndex <= s2.length; colIndex += 1) {
 matrix[0][colIndex] = 0;
 }

 // Fill the matrix
 for (let rowIndex = 1; rowIndex <= s1.length; rowIndex += 1) {
 for (let colIndex = 1; colIndex <= s2.length; colIndex += 1) {
 if (s1[rowIndex - 1] === s2[colIndex - 1]) {
 matrix[rowIndex][colIndex] = matrix[rowIndex - 1][colIndex - 1] + 1;
 } else {
 matrix[rowIndex][colIndex] = Math.max(
 matrix[rowIndex - 1][colIndex],
 matrix[rowIndex][colIndex - 1],
 );
 }
 }
 }

 // Extract the longest common sub-sequence from the matrix
 const longestSubsequence = [];
 let rowIndex = s1.length;
 let colIndex = s2.length;
 while (rowIndex !== 0 || colIndex !== 0) {
 if (s1[rowIndex - 1] === s2[colIndex - 1]) {
 longestSubsequence.unshift(s1[rowIndex - 1]);
 rowIndex -= 1;
 colIndex -= 1;
 } else if (matrix[rowIndex][colIndex] === matrix[rowIndex - 1][colIndex]) {
 rowIndex -= 1;
 } else {
 colIndex -= 1;
 }
 }

 return longestSubsequence;
}

