function evaluateExpression(expression) {
  const stack = [];
  for(let i = 0; i < expression.length; i++) {
    const char = expression.charAt(i);
    if(!isNaN(Number(char))) {
      stack.push(Number(char));
    } else {
      const x = stack.pop();
      const y = stack.pop();
      switch(char) {
        case '+': stack.push(y + x); break;
        case '-': stack.push(y - x); break;
        case '*': stack.push(y * x); break;
        case '/': stack.push(y / x); break;
      }
    }
  }
  return stack.pop();
}

