// function to remove duplicates 
void removeDuplicates(int arr[], int n) 
{ 
    // Store occurrence in an array
    int temp[n]; 

    // Initialize the occurrence array
    memset(temp, 0, sizeof(temp)); 

    for (int i=0; i<n; i++) 
    {  
        temp[arr[i]]++; 
    } 

    int index = 0; // to store index of modified array 
    for (int i=0; i<n; i++) 
    { 
        if (temp[arr[i]] != 0) 
        { 
            arr[index++] = arr[i]; 
            temp[arr[i]] = 0; 
        } 
    } 

    // print the array after removing duplicates
    for (int i=0; i<index; i++) 
        cout << arr[i] << " "; 
} 

