void freq(int arr[], int n) 
{ 
    // Flag array to store whether an element 
    // has been visited or not 
    int visited[n]; 

    for (int i = 0; i < n; i++) 
        visited[i] = 0; 

    for (int i = 0; i < n; i++) 
    { 
        if (visited[i] == 0) 
        { 
            int count = 1; 
            for (int j = i + 1; j < n; j++) 
            { 
                if (arr[i] == arr[j]) 
                { 
                    visited[j] = 1; 
                    count++; 
                } 
            } 
            cout << arr[i] << " occurs "
                 << count << " times" << endl; 
        } 
    } 
} 

