class Node {
    int data; 
    Node next;
}

// Function to determine if a linked list contains a cycle
boolean hasLoop(Node head) {
    Node slow = head; 
    Node fast = head;

    while(fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;

        if(slow == fast)
            return true;
    }

    return false; 
}

