def binary_tree_to_array(root):
    output = []
    if not root:
        return output

    # Create a queue to do level order traversal
    queue = [root]
    while queue:
        node = queue.pop(0)
        output.append(node.val)

        # Enqueue the children of the popped node
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)

    return output

def quick_sort(list):
    if len(list) <= 1:
        return list
    else:
        pivot = list[0]
        less = [element for element in list[1:] if element < pivot]
        greater = [element for element in list[1:] if element >= pivot]
        return quick_sort(less) + [pivot] + quick_sort(greater)

