// Function to find the median of an array 
double findMedian(int array[], int size)
{ 
    double median;
    // Sanity check for cases with 0 elements 
    if (size == 0) 
        return 0; 
    // Sort the array 
    std::sort(array, array + size); 

    // Create an index which finds the middle 
    // of array
    int mid = (size - 1) / 2; 

    // If size of array is even 
    if (size % 2 == 0) 
        median = (array[mid] + array[mid + 1]) / 2.0; 
    else
        median = array[mid]; 

    return median; 
} 

