def quickSort(list1):
    if len(list1) < 2:
        return list1
    else:
        pivot = list1[0]
        less_than_pivot = [i for i in list1[1:] if i <= pivot]
        greater_than_pivot = [i for i in list1[1:] if i > pivot]
        return quickSort(less_than_pivot) + [pivot] + quickSort(greater_than_pivot)

