def unique_values(arr):
    # Initialize count
    count=0

    # Iterate through the array
    for i in range(len(arr)):
        found = False
        #Iterate through the remainder of array 
        for j in range(i+1, len(arr)):
            if arr[i]== arr[j]:
                found = True
        # If the same number not found, then increase count
        if found == False:
            count+=1

    # Return the count
    return count

