void solveEquation(int a, int b, int c) { 
    double x, y;

    if (a == 0) // if a is zero
    {
        if (b == 0)        
            std::cout << "No solution"; // no solution exists
        else 
            std::cout << "Infinite solutions"; // infinite solutions exist
    } 
    else 
    { 
        y = (c - a*x) / b; // solve for y 
