    } 
} 

// Function to solve a system of equations 
void solveSystemOfLinearEquations(int a1, int b1, int c1, int a2, int b2, int c2) 
{ 
    int a, b, c; 

    a = (b2*c1 - b1*c2) / (a1*b2 - b1*a2); 
    b = (a1*c2 - a2*c1) / (a1*b2 - b1*a2); 
    c = (a1*b2*c1 - b1*a2*c2) / (a1*b2 - b1*a2); 

    std::cout << "Solution:\n"; 
    solveEquation(a, b, c); 
} 

