struct Node 
{ 
    int data; 
    struct Node* next; 
}; 

// function to delete nodes 
void delete_nodes(struct Node* head, int n) 
{ 
    struct Node* current = head; 

    // Base case 
    if (head == NULL) 
        return; 

    // Traverse list 
    for (int i = 0; current != NULL && i < n; i++) { 
        struct Node* temp = current; 
        current = current->next; 
        free(temp); 
    } 

    head = current; 
}

