import re

def get_answer(string):
    nums = re.findall('([0-9]+)', string)
    operators = re.findall('([+-/*])', string)
    result = int(nums[0])
    if operators:
        operators = [op for op in operators if op != ' ']
        for i in range(len(operators)):
            if operators[i] == '+':
                result += int(nums[i+1])
            elif operators[i] == '-':
                result -= int(nums[i+1])
            elif operators[i] == '*':
                result *= int(nums[i+1])
            elif operators[i] == '/':
                result /= int(nums[i+1])
    return result

