class PrimeNumber {
    public static void main (String[] args) {
        int i = 2;
        int smallestNumber = 2;
        while (true) {
            boolean isPrime = true;
            for (int j = 2; j * j <= i; j++) {
                if (i % j == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime && i * i <= Integer.MAX_VALUE) {
                smallestNumber = i;
                break;
            }
            i++;
        }

        System.out.print("The smallest positive integer which when multiplied by itself forms a prime number is:" + smallestNumber);
    }
}

