def select_kth_smallest(numbers, k):
  """
  This function takes in a list of numbers and an integer k and 
  returns the kth smallest element in the list. 
  """

  # Quick select algorithm
  if k > 0 and k <= len(numbers):
    pivot = numbers[0]
    left = [x for x in numbers[1:] if x < pivot]
    right = [x for x in numbers[1:] if x >= pivot]

    if k - 1 < len(left):
      return select_kth_smallest(left, k)
    elif k - 1 == len(left):
      return pivot
    else:
      return select_kth_smallest(right, k - len(left) - 1)

