public class Optimization {
 // Function to be optimized
 public static double f(double x, double a, double b, double c) {
 return (a * Math.pow(x, 2) + b * x + c);
 }

 public static void main(String[] args) {
 // Initialize parameters
 double a = 1.0; double b = 0.0; double c = 1.0;

 // Gradient descent optimization
 double learningRate = 0.01;
 while (true) {
 // Compute error
 double error = 0;
 for (int i = 0; i < N; i++) {
 double x = inputs.get(i);
 double y = outputs.get(i);
 error += Math.pow(f(x, a, b, c) - y, 2);
 }

 // Break if error is below a certain threshold
 if (error < EPSILON) {
 break;
 }

 // Compute partial derivatives
 double grad_a = 0;
 double grad_b = 0;
 double grad_c = 0;
 for (int i = 0; i < N; i++) {
 double x = inputs.get(i);
 double y = outputs.get(i);
 grad_a += 2 * (f(x, a, b, c) - y) * Math.pow(x, 2);
 grad_b += 2 * (f(x, a, b, c) - y) * x;
 grad_c += 2 * (f(x, a, b, c) - y);
 }

 // Update parameters
 a -= learningRate * grad_a;
 b -= learningRate * grad_b;
 c -= learningRate * grad_c;
 }

 // Print optimized parameters
 System.out.println("a = " + a);
 System.out.println("b = " + b);
 System.out.println("c = " + c);
 }
}

