public class CaesarCipher {

    public static string Encrypt(string plainText, int shift) {
        if (shift > 26) {
            shift = shift % 26;
        } else if (shift < 0) {
            shift = (shift % 26) + 26;
        }
        string cipherText = string.Empty;
        int len = plainText.Length;
        for (int i = 0; i < len; i++) {
            char ch = plainText[i];
            if (char.IsLetter(ch)) {
                char offset = char.IsUpper(ch) ? 'A' : 'a';
                cipherText += (char)((ch - offset + shift) % 26 + offset);
            } else {
                cipherText += ch;
            }
        }
        return cipherText;
    }

}

