def delete_every_second_element(head): 
    if head is None: 
        return None 
    prev, curr = None, head 

    while curr is not None:  
        next = curr.next
        if next is not None: 
            prev = curr 
            curr = next.next 
        else: 
            prev = curr
            curr = next 

        prev.next = curr 
    return head

