public class TwoDSorting {  
    // Function to sort a 2D array in ascending order  
    public static void sort2DArray(int[][] arr) {  
        int temp = 0;  
        for (int i = 0; i < arr.length; i++) {  
            for (int j = 0; j < arr[i].length; j++) {  
                for (int k = j+1; k < arr[i].length; k++) {  
                    if(arr[i][j] > arr[i][k]) {  
                        temp = arr[i][j];  
                        arr[i][j] = arr[i][k];  
                        arr[i][k] = temp;  
                    }  
                }  
            }  
        }  
    }  
    public static void main(String[] args) {  
        // Sample 2D array  
        int arr[][] = {{2, 3, 5}, {7, 9, 6}, {8, 4, 1}};   
