public static int binarySearch(int[] array, int target) {
 int l = 0, r = array.length - 1;
 while (l <= r) {
 int mid = (l + r) / 2;
 if (array[mid] == target) {
 return mid;
 } else if (array[mid] < target) {
 l = mid + 1;
 } else {
 r = mid - 1;
 }
 }
 return -1;
}

