char* convertToCharArray(vector<string> strList) 
{ 
    int string_length = 0; 
    for (int i=0; i<strList.size(); i++){ 
        string_length += strList[i].length(); 
    } 

    // Create an array of size string_length 
    char* array_char = (char*)malloc((string_length+1)*sizeof(char)); 

    int index = 0; 
    for (int i=0; i<strList.size(); i++) { 
        // Copy the current string to array_char[] 
        int j; 
        for (j=0; j<strList[i].length(); j++) 
            array_char[index++] = strList[i][j]; 

        // Add a space after current string 
