public class SnakeGame extends JFrame {
 // Game window size
 private static final int WIDTH = 300;
 private static final int HEIGHT = 300;

 // start position and size of snake
 private static final int SNAKE_X_START = 150;
 private static final int SNAKE_Y_START = 150;
 private static final int SNAKE_SIZE = 10;

 // game state
 private boolean isRunning;
 private boolean isPaused;

 // score
 private int score;

 // create snake
 private Snake snake = new Snake(SNAKE_X_START, SNAKE_Y_START, SNAKE_SIZE);

 public SnakeGame() {
  // set window size and title
  setSize(WIDTH, HEIGHT);
  setTitle("Snake");

  // add canvas to window
  add(new GameCanvas());

  // set default close operation
  setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
  // set window to appear in the center of the screen
  setLocationRelativeTo(null);
  // make it visible
  setVisible(true);
  // disables resizing
  this.setResizable(false);

  // key listener
  addKeyListener(new SnakeKeyListener());

  isRunning = true;
 }

 private class GameCanvas extends Canvas {
  @Override
  public void paint(Graphics g) {
   snake.paint(g);
  }
 }

 private class SnakeKeyListener extends KeyAdapter {
  @Override
  public void keyPressed(KeyEvent e) {
   if(e.getKeyCode() == KeyEvent.VK_UP) {
    // up key is pressed
    snake.changeDirection(Snake.Direction.UP);
   } else if(e.getKeyCode() == KeyEvent.VK_DOWN) {
    // down key is pressed
    snake.changeDirection(Snake.Direction.DOWN);
   } else if(e.getKeyCode() == KeyEvent.VK_LEFT) {
    // left key is pressed
    snake.changeDirection(Snake.Direction.LEFT);
   } else if(e.getKeyCode() == KeyEvent.VK_RIGHT) {
    // right key is pressed
    snake.changeDirection(Snake.Direction.RIGHT);
   } else if(e.getKeyCode() == KeyEvent.VK_P) {
    isPaused = !isPaused;
   }
  }
 }

 public void run() {
  while(isRunning) {
   if (!isPaused) {
    snake.update();
    repaint();
    score++;
   }
  }
 }

 public static void main(String[] args) {
  SnakeGame game = new SnakeGame();
  game.run();
 }
}

class Snake {
 // snake position and size
 private int x, y, size;
 // the snake's direction
 private Direction direction;

 public enum Direction {
  UP, DOWN, LEFT, RIGHT
 }

 public Snake(int x, int y, int size) {
  this.x = x;
  this.y = y;
  this.size = size;
  this.direction = Direction.RIGHT;
 }

 public void changeDirection(Direction dir) {
  this.direction = dir;
 }

 public void update() {
  // update the position of the snake according to its current direction
  switch (direction) {
   case UP:
    y -= size;
    break;
   case DOWN:
    y += size;
    break;
   case LEFT:
    x -= size;
    break;
   case RIGHT:
    x += size;
    break;
  }
 }

 public void paint(Graphics g) {
  g.setColor(Color.GREEN);
  g.fillRect(x, y, size, size);
 }
}

