public class PerfectBinaryTree {
 public Node create(int n) {
 if (n <= 0) {
 return null;
 }

 Node root = new Node(1);
 Queue<Node> q = new LinkedList<>();
 q.add(root);

 while (n > 1) {
 n -= 2;
 Node node = q.remove();
 node.left = new Node(n);
 node.right = new Node(n - 1);
 q.add(node.left);
 q.add(node.right);
 }

 return root;
 }

}

