public class SpiralMatrix { 

    public static void printMatrixInSpiralOrder(int N) { 
       int rowStart = 0; 
        int rowEnd = N-1; 
        int colStart = 0; 
        int colEnd = N-1; 

        int[][] matrix = new int[N][N]; 

        int num = 1; 
        while (rowStart <= rowEnd && colStart <= colEnd) { 
            // print top row 
            for (int i = colStart; i <= colEnd; i++) 
                matrix[rowStart][i] = num++; 

            // print right col 
            rowStart++; 
            for (int i = rowStart; i <= rowEnd; i++) 
                matrix[i][colEnd] = num++; 

            // print bottom row 
            colEnd--; 
            if (rowStart <= rowEnd) 
                for (int i = colEnd; i >= colStart; i--) 
                    matrix[rowEnd][i] = num++; 

            // print left col 
            rowEnd--; 
            if (colStart <= colEnd) 
                for (int i = rowEnd; i >= rowStart; i--) 
                    matrix[i][colStart] = num++; 

            colStart++; 
        } 

        // print Matrix 
        for (int i = 0; i < N; i++) { 
            for (int j = 0; j < N; j++) 
                System.out.print(matrix[i][j] + " "); 
            System.out.println(); 
        } 
    } 

    public static void main(String[] args) { 
       int N = 4; 
       printMatrixInSpiralOrder(N); 
    } 
}

