def create_nested_list(length, params):
    res = []
    for i in range(length):
        if params == 2:
            res.append([i] * params)
        else:
            res.append(create_nested_list(i + 1, params - 1))
    return res

function printPrimeNumbers(limit) 
{ 

    // Create a boolean array "prime[0..limit]" 
    // to mark the prime numbers
    var prime = new Array(limit+1); 

    for (var p=2; p*p<=limit; p++) 
    { 
        // If prime[p] is not changed, then 
        // it is a prime 
        if (prime[p] == undefined) 
        { 
            // Update all multiples of p 
            for (var i=p*2; i<=limit; i += p) 
                prime[i] = false; 
        } 
    } 

    // Print all prime numbers 
    for (var p=2; p<=limit; p++) 
    { 
        if (prime[p] == undefined) 
            console.log(p + " is a prime number."); 
    } 
} 

