def islands(matrix): 
	count = 0
	for i in range(len(matrix)): 
		for j in range(len(matrix[0])): 
			if (matrix[i][j] == 1): 
				count += dfs(matrix, i, j) 
	return count 

def dfs(matrix, i, j): 
	if (i < 0 or j < 0 or i >= len(matrix) or j >= len(matrix[0]) or matrix[i][j] == 0): 
		return 0

	matrix[i][j] = 0
	dfs(matrix, i - 1, j) 
	dfs(matrix, i + 1, j) 
	dfs(matrix, i, j - 1) 
	dfs(matrix, i, j + 1) 
	return 1

