import random

# Function for randomly generating a chromosome
def generate_chromosome(songs):
    chromo = []
    for song in songs:
        chromo.append(random.randint(0,1))
    return chromo

def generate_playlist(songs):
    pop_size = 4
    generations = 10

    population = []
    # Generate a population of randomly generated chromosomes
    for _ in range(pop_size):
        population.append(generate_chromosome(songs))

    # Iterate through the number of generations
    for _ in range(generations):
        new_population = []
        # Iterate through the population
        for i in range(pop_size):
            parent1 = population[i]
            parent2 = population[i + 1]
            child = crossover(parent1, parent2)
            child = mutate(child)
            new_population.append(child)
        population = new_population

    playlist = []   
    # Iterate through the final population
    for chromo in population[:pop_size]:
        # Iterate through the chromosomes
        for pos, gene in enumerate(chromo):
            if gene == 1:
                playlist.append(songs[pos])
    return playlist

# Function for crossover between two parent chromosomes
def crossover( parent1, parent2 ):
    child = []
    for i in range(len(parent1)):
        if random.random() < 0.5:
            child.append(parent1[i])
        else:
            child.append(parent2[i])
    return child

# Function for mutation within a chromosome
def mutate(chromo):
    for pos, gene in enumerate(chromo):
        if random.random() < 0.1:
            chromo[pos] = int(not gene)
    return chromo

