vector<string> parseString(string str, char delimiter) { 
    vector<string> parsedString; 
    string word = ""; 

    for (auto x : str) { 
        if (x == delimiter) { 
            parsedString.push_back(word); 
            word = ""; 
        } 
        else { 
            word = word + x; 
        } 
    } 

    parsedString.push_back(word); 
    return parsedString; 
} 

