// Function to return whether a number is an odd prime or not
bool isOddPrime(int n) {
    bool isPrime = true;
    int len = sqrt(n);

    // If number is even, it will not be a prime number
    if (n % 2 == 0)
        return false;

    // Check for odd divisors from 3 to the sqrt of the number
    for (int i = 3; i <= len; i+= 2) {
        if (n % i == 0) {
            isPrime = false;
            break;
        }
    }

    return isPrime;
}

