function maxLengthSubArray(array) {
    let start = 0; 
	let maxLen = 0;

    for (let i = 1; i < array.length; i++) { 
        if (array[i] !== array[start]) {
            if (maxLen < (i - start)) 
                maxLen = i - start; 

            start = i; 
        } 
    } 

    // If last subarray is longest 
    if (maxLen < (array.length - start)) 
        maxLen = array.length - start;

    return maxLen;
}

