public class MatchingSubarray {
    public static int[] findSubarray(int[] arr, int[] subarr) {
        int beginIndex = -1;
        for (int i=0; i<arr.length-subarr.length+1; i++) {
            if (arr[i] == subarr[0]) {
                int j;
                for (j=1; j<subarr.length; j++) {
                    if (arr[i+j] != subarr[j]) {
                        break;
                    }
                }
                if (j == subarr.length) {
                    beginIndex = i;
                    break;
                }
            }
        }
        if (beginIndex == -1) {
            return null;
        } else {
            return new int[] {beginIndex, beginIndex+subarr.length-1};
        }
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4, 5};
        int[] subarr = {4, 5};
        int[] indices = findSubarray(arr, subarr);
        if (indices == null) {
            System.out.println("Subarray does not exist.");
        } else {
            System.out.println("Starting index: " + indices[0] + ", Ending index: " + indices[1]);
        }
    }
}

