public class NumberToWord
{
    public static String numToWords(int n)
    {
        String[] units = { "zero", "one", "two", "three",
                          "four", "five", "six", "seven",
                          "eight", "nine", "ten", "eleven",
                          "twelve", "thirteen", "fourteen",
                          "fifteen", "sixteen", "seventeen",
                          "eighteen", "nineteen" };

        String[] tens = { "", "ten", "twenty", "thirty", "forty",
                         "fifty","sixty", "seventy", "eighty",
                         "ninety" };

        if (n < 0)
            return "minus " + numToWords(-1 * n);
        if (n < 20)
            return units[n];
        if (n < 100)
            return tens[n / 10] + ((n % 10 != 0) ? " " : "") + units[n % 10];
        if (n < 1000)
            return units[n / 100] + " hundred" + ((n % 100 != 0) ? " " : "") + numToWords(n % 100);
        if (n < 100000)
            return numToWords(n / 1000) + " thousand" + ((n % 10000 != 0) ? " " : "") + numToWords(n % 1000);
        if (n < 10000000)
            return numToWords(n / 100000) + " lakh" + ((n % 100000 != 0) ? " " : "") + numToWords(n % 100000);

        return numToWords(n / 10000000) + " crore" + ((n % 10000000 != 0) ? " " : "") + numToWords(n % 10000000);        
    }
    public static void main(String[] args) 
    {
        int num = 987;
        System.out.println(numToWords(num));
    }     
}

