    vowels = ['a', 'e', 'i', 'o', 'u']

    # Split the sentence into words
    words = sentence.split(' ')
    pig_latin_words = []

    # Iterate over the words 
    for word in words:

        # Check if the first letter is a vowel
        if word[0] in vowels:
            pig_word = word + 'ay'
        else:
            pig_word = word[1:] + word[0] + 'ay'

