def flatten(d):
    flat = {}
    if not isinstance(d, dict):
        return d

    for k in d.keys():
        if isinstance(d[k], dict):
            flattenInner = flatten(d[k])
            for innerK in flattenInner.keys():
                flat[k+'.'+innerK] = flattenInner[innerK]
        else:
            flat[k] = d[k]
    return flat

