def calculate_max_product(arr): 
    # Setting the first two highest numbers 
    first_highest = max(arr[0], arr[1]); 
    second_highest = min(arr[0], arr[1]); 

    # Iterating over the remaining numbers 
    for i in range(2, len(arr)): 
        # Updating the highest numbers 
        if arr[i] >= first_highest: 
            second_highest = first_highest; 
            first_highest = arr[i]; 

        # Updating the second highest number 
        elif arr[i] > second_highest: 
            second_highest = arr[i]; 

    # Return the product of the two highest numbers 
    return first_highest * second_highest; 

