import java.util.*;
import org.apache.hadoop.io.*;
import org.apache.hadoop.mapreduce.*;

public class MapReduce {
 public static class Map extends Mapper<LongWritable, Text, Text, IntWritable> {
  private final static IntWritable one = new IntWritable(1);

  public void map(LongWritable key, Text value, Context context) throws IOException, InterruptedException {
   String line = value.toString();
   String[] items = line.split(" ");

   for (String item: items) {
    context.write(new Text(item), one);
   } 
  }
 } 

 public static class Reduce extends Reducer<Text, IntWritable, Text, IntWritable> {
  public void reduce(Text key, Iterator<IntWritable> values, Context context) throws IOException, InterruptedException {
   int sum = 0;

   while(values.hasNext()) {
    sum += values.next().get();
   }

   context.write(key, new IntWritable(sum));
  }
 }

 public static void main(String[] args) throws Exception {
  Configuration conf = new Configuration();

  // Retrieve the array of values
  int[] values = {1, 2, 3, 4, 5};

  // Create and setup the MapReduce job
  Job job = Job.getInstance(conf, "MapReduce");
  job.setJarByClass(MapReduce.class);
  job.setMapperClass(Map.class);
  job.setReducerClass(Reduce.class);
  job.setOutputKeyClass(Text.class);
  job.setOutputValueClass(IntWritable.class);

  // Add each value to the job as an input
  for (int value : values) {
   FileInputFormat.addInputPath(job, new Path(value));
  }

  // Set the output path
  FileOutputFormat.setOutputPath(job, new Path(args[1]));

  // Submit the job and wait for its completion
  System.exit(job.waitForCompletion(true) ? 0 : 1);
 }
}

