import java.util.Arrays;

public class PairDifference {

    public static boolean findPair(int[] array, int diff) {
        Arrays.sort(array);

        int low = 0;
        int high = 0;

        if (array.length == 0)
            return false;

        high = array.length - 1;

        while (low < high) {
            int temp = Math.abs(array[low] - array[high]);

            if (temp == diff)
                return true;

            if (temp < diff)
                low++;
            else
                high--;
        }
        return false;
    }

    public static void main(String[] args) {
        int[] array = { 10, 20, 30, 40, 50 };
        int diff = 10; 

        System.out.println(findPair(array, diff));
    }
}

