function firstTenPrimes() { 
  // Array to store the first ten primes 
  let primes = []; 

  // Loop till primes has 10 elements 
  while (primes.length < 10) { 

    // Take a number 
    let i = 0;
    while (true) { 
      i++; 

      // Function to check if the number is prime 
      function isPrime(x) { 
        for (let i = 2; i < x; i++) { 
          if (x % i == 0) { 
            return false; 
          } 
        } 
        return true; 
      } 

      // If the number is prime, add it to the list 
      if (isPrime(i)) { 
        primes.push(i); 
        break; 
      } 
    } 
  } 

  // Return the list 
  return primes; 
} 

