import java.util.HashMap;

public class CountOccurrences {
    public static int countOccurrences(String string, String targetWord) {
        HashMap<String, Integer> wordCount = new HashMap<>();

        // Split the string into words by space
        String[] words = string.split(" ");
        for (String word : words) {
            // Initialize counter to 0
            Integer count = wordCount.get(word);
            if (count == null) {
               count = 0;
            }
            // Count the target word
            if (word.equals(targetWord)) {
                count++;
            }
            // Put the word with the updated count in hashmap
            wordCount.put(word, count);
        }
        return wordCount.get(targetWord);
    }

