class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_string_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, s):
        temp = self.root
        for c in s:
            if c not in temp.children:
                temp.children[c] = TrieNode()
            temp = temp.children[c]
        temp.is_string_end = True

    def search(self, s):
        temp = self.root
        for c in s:
            if c not in temp.children:
                return False
            temp = temp.children[c]
        return temp.is_string_end

