  Node curr = head;
  while (curr != null) {
   if (curr.data.equals(value)) {
    return true;
   }
   curr = curr.next;
  }
  return false;
 }

 // Delete the first node with the given value from the list
 public void delete(String value) {
  Node curr = head;
  Node prev = null;

  if (curr != null && curr.data.equals(value)) {
   head = curr.next;
   return;
  }

  while (curr != null && !curr.data.equals(value)) {
   prev = curr;
   curr = curr.next;
  }

  if (curr == null) {
   return;
  }

  prev.next = curr.next;
 }
}

