class Paginator {
 // initialize the Paginator class with a data array and page size
 constructor(dataArray, pageSize) {
  this.data = dataArray;
  this.pageSize = pageSize;
 }

 // method to split data into individual pages
 paginate() {
  let pages = [];
  let pageNumber = 1;
  let page = [];
  for (let i = 0; i < this.data.length; i++) {
   page.push(this.data[i]);
   if (page.length === this.pageSize || i === this.data.length - 1) {
    let b = {
     pageNumber: pageNumber,
     pageData: page
    };
    pages.push(b);
    pageNumber++;
    page = [];
   }
  }
  return pages;
 }
}

