// Function to print permutations of string s 
void permute(string s, int l, int r) 
{ 
    // Base case 
    if (l == r) 
        cout<<s<<endl; 
    else
    { 
        // Permutations made 
        for (int i = l; i <= r; i++) 
        { 

            // Swapping done 
            swap(s[l], s[i]); 

            // Recursion called 
            permute(s, l+1, r); 

            //backtrack 
            swap(s[l], s[i]); 
        } 
    } 
} 

