use std::collections::HashSet;

fn find_all_palindromes(s: &str) -> HashSet<String> {
 let mut result = HashSet::new();
 let n = s.len();

for i in 0..n {
 for j in i..n {
 let substring = &s[i..j];
 if is_palindrome(substring) {
 result.insert(substring.to_string());
 }
 }
}

return result;
}

fn is_palindrome(s: &str) -> bool {
 let n = s.len();

for i in 0..n/2 {
 if s.chars().nth(i) != s.chars().nth(n - i - 1) {
 return false;
 }
}

return true;
}

