void insertionSort(int arr[], int n)  
{  
    int i, key, j;  
    for (i = 1; i < n; i++) 
    {  
        key = arr[i];  
        j = i - 1;  

        while (j >= 0 && arr[j] > key) 
        {  
            arr[j + 1] = arr[j];  
            j = j - 1;  
        }  
        arr[j + 1] = key;  
    }  
}  

int main(){ 
    int arr[] = {7, 2, 5, 3};
    int n = sizeof(arr)/sizeof(arr[0]);
    insertionSort(arr, n);

    cout << "Sorted array: \n";  
    for (int i=0; i < n; i++)  
        cout << arr[i] << " ";  

    return 0;  
}

function sortArray(arr) {
    let temp;
    do {
        swapped = false;
        for (let i = 0; i < arr.length; i++) {
            if (arr[i] > arr[i + 1]) {
                temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                swapped = true;
            }
        }
    } while (swapped);
    return arr;
}

