public class BMICalculator {
 public static void main(String[] args) {
 // get user input
 double weight = 143;
 double heightFeet = 5;
 double heightInches = 3;

 // convert weight from lbs to kg
 double weightKG = weight * 0.4535923;

 // convert height from feet and inches to cm
 double heightCM = (heightFeet * 12 + heightInches) * 2.54;

 // calculate BMI
 double bmi = weightKG / (heightCM * heightCM);

 // format output
 DecimalFormat df = new DecimalFormat("#.##");

 System.out.println("Body Mass Index: " + df.format(bmi));

 // classify BMI
 if (bmi < 18.5) {
 System.out.println("Underweight");
 } else if (bmi >= 18.5 && bmi <= 24.9) {
 System.out.println("Normal Weight");
 } else if (bmi >= 25 && bmi <= 29.9) {
 System.out.println("Overweight");
 } else {
 System.out.println("Obese");
 }
 }
}

