function optimizeList(list) {
  // Sort list in ascending order
  list.sort((a, b) => a - b);

  // Iterate over the list
  for (let i = 0; i < list.length - 1; i++) {
    // Get the current value and the value after it
    const prevVal = list[i];
    const nextVal = list[i + 1];

    // If values are not same, replace nextVal with prevVal
    if (prevVal !== nextVal) {
      list[i + 1] = prevVal;
    }
  }

  return list;
}

