  int string2Length = string2.length();

  int[][] matrix = new int[string1Length+1][string2Length+1];

  for (int i = 0; i <= string1Length; i++) {
   matrix[i][0]=i;
  }

  for (int j = 0; j <= string2Length; j++) {
   matrix[0][j]=j;
  }

  for (int i = 1; i <= string1Length; i++) {
   char string1Char = string1.charAt(i - 1);
   for (int j = 1; j <= string2Length; j++) {
    char string2Char = string2.charAt(j - 1);

    int cost = string1Char == string2Char ? 0 : 1;

    int minimumCost = Math.min(matrix[i - 1][j] + 1,
                          matrix[i][j - 1] + 1);
    matrix[i][j] = Math.min(minimumCost ,
                       matrix[i - 1][j - 1] + cost);
   }
  }
  return matrix[string1Length][string2Length];
 }
}

