def findSubArraySums(nums, target) {
  let result = [];
  let temp = [];
  findSubArraySumsHelper(nums, target, 0, temp, result);
  return result;
}

function findSubArraySumsHelper(nums, target, start, temp, result) {
  if (target === 0) {
    result.push([...temp]);
    return;
  }

  for (let i = start; i < nums.length; i++) {
    temp.push(nums[i]);
    findSubArraySumsHelper(nums, target - nums[i], i + 1, temp, result);
    temp.pop();
  }
}

