/**
 * Function to optimize the solution time of a given 
 * mathematical equation f(x) = 3*x^2 + 2*x - 5
 */
double optimizeSolution(double x) {
    // Calculate f(x)
    double result = 3 * pow(x, 2) + 2 * x - 5;
    // Calculate f'(x)
    double derivative = 6 * x + 2;
    // Update x with x1 = x0 - f(x) / f'(x)
    x = x - result / derivative;
    return x;
}

