// Function to generate a random sequence of unique numbers from 1 to 100
void generateRandomSequence(int arr[], int n) 
{ 
    // Create an array to store result
    int result[n]; 

    // Array to hold the sequence 
    bool used[n+1];
    memset(used, 0, sizeof(used)); 

    // Iterate until all numbers are generated in the sequence
    for (int i = 0; i< n; i++) 
    { 
        // Generate a random number from 1 to n 
        int x = (rand() % (n + 1)); 
        while (used[x] == true) 
            x = (rand() % (n + 1)); 

        // Store result
        result[i] = x; 

        // Set used flag to 1
        used[x] = true; 
    } 

    // Store the result in the given array
    for (int i=0; i<n; i++) 
        arr[i] = result[i]; 

} 

