void insertionSort(int array[], int len)
{
 int temp, i , j;
 for (i=1; i<len; i++)
 {
  temp= array[i];
  j = i-1;

  while ( (j > -1) && ( array [j] > temp ) )
  {
   array [j+1] = array [j];
   j--;
  }
  array[j+1] = temp;
 }
