public class Fibonacci {

  public static int getFibonacci(int n) {
    if (n == 0) {
      return 0;
    } else if (n == 1) {
      return 1;
    }
    int a = 0;
    int b = 1;
    for (int i = 2; i <= n; i++) {
      int c = a + b;
      a = b;
      b = c;
    }
    return b;
  }

  public static void main(String[] args) {
    System.out.print(getFibonacci(10)); // 55
  }
}

