public static int longestSequence(int[] array){
    int longest = 0;
    int currentLength = 1;
    for(int i = 0; i < array.length - 1; i++){
        if(array[i] + 1 == array[i+1]){
            currentLength++; 
        } else {
            longest = Math.max(longest, currentLength);
            currentLength = 1; 
        }
    }
    return Math.max(longest, currentLength);
}

