public static void subset(int[] arr, int start, int end, int subsetSize, int currIndex, int[] data) {
    if (currIndex > subsetSize) {
        printSubsets(data);
        return;
    }

    if (start <= end) {
        data[currIndex] = arr[start];
        subset(arr, ++start, end, subsetSize, ++currIndex, data);
        subset(arr, start, end, subsetSize, currIndex, data);
    }
}

