    for (let i = 3; i < arr.length; i++) {
        if (arr[i] > highest[0]) {
            highest[0] = arr[i];
        } else if (arr[i] > highest[1]) {
            highest[1] = arr[i];
        } else if (arr[i] > highest[2]) {
            highest[2] = arr[i];
        }
    }
    return highest;
}

