string encrypt(string message, int key) 
{ 
    string encrypted_message = ""; 

    // Iterate over the original message 
    for (int i=0; i<message.length(); i++)  
    { 
        // Encrypt by shifting ASCII value 
        int tmp = int(message[i]) + key; 

        // Add resulting character 
        encrypted_message += char(tmp); 
    } 
    return encrypted_message; 
} 

