def quick_sort(list):
    if len(list) <= 1:
        return list

    pivot = list[len(list)//2]
    left_list = []
    right_list = []

    for i in list:
        if i < pivot:
            left_list.append(i)
        elif i > pivot:
            right_list.append(i)
        else:
            pass

    left_list = quick_sort(left_list)
    right_list = quick_sort(right_list)

    return left_list + [pivot] + right_list

