int mostFrequentNumber(int array[], int size)
{
    int maxCount = 0, maxElement = 0;

    for (int i = 0; i < size; i++)
    {
        int count = 0;
        for (int j = 0; j < size; j++)
        {
            if (array[i] == array[j])
            {
                count++;
            }
        }
        if (count > maxCount)
        {
            maxCount = count;
            maxElement = array[i];
        }
    }
