#include <iostream>

using namespace std;

// Structure for a node of the linked list
struct ListNode {
 int data;
 ListNode* next;
};

// Function to create a new node with given data and 
// link to next node 
ListNode* newNode(int x) {
 ListNode* temp = new ListNode;
 temp->data = x;
 temp->next = NULL;
 return temp;
}

// Function to insert a node at the beginning of linked list
void insertAtBeginning(ListNode** head_ref, int x) {
 // Create a new node with given data
 ListNode* temp = newNode(x);

 // Change the next of new node to head
 temp->next = (*head_ref);

 // Change the head to point to new node
 (*head_ref) = temp;
}

// Function to search a given key recursively 
bool searchRecursive(ListNode* head_ref, int key) {
 // Base case 
 if (head_ref == NULL)
 return false;

 // if key is present in current node,
 // return true
 if (head_ref->data == key)
 return true;

 // Recur for remaining list
 return searchRecursive(head_ref->next, key);
}

// Main code
int main() {
 // Let us create a linked list
 ListNode* head = NULL;

 // Let us insert some items in linked list
 insertAtBeginning(&head, 5);
 insertAtBeginning(&head, 4);
 insertAtBeginning(&head, 3);
 insertAtBeginning(&head, 2);
 insertAtBeginning(&head, 1);

