void countVowels(string str) 
{ 
    // Initialize the frequency array to 0
    int freq[5] = {0}; 

    // Traverse the string str
    for (int i = 0; str[i] != '\0'; i++) { 

        if (str[i] == 'a' || str[i] == 'A') 
            freq[0]++; 
        else if (str[i] == 'e' || str[i] == 'E') 
            freq[1]++; 
        else if (str[i] == 'i' || str[i] == 'I') 
            freq[2]++;
        else if (str[i] == 'o' || str[i] == 'O') 
            freq[3]++; 
        else if (str[i] == 'u' || str[i] == 'U') 
            freq[4]++; 
    } 

    // Print the frequency of vowels
    cout << "Frequency of a = " << freq[0]; 
    cout << "\nFrequency of e = " << freq[1]; 
    cout << "\nFrequency of i = " << freq[2]; 
    cout << "\nFrequency of o = " << freq[3]; 
    cout << "\nFrequency of u = " << freq[4]; 
} 

