public static void BubbleSort(int[] arrayToSort) 
{
    // Set upperbound for unsorted part of array
    int lastUnsortedIndex = arrayToSort.Length - 1;

    for (int i = 0; i < arrayToSort.Length; i++)
    {
        // Reset boolean flag
        bool arrayUnsortedFlag = false;

        // Iterate over array
        for (int j = 0; j < lastUnsortedIndex; j++)
        {
            // Swap element if needed
            if (arrayToSort[j] > arrayToSort[j + 1])
            {
                SwapElements(arrayToSort, j, j + 1);
                arrayUnsortedFlag = true;
            }
        }

        if (!arrayUnsortedFlag)
        {
            break;
        }

        lastUnsortedIndex--;
    }
}

public static void SwapElements(int[] arrayToSwap, int firstIndex, int secondIndex)
{
    int tempElementHolder = arrayToSwap[firstIndex];
    arrayToSwap[firstIndex] = arrayToSwap[secondIndex];
    arrayToSwap[secondIndex] = tempElementHolder;
}

