 * Function to detect any cycle in a given linked list
 * 
 * @param  {object} list The linked list
 * @return {boolean} True or False if the linked list contains a cycle
 */
const detectCycle = (list) => {
    let slowPointer = list.head;
    let fastPointer = list.head;

    while(fastPointer && fastPointer.next) {
        slowPointer = slowPointer.next;
        fastPointer = fastPointer.next.next;

        if(slowPointer === fastPointer) {
            return true;
        }
    }

    return false;
}

