function getLongestSubstring(str, k) {
 let max = '';
 for (let i=0; i<str.length; i++) {
 let currentSubstring = str[i]; 
 let seen = new Set(str[i]);
 let j = i+1;
 while (seen.size <= k && j < str.length) {
 currentSubstring += str[j];
 seen.add(str[j]);
 j++;
 }
 if (seen.size <= k && currentSubstring.length > max.length) {
 max = currentSubstring;
 }
 }
 return max;
}

