def longestCommonSubsequence(string1, string2): 
    # create a matrix to store the lengths of longest common subsequences
    lcs = [[0 for x in range(len(string2) + 1)] for x in range(len(string1) + 1)] 

    # Loop through the strings 
    for i in range(len(string1) + 1): 
        for j in range(len(string2) + 1): 

            # If either string is empty
            if i == 0 or j == 0: 
                lcs[i][j] = 0

            # If the characters match 
            elif string1[i-1] == string2[j-1]: 
                lcs[i][j] = lcs[i-1][j-1] + 1

            # If the characters do not match 
            else: 
                lcs[i][j] = max(lcs[i-1][j], lcs[i][j-1]) 

    return lcs[len(string1)][len(string2)]

