public class ISBNChecker {

 public static boolean checkISBN(String code) {

 // ISBN-10 codes should have 10 digits
 if (code.length() != 10) {
 return false;
 }

 // Calculate check digit
 int sum = 0;
 for (int i = 0; i < 9; i++) {
 sum += (i + 1) * Character.getNumericValue(code.charAt(i));
 }
 int checkDigit = 11 - (sum % 11);

 // ISBN-10 codes have a special char for 'X' check digit
 if (checkDigit == 10) {
 checkDigit = 'X';
 }

 // Compare check digit with the last digit of the ISBN-10 code
 return (checkDigit == code.charAt(9));
 }

 public static void main(String[] args) {
 String test1 = "0-7475-3269-9";
 String test2 = "0-7475-3269-X";

 System.out.println(checkISBN(test1)); // true 
 System.out.println(checkISBN(test2)); // true
 }
}

