// The function assumes that arr[]  
// is sorted. It returns the length 
// of the longest increasing subsequence 
public static int _lis(int arr[], int n) 
{ 
    // Add boundary case, when array  
    // n is zero or 1 
    if (n == 0 || n == 1) 
        return n; 

    // Construct an array to store  
    // the numbers. Initialize all  
    // values as 1. 
    int[] lis = new int[n]; 
    int i, j, max = 0; 

    // Compute LIS values in top  
    // down manner 
    for ( i = 0; i < n; i++ ) 
        lis[i] = 1; 

    // Evaluate the LIS values  
    // from left to right 
    for ( i = 1; i < n; i++ ) 
        for ( j = 0; j < i; j++ ) 
            if ( arr[i] > arr[j] && 
                 lis[i] < lis[j] + 1) 
                lis[i] = lis[j] + 1; 

    // Pick the maximum of all LIS values 
    for ( i = 0; i < n; i++ ) 
        if ( max < lis[i] ) 
            max = lis[i]; 

    return max; 
}

