{
 int n = arr.Length;
 if (k > n)
 {
 k %= n;
 }

 Reverse(arr, 0, k-1);
 Reverse(arr, k, n-1);
 Reverse(arr, 0, n-1);
 return arr;
}

public static void Reverse(int[] arr, int start, int end)
{
 int temp;
 while (start < end)
 {
 temp = arr[start];
 arr[start] = arr[end];
 arr[end] = temp;
 start++;
 end--;
 }
}

