def a_star_search(startState, goalState): 
	openSet = {startState}:  # Set of node to consider 
	closedSet = set()        # set of already considered nodes
	gScore = {startState : 0} # distance from start to node
	fScore = {startState : heuristic(startState, goalState)} # estimated distance from start to goal

	while openSet != set(): 
		current = findMin(openSet, fScore)	# node with lowest fScore from openSet  
		if current == goalState:
			return reconstructPath(current) 

		openSet.remove(current)
		closedSet.add(current)

		for neighbor in neighbors(current): 
			if neighbor in closedSet: 
				continue

			newGscore = gScore[current] + distance(current,neighbor)
			if neighbor not in openSet: 
				openSet.add(neighbor)
			elif newGscore >= gScore[neighbor]: 
				continue # This is not better path

			# This path is the best path till now
			gScore[neighbor] = newGscore
			fScore[neighbor] = gScore[neighbor] + heuristic(neighbor, goalState)

	# No path possible 
	return failure

