import requests
import re

def crawl(url):
    visited_urls = set()

    response = requests.get(url)
    if response.status_code == 200:
        urls = get_urls(response.text)

        for u in urls:
            absolute_url = make_absolute_url(u, url)
            if absolute_url not in visited_urls:
                visited_urls.add(absolute_url)
                crawl(absolute_url)

    return visited_urls

def get_urls(html):
    return re.findall('(?:href=")(.*?)"', html)

def make_absolute_url(url, base):
    if url.startswith('http'):
        return url
    else:
        return base + url

if __name__ == '__main__':
    base_url = 'https://www.example.com/'
    print(crawl(base_url))

