def backtrack(result, curstring, open, close, max):
    if len(curstring) == max * 2:
        result.append(curstring)
        return
    if open < max:
        backtrack(result, curstring + "(", open + 1, close, max)
    if close < open:
        backtrack(result, curstring + ")", open, close + 1, max)

