import java.util.BitSet;

public class BloomFilter {

	// size of BitSet used
	public int size;
	public BitSet set;

	// constructor which initializes the BitSet
	public BloomFilter(int size) {
		this.size = size;
		set = new BitSet(size);
	}

	// function to calculate hashes
	public int[] hashCodes(String element) {
		int hash1 = element.hashCode();
		int hash2 = (int) Math.abs(element.hashCode() * 11);
		int[] hashes = new int[]{hash1,hash2};
		return hashes;
	}

	// function to add elements to the Bloom Filter
	public void add(String element) {
		int[] hashes = hashCodes(element);
		set.set(Math.abs(hashes[0] % size));
		set.set(Math.abs(hashes[1] % size));
	}

	// function to query/search elements in the Bloom Filter
	public boolean isPresent(String element) {
		boolean found = true;
		int[] hashes = hashCodes(element);
		if (!set.get(Math.abs(hashes[0] % size)))
			found = false;
		if (!set.get(Math.abs(hashes[1] % size)))
			found = false;
		return found;
	}

}

