class TemperatureData {
 // array of 10 locations
 locations = [];

 // array of 365 x 24 timestamps
 timestamps = [];

 // two-dimensional array of temperature values
 temperatures = [];

 // constructor
 constructor(locations) {
 this.locations = locations;
 this.timestamps = this.generateTimestamps();
 this.temperatures = new Array(locations.length).fill([]);
 }

 // generate timestamps
 generateTimestamps() {
 let timestamps = [];

 for (let i = 0; i < 365; i++) {
 for (let j = 0; j < 24; j++) {
 timestamps.push(new Date(2019, 1, i, j));
 }
 }

 return timestamps;
 }

 // add temperature readings
 addTemperature(location, timestamp, temp) {
 let locationIndex = this.locations.indexOf(location);

 let timestampIndex = this.timestamps.findIndex(date => 
 date.getTime() === timestamp.getTime());

 this.temperatures[locationIndex][timestampIndex] = temp;
 }

}

