public class PalindromeDetector { 
    public static boolean isPalindrome(String str) { 
        int n = str.length(); 

        // start iterating from the leftmost character
        for (int i=0; i < n/2; i++ ) 
            // comparing the leftmost and rightmost character 
            if (str.charAt(i) != str.charAt(n-i-1)) 
                return false; 

        // if the loop ends that means the whole string is a palindrome
        return true; 
    } 

    // main method
    public static void main(String args[]) {
        String str = "malayalam";

        if (isPalindrome(str)) 
            System.out.println("The given string is a palindrome.");
        else
            System.out.println("The given string is not a palindrome.");
    } 
}

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class Stack:

    def __init__(self):
        self.top = None

    def push(self, data):
        if not self.top:
            self.top = Node(data)
        else:
            node = Node(data)
            node.next= self.top
            self.top = node

    def pop(self):
        if self.top == None:
            return None
        data = self.top.data
        self.top = self.top.next
        return data

