int getMaxOccuringChar(char* str) 
{ 
    // Create array to keep the count of individual characters and initialize the array as 0 
    int count[256] = {0}; 

    // Construct character count array from the input string. 
    int len = strlen(str); 
    for (int i=0; i<len; i++) 
        count[str[i]]++; 

    // Return the maximum occuring character 
    int max = 0, result;   
    for (int i = 0; i < 256; i++) { 
        if (max < count[i]) { 
            max = count[i]; 
            result = i; 
        } 
    } 

    return result; 
} 

