void insertAtBeginning(int arr[], int n, int x) 
{ 
    // shift all the elements from 
    // position 0 till n-1 to 
    // one position ahead 
    for (int i = n; i > 0; --i) 
    arr[i] = arr[i - 1]; 

    // put x at position 0 
    arr[0] = x; 
} 

