class Bank {
 constructor () {
 this.accounts = [];
 }

 addAccount(account) {
 this.accounts.push(account);
 }

 getAccountByNumber(number) {
 for (let i = 0; i < this.accounts.length; i++) {
 if (this.accounts[i].accountNumber === number) {
 return this.accounts[i];
 }
 }
 }

 transfer(fromAccountNumber, toAccountNumber, amount) {
 const fromAccount = this.getAccountByNumber(fromAccountNumber);
 const toAccount = this.getAccountByNumber(toAccountNumber);

 if (fromAccount != null && toAccount != null) {
 fromAccount.balance -= amount;
 toAccount.balance += amount;

 return new Transaction (null, fromAccountNumber, toAccountNumber, amount, 'transfer', new Date());
 }
}
}

