class Node {
  public:
    int data;
    Node* next;
    Node* prev;

    Node(int data) {
      this->data = data;
      next = NULL;
      prev = NULL;
    }
};

class DoublyLinkedList {
  Node* head;
  Node* tail;

  public:
    DoublyLinkedList() {
      head = NULL;
      tail = NULL;
    }

    void insert_node(int data) { 
      Node* new_node = new Node(data);
      if (!head) {
        head = new_node;
      }
      else {
        new_node->next = head;
        head->prev = new_node;
        head = new_node;
      }
    }

    void print_list() {
      Node* temp = head;
      while (temp != NULL) {
        std::cout << temp->data << " ";
        temp = temp->next;
      }
    }
};

