def num_of_factors(x, y):
    """This function takes two integers and returns the number of factors of each number."""
    num_x = 0
    num_y = 0
    for i in range(1, x+1):
        if x % i == 0:
            num_x += 1
    for j in range(1, y+1):
        if y % j == 0:
            num_y += 1
    return num_x, num_y

