public class QuickSort {

    // function to sort array using quicksort
    public static void sort(int array[]) {
        sort(array, 0, array.length - 1);
    }

    private static void sort(int array[], int start, int end) {
        // check for empty or null array
        if (array == null || array.length == 0) {
            return;
        }

        // check if start index is larger then end index
        if (start >= end) {
            return;
        }

        // store the pivot index value
        int pivot = array[start + (end - start) / 2];

        // calculate index of the pivot value
        int index = partition(array, start, end, pivot);

        // sort first and second halves 
        sort(array, start, index - 1);
        sort(array, index, end);
    }

    private static int partition(int array[], int start, int end, int pivot) {
        while (start <= end) {
            // start index smaller then pivot, increase the index 
            while (array[start] < pivot)  {
                start++;
            }

            // end index greater then pivot, decrease the index
            while (array[end] > pivot) {
                end--;
            }

            if (start <= end) {
                swap(array, start, end);

                start++;
                end--;
            }
        }
        return start;
    }

    // swap array elements
    private static void swap(int array[], int a, int b) {
        int temp = array[a];
        array[a] = array[b];
        array[b] = temp;
    }
}

