def find_mode(arr):
    # Create a dictionary to keep track of frequency of each number
    d = {}
    for num in arr:
        if num in d:
            d[num] += 1
        else:
            d[num] = 1

    # Find the number with the highest frequency
    max_freq = 0
    mode = 0
    for key, value in d.items():
