public class SudokuSolver {
 private int[][] board;

 public SudokuSolver(int[][] board) {
 this.board = board;
 }

 public boolean solve() {
 for (int row = 0; row < 9; row++) {
 for (int col = 0; col < 9; col++) {

 if (board[row][col] != 0) {
 continue;
 }

 // try the numbers 1-9
 for (int k = 1; k < 10; k++) {
 if (isValid(row, col, k)) {
 board[row][col] = k;

 if (solve()) {
 return true;
 }
 else {
 board[row][col] = 0;
 }
 }
 }

 return false;
 }
 }

 return true;
 }

 // check if a number is valid at given coordinates
 private boolean isValid(int row, int col, int k) {
 // check row
 for (int c = 0; c < 9; c++) {
 if (board[row][c] == k) {
 return false;
 }
 }

 // check col
 for (int r = 0; r < 9; r++) {
 if (board[r][col] == k) {
 return false;
 }
 }

 // check 3x3 box
 int boxRow = row - (row % 3);
 int boxCol = col - (col % 3);

 for (int r = 0; r < 3; r++) {
 for (int c = 0; c < 3; c++) {
 if (board[boxRow + r ][boxCol + c] == k) {
 return false;
 }
 }
 }

 return true;
 }
}

