class MinHeap:
    def __init__(self):
        self.min_heap = []

    def insert(self, elem): 
        self.min_heap.append(elem) 
        self.heapify_up() 

    def heapify_up(self): 
        pos = len(self.min_heap) - 1
        while pos > 0: 
            parent = (pos - 1)//2
            if self.min_heap[parent][1] > self.min_heap[pos][1]: 
                tmp = self.min_heap[parent] 
                self.min_heap[parent] = self.min_heap[pos] 
                self.min_heap[pos] = tmp 
            pos = parent 

    def get_min(self): 
        if self.min_heap == []: 
            return None
        return self.min_heap[0]

