void rearrangeEvenOdd(int arr[], int n) 
{ 
    int even[n], odd[n];
    int k = 0, l = 0;
    for (int i = 0; i < n; i++) 
    { 
        if (arr[i] % 2 == 0) 
            even[k++] = arr[i];
        else
            odd[l++] = arr[i];
    }
    for (int i = 0; i < k; i++) 
        arr[i] = even[i];
    for (int i = 0; i < l; i++)
        arr[k + i] = odd[i];
}

