fn bubble_sort(arr: &mut [i32]) {
    let mut n = arr.len();

    loop {
        let mut newn = 0;
        for i in 1..n {
            if arr[i - 1] > arr[i] {
                arr.swap(i - 1, i);
                newn = i;
            }
        }
        n = newn;
        if n == 0 {
            break;
        }
    }
}

