using System;

public class Example
{
  public static void Main()
  {
    int N = 10;
    // generate the sequence
    Random rand = new Random();
    int[] sequence = new int[N];
    for(int i = 0; i < N; i++) 
    {
        sequence[i] = rand.Next(1, 100);
    }
    // calculate the mean
    double mean = 0;
    for(int i = 0; i < N; i++)
    {
        mean += sequence[i];
    }
    mean = mean / N;
    // calculate the median
    Array.Sort(sequence);
    double median;
    if (N % 2 == 0)
    {
        // if N is even
        int mid1 = N/2;
        int mid2 = mid1 - 1;
        median = (sequence[mid1] + sequence[mid2])/2;
    }
    else 
    {
        // if N is odd
        median = sequence[N/2];
    }
    // calculate the standard deviation
    double variance = 0;
    for (int i = 0; i < N; i++)
    {
        variance += Math.Pow(sequence[i] - mean, 2);
    }
    double std_dev = Math.Sqrt(variance / (N - 1));
    // output the result
    Console.WriteLine("Mean: {0}, Median: {1}, Standard Deviation: {2}", mean, median, std_dev);
  }
}

