def isPermutation(str1, str2): 
    # If both strings are of different length then they cannot be permutations.
    if len(str1) != len(str2) : 
        return False

    # Create a list to store character count 
    count_list = [0] * 256

    # Traverse the first string and increment the count of character in the count list.
    for char in str1:
        count_list[ord(char)] += 1

    # Traverse the second string and decrement the count of character in the count list.
    for char in str2:
        count_list[ord(char)] -= 1

    # If any of the values in the count list is greater than 0 then the two strings are not permutations of each other.
    for count in count_list:
        if count > 0:
            return False

    # The two strings are permutations of each other.
    return True

