// Binary search in JavaScript 
function binary_Search(arr, item) {
    let first = 0;
    let last = arr.length - 1;
    let middle = Math.floor((first + last) / 2);

    while (arr[middle] !== item && first <= last) {
        if (item < arr[middle])
            last = middle - 1;
        else
            first = middle + 1;
        middle = Math.floor((first + last) / 2);
    }

    if (arr[middle] === item)
        return middle;
    else
        return -1;
}

