class EqualData {
  isEqual(dataSet1, dataSet2) {
    if (dataSet1.length !== dataSet2.length) return false;
    for (let i = 0; i<dataSet1.length; i++) {
        if (dataSet1[i] !== dataSet2[i]) return false;
    } 
    return true;
  }
  areEqual(dataSet1, dataSet2) {
    if (dataSet1.length !== dataSet2.length) return false;
    let obj1 = {};
    let obj2 = {};
    for (let i = 0; i<dataSet1.length; i++) {
        obj1[dataSet1[i]] = true;
        obj2[dataSet2[i]] = true;
    }
    for (let prop in obj1) {
        if(!obj2[prop]) return false;
    }
    return true;  
  };
}

