void quick_sort_recursive(std::vector<int> &input, int left, int right)
{
    int mid = (left + right) / 2;
    int pivot = input[mid];

    int i = left, j = right;

    while (i <= j) {
        while (input[i] < pivot)
            ++i;

        while (input[j] > pivot)
            --j;

        if (i <= j) {
            std::swap(input[i], input[j]);
            ++i;
            --j;
        }
    }

    if (left < j)
        quick_sort_recursive(input, left, j);

    if (i < right)
        quick_sort_recursive(input, i, right);
}

