function sort(nums) {
 // loop through the array
 for (let i = 0; i < nums.length; i++) {
 // loop through the array again
 for (let j = 0; j < nums.length; j++) {
 // if the current number is greater than 
 // the next number, swap them
 if (nums[j] > nums[j + 1]) {
 let temp = nums[j];
 nums[j] = nums[j + 1];
 nums[j + 1] = temp;
 }
 }
 }
 return nums;
}

