import java.time.LocalDate;
import java.util.HashMap;

public class ExpenseTracker {

 private HashMap<LocalDate, Double> monthlyExpenses;

 public ExpenseTracker(){
   monthlyExpenses = new HashMap<>();
 }

 public void addExpense(LocalDate date, double amount){
  monthlyExpenses.put(date, amount);
 }

 public double getTotalExpenseForMonth(LocalDate date){
  LocalDate month = date.withDayOfMonth(1);
  LocalDate nextMonth = month.plusMonths(1);
  double totalExpenses = 0;
  for (LocalDate expenseDate : monthlyExpenses.keySet()) {
   if (expenseDate.compareTo(month) >= 0 && expenseDate.compareTo(nextMonth) < 0) {
    totalExpenses += monthlyExpenses.get(expenseDate);
   }
  }

  return totalExpenses;
 }

 public double getTotalExpensesForTimePeriod(LocalDate startDate, LocalDate endDate){
  double totalExpenses = 0;
  for (LocalDate expenseDate : monthlyExpenses.keySet()) {
   if (expenseDate.compareTo(startDate) >= 0 && expenseDate.compareTo(endDate) <= 0) {
    totalExpenses += monthlyExpenses.get(expenseDate);
   }
  }

  return totalExpenses;
 }

}

function isPalindrome(str) {
    // lowercase the string and remove all non-alphanumeric characters
    let processedString = str.toLowerCase().replace(/[^a-z0-9]/g, '');

    // reverse the processed string
    let reversedString = processedString.split('').reverse().join('');

    // check if reversed string is equal to processed string
    return reversedString === processedString;
}

