def count_num(arr, num): 
    first = first_occurence(arr, num) 
    last = last_occurence(arr, num)
    if first != -1 and last != -1:
        return (last - first + 1) 
    else:
        return 0

def first_occurence(arr, num): 
    start = 0
    end = len(arr) - 1
    result = -1
    while start <= end: 
        mid = (start + end) // 2

        if arr[mid] == num: 
            result = mid 
            end = mid - 1
        elif arr[mid] > num: 
            end = mid - 1
        else: 
            start = mid + 1
    return result 

def last_occurence(arr, num): 
    start = 0
    end = len(arr) - 1
    result = -1
    while start <= end: 
        mid = (start + end) // 2

        if arr[mid] == num: 
            result = mid 
            start = mid + 1
        elif arr[mid] > num: 
            end = mid - 1
        else: 
            start = mid + 1
    return result

