Function to identify the longest consecutive sequence of numbers in a given array
"""

def longest_sequence(arr):
    longest_start = 0
    longest_len = 0
    current_start = 0
    current_len = 0

    for i in range(len(arr)):
        if arr[i] == arr[i-1]+1: 
            current_len += 1
        else: 
            current_start = i
            current_len = 1

        if current_len > longest_len: 
            longest_start = current_start
            longest_len = current_len

    return longest_start, longest_len

