bool matchPattern(std::string string, std::string pattern){
 int pIndex = 0;
 for(int sIndex = 0; sIndex < string.size(); sIndex++){
 if(pattern[pIndex] == '?' || pattern[pIndex] == string[sIndex]){
 pIndex++;
 } else if(pattern[pIndex] == '*'){
 while(string[sIndex] != pattern[pIndex+1] && sIndex < string.size()){
 sIndex++;
 }
 pIndex++;
 } else if(pattern[pIndex] == '+'){
 while(pattern[pIndex] == '+' && string[sIndex] == pattern[pIndex+1] && sIndex < string.size()){
 sIndex++;
 }
 pIndex++;
 }
 }

 return (pIndex == pattern.size()) ? true : false;
}

