def evaluate(expr):
    stack = []

    # iterate through the expression
    for char in expr:
        # push operand onto the stack
        if char.isdigit():
            stack.append(int(char))
        # if operator is encountered, pop 2 elements from
        # the stack and evaluate the operation
        else:
            x = stack.pop()
            y = stack.pop()

            # evaluate the operation
            if char == "+":
                z = x + y
            elif char == "-":
                z = y - x
            elif char == "*":
                z = x * y
            elif char == "/":
                z = y / x
            else:
                z = x ** y

            # evaluate the remaining expression
            stack.append(z)

    # return result
    return stack.pop()

