// Function to print the longest palindrome substring
public String longestPalindromeSubstring(String s) {

 // Start and end indexes of the longest palindrome
 int startIndex = 0;
 int endIndex = 0;

 // Length of the original string
 int n = s.length();

 // Table for dp
 boolean[][] dpTable = new boolean[n][n];

 // Iterate through the string
 for (int i = n-1; i >= 0; i--) {

 // Fill the table
 for (int j = i; j < n; j++) {

 // Check for two characters and store its result
 boolean isPali = s.charAt(i) == s.charAt(j) && (j - i < 3 || dpTable[i+1][j-1]);

 // Save the result
 dpTable[i][j] = isPali;

 // Update the longest palindrome
 if (isPali && j - i > endIndex - startIndex) {
 startIndex = i;
 endIndex = j;
 }
 }
 }

 return s.substring(startIndex, endIndex + 1);
}

