import java.util.ArrayList;

public class Sudoku {
    int[][] grid;

    // Constructor to initialize the sudoku grid
    public Sudoku(int[][] grid) {
        this.grid = grid;
    }

    // Function to solve the Sudoku
    public boolean solveSudoku() {
        int row = -1;
        int col = -1;
        boolean isEmpty = true;

        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (grid[i][j] == 0) {
                    row = i;
                    col = j;

                    // We still have some remaining missing values in Sudoku
                    isEmpty = false;
                    break;
                }
            }
            if (!isEmpty) {
                break;
            }
        }

        // no empty space left
        if (isEmpty) {
            return true;
        }

        // else for each-row backtrack
        for (int num = 1; num <= 9; num++) {
            if (isSafe(row, col, num)) {
                grid[row][col] = num;
                if (solveSudoku()) {
                    // print(grid, row, col, num);
                    return true;
                } else {
                    // replace it
                    grid[row][col] = 0;
                }
            }
        }
        return false;
    }

    // function to check if safe
    private boolean isSafe(int row, int col, int num) {
        // Check if 'num' is not already placed in current row,
        // current column and current 3x3 box
        return !UsedInRow(row, num) &&
                !UsedInCol(col, num) &&
                !UsedInBox(row - row % 3, col - col % 3, num);
    }

    // check in row
    private boolean UsedInRow(int row, int num) {
        for (int col = 0; col < 9; col++)
            if (grid[row][col] == num)
                return true;
        return false;
    }

    // check in col
    private boolean UsedInCol(int col, int num) {
        for (int row = 0; row < 9; row++)
            if (grid[row][col] == num)
                return true;
        return false;
    }

    // Used in 3x3 box
    private boolean UsedInBox(int boxStartRow, int boxStartCol, int num) {
        for (int row = 0; row < 3; row++)
            for (int col = 0; col < 3; col++)
                if (grid[row + boxStartRow]
                        [col + boxStartCol] == num)
                    return true;
        return false;
    }

    // print grid
    public void printGrid() {
        for (int row = 0; row < 9; row++) {
            for (int col = 0; col < 9; col++)
                System.out.print(grid[row][col] + " ");
            System.out.println();
        }
    }
}

