def find_longest_valid_parens(string):
    stack = []
    longest_match = 0
    current_match = 0
    for char in string:
        if char == "(":
            stack.append(char)
        elif char == ")":
            if stack:
                stack.pop()
                current_match += 2
                longest_match = max(longest_match, current_match)
            else:
                current_match = 0
    return longest_match

