class Chatbot:
    # constructor
    def __init__(self):
        self.responses = {
            # greetings
            "hi": ["Hello!", "Hi!", "Hey!", "Hi there!"],
            "hello": ["Howdy!", "Hey!", "Hey there!"],
            # farewells
            "bye": ["Goodbye!", "Bye!", "See you later!"],
