def expand_from_center(string, left, right):
    while left >= 0 and right < len(string) and string[left] == string[right]:
        left -= 1
        right += 1
    return string[left + 1:right]

public static int nthPrime(int n) { 

    //Initialize 2 counter, one of elements and one of prime numbers 
    int primeCount = 0,i = 2;  

    //run the loop until the primeCount is n 
    while (primeCount != n) 
    { 
        //check each integer from 2 till i 
        //are any of them factors of i 
        for (int j = 2; j < i; j++)                                                                                        
          if (i % j == 0) break; 

        //If none of them are factors, increment the primeCount 
        //and the value of primeNumber 
        if (i == j)
        { 
            primeCount++; 
        } 

        i++; 
    } 

    // return the nth prime number 
    return (i - 1); 
}

