// Function to merge two sorted arrays 
int * mergeArrays(int arr1[], int arr2[], int n, int m) {
 // Merge both arrays
 int * mergedArray = new int[n+m];
 int i = 0, j = 0, k = 0;
 while (i < n && j < m) {
 if (arr1[i] < arr2[j])
 mergedArray[k++] = arr1[i++];
 else
 mergedArray[k++] = arr2[j++];
 }

// Copy remaining elements
 while (i < n)
 mergedArray[k++] = arr1[i++];
 while (j < m)
 mergedArray[k++] = arr2[j++];

return mergedArray;
}

