def minCost(matrix):
    minCosts = [[0 for _ in range(len(matrix[0]))] for _ in range(len(matrix))]
    minCosts[0][0] = matrix[0][0] 
    for i in range(1, len(matrix[0])):
        minCosts[0][i] = matrix[0][i] + minCosts[0][i - 1] 
    for i in range(1, len(matrix)): 
        minCosts[i][0] = matrix[i][0] + minCosts[i - 1][0] 
    for i in range(1, len(matrix)): 
        for j in range(1, len(matrix[0])): 
            minCosts[i][j] = min(minCosts[i - 1][j], minCosts[i][j - 1]) + matrix[i][j]
    return minCosts[len(matrix) - 1][len(matrix[0]) - 1]

