def knapsack(capacity, weights, values):
    n = len(values)
    knapsack_matrix = [[]]*(n+1)
    for i in range(n+1):
        knapsack_matrix[i] = [0]*(capacity+1)
    for i in range(1,n+1):
        for w in range(1,capacity+1):
            if weights[i-1] > w:
                knapsack_matrix[i][w] = knapsack_matrix[i-1][w]
            else:
                knapsack_matrix[i][w] = max(knapsack_matrix[i-1][w],values[i-1] + knapsack_matrix[i-1][w-weights[i-1]])  
    return knapsack_matrix[-1][-1]

