public static int[] merge(int[] arr1, int[] arr2) { 
    int n1 = arr1.length; 
    int n2 = arr2.length; 
    int n3 = n1 + n2; 
    int[] arr3 = new int[n3]; 

    int i = 0, j = 0, k = 0; 

    // loop through arrays, until one is empty 
    while (i < n1 && j < n2) { 

        if (arr1[i] < arr2[j]) 
            arr3[k++] = arr1[i++]; 

        else
            arr3[k++] = arr2[j++]; 
    } 

    // if arr2 is exhausted 
