    """Print the permutations of a given array."""
    if len(arr) == 0: 
        return [] 
    elif len(arr) == 1: 
        return [arr] 
    else:
        l = [] 
        for i in range(len(arr)):
            m = arr[i]

            # Extract l and r
            remLst = arr[:i] + arr[i+1:]

            # Generating all permutations where m is first element 
            for p in get_permutations(remLst): 
                l.append([m] + p) 
        return l

