def exponential_search(arr, num):
	if arr[0] == num:
		return 0

	i = 1
	while i < len(arr) and arr[i] <= num:
		i = i * 2

	return binary_search(arr, i//2, min(i, len(arr)), num)

def binary_search(arr, l, r, x):
	if r >= l:
		mid = l + (r - l) // 2
		if arr[mid] == x:
			return mid

		elif arr[mid] > x:
			return binary_search(arr, l, mid-1, x)

		else:
			return binary_search(arr, mid+1, r, x)

	else:
		return -1

