"""
Design an algorithm to find the shortest path from a starting node to an ending node.
"""

def shortest_path(graph, start_node, end_node): 
    # keep track of the total cost of paths from the start node to each node 
    cost_from_start = {start_node: 0} 
    # keep track of the path taken to reach each node 
    path_taken = {} 

    # initialiase the nodes to explore next 
    nodes_to_explore = set([start_node]) 

    while nodes_to_explore: 
        # select the node with the lowest cost (remove from set) 
        current_node = min(nodes_to_explore, key=lambda node: cost_from_start[node]) 
        nodes_to_explore.remove(current_node) 

        # loop through the neighbours of the current node 
        for neighbour, cost in graph[current_node]: 
            # calculate the cost to the neighbour and update
            neighbour_cost = cost_from_start[current_node] + cost 
            if neighbour not in cost_from_start or neighbour_cost < cost_from_start[neighbour]: 
                # record the lowest cost
                cost_from_start[neighbour] = neighbour_cost 
                # update the path taken
                path_taken[neighbour] = current_node 

                # add the neighbour to the set of nodes to explore next
                nodes_to_explore.add(neighbour) 

        # if the end node has been found, trace the path back
        if end_node in cost_from_start: 
            return trace_shortest_path(start_node, end_node, path_taken) 

    return None # no path found

def trace_shortest_path(start_node, end_node, path_taken): 
    path = [] 
    current_node = end_node 

    while current_node != start_node: 
        path.append(current_node) 
        current_node = path_taken[current_node] 

    return list(reversed(path))

