def caesar_cipher(text, shift):
    cipher_text = ""
    for char in text: 
        if (char.isupper()):
            cipher_text += chr((ord(char) + shift - 65) % 26 + 65) 
        else:
            cipher_text += chr((ord(char) + shift - 97) % 26 + 97)

    return cipher_text

