int countWords(string str)
{
    int word_count = 0; // Initialize a variable to count the words

    // Traverse the given string character by character
    for (int i = 0; str[i] != '\0'; i++)
    {
        // If the current character is not an alphabet or if it is the last character
        if ((str[i] == ' ' && str[i - 1] != ' ') || (str[i + 1] == '\0' && str[i] != ' '))
            word_count++;
    }

    // Return the total count
    return word_count;
}

