bool isMirror(Node* node1, Node* node2)
{
    if (node1 == NULL && node2 == NULL)
        return true;

    if (node1 && node2 && node1->key == node2->key)
        return  isMirror(node1->left, node2->right) && isMirror(node1->right, node2->left);

    return false;
}

