// Algorithm to find the maximum subarray sum
// We accept an array and an optional parameter to denote the start and end indices of the subarray
// Returns the maximum subarray sum

def findMaxSubArraySum(arr, start_index=0, end_index=-1):
    # If no end index provided, set it to the length of the array
    if end_index == -1:
        end_index = len(arr) - 1

    # If no elements in the array, return 0
    if end_index < start_index:
        return 0

    # Calculate the mid index and recursively find the maximum subarray sum
    mid_index = (start_index + end_index) // 2
    low_index_sum = findMaxSubArraySum(arr, start_index, mid_index)
    high_index_sum = findMaxSubArraySum(arr, mid_index + 1, end_index)

    cross_sum = findMaxCrossIndexSum(arr, start_index, mid_index, end_index)
    return max(low_index_sum, high_index_sum, cross_sum)


# Function to calculate maximum subarray sum between two indices
def findMaxCrossIndexSum(arr, start_index, mid_index, end_index):
    # Calculate left sum
    left_max_sum = -float('inf')
    sum = 0
    for i in range(mid_index, start_index - 1, -1):
        sum += arr[i]
        if sum > left_max_sum:
            left_max_sum = sum

    # Calculate the right sum
    right_max_sum = -float('inf')
    sum = 0
    for i in range(mid_index + 1, end_index + 1):
        sum += arr[i]
        if sum > right_max_sum:
            right_max_sum = sum

    # Return the combined sum
    return left_max_sum + right_max_sum

