def sort_ascending(arr):
    """
    Function to sort an array in ascending order
    """
    # Perform bubble sort
    for i in range(0, len(arr)-1):
        for j in range(0, len(arr)-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]

    return arr

