// Function to find the length of maximum
// length subsequence with no repeating
// characters in a given string
int maxLenNoRepeatSubStr(string s)
{
    // create an empty set to store last
    // indexes of already visited characters
    unordered_set<int> set;

    // maintain a sliding window [low..high]
    int n = s.length();
    int low = 0, high = 0;

    // store length of maximum length
    // substring with no repeating characters
    int maxlen = 0;

    while (high < n)
    {
        // if character is not present in the
        // set, increase the sliding window
        if (set.find(s[high]) == set.end())
        {
            set.insert(s[high]);
            high++;

            // update maximum length substring
            maxlen = max(maxlen, high - low);
        }

        // if the current character is already
        // present in the set, decrease the sliding
        // window from low side
        else
        {
            set.erase(s[low]);
            low++;
        }
    }

    return maxlen;
}

