def minCoins(amount, coins):

    dp = [float('inf') for _ in range(amount + 1)] 
    dp[0] = 0

    for i in range(1, amount + 1): 
        for j in range(len(coins)): 
            if coins[j] <= i: 
                sub_res = dp[i - coins[j]] 
                if sub_res != float('inf') and sub_res + 1 < dp[i]: 
                    dp[i] = sub_res + 1

    return dp[amount]

