class Vector3D: 
    def __init__(self, x, y, z): 
        self.x = x 
        self.y = y 
        self.z = z 

    def magnitude(self): 
        return (self.x**2 + self.y**2 + self.z**2)**0.5 

    def normalize(self): 
        magnitude = self.magnitude() 
        self.x /= magnitude 
        self.y /= magnitude 
