function copyValuesToMasterSheet() {
  // Get the master sheet
  const masterSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("MasterSheet");

  // Get the number of rows in the master sheet
  const numRows = masterSheet.getMaxRows();

  // Iterate through the sheets
  const sheets = ["Sheet1", "Sheet2", "Sheet3"];
  for (var sheet of sheets) {
    var sourceSheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(sheet);
    var values = sourceSheet.getDataRange().getValues();

    // Copy the values to the master sheet
    masterSheet.getRange(numRows + 1, 1, values.length, values[0].length).setValues(values);
  }
}

