public class DeleteElement 
{ 
	public static int[] delete(int[] arr, 
                            int pos) 
	{ 
		if (arr == null) 
			return null; 

		// If the position 
		// to be deleted 
		// is more than the 
		// count of elements 
		if (pos >= arr.length) 
			return arr; 

		// Create a temp array 
		// to store the elements 
		int[] temp = new int[arr.length - 1]; 

		// Copy the elements from 
		// starting to the given position 
		for (int i = 0; i < pos; i++) 
			temp[i] = arr[i]; 

		// Copy the elements after 
		// the given position 
		for (int i = pos; i < temp.length; i++) 
			temp[i] = arr[i + 1]; 

		return temp; 
	} 

	public static void main(String[] args) 
	{ 
		int[] arr = {1, 2, 3, 4, 5}; 
		int position = 2; 

		arr = delete(arr, position); 

		System.out.println("The new array is:"); 
		for (int i = 0; i < arr.length; i++) 
			System.out.print(arr[i] + " "); 
	} 
}

public class LevenshteinDistance {

 public int computeLevenshteinDistance(String s1, String s2) {

 int[][] distance = new int[s1.length() + 1][s2.length() + 1];

 for (int i = 0; i <= s1.length(); i++)
 distance[i][0] = i;
 for (int j = 0; j <= s2.length(); j++)
 distance[0][j] = j;

 for (int i = 1; i <= s1.length(); i++)
 for (int j = 1; j <= s2.length(); j++)
 distance[i][j] = minimum(
 distance[i - 1][j] + 1,
 distance[i][j - 1] + 1,
 distance[i - 1][j - 1] +
  ((s1.charAt(i - 1) == s2.charAt(j - 1)) ? 0 : 1));

 return distance[s1.length()][s2.length()];
 }

 public static int minimum(int a, int b, int c) {
 return Math.min(Math.min(a, b), c);
 }

}

