public class LocationTracker {
 private Context mContext;
 private LocationManager mLocationManager;
 private double mCurrentLatitude;
 private double mCurrentLongitude;

 public LocationTracker(Context context) {
 mContext = context;
 mLocationManager = (LocationManager) mContext.getSystemService(Context.LOCATION_SERVICE);
 }

public void startTracking() {
 if (ActivityCompat.checkSelfPermission(mContext, Manifest.permission.ACCESS_COARSE_LOCATION) != PackageManager.PERMISSION_GRANTED) {
   showPermissionDialog();
   return;
 }

 mLocationManager.requestLocationUpdates(LocationManager.GPS_PROVIDER, 1000, 0, new LocationListener() {
 @Override
  public void onLocationChanged(Location location) {
   mCurrentLatitude = location.getLatitude();
   mCurrentLongitude = location.getLongitude();
   Log.e("location", mCurrentLatitude + "  " + mCurrentLongitude);
   saveToDatabase(mCurrentLatitude, mCurrentLongitude);
  }

  @Override
  public void onStatusChanged(String provider, int status, Bundle extras) {

  }

  @Override
  public void onProviderEnabled(String provider) {

  }

  @Override
  public void onProviderDisabled(String provider) {

  }
 });
}

private void saveToDatabase(double latitude, double longitude) {
 RequestQueue queue = Volley.newRequestQueue(mContext);
 String url = "http://yourserver.net/saveLocation" +
              "?latitude=" + latitude +
              "&longitude=" + longitude;

 StringRequest stringRequest = new StringRequest(Request.Method.POST, url,
  new Response.Listener<String>() {
  @Override
   public void onResponse(String response) {
    Log.e("location", response);
   }
  }, new Response.ErrorListener() {
  @Override
   public void onErrorResponse(VolleyError error) {
    Log.e("location", error.getMessage());
   }
 });
 queue.add(stringRequest);
}

