public static boolean isPalindrome(int [] arr) {
    int startIndex = 0;
    int lastIndex = arr.length - 1;

    while (lastIndex > startIndex) {
        if (arr[startIndex] != arr[lastIndex]) {
            return false;
        }
        ++startIndex;
        --lastIndex;
    }
    return true;
}

