public class PalindromeCheck {
    public static boolean isPalindrome(String str) {
        int n = str.length(); 

        // Reverse the string
        String rev = "";
        for(int i=n-1; i>=0; i--) 
        	rev = rev + str.charAt(i); 

        // If the string is equal to its reverse, it's a palindrome
        return str.equals(rev);
    }
}

