def encryptString(string, n):
    encryptedString = ""

    for i in range(len(string)):
        char = string[i]

        if (char.isupper()):
            encryptedString += chr((ord(char) + n - 65) % 26 + 65)
        else:
            encryptedString+= chr((ord(char) + n - 97) % 26 + 97)

    return encryptedString

