def eval_expr(expr):
    stack = []
    current_num = 0
    for c in expr:
        if c.isdigit():
            current_num = current_num*10 + int(c)
        else:
            if c == '*' or c == '/':
                stack.append(current_num)
                stack.append(c)
            elif c == '+' or c == '-':
                if not stack or stack[-1] not in '*/':
                    stack.append(current_num)
                else:
                    while stack and stack[-1] in '*/':
                        symbol = stack.pop()
                        num1 = stack.pop()
                        num2 = current_num
                        if symbol == '*':
                            current_num = num1*num2
                        elif symbol == '/':
                            current_num = num1/num2
                    stack.append(current_num)
                stack.append(c)
            current_num = 0
    stack.append(current_num)

    ans = 0
    for c in stack:
        if type(c) == int:
            ans += c
            continue
        if c == '+':
            ans += stack.pop()
        elif c == '-':
            ans -= stack.pop()
    return ans

