def calculateMedian(array):
  sorted_array = sorted(array)
  length = len(array)
  middle_index = int(length / 2)
  if length % 2 == 0:
    return (sorted_array[middle_index] + sorted_array[middle_index - 1]) / 2
  else:
    return sorted_array[middle_index]

