int findMode(vector<int> &arr)
{
    unordered_map<int, int> freqMap;
    int maxFreq = 0, mode = 0;
    for (int i : arr) {
        freqMap[i]++;
        if (freqMap[i] > maxFreq) {
            maxFreq = freqMap[i];
            mode = i;
        }
    }

    return mode;
}

