public class SumReducer {
   public static void main(String[] args) {
      List<Integer> array = Arrays.asList(2, 3, 4, 5, 6);

      // call the map
      List<Integer> mappedArray = map(array);

      // call the reduce
      Integer result = reduce(mappedArray);

      System.out.println(result);
   }

   // function to map the array
   public static List<Integer> map(List<Integer> array) {
      List<Integer> mappedArray = new ArrayList<>();
      for (Integer number : array) {
         mappedArray.add(number*number);
      }
      return mappedArray;
   }

   // function to reduce the array
   public static Integer reduce(List<Integer> mappedArray) {
      int result = 0;
      for (Integer number : mappedArray) {
         result += number;
      }
      return result;
   }
}

