fn contains(target: &str, substring: &str) -> bool {
    let mut position = 0;
        while position < target.len() {
            let starting_position = position;
            let mut substring_position = 0;
            while substring_position < substring.len() && starting_position < target.len()
                && substring.as_bytes()[substring_position] == target.as_bytes()[starting_position] {
                    starting_position += 1;
                    substring_position += 1;
            }
            if substring_position == substring.len() {
                return true;
            }
            position += 1;
        }
    return false;
}

