bool isAnagram(char* s1, char* s2) 
{ 
    // Get the lengths of both strings 
    int n1 = strlen(s1); 
    int n2 = strlen(s2); 

    // Check if lengths are not equal 
    if (n1 != n2) 
        return false; 

    // Sort both strings 
    sort(s1, s1 + n1); 
    sort(s2, s2 + n2); 

    // Compare sorted strings 
