/* function to calculate determinant of matrix */
int determinant(int a[3][3], int n)
{

    int det = 0;

    for (int i=0; i<n; i++)
    {
        int sub_det = 1;
        for (int j=0; j<n; j++)
        {
            sub_det *= a[ ((i+j)%n ) ][ j ];
        }
        det = det + ((i%2==1)? -sub_det : sub_det );
    }
    return det;
}

