import java.util.LinkedList;

public class RoundRobin {

 public static void main(String[] args) {
 // Linked list for all processes
 LinkedList<Integer> processQueue = new LinkedList<>();

 // Enter process burst times into the processQueue
 // Example: processQueue.add(4);

 // Quantum time. This is the amount of time for each process to occupy the CPU
 int quantum = 2;

 // Number of processes
 int n = processQueue.size();

 // Transfer processes in the queue to the Array
 int[] processes = new int[n];
 for (int i = 0; i < n; i++) {
 processes[i] = processQueue.remove();
 }

 int[] bt = new int[n];
 int[] wt = new int[n];
 int[] tat = new int[n];

 // Initializing of bt (Burst time)
 for (int i = 0; i < n; i++) {
 bt[i] = processes[i];
 }
 // Creating temporary array to store remaining burst time
 int[] temp = new int[n];
 for (int i = 0; i < n; i++)
 temp[i] = bt[i];

 //Initializing values of waiting time and turn around time
 int count = 0;
 while (true) {
 boolean done = true;
 // Executing each process one by one repeatedly
 for (int i = 0; i < n; i++) {
 // If control reaches here, it means a process is still remaining
 if (temp[i] > 0) {
 done = false; // There is a process still remaining
 if (temp[i] > quantum) {
 // Increase the value of t (time)
 count = count + quantum;
 // Decreasing the burst time of process by quantum
 temp[i] = temp[i] - quantum;
 } else {
 // Increase the value of t (time)
 count = count + temp[i];
 // Waiting time is current time minus burst time
 wt[i] = count - bt[i];
 // As burst time of process is 0, process is terminated
 temp[i] = 0;
 }
 }
 }
 // If All process are complete
 if (done == true)
 break;
 }
 // Calculate Turn around time
 for (int i = 0; i < n; i++)
 tat[i] = bt[i] + wt[i];
 }
}

def memoize(f, k):
    memo = dict()

    def helper(x):
        if x not in memo:            
            memo[x] = f(x)
        return memo[x]

    return helper(k)

