def sort_binary_array(arr): 
    low = 0
    high = len(arr) - 1

    while low < high: 
        if (arr[low] == 1): 
            arr[low], arr[high] = arr[high], arr[low] 
            high -= 1
        else: 
            low += 1
    return arr

