class TextEditor:
    def __init__(self, text):
        self.text = text
        self.history = []
        self.unindex = -1

    def edit(self, start, end, new_text):
        prev_text = self.text[start:end]
        self.text = self.text[:start] + new_text + self.text[end:]
        self.add_to_history(prev_text, start)

    def add_to_history(self, prev_text, start):
        self.history.append((prev_text, start))
        self.unindex = len(self.history) - 1

    def undo(self):
        if self.unindex >= 0:
            prev_text, start = self.history[self.unindex]
            end = start + len(prev_text)
            self.text = self.text[:start] + prev_text + self.text[end:]
            self.unindex -= 1

    def redo(self):
        if self.unindex < len(self.history) - 1:
            self.unindex += 1
            prev_text, start = self.history[self.unindex]
            end = start + len(prev_text)
            self.text = self.text[:start] + prev_text + self.text[end:]

