class Queue {
  constructor() {
    this.head = null;
    this.tail = null;
  }
  // enqueue an item to the end of the queue
  enqueue(item) {
    if (!this.head) {
      this.head = this.tail = { item, next: null };
    } else {
      this.tail.next = { item, next: null };
      this.tail = this.tail.next;
    }
  }
  // dequeue an item from the beginning of the queue
  dequeue() {
    if (!this.head) {
      return "The queue is empty!";
    }
    const item = this.head.item;
    this.head = this.head.next;
    return item;
  }
  isEmpty(){
    return this.head === null;
  }
}

def find_all_ways(x, y):
    if x == 0 and y == 0:
        return [[(0, 0)]]

    paths = []
    if x > 0:
        paths += find_all_ways(x-1, y)
    if y > 0:
        paths += find_all_ways(x, y-1)

    for path in paths:
        path.append((x, y))
    return paths

