             [0, 0, 0],
             [0, 0, 0]]
    return board

def move_possible(board):
    moves = []
    for i in range(3):
        for j in range(3):
            if board[i][j] == 0:
                moves.append([i, j])
    return moves

def player_turn(board, players_mark, ai_mark):

    move = input('Your move? (row, column): ')
    x = int(move.split(',')[0])
    y = int(move.split(',')[1])

    if x > 2 or x < 0 or y > 2 or y < 0:
        print('Invalid move!')
        return player_turn(board, players_mark, ai_mark)

    if board[x][y] != 0:
        print('Invalid move!')
        return player_turn(board, players_mark, ai_mark)

    board[x][y] = players_mark

    if victory_check(board, players_mark):
        print("Player wins!")
        print_board(board)
        return

    if move_possible(board):
        board = ai_turn(board, players_mark, ai_mark)
    else:
        print("It's a draw!")
        print_board(board)
        return

    if victory_check(board, ai_mark):
        print("AI wins!")
        print_board(board)
        return

def ai_turn(board, players_mark, ai_mark):

    moves = move_possible(board)
    move = random.choice(moves)

    board[move[0]][move[1]] = ai_mark
    return board

# Checks if player has 3 marks in a row 
def victory_check(board, mark):

    # Horizontal
    if board[0][0] == board[0][1] == board[0][2] == mark:
        return True
    if board[1][0] == board[1][1] == board[1][2] == mark:
        return True
    if board[2][0] == board[2][1] == board[2][2] == mark:
        return True

    # Vertical
    if board[0][0] == board[1][0] == board[2][0] == mark:
        return True
    if board[0][1] == board[1][1] == board[2][1] == mark:
        return True
    if board[0][2] == board[1][2] == board[2][2] == mark:
        return True

    # Diagonal
    if board[0][0] == board[1][1] == board[2][2] == mark:
        return True
    if board[2][0] == board[1][1] == board[0][2] == mark:
        return True

    return False

