    words = sentence.split(" ")
    translated_words = []
    vowels = ["a", "e", "i", "o", "u"]

    for word in words:
        if word[0] in vowels:
            translated_words.append(word + "way")
        else:
            translated_words.append(word[1:] + word[0] + "ay")

    return " ".join(translated_words)

