import java.util.Scanner;

public class Hangman {

 final String word;
 final String[] hiddenWord;
 int tries;

 public Hangman(String word) {
 this.word = word;
 this.tries = 6;
 this.hiddenWord = new String[this.word.length()];
 }

 public void startGame() {
 // Initialize hidden word with underscores
 for (int i = 0; i < hiddenWord.length; i++) {
 hiddenWord[i] = "_";
 }
 System.out.println("Let's play Hangman!");
 while(tries > 0) {
 System.out.println("You have " + tries + " tries remaining.");
 // Display hidden word
 System.out.println("");
 for (String letter : hiddenWord) {
 System.out.print(letter + " ");
 }
 // Get user guess
 Scanner scanner = new Scanner(System.in);
 System.out.print("\nPlease enter your guess: ");
 String guess = scanner.nextLine().toUpperCase();

 if(word.contains(guess)) {
 for(int i = 0; i < word.length(); i++) {
 if(word.charAt(i) == guess.charAt(0)) {
 hiddenWord[i] = guess;
 }
 }
 } else {
 // Reduce the available tries
 tries--;
 }
 }
 System.out.println("You won!");
 }
}

