public class SumPairs {

    public static int[] sumPairs(int[] arr, int sum) {
        Map<Integer, Integer> map = new HashMap<>(); 
        int[] result = {-1, -1};

        for (int i = 0; i < arr.length; i++) {
            //find the complement in the map
            int comp = sum - arr[i]; 
            if (map.containsKey(comp)) { 
                result[0] = map.get(comp); 
                result[1] = i; 
            } 
            //store the processed value in the map 
            map.put(arr[i], i); 
        } 

        return result;
    }

    public static void main(String[] args) 
    { 
        int arr[] = { 10, 13, 4, 8, 24 }; 
        int sum = 17;
        int[] result = sumPairs(arr, sum); 
        System.out.println("The two indices with the given sum are: "+result[0]+" and "+ result[1]);
    } 
    }

function sort(arr) {
 let minIdx;

 for (let i = 0; i < arr.length; i++) {
 minIdx = i;

 for (let j = i+1; j < arr.length; j++) {
  if (arr[j] < arr[minIdx]) {
   minIdx = j;
  }
 }

 if (i !== minIdx) {
  let temp = arr[i];
  arr[i] = arr[minIdx];
  arr[minIdx] = temp;
 }
