def find_longest_increasing_subsequence(arr):

    # Create an array to store the length of longest increasing subsequence 
    lengths = [1]*len(arr)

    # fill the array with dynamic programming
    for i in range(1, len(arr)):
        for j in range(0, i):
            if arr[i] > arr[j] and lengths[i] < lengths[j] + 1 :
                lengths[i] = lengths[j]+1

    # return the maximum longest increasing subsequence
    return max(lengths)

