public static String findLongestWord(String str) { 
  String[] arr = str.split("\\s+"); 
  int len = 0; 
  String longestWord = "";    
  for (String s : arr) { 
    if (s.length() > len) { 
      len = s.length(); 
      longestWord = s; 
    } 
  } 
  return longestWord; 
}

