// Find the longest consecutive sequence in an array
function longestConsecutiveSequence(arr) {
    // Store the longest sequence
    let longestLength = 0;

    // Store the numbers seen
    let seen = {};

    // Iterate through the array
    for (let i=0; i < arr.length; i++) {
        // Store the current element in the array
        let current = arr[i];

        // If the current element is seen, move on to the next element
        if (seen[current]) continue;

        // Store the current sequence
        let currentSequenceLength = 1;

        // Begin going up in sequence
        let up = current+1;

        // While the numbers seen includes the number up
        while (seen[up]) {
            // Increment the current sequence length
            currentSequenceLength++;

            // Increment up
            up++;
        }

        // Begin going down in sequence
        let down = current-1;

        // While the numbers seen includes the number down
        while (seen[down]) {
            // Increment the current sequence length
            currentSequenceLength++;

            // Increment down
            down--;
        }

        // Store the current element in the numbers seen
        seen[current] = current;

        // Update the longest sequence
        longestLength = Math.max(longestLength, currentSequenceLength);
    }

    return longestLength;
}

