function traverseTree(tree) {
    var activeNodes = [];
    var queue  = [];
    queue.push(tree);
    while (queue.length > 0) {
        var node = queue.shift();
        if (node.status === 'active') {
            activeNodes.push(node);
        }
        if (node.children) {
            queue.push(...node.children);
        }
    }
    return activeNodes;
}

