 public static void insertSorted(ListNode head, int element) {
 // Find the appropriate position for the element
 ListNode curr = head;
 while (curr.next != null && curr.next.data < element) {
 curr = curr.next;
 }

 // Insert the element 
 ListNode newNode = new ListNode(element);
