A hash table can be used to store contact information with fast search and update capabilities. A hash function maps the contact's name to an integer value to index the array, and the contact information is stored in the corresponding array index. This makes retrieving the contact information very fast, since it can be done in O(1) time. Updating the contact information is also very fast.

Example:

public class ContactHashTable {
    private final int SIZE = 50; 
    private List<Contact>[] table;

    public ContactHashTable() {
        // Initialize the hash table
        table = new ArrayList[SIZE];
        for (int i = 0; i < SIZE; i++) {
            table[i] = new ArrayList<>();
        }
    }

    // Hash function to compute the index of the array
    public int hash(String name) {
        int hash = 0;
        for (int i = 0; i < name.length(); i++) {
            hash += (int)name.charAt(i);
        }
        hash %= SIZE;
        return hash;
    }

    // Inserts a contact into the hash table
    public void insert(Contact contact) {
        int index = hash(contact.getName());
        table[index].add(contact);
    }

    // Search for a contact in the hash table
    public Contact search(String name) {
        int index = hash(name);

        // Retrieve the contact from the linked list at the index
        for (Contact contact : table[index]) {
            if (name.equals(contact.getName()))
                return contact;
        }
        return null;
    }

    // Update a contact in the hash table
    public void update(String name, Contact contact) {
        int index = hash(name);

        // Find the contact and update its information
        for (Contact c : table[index]) {
            if (name.equals(c.getName())) {
                c.setName(contact.getName());
                c.setPhoneNumber(contact.getPhoneNumber());
                c.setEmail(contact.getEmail());
            }
        }
    }
}

