public void convertStr(std::string& str)
{
    std::string newString = "";
    for(int i = 0; i < str.length(); i++)
    {
        if(str[i] == '_')
        {
            newString += " ";
        }
        else
        {
            newString += toupper(str[i]);
        }
    }
    str = newString;
}

