def groupBasedOnProximity(locations, threshold_distance):
    group_num = 0
    group_list = []
    for i in range(len(locations)-1):
        group_list.append([])
        group_list[group_num].append(locations[i])
        for j in range(i+1, len(locations)):
            if get_distance(locations[i], locations[j]) <= threshold_distance:
                group_list[group_num].append(locations[j])
            else:
                if len(group_list[group_num]) == 1:
                    group_num += 1
                    if i == len(locations) - 1:
                        break
                    group_list.append([])
                    group_list[group_num].append(locations[i+1])
    return group_list

