def find_most_repeating_number(arr):
    freq = dict()
    for elem in arr:
        if elem not in freq:
            freq[elem] = 1
        else:
            freq[elem] = freq[elem] + 1
    max_elem = 0
    max_freq = 0
    for key, value in freq.items():
        if value > max_freq:
            max_elem = key
            max_freq = value
    return max_elem

def prime_factors(n):
    factors = []
    d = 2
    while n > 1:
        while n % d == 0:
            factors.append(d)
            n /= d
        d += 1
        if d*d > n:
            if n > 1: 
                factors.append(n)
            break
    return factors

