// Returns maximum profit for given array of jobs
int maxProfit(int n, int job[][2]) 
{ 
    int i, j, totalProfit, jobsDone; 

    // Sort jobs in increasing order of deadline
    // Using bubble sort 
    for (i = 0; i < n; i++) { 
        for (j = 0; j < n - 1; j++) { 
            if (job[j][1] > job[j + 1][1]) { 
                int tempReward = job[j][0]; 
                int tempDeadline = job[j][1]; 
                job[j][0] = job[j + 1][0]; 
                job[j][1] = job[j + 1][1]; 
                job[j + 1][0] = tempReward; 
                job[j + 1][1] = tempDeadline; 
            } 
        } 
    } 

    totalProfit = 0; 

    // Consider jobs one by one in decreasing order of their deadline 
    for (jobsDone = 0; jobsDone < n; jobsDone++) { 

        for (i = 0; i <= jobsDone; i++) { 
            // Compare deadline of new job with 
            // already processed jobs 
            if (job[i][1] >= jobsDone - i + 1) 
                totalProfit += job[i][0]; 
        } 
    } 

    return totalProfit; 
}

