    '''This function takes a list of strings and returns a list of all anagrams found.'''
    anagrams = []

    for i in range(len(strings) - 1):
        for j in range(i + 1, len(strings)):
            if sorted(strings[i]) == sorted(strings[j]):
                anagrams.append([strings[i], strings[j]])

    return anagrams


