def longestCommonPrefix(strings):
    if len(strings) == 0:
        return ""

    shortest_string = strings[0]

    for string in strings:
        if len(shortest_string) > len(string):
            shortest_string = string

    longest_prefix = ""
    for i in range(len(shortest_string)):
        character = shortest_string[i]
        prefix_exists = True
        for string in strings:
            if string[i] != character:
                prefix_exists = False
                break
        if not prefix_exists:
            break
        longest_prefix += character
    return longest_prefix

