def dijkstra(graph,start,end):

    #Set the distance for the start node to zero 
    shortest_distance = {start:0}
    current_node = start
    visited = set()

    while current_node != end:
        visited.add(current_node)
        neighbors = graph[current_node]
        distance = shortest_distance[current_node]

        for key in neighbors.keys():
            if key not in visited:
                new_distance = distance + neighbors[key]
                if key not in shortest_distance or new_distance<shortest_distance[key]:
                    shortest_distance[key] = new_distance
        next_destinations = {node: shortest_distance[node] for node in shortest_distance if node not in visited}
        if not next_destinations:
            return "Route Not Possible"
        #next node is the destination with the lowest distance
        current_node = min(next_destinations, key=next_destinations.get)

    return shortest_distance[end]

