def solve_maze(maze):
    path = []
    stack = [maze[0][0]]

    while stack:
        curr = stack[-1]
        if curr == maze[-1][-1]:
            break
        else:
            if maze[curr[0]][curr[1] + 1] != 'x':
                stack.append([curr[0], curr[1] + 1])
            elif maze[curr[0] + 1][curr[1]] != 'x':
                stack.append([curr[0] + 1, curr[1]])
            else:
                stack.pop()
    for point in stack:
        path.append(point)
    return path

