"""
Develop a matrix class that implements basic linear algebra operations

"""
class Matrix:

    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.matrix = [[0 for c in range(cols)] for r in range(rows)]

    # Addition of two matrices
    def add(self, matrix2):
        if ((self.rows == matrix2.rows) and (self.cols == matrix2.cols)):
            matrix3 = Matrix(self.rows, self.cols)
            for i in range(self.rows):
                for j in range(self.cols):
                    matrix3.matrix[i][j] = self.matrix[i][j] + matrix2.matrix[i][j]
            return matrix3
        else:
            return False

    # Multiplication of two matrices
    def mul(self, matrix2):
        if (self.cols == matrix2.rows):
            matrix3 = Matrix(self.rows, matrix2.cols)
            for i in range(self.rows):
                for j in range(matrix2.cols):
                    total = 0
                    for k in range(self.cols):
                        total += (self.matrix[i][k] * matrix2.matrix[k][j])
                    matrix3.matrix[i][j] = total
            return matrix3
        else:
            return False

    # Scalar multiplication of matrix
    def mulScalar(self, scalar):
        matrix2 = Matrix(self.rows, self.cols)
        for i in range(self.rows):
            for j in range(self.cols):
                matrix2.matrix[i][j] = self.matrix[i][j] * scalar
        return matrix2

