class HashTable: 
 def __init__(self): 
   self.table = [[] for _ in range(1000)]

 def add(self, key, value): 
  # converts key to a hash code, which is an integer between 0 and 999
  h = hash(key) % 1000 
  # If a new key is found
  if not self.find(key): 
    self.table[h].append((key, value)) 
  # If key is already present
  else:  
    for i in range(len(self.table[h])):
  # Replace the old value
      if self.table[h][i][0] == key: 
        self.table[h][i] = (key, value)

 def find(self, key): 
  h = hash(key) % 1000 
  for (k, v) in self.table[h]: 
    if k == key: 
      return v
  return False

