def most_frequent_value(array):
    counter_dict = {}
    for val in array:
        if val in counter_dict:
            counter_dict[val] += 1
        else:
            counter_dict[val] = 1
    max_count = 0
    frequent_val = 0
    for key,val in counter_dict.items():
        if val > max_count:
            max_count = val
            frequent_val = key
    return frequent_val

