public static int longestIncreasingSeq(int[] arr) {
    int longestSeq = 0;
    int currSeq = 0;

    for (int i = 0; i < arr.length; i++) {
        if (i == 0 || arr[i - 1] < arr[i]) {
            currSeq += 1;
            longestSeq = Math.max(currSeq, longestSeq); 
        } else {
            currSeq = 1;
        }
    }
    return longestSeq;
}

