def combine_sorted_arrays(arr1, arr2):
    len1 = len(arr1)
    len2 = len(arr2)
    i = 0 # pointer to arr1
    j = 0 # pointer to arr2
    res = []
    while i < len1 and j < len2:
        if arr1[i] < arr2[j]:
            res.append(arr1[i])
            i += 1
        else:
            res.append(arr2[j])
            j += 1
    while i <len1:
        res.append(arr1[i])
        i += 1
    while j <len2:
        res.append(arr2[j])
        j += 1
    return res

