//Reducer to handle the state changes
const listReducer = (state = [], action) => {
    switch (action.type) {
        case 'ADD_ITEM':
            return state.concat([action.item]);
        case 'REMOVE_ITEM':
            return state.filter((item, idx) => idx !== action.idx);
        default:
            return state;
    }
}

// Create a Redux store holding the state of your app
