// Render the UI as per the current state
const render = () => {
    ReactDOM.render(
        <ul>
            {store.getState().map((item, idx) => (
                <li key={idx}>
                    {item}
                    <button onClick={() => store.dispatch({type: 'REMOVE_ITEM', idx})}>x</button>
                </li>
            ))}
        </ul>,
        document.getElementById('root')
    );
};

