import re

def detect_malicious_activity(log):
    # regular expressions to match suspicious activity
    malicious_activity = [
        re.compile('.*sql injection.*', re.IGNORECASE),
        re.compile('.*command injection.*', re.IGNORECASE),
        re.compile('.*xss attack.*', re.IGNORECASE)
    ]
    malicious_ips = []
