class FrequencyDataStructure {
    // is used to store the data
    private Map<Integer, List<Integer>> numToFreq;

    // constructor
    public FrequencyDataStructure() {
        // initialize numToFreq
        numToFreq = new HashMap<>();
    }

    // adds a number to the data structure
    public void add(int number) {
        if (numToFreq.containsKey(number)) {
            List<Integer> list = numToFreq.get(number);
            list.add(number);
        } else {
            List<Integer> list = new ArrayList<>();
            list.add(number);
            numToFreq.put(number, list);
        }
    }

    // retrieves all numbers with a certain frequency
    public List<Integer> getNumbers(int frequency) {
        List<Integer> res = new ArrayList<>();
        for (Integer key : numToFreq.keySet()) {
            if (numToFreq.get(key).size() == frequency) {
                res.add(key);
            }
        }
        return res;
    }
}

