def shortest_path(adj_matrix, start, end):
    queue = [start]
    visited = set()

    while queue:
        node = queue.pop(0)
        visited.add(node)

        if node == end:
            return True

        for i in range(len(adj_matrix[node])):
            if adj_matrix[node][i] == 1 and i not in visited:
                queue.append(i)

    return False

