def find_paths(startpoint, endpoint, grid): 
    result = [] 
    # Mark all the obstacles as blocked 
    for i in range(len(grid)): 
        for j in range(len(grid[0])): 
            if (grid[i][j] == 0): 
                grid[i][j] = -1

    # Initialize the queue 
    q = queue.Queue() 
    # Push the start point to the queue 
    q.put(startpoint) 
    while not q.empty(): 
        r, c = q.get() 
        # Print the result if the coordinates match the end point 
        if (r == endpoint[0] and c == endpoint[1]): 
            result.append([r, c]) 
        else: 
            # Explore North 
            if (valid(r-1, c, grid)): 
                q.put([r-1, c]) 
                grid[r-1][c] = 1
            # Explore South 
            if (valid(r+1, c, grid)): 
                q.put([r+1, c]) 
                grid[r+1][c] = 1
            # Explore East 
            if (valid(r, c+1, grid)): 
                q.put([r, c+1]) 
                grid[r][c+1] = 1
            # Explore West 
            if (valid(r, c-1, grid)): 
                q.put([r, c-1]) 
                grid[r][c-1] = 1
    return result

def valid(r, c, grid): 
    return (r >= 0 and r < len(grid) and 
            c >= 0 and c < len(grid[0]) and 
            grid[r][c] == 0)

