def evaluateExpression(expression):
    exp_list = expression.split()
    result = 0
    num1 = 0
    num2 = 0
    operator = ''
    for item in exp_list:
        if item.isdigit():
            if num1 == 0:
                num1 = int(item)
            else:
                num2 = int(item)
        else:
            operator = item

    if operator == '+':
        result = num1 + num2
    elif operator == '-':
        result = num1 - num2
    elif operator == '*':
        result = num1 * num2
    elif operator == '/':
        result = num1 / num2

    return result

