def construct_tree(edges):
    edges_dict = {edge[0]: edge[1] for edge in edges}
    root = None
    for edge in edges:
        if edge[0] not in edges_dict:
            root = edge[0]

    def build_tree(node):
        left = None
        if node in edges_dict:
            left = edges_dict[node]
            del edges_dict[node]
            build_tree(left)

        right = None
        for edge in edges:
            if edge[0] == node:
                right = edge[1]
                del edges_dict[node]
                build_tree(right)

        return TreeNode(node, left, right)

    if root:
        return build_tree(root)

