public class LinearEquation {
    public int solveEquation(int a, int b, int c, int d, int e, int f) { 
        int x, y, determinant;   
        //Calculate Determinant
        determinant = a*d - b*c;
        //Calculate x and y
        x = (e*d - b*f)/determinant;
        y = (a*f - e*c)/determinant;
        return new int[]{x, y};
    } 
}

