int Fibonacci(int n)
{
    if(n <= 1)
        return n;

    int f1 = 0, f2 = 1, i;
    int nextTerm;

    for(i = 2; i <= n; i++)
    {
        nextTerm = f1 + f2;
        f1 = f2;
        f2 = nextTerm;
    }

    return nextTerm;
}

