string removeExtraSpaces(string s)
{
    int count = 0;
    int n = s.length();

    for (int i = 0; i < n; i++) {

        if (s[i] != ' ')
            s[count++] = s[i];

        else if (s[i] == ' ')
            while (s[i] == ' ')
                i++;

        s[count++] = s[i];
    }

    s[count] = '\0';

    return s;
