} 

// This function searches a given 
// key x in a linked list pointed 
// by head. 
// Returns true if x is present 
// in linked list; false otherwise 
static boolean search(Node head, int x) 
{ 
	Node current = head;
	while (current != null) 
	{ 
		if (current.data == x) 
			return true; 

		current = current.next; 
	} 
	return false; 
}

