public class SortArray {

 public static void main(String[] args) {
  int[] nums = {2, 7, 3, 5, 8, 1, 9};

  // Bubble Sort
  int n = nums.length;
  int temp = 0;

  for (int i = 0; i < n; i++) {
   for (int j = 1; j < (n - i); j++) {
    if (nums[j - 1] > nums[j]) {
     // swap elements
     temp = nums[j - 1];
     nums[j - 1] = nums[j];
     nums[j] = temp;
    }
   }
  }

  System.out.println("Sorted array:");

  for (int i = 0; i < nums.length; i++) {
   System.out.print(nums[i] + " ");
  }
 }
}

