func stepClimb(steps int, goal int) int {
 // table to store results of subproblems
 table := make([]int, goal+1)

 // init table 
 table[0] = 1 // base case 

 // compute values in bottom up manner 
 for i := 1; i <= goal; i++ {
  for j := 1; j <= steps && j <= i; j++ {
   table[i] += table[i - j]
  }
 }

 return table[goal]
}

func main() {
 fmt.Println(stepClimb(5, 10))
}

