void findPermutations(std::string str, int index, int n) 
{ 
    if (index >= n) 
    { 
        std::cout << str << std::endl; 
        return; 
    } 

    for (int i = index; i < n; i++) 
    { 
        std::swap(str[index], str[i]); 

        findPermutations(str, index + 1, n); 

        std::swap(str[index], str[i]); 
    } 
} 

int main() 
{ 
    std::string str = "ABC"; 
    int n = str.size(); 
    findPermutations(str, 0, n); 

    return 0; 
}

