#define ROWS 4
#define COLS 4

void spiralPrint(int arr[ROWS][COLS], int row, int col) 
{ 
    int i, rowCount = 0, colCount = 0; 
    while (rowCount < row && colCount < col) {
        for (i = colCount; i < col; ++i) {
            printf("%d ", arr[rowCount][i]); 
        } 
        rowCount++;
        for (i = rowCount; i < row; ++i) { 
            printf("%d ", arr[i][col - 1]); 
        } 
        col--;
        if (rowCount < row) {
            for (i = col - 1; i >= colCount; --i) {
                printf("%d ", arr[row - 1][i]); 
            }
            row--;
        } 
        if (colCount < col) {
            for (i = row - 1; i >= rowCount; --i) {
                printf("%d ", arr[i][colCount]); 
            } 
            colCount++;
        } 
    }
}

