def largest_prime_factor(n):
    # Special case for 0,1
    if n <= 1:
        return 1

    largest_prime_factor = 1
    # Find the smallest prime number that can divide n
    for i in range(2, n + 1):
        if n % i == 0:
            largest_prime_factor = i
            break

    # Divide n and call the same function with n = n/i
    return max(largest_prime_factor, largest_prime_factor(int(n / i)))

