public boolean isPerfectSquare(int num) { 
    int l = 1, r = num; 
    while (l <= r) { 
        int m = l + (r - l) / 2; 
        int n = m*m; 

        if (n == num) 
            return true; 

        if (n < num) 
            l = m + 1; 
        else
            r = m - 1; 
    } 
    return false; 
}

