def print_combinations(n, k): 

    # first boundary case, if K is 0, print empty set 
    if (k == 0): 
        print("{}") 
        return

    # second boundary case when k is n, print single set 
    if (k == n): 
        for i in range(0, n): 
            print("{", i, "}") 
        return

    # recursive call
    print_combinations(n-1, k) 

    # include nth element in current combination 
    for i in range(0, n):
        if (k-1 > 0): 
            # generate new set by adding nth element 
            print("{", i, end = "") 
            print_combinations(n-1, k-1) 
            print("}", end = "")

