    // can be expressed as sum of 
    // two prime numbers 
    static boolean isExpressibleAsSumOfTwoPrimes(int n) 
    { 
        // iterating through all prime 
        // numbers smaller than n 
        for (int i = 2; i < n; i++) { 

            if (isPrime(i)) { 
                if (isPrime(n - i)) { 
                    return true; 
                } 
            } 
        } 
        return false; 
    } 

    // Function to check prime number 
    static boolean isPrime(int n) 
    { 
        for (int j = 2; j <= Math.sqrt(n); j++) { 
            if (n % j == 0) { 
                return false; 
            } 
        } 
        return true; 
    } 

