string encode(string s) 
{ 
    string res; 

    for (int i = 0; i < s.length(); i++) { 
        int count = 1; 
        while (i + 1 < s.length() && s[i] == s[i + 1]) { 
            count++; 
            i++; 
        } 
        res += s[i]; 
        res += to_string(count); 
    } 
    return res; 
}

string decode(string s) 
{ 
    string res; 
    int i = 0; 
    while (i < s.length()) { 
        int count = 0; 
        if (s[i + 1] >= '0' && s[i + 1] <= '9') { 
            count = (s[i + 1] - '0'); 
        } 

        for (int j = 0; j < count; j++) { 
            res += s[i]; 
        } 

        i = i + 2;  
    } 
    return res;
}

