const App = () => {
 const location = useLocation();

 useEffect(() => {
 // Set a boundary for the alert 
 const boundary = {
 latitude: 50.0,
 longitude: 25.0,

 // Set boundary radius 
 radius: 1000, // 1km 
 };

 Geolocation.watchPosition(
 (position) => {
 // Check if user left boundary
 const leftBoundary = checkWithinBoundary(boundary, position.coords);

 // Send an alert if user has left boundary
 if (leftBoundary) {
 Alert.alert('Alert', 'You have left the boundary');
 }
