string caesarCipher(string message, int shift) {
  string output = "";
  for(int i=0; i < message.length(); i++) {
    char letter = message[i];
    if(letter >= 'a' && letter <= 'z') {
      letter = char(int(letter) + shift);
      if(letter > 'z')
        letter -= 'z' - 'a' + 1;
    } else if(letter >= 'A' && letter <= 'Z') {
      letter = char(int(letter) + shift);
      if(letter > 'Z')
        letter -= 'Z' - 'A' + 1;
    }
    output += letter;
  }
  return output;
}

