public class RaceCondition { 
   public static void main(String[] args) throws InterruptedException { 
      SharedCounter counter = new SharedCounter(); 

      Thread thread1 = new Thread(counter, "Thread1"); 
      Thread thread2 = new Thread(counter, "Thread2"); 

      thread1.start(); 
      thread2.start(); 

      thread1.join(); 
      thread2.join(); 

      System.out.println("Final count is : " + counter.count); 
   } 
} 

class SharedCounter implements Runnable { 
   int count = 0; 

   @Override
   public void run() { 
      for (int i = 0; i < 5; i++) { 
        processSomething(i); 
        count++; 
      } 
   } 

   public void processSomething(int i) { 
        // processing some job
        try { 
            Thread.sleep(i * 1000); 
        }
        catch (InterruptedException e) { 
            e.printStackTrace(); 
        } 
   } 
}

