const isTriangle = (arr, target) => {
 for (let i = 0; i < arr.length; i++) {
  for (let j = i + 1; j < arr.length; j++) {
   for (let k = j + 1; k < arr.length; k++) {
    let a = Math.abs(arr[i].x - arr[j].x);
    let b = Math.abs(arr[i].y - arr[j].y);
    let c = Math.abs(arr[j].x - arr[k].x);
    let d = Math.abs(arr[j].y - arr[k].y);
    let s = (a + b + c + d) / 2;
    let area = Math.sqrt((s - a) * (s - b) * (s - c) * (s - d));
    if (area === target) return true;
   }
  }
 }
 return false;
}

