public class MinCostTrip {
    static int minCost(int cost[][], int from, int to) {
        int[] dist = new int[cost.length];

        for (int i = 0; i < cost.length; i++) {
            if (i == from) {
                dist[i] = 0;
            } else {
                dist[i] = Integer.MAX_VALUE;
            }
        }

        for (int i = 0; i < cost.length; i++) {
            for (int j = 0; j < cost[i].length; j++) {
                if (i != j && cost[i][j] > 0 &&
                    dist[i] != Integer.MAX_VALUE &&
                    dist[i] + cost[i][j] < dist[j]) {
                    dist[j] = dist[i] + cost[i][j];
                }
            }
        }
        return dist[to];
    }

    // Driver program
