public class LongestSubstring {
	public static String longestSubstring(String x, int y) 
	{ 
		int n = x.length(); 

		// To store last index of every character 
		int[] lastIndex = new int[256]; 

		for (int i=0; i<256; i++) 
			lastIndex[i] = -1; 

		// For storing result 
		int ans = 0; 

		int j = 0; // start of current substring 
		int unique = 0; // unique character count 

		for (int i=0; i<n; i++) 
		{ 
			// if current character is not present in the 
			// existing substring 
			if (lastIndex[x.charAt(i)] == -1) 
				unique++; 

			// update last index of current character 
			lastIndex[x.charAt(i)] = i; 

			// if unique character count becomes more than 
			// k, then shrink the window from beginning 
			if (unique > y) 
			{ 
				// k is exceeded, remove from starting 
				while (lastIndex[x.charAt(j)] != j) 
					j++; 

				// update unique 
				unique--; 
				j++; 
			} 

			// update the maximum length substring 
			// if required 
			ans = Math.max(ans, i-j+1); 
		} 

		// return a substring from x with length of ans 
		return x.substring(j,ans+j); 
	} 
}

