import uuid

class LoginSystem:
    def __init__(self):
        # Unique User ID should be generated when the user registers
        self.user_id = None
        # Dictionary to store the user credentials
        self.credentials = {}

    def register_user(self, username, password):
        # Generate unique user ID for new user
        self.user_id = uuid.uuid4().hex 
        # Salt & Password
        salt = uuid.uuid4().hex
        hashed_password = hashlib.sha512(salt.encode() + password.encode()).hexdigest()
        # Store the user credentials 
        self.credentials[self.user_id] = [
            {'username': username}, 
            {'salt': salt}, 
            {'hashed_password': hashed_password}
        ]
        return self.user_id 

# The function to be used to validate a user login 
    def validate_user(self, user_id, password):
        user_data = self.credentials.get(user_id)
        if user_data is None:
            # user ID not found
            return False
        salt = user_data[1]['salt']
        hashed_password = hashlib.sha512(salt.encode() + password.encode()).hexdigest()
        if hashed_password == user_data[2]['hashed_password']:
            return True
        else:
            return False

