    public static int[] deleteElement(int arr[], int pos) { 

        // If the array is empty 
        if (arr == null) { 
            return arr; 
        } 

        // if the position to delete is valid 
        if (pos >= 0 && pos < arr.length) { 

            // Create another array only with the good elements
            int[] newArr = new int[arr.length - 1]; 

            // Copy elements, except the one to delete 
            for (int i = 0, k = 0; i < arr.length; i++) { 

                // if the index is 
                // the removal element index 
                if (i == pos) { 
                    continue; 
                } 

                // if the index is not 
                // the removal element index 
                newArr[k++] = arr[i]; 
            } 

            // return the resultant array 
            return newArr; 
        } 

        // if the position is not in the array 
        else { 
            System.out.println("invalid position"); 
            return arr; 
        } 
    } 

