// Searches 'arr' for 'key'. If found, returns index of 'key' in 'arr', otherwise returns -1
int binarySearch(int arr[], int n, int key)
{
 int left = 0;
 int right = n-1;
 int middle;

 while (left <= right)
 {
  middle = left + (right - left) / 2;

  // key found
  if (arr[middle] == key)
   return middle;

  // search left half
  if (key < arr[middle])
   right = middle - 1;

  // search right half
  else 
   left = middle + 1;
 }

 // key not found
 return -1;
}

