#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>

int main(int argc, char *argv[])
{
    // create a socket and check for errors
    int socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        error("ERROR opening socket");
    }

    // bind the socket, check for errors, then start listening
    struct sockaddr_in server_addr;
    bzero((char *) &server_addr, sizeof(server_addr));
    server_addr.sin_port = htons(port_number);
    server_addr.sin_family = AF_INET;
    if (bind(socket_fd, (struct sockaddr *) &server_addr, sizeof(server_addr)) < 0) {
        error("ERROR binding socket");
    }
    listen(socket_fd, 5);

    // create new socket for client and check for errors
    int client_socket_fd;
    socklen_t client_addr_len = sizeof(struct sockaddr_in);
    if ((client_socket_fd = accept(socket_fd, (struct sockaddr *) &client_addr, &client_addr_len)) < 0) {
        error("ERROR on accept");
    }

    // start serving the client 
    serving_client(client_socket_fd);

    // close the client socket and check for errors
    if (close(client_socket_fd) < 0) {
        error("ERROR closing client socket");
    }

    return 0;
}

// serving_client() function
void serving_client(client_socket_fd) {
    int n;
    char buffer[255];

    bzero(buffer, 256);
    n = read(client_socket_fd, buffer, 255);
    if (n < 0) {
        error("ERROR reading from client socket");
    }

    // parsing and processing the HTTP request
    char* first_line = strtok(buffer, "\n");
    if (strstr(first_line, "GET")) {
        int request_len = strlen(first_line);
        char* request = malloc((request_len + 1) * sizeof(char));
        strcpy(request, first_line);
        request[request_len - 1] = 0;

        // creating and sending the HTTP response
        int content_length = get_content_length(request);
        response_headers(client_socket_fd, content_length);
        send_content(client_socket_fd, content_length);
        free(request); 
    }
}

// get_content_length() function
int get_content_length(char *req) {
    FILE *fp;
    char line[255]; 
    int content_len = 0;

    fp = fopen("index.html", "r");
    if (fp == NULL) {
        error("ERROR opening file");
    }

    while (fgets(line, 255, fp) != NULL) {
        content_len += strlen(line);
    }
    fclose(fp);

    return content_len;
}

// response_headers() function
void response_headers(client_socket_fd, content_length) {
    char http_headers[255];

    // creating the http headers
    sprintf(http_headers, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: %d \r\nConnection: keep-alive\r\n\r\n" , content_length);

    // sending the http headers
    write(client_socket_fd, http_headers, strlen(http_headers));
}

// send_content() function
void send_content(client_socket_fd, content_length) {
    FILE *fp;
    char buffer[255]; 

    fp = fopen("index.html", "r");
    if (fp == NULL) {
        error("ERROR opening file");
    }

    int n = 0;
    while (n < content_length) {
        // clear the buffer
        bzero(buffer, 256);

        // read the content from the file
        int bytes_read = fread(buffer, sizeof(char), 255, fp);
        n += bytes_read;

        // write the content to the client 
        write(client_socket_fd, buffer, bytes_read);
    }
    fclose(fp);
}

