function maxProfit(stockPrices) {
    let maxProfit = 0;

    for (let i = 0; i < stockPrices.length; i++) {
        // Check if the current stock price is less than the next
        if (stockPrices[i + 1] > stockPrices[i]) {
            // Calculate the maximum profit
            let currentProfit = stockPrices[i + 1] - stockPrices[i];
            maxProfit = Math.max(currentProfit, maxProfit);
        }
    }

    return maxProfit;
}

