using namespace std; 

int evaluatePostfix(string exp) 
{ 
    stack<int> s; 
    for (int i = 0; i < exp.length(); i++) { 
        if (isdigit(exp[i])) 
            s.push(exp[i] - '0'); 
        else { 
            int val1 = s.top(); 
            s.pop(); 
            int val2 = s.top(); 
            s.pop(); 
            switch (exp[i]) { 
            case '+': 
                s.push(val2 + val1); 
                break; 
            case '-': 
                s.push(val2 - val1); 
                break; 
            case '*': 
                s.push(val2 * val1); 
                break; 
            case '/': 
                s.push(val2/val1); 
                break; 
            } 
        } 
    } 
    return s.top(); 
} 

int main() 
{ 
    string exp = "2 3 + 5 *";
    cout << evaluatePostfix(exp) << endl;
}

