public static int getSecondHighestElement(int[] arr) {
    if (arr == null || arr.length < 2) {
        return Integer.MIN_VALUE;
    }
    int max = Integer.MIN_VALUE;
    int secondMax = Integer.MIN_VALUE;
    for (int i : arr) {
        if (i > max) {
            secondMax = max;
            max = i;
        } else if (i > secondMax && i != max) {
            secondMax = i;
        } 
    }
    return secondMax;
}

