public class StepCountService extends Service {

 private SensorManager mSensorManager;
 private StepCounter mStepCounter;

 public StepCountService() {
 }

 @Override
 public int onStartCommand(Intent intent, int flags, int startId) {
 mSensorManager = (SensorManager) getSystemService(Context.SENSOR_SERVICE);
 mStepCounter = new StepCounter(mSensorManager);
 return START_STICKY;
 }

 @Override
 public void onDestroy() {
 mStepCounter.stop();
 super.onDestroy();
 }

 private class StepCounter {
 private Sensor mStepCounterSensor;

 StepCounter(SensorManager sensorManager) {
 mStepCounterSensor = sensorManager.getDefaultSensor(Sensor.TYPE_STEP_COUNTER);
 sensorManager.registerListener(mSensorEventListener, mStepCounterSensor, SensorManager.SENSOR_DELAY_NORMAL);
 }

 void stop() {
 mSensorManager.unregisterListener(mSensorEventListener);
 }

 private SensorEventListener mSensorEventListener = new SensorEventListener() {
 @Override
 public void onSensorChanged(SensorEvent event) {
 // Track the value of the counter
 int steps = (int)event.values[0];
 // Log the change
 Log.d("StepCount", "step count changed to " + steps);
 // Send a notification
 createNotification(steps);
 }

 @Override
 public void onAccuracyChanged(Sensor sensor, int accuracy) {
 // Do nothing
 }
 };

 private void createNotification(int steps) {
 // Create a notification
 NotificationCompat.Builder builder = new NotificationCompat.Builder(StepCountService.this, "default")
 .setContentTitle("Step Count Update")
 .setContentText("You have taken " + steps + " steps.")
 .setSmallIcon(R.drawable.ic_steps);

 // Show the notification
 NotificationManager notificationManager = (NotificationManager) getSystemService(Context.NOTIFICATION_SERVICE);
 notificationManager.notify(0, builder.build());
 }
 }
}

