public class PiCalc {

    public static void main(String[] args) {
        final double EPSILON = 0.00001;
        double pi = 0;
        double term = 1.0;
        int n = 0;

        while (Math.abs(Math.PI - pi * 4.0) > EPSILON) {
            pi += 4 * (term *= -1.0 / (2 * n + 1));
            n++;
        }
        System.out.println("Calculated PI Value: " + String.format("%.5f", pi));
        System.out.println("Actual PI Value: " + String.format("%.2f", Math.PI));
    }
}

