int isFibonacci(int n) 
{ 
    int a = 0, b = 1, c; 
    if (n == a || n == b) 
        return 1; 
    c = a + b; 
    while (c < n) 
    { 
        a = b; 
        b = c; 
        c = a + b; 
    } 
    if (c == n) 
        return 1; 
    else
        return 0; 
} 

int main(void) 
{ 
    int n; 
    scanf("%d", &n); 
    if(isFibonacci(n))
        printf("Yes\n");
    else
        printf("No\n");
    return 0;
}

def min_ops(start, target):
    ops = 0

    while start != target:
        if start > target:
            start = start - 1
            ops += 1
        else: 
            start = start * 2
            ops += 1

    return ops

