def second_largest(nums):
    largest = max(nums[0], nums[1])
    s_largest = min(nums[0], nums[1])

    for i in range(2, len(nums)):
        if nums[i] > largest:
            s_largest = largest
            largest = nums[i]
        elif nums[i] > s_largest and nums[i] < largest:
            s_largest = nums[i]
    return s_largest

