def intersection_length(arr1, arr2):
    i = 0
    j = 0
    count = 0
    while (i < len(arr1) and j < len(arr2)):
        if (arr1[i] == arr2[j]):
            count += 1
            i += 1
            j += 1
        elif (arr1[i] < arr2[j]):
            i += 1
        elif (arr1[i] > arr2[j]):
            j += 1
    return count

