let fib = (n, cache = []) => {
  // if the nth number is already calculate
  // then just return it
  if (cache[n] !== undefined) return cache[n];
  // If n less than or equal 1 then return n
  if (n <= 1) return n;
  // otherwise, cache the result and return it
  return cache[n] = fib(n - 1, cache) + fib(n - 2, cache);
};

