// Generate a board grid
function generateBoard() {
 board.innerHTML = '';

 for (let row = 0; row < numRows; row++) {
 // Create a row div
 const rowDiv = document.createElement('div');
 // Create a grid cell for each element in the row
 for (let col = 0; col < numCols; col++) {
 // Create a grid cell div
 const cellDiv = document.createElement('div');
 // Set the class attribute to "cell"
 cellDiv.setAttribute('class', 'cell');
 // Set the id attribute to the row and column
 cellDiv.setAttribute('id', `${row}-${col}`);

 // Set a click handler for the cell div
 cellDiv.addEventListener('click', handleCellClick);

 // Append the cell div to the row div
 rowDiv.appendChild(cellDiv);
 }

 // Append the row div to the board
 board.appendChild(rowDiv);
 }
}

// Place a marker on the board
function handleCellClick(e) {
 // Get the row and column from the id
 const cellIdSplit = e.target.id.split('-');
 const row = cellIdSplit[0];
 const col = cellIdSplit[1];

 // Place a marker
 boardState[row][col] = 'X';

 // Update the board
 updateBoard();
}

// Update the board
function updateBoard() {
 for (let row = 0; row < numRows; row++) {
 for (let col = 0; col < numCols; col++) {
 const cellDiv = document.querySelector(`#${row}-${col}`);

 // If there is a marker, add a class of "marked"
 if (boardState[row][col] === 'X') {
 cellDiv.classList.add('marked');
 } else {
 cellDiv.classList.remove('marked');
 }
 }
 }
}

// Reset the board
resetBtn.addEventListener('click', () => {
 boardState = [];
 for (let row = 0; row < numRows; row++) {
 boardState.push([]);
 for (let col = 0; col < numCols; col++) {
 // Initialize the boardState with empty strings
 boardState[row].push('');
 }
 }

 updateBoard();
});

