def max_subseq_sum(arr):
    max_so_far = 0
    max_ending_here = 0
    for n in arr:
        max_ending_here = max_ending_here + n
        if max_so_far < max_ending_here:
            max_so_far = max_ending_here
        if max_ending_here < 0:
