def knapsack(items_weight, items_profit, bag_capacity):
    items_length = len(items_weight)
    table = [[0 for x in range(bag_capacity + 1)] for x in range(items_length + 1)]

    for i in range(items_length + 1):
        for w in range(bag_capacity + 1):
            if i == 0 or w == 0:
                table[i][w] = 0
            elif items_weight[i - 1] <= w:
                table[i][w] = max(items_profit[i - 1] 
                          + table[i - 1][w - items_weight[i - 1]], 
                          table[i - 1][w])
            else:
                table[i][w] = table[i - 1][w]

    return table[items_length][bag_capacity]

