function getDupCount(arr) {
    const countMap = new Map();

    arr.forEach(item => {
      const currentCount = countMap.get(item) || 0;
      countMap.set(item, currentCount + 1);
    });

    let duplicates = 0;
    Array.from(countMap.entries()).forEach(([key, value]) => {
      if (value > 1) {
        duplicates += value - 1;
      }
    });

    return duplicates;
  }

