def solve_sudoku(grid):
    empty_cells = find_empty_cells(grid)

    if not empty_cells:
        return True

    cell = empty_cells[0]
    row, col = cell

    for number in range(1, 10):
        if is_valid(grid, number, (row, col)):
            grid[row][col] = number

            if solve_sudoku(grid):
                return True

            grid[row][col] = 0

    return False

def is_valid(grid, number, cell):
    row, col = cell

    for i in range(9):
        if grid[row][i] == number:
            return False

    for i in range(9):
        if grid[i][col] == number:
            return False

    x_box = col // 3
    y_box = row // 3

    for i in range(y_box * 3, y_box * 3 + 3):
        for j in range(x_box * 3, x_box * 3 + 3):
            if grid[i][j] == number:
                return False

    return True

def find_empty_cells(grid):
    empty_cells = []
    for i in range(9):
        for j in range(9):
            if grid[i][j] == 0:
                empty_cells.append((i, j))

    return empty_cells

