public static boolean isPalindrome(String str) {
    int len = str.length();

    /* The only strings of length 1 or 0 are palindromes */
    if(len <= 1)
        return true;

    /* Iterate through the string and compare the first and
     * last character. If they don't match, the string isn't
     * a palindrome */
    for(int i = 0; i < len/2; i++) {
        if(str.charAt(i) != str.charAt(len - 1 - i))
            return false;
    }

    /* If we finished looping over the string without
     *  returning false, the string must be a palindrome */
    return true;
}

