sub validate_credit_card_number {
    my $input = shift;

    # Strip the spaces and hyphens
    $input =~ s/\\s+//g;
    $input =~ s/-//g;

    # Compute the checksum
    my @list = split(//, $input);
    my $sum = 0;
    my $i;
    for($i=0; $i <= $#list; $i++) {
        my $num = $list[$i];
        if(($i % 2) == 0) {
            $num = ($num * 2);
            if($num > 9) {
                $num -= 9;
            }
        }
        $sum += $num;
    }

    # Return true if checksum is a multiple of 10
    if( ($sum % 10) == 0) {
        return 1;
    }
    else {
        return 0;
    }
}

