def mostEdgesVertex(G, V, E):
    # create an empty dictionary
    d = {}
    for v in V:
        d[v] = 0

    # loop through edges and store v, e pair in dict
    for e in E:
        (v1, v2) = e
        d[v1] += 1
        d[v2] += 1

    # find max value in dict
    maxValue = -1
    maxVertex = "none"

    for v in V:
        if maxValue < d[v]:
            maxValue = d[v]
            maxVertex = v

    # return vertex with max edges
    return maxVertex

