// Convert a given Binary Search Tree to Sorted Linked List 
// root --> Pointer to root Node of the BST 
// head --> Pointer to head node of created linked list 
void BSTToSortedLL(Node *root, Node **head) 
{ 
    // Base Case 
    if (root == NULL) 
        return; 

    // Recursively convert right subtree 
    BSTToSortedLL(root->right, head); 

    // Insert root into linked list 
    root->right = *head; 

    // Change left pointer of previous head 
    // to point to NULL 
    if (*head != NULL) 
        (*head)->left = NULL; 

    // Change head of Linked List 
    *head = root; 

    // Recursively convert left subtree 
    BSTToSortedLL(root->left, head); 
}

