//We will use the QuickSelect algorithm

public static int QuickSelect(int[] arr, int k) 
{ 
 int l = 0, h = arr.length - 1; 

 // divide the array 
 int p = partition(arr, l, h); 

 // if the partition's index == k ==> return arr[p] 
 if (p == k) 
  return arr[p]; 

 // if p > k ==> search the left side 
 else if (p > k) 
  return QuickSelect(arr, l, p - 1, k); 

 // else ==> search the right side 
 else
  return QuickSelect(arr, p + 1, h, k); 
} 

private static int partition(int[] arr, int l, int h) 
{ 
 int pivot = arr[h]; 
 int i = l - 1; 

 for (int j = l; j <= h - 1; j++) 
 { 
  if (arr[j] <= pivot) 
  { 
   i ++; 
   int temp = arr[i]; 
   arr[i] = arr[j]; 
   arr[j] = temp; 
  } 
 } 

 int temp = arr[i + 1]; 
 arr[i + 1] = arr[h]; 
 arr[h] = temp; 

 return i + 1; 
}

