func findMode(nums: [Int]) -> Int {
	var modeCount = 0
	var mode = 0

	for i in 0..<nums.count {
		var currentCount = 0

		for num in nums {
			if (num == nums[i]) {
				currentCount += 1
			}
			if (currentCount >= modeCount) {
				modeCount = currentCount
				mode = nums[i]
			}
		}
	}
	return mode
}

