def solve_knight_tour(size):
    board = [[0 for i in range(size)] for j in range(size)]

    r = 0
   c = 0
    move = 0

    while True:
        board[r][c] = move
        move += 1

        if move == size**2:
            break

        if can_move_knight(r, c, board):
            r, c = move_knight(r, c, board)
        else:
            break

    return board

def can_move_knight(r, c, board):
    directions = [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]

    for dy, dx in directions:
        if 0 <= r + dy < len(board) and 0 <= c + dx < len(board) and board[r + dy][c + dx] == 0:
            return True

    return False

def move_knight(r, c, board):
    directions = [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]

    for dy, dx in directions:
        if 0 <= r + dy < len(board) and 0 <= c + dx < len(board) and board[r + dy][c + dx] == 0:
            return r + dy, c + dx

function searchBooks(books, query) {
 //create a list of books that match the query
 let matches = [];
 //iterate through the books
 for (let book of books) {
  //compare the book title to the query
  if (book.title.includes(query)) {
   //add the book to the matches array
   matches.push(book);
  }
 }
 //sort the matches array by relevance
 matches.sort((a, b) => {
  //compare the number of matches
  let aMatches = (a.title.match(new RegExp(query, 'gi')) || []).length;
  let bMatches = (b.title.match(new RegExp(query, 'gi')) || []).length;
  //return the result of the comparison
  return bMatches - aMatches;
 });
 //return the top 5 matches
 return matches.slice(0, 5);
}

