function findPalindromes(inputString) {

    let palindromes = [];

    for (i = 0; i < inputString.length; i++) { 

        let palindrome = ''; 

        //check for the Odd length palindrome  
        for (let j = i - 1, k = i + 1; j >= 0 && k < inputString.length; j--, k++) { 
            if (inputString[j] != inputString[k]) 
                break; 
            palindrome = inputString.substring(j, k + 1); 
        } 
        if (palindrome.length != 0) 
            palindromes.push(palindrome); 

        //check for the Even length palindrome 
        palindrome = ''; 
        for (let j = i, k = i + 1; j >= 0 && k < inputString.length; j--, k++) { 
            if (inputString[j] != inputString[k]) 
                break; 
            palindrome = inputString.substring(j, k + 1); 
        } 
        if (palindrome.length != 0) 
            palindromes.push(palindrome); 
    } 

    return palindromes; 
} 

