using namespace std; 

// Node which will represent each data 
struct Node { 
    int data; 
    Node* left; 
    Node* right; 
}; 

// function to create a new Node 
Node* root =NULL; 
Node* getNewNode(int data) { 
    Node* node =new Node(); 
    node->data =data; 
    node->left =NULL; 
    node->right =NULL; 
    return node; 
} 

// function to classify the given data based on its value 
void classification( vector<int> list, int min, int max, Node* root) { 
    if( root == NULL) { 
        root = getNewNode( (min + max) / 2); 
    } 
    // iterate over the list 
    for( int i = 0; i < list.size(); i++) { 
        if( list[i] <= root->data) { 

            if(root->left == NULL) { 
                root->left =getNewNode( (min + root->data)/2); 
            } 
            // recursive call 
            classification( list, min, root->data, root->left); 

        } else if ( list[i] > root->data) { 

            if(root->right == NULL) { 
                root->right = getNewNode( (root->data + max)/2); 
            } 
            // recursive call 
            classification(list, root->data, max, root->right); 
        } 
    } 
} 

int main() { 
    // Given data set 
    vector<int> list = { 5, 6, 7, 8, 9, 10}; 
    int min = 5, max = 10; 
    // Call of classification() 
    classification( list, min, max, root); 
    return 0; 
}

