def longestIncreasingSubsequence(arr):
    lis = [1] * len(arr)

    for i in range(1, len(arr)):
        for j in range(0, i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    maxLis = 0

    for i in range(len(arr)):
        maxLis = max(maxLis, lis[i])

    return maxLis

