def computeEditDistance(str1, str2): 
    LengthStr1 = len(str1) 
    LengthStr2 = len(str2)

    D = [[0 for x in range(LengthStr2+1)] for x in range(LengthStr1+1)]

    for i in range(LengthStr1+1): 
        for j in range(LengthStr2+1): 
            if i == 0: 
                D[i][j] = j
            elif j == 0: 
                D[i][j] = i
            elif str1[i-1] == str2[j-1]: 
                D[i][j] = D[i-1][j-1] 
            else: 
                D[i][j] = 1 + min(D[i][j-1], D[i-1][j], D[i-1][j-1]) 

    return D[LengthStr1][LengthStr2] 

