// Node in a linked list 
struct Node 
{ 
    int x; 
    struct Node *next; 
}; 

// Function to reverse the linked list 
void reverse(struct Node** head_ref) 
{ 
    struct Node* prev   = NULL; 
    struct Node* current = *head_ref; 
    struct Node* next; 
    while (current != NULL) 
    { 
        next  = current->next; 
        current->next = prev; 
        prev = current; 
        current = next; 
    } 
