# Solve the sudoku assuming input is valid

def solve_sudoku(grid):
    n = len(grid)
    find = False
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                find = True
                break
        if find:
            break
    if not find:
        return True
    for data in range(1, n+1):
        # Check rows and columns
        is_valid = True
        for k in range(n):
            if grid[i][k] == data or grid[k][j] == data:
                is_valid = False
                break
        if is_valid:
            box_x = (i//3) * 3
            box_y = (j//3) * 3

            # Check box
            for l in range(3):
                for m in range(3):
                    if grid[box_x+l][box_y+m] == data:
                        is_valid = False
                        break
            if is_valid:
                grid[i][j] = data
                if solve_sudoku(grid):
                    return True
                grid[i][j] = 0
    return False

