import random

# Function to simulate one game
def one_game():
    # Generate random numbers to represent moves
    player1_move = random.randint(1, 3)
    player2_move = random.randint(1, 3)

    # Return 1 if player1 wins, 0 if player2 wins
    if player1_move == player2_move:
        return 0
    elif (player1_move == 1 and player2_move == 2) or (player1_move == 2 and player2_move == 3) or (player1_move == 3 and player2_move == 1):
        return 0 
    else:
        return 1

def monte_carlo(num_sims):
    wins = 0
    for _ in range(num_sims):
        wins += one_game()

    return wins/num_sims

