/*
 * Plagiarism Detector Algorithm
 * 
 * This algorithm identifies phrases and words in a given input document that are similar to the words and phrases present in other documents.
 */

// First, we convert the input document into an array of words
function stringToArray(input) {
  // trim whitespaces
  input = input.trim();

  // split into words and convert into array
  let arr = input.split(" ");

  // remove unnecessary characters
  let clean_arr = [];
  for (let word of arr) {
    word = word.replace(/[\W_]/g, "");
    clean_arr.push(word);
  }
  return clean_arr;
}

// Next, we will compare each word of the input document to words from other documents
// We will count the number of matched words between both documents and return a percentage
// If the percentage is above a preset threshold, we can conclude that the input document is a plagiarized document

function plagiarismDetector(input_words, other_documents) {
  // First, we create a dictionary of the words in input document
  let input_words_dict = {};
  for (let word of input_words) {
    input_words_dict[word] = (input_words_dict[word] || 0) + 1;
  }

  // Initialize variable for counting matched words
  let matched_words_count = 0;

  // For each of the other documents, we compare the words against those in input document
  for (let other_document of other_documents) {

    // Create a dictionary of words in other document
    let other_document_words_dict = {};
    for (let word of other_document) {
      other_document_words_dict[word] = (other_document_words_dict[word] || 0) + 1;
    }

    // Compare the words in both documents
    for (let word in input_words_dict) {
      // If the word is in both documents, increment the match count
      if (word in other_document_words_dict) {
        matched_words_count += 1;
      }
    }
  }

  // Calculate the percentage of words that are matched
  let matched_words_percentage = (matched_words_count / input_words.length) * 100;

  // Check if the percentage is over the preset threshold value
  // If so, return true (document is a plagiarism)
  if (matched_words_percentage > 50) {
    return true;
  } else {
    return false;
  }

}

