def multiply(x, y):
    result = 0
    if x >= 0 and y >= 0:
        for i in range(y):
            if result > (2**64)-1:
                raise OverflowError("Multiplication result is too large")
            result += x
    elif x < 0 and y < 0:
        for i in range(-y):
            if result < -2**64:
                raise OverflowError("Multiplication result is too small")
            result += x
    elif (x < 0 and y > 0) or (x > 0 and y < 0):
        result = -multiply(abs(x), abs(y))

    return result

