// Optimized bubble sort
// Time complexity: O(n)
// Space complexity: O(1)

def bubble_sort(arr: List[int]) -> List[int]:
 n = len(arr)
 for i in range(n):
 swapped = False
 for j in range(n - i - 1):
 if arr[j] > arr[j + 1]:
 arr[j], arr[j + 1] = arr[j + 1], arr[j]
 swapped = True
 if swapped == False:
 break
 return arr

