function binarySearch(arr, target) {
 // set initial indices
 let start = 0,
  end = arr.length - 1;

 // loop until target is found
 while (start <= end) {
  // calculate midpoint
  let mid = Math.floor((start + end) / 2);

  // check if midpoint is target
  if (arr[mid] === target) {
   return mid;
  } else if (arr[mid] < target) {
   // target is greater, search upper part of the array
   start = mid + 1;
  } else {
   // target is smaller, search lower part of the array
   end = mid - 1;
  }
 }

 // target was not found
 return -1;
}

