def predictScore(genre, popularity):
  # initial score is 0
  score = 0
  # determine base score based on popularity
  if popularity >= 5:
    score += 5
  elif popularity >= 3:
    score += 3
  elif popularity >= 1:
    score += 1

  # adjust score based on genre
  if genre == "Action" || genre == "Adventure":
    score += 3
  elif genre == "Comedy" || genre == "Romance":
