def findPrimesInRange(start, end):
    '''This function takes two integers (start and end) as parameters and returns a list of all the prime numbers between the two inputs'''

    primes = []
    for num in range(start, end+1):
        # Numbers that are divisible by any number other than itself or 1 are composite
        if num > 1:
            for i in range(2, num):
                if (num % i) == 0:
                    break
            else:
                primes.append(num)
    return primes

