def euclidean_distance(point1, point2):
	sum_squared_distance = 0
	for i in range(len(point1)): 
		sum_squared_distance += (point1[i] - point2[i])**2
	return sqrt(sum_squared_distance)

def knn_classifier(training_set, training_labels, new_example, k):
	distances = [] # List to store the distances from the new point to the each of training points
	for index in range(len(training_set)):
		distance = euclidean_distance(training_set[index], new_example) 
		distances.append([distance, index])
	distances.sort() # Sort the distances list
	neighbors = [] 

	# Pick the first K entries from the sorted distances list
	for i in range(k):
		index = distances[i][1]
		neighbors.append(training_labels[index])
	return max(set(neighbors), key=neighbors.count)

