void sort2DArray(int array[][3], int rowSize, int colSize) {

    // bubble sort each row
    for (int row = 0; row < rowSize; row++) {
        for (int col = 0; col < colSize; col++) {
            for (int prevCol = 0; prevCol < col; prevCol++) {
                if (array[row][col] < array[row][prevCol]) {
                    int temp = array[row][col];
                    array[row][col] = array[row][prevCol];
                    array[row][prevCol] = temp;
                }
            }
        }
    }
}

