function roadTrip(numStops, distance, distBetweenStops, pricePerGal, mpg, money) {
 let gasNeeded = 0;
 let moneyLeft = money;

 for (let i = 0; i < numStops; i++) {
  let remainingDistance = distance - (i * distBetweenStops);
  let gallonsNeeded = (remainingDistance / mpg).toFixed(2);
  let totalCost = gallonsNeeded * pricePerGal;

  if (moneyLeft >= totalCost) {
   // Enough money for this fill-up
   moneyLeft -= totalCost;
   gasNeeded += gallonsNeeded;
  } else {
   // Not enough money for this fill-up.
   // Calculate how much more gas is remaining.
   let remGas = (moneyLeft / pricePerGal).toFixed(2);
   gasNeeded += remGas;
   moneyLeft = 0;
   break;
  }
 }

 return {
  "gas_needed": gasNeeded,
  "money_left": moneyLeft
 };
}

