def depth_first_search(graph, root):
    """
    This function will implement the depth first search algorithm.
    """
    visited = set([root])
    stack = [root]
    while stack:
        v = stack.pop()
        for w in graph[v]:
            if w not in visited:
                visited.add(w)
                stack.append(w)
    return visited

