public class FibonacciChecker {

    public static boolean isFibonacciNumber(int n) {
        if (n == 0 || n == 1)
            return true;

        int sum = 0, first = 0, second = 1;
        while (n > sum) {
            sum = first + second;
            first = second;
            second = sum;
        }
        return sum == n;
    }

    public static void main(String[] args) {
        System.out.println("Is 6 a Fibonacci number: " + isFibonacciNumber(6));
        System.out.println("Is 15 a Fibonacci number: " + isFibonacciNumber(15));
