def fill_missing_data(arr):
    for i in range(len(arr)):
        if arr[i] == None:
            if i == 0:
                arr[i] = arr[i+1]
            elif i == len(arr)-1:
                arr[i] = arr[i-1]
            else:
                arr[i] = (arr[i-1] + arr[i+1])/2
    return arr

