using namespace std; 

int* Merge(int arr1[], int arr2[], int m, int n) 
{ 
    int size = m+n; 
    int *mergedArr = new int[size]; 

    int i = 0, j = 0, k = 0; 

    while (i < m && j < n) { 
        if (arr1[i] < arr2[j]) 
            mergedArr[k++] = arr1[i++]; 
        else
            mergedArr[k++] = arr2[j++]; 
    } 
    while (i < m) 
        mergedArr[k++] = arr1[i++]; 
    while (j < n) 
        mergedArr[k++] = arr2[j++]; 

    return mergedArr; 
} 

