def first_positive_integer(arr):
    """This function finds the first missing positive integer in an array."""
    # Create a hashset to store the numbers that have been seen in the array
    seen = set()
    for num in arr:
        seen.add(num)

    # Iterate through the array and find the first missing positive integer
    for i in range(1, len(arr)+1):
        if i not in seen:
            return i

