func findCommonElements(array1: [Int], array2: [Int]) -> [Int] {
    var result = [Int]()
    var i = 0
    var j = 0

    while (i < array1.count && j < array2.count) {
        if array1[i] == array2[j] {
            result.append(array1[i])
            i += 1
            j += 1
        } else {
            if array1[i] < array2[j] {
                i += 1
            } else {
                j += 1
            }
        }
    }

    return result
}

