  Thread[] threads = new Thread[10];
  for (int i = 0; i < 10; i++) {
   threads[i] = new Thread(() -> {
    for (int j = 100; j > 0; j -= 10) {
     for (int k = j; k > j - 10; k--) {
      System.out.printf("%d ", k);
     }
    }
   });
  }
  for (Thread t : threads) {
