def pascal_row_sum(n):
  if n == 0:
    return 1

  prev_row = pascal_row_sum(n - 1)
  curr_row = [1]

  for i in range(len(prev_row) - 1):
    curr_row.append(prev_row[i] + prev_row[i+1])

  curr_row.append(1)
  return sum(curr_row)

