import java.util.HashMap;
import java.util.Map;

public class MostFrequentWords {

    public static void main(String[] args) {
        String sentence = "This is an sample sentence";

        // Split the sentence into words
        String[] words = sentence.split(" ");

        // Calculate the frequency of the words
        Map<String, Integer> frequency = new HashMap<>();
        for (String word : words) {
            if (frequency.containsKey(word)) {
                frequency.put(word, frequency.get(word) + 1);
            } else {
                frequency.put(word, 1);
            }
        }

        //Find the most frequent words
        int maxFrequency = 0;
        String mostFrequentWord = "";
        for (String key : frequency.keySet()) {
            if (frequency.get(key) > maxFrequency) {
                maxFrequency = frequency.get(key);
                mostFrequentWord = key;
            }
        }
        System.out.println("Most frequent word is \"" + mostFrequentWord + "\" with frequency of " + maxFrequency);
    }

}

