public static int largestPalindromeProduct() {
    int i, j, max = 0;
    for (i = 999; i >= 100; i--) {
        for (j = 999; j >= 100; j--) {
            int prod = i * j;
            if (prod > max && isPalindrome(prod)) {
                max = prod;
            }
        }
    }
    return max;
}

public static boolean isPalindrome(int prod) {
    String s = String.valueOf(prod);
    int n = s.length();
    for (int i = 0; i < n / 2; i++) {
        if (s.charAt(i) != s.charAt(n - i - 1)) {
            return false;
        }
    }
    return true;
}

