function subarraysWithSum(arr, sum) {
 let result = [];
 let sum_so_far = 0;
 let startIndex = 0;

 for(let i = 0; i < arr.length; i++) {
  sum_so_far += arr[i];

  //condition to check if sum so far equals to sum
  if (sum_so_far == sum) {
   let subarr = arr.slice(startIndex, i + 1);
   result.push(subarr);
  }

  //condition to check if sum so far is greater than sum 
  while(sum_so_far > sum && startIndex < i) {
   sum_so_far -= arr[startIndex];
   startIndex++;
   if (sum_so_far == sum) {
    let subarr = arr.slice(startIndex, i + 1);
    result.push(subarr);
   }
  }
 }
 return result;
}

