public static String removeDuplicates(String s) {
	Set<Character> set = new HashSet<>();
	StringBuilder sb = new StringBuilder();

	for (int i = 0; i < s.length(); i++) {
		Character c = s.charAt(i);
		if (!set.contains(c)) {
			sb.append(c);
			set.add(c);
		}
	}

	return sb.toString();
}

