// A Linked List node
struct Node
{
    int data;
    Node *next;
};

// Merge two sorted linked list and return the head node
Node *merge(Node *list1, Node *list2)
{
    // Create a new node to store the result
    Node *result = NULL;

    if (list1 == NULL)
        return (list2);
    else if (list2 == NULL)
        return (list1);

    // Pick the smallest node from both the list
    if (list1->data < list2->data)
    {
        result = list1;
        result->next = merge(list1->next, list2);
    }
    else
    {
        result = list2;
        result->next = merge(list1, list2->next);
    }

    return (result);
}

