def find_most_frequent(arr):
    # stores a map of elements in the array to their respective count
    element_map = dict()

    # loop over all elements in the array
    for element in arr:
        # check if the element is in the map
        if element in element_map:
            # if yes, increment the count
            element_map[element] = element_map[element] + 1
        else:
            # if not, add the element to the map and set the count to 1
            element_map[element] = 1

    # initialize a max count
    max_count = 0

    # loop over all elements map to find the max count
    for element in element_map:
        current_count = element_map[element]
        if current_count > max_count:
            max_count = current_count

    # return the elements with the max count
    most_frequent = []
    for element in element_map:
        if element_map[element] == max_count:
            most_frequent.append(element)
    return most_frequent

