const findPaths = (matrix) => {

 // To store the number of rows
 const rows = matrix.length;

 // To store the number of columns
 const cols = matrix[0].length;

 // To store the distinct paths 
 let paths = [];

 // Helper function to find paths 
 const findPathsUtil = (curRow, curCol, curPath) => {

 // Reached the bottom right
 if (curRow === rows - 1 && curCol === cols - 1) {
 paths.push(curPath);
 return;
 }

 // Down move allowed
 if (curRow + 1 < rows && matrix[curRow + 1][curCol] === 0) {
 findPathsUtil(curRow + 1, curCol, [...curPath, [curRow + 1, curCol]]);
 }

 // Right move allowed
 if (curCol + 1 < cols && matrix[curRow][curCol + 1] === 0) {
 findPathsUtil(curRow, curCol + 1, [...curPath, [curRow, curCol + 1]]);
 }
 };

 // Initialize path to empty array 
 let curPath = [];

 // Find the paths starting from top left 
 findPathsUtil(0, 0, curPath);

 // Return all the paths
 return paths;
};

