 public static void main(String [] args) {
  // Set the number of disks
  int numDisks = 3;

  // Call the moveTower method
  moveTower(numDisks, 'A', 'B', 'C');
 }

 public static void moveTower(int n, char from,
 char with, char to) {
  // If there is only one disk, move it from the
  // source tower to the destination tower
  if (n == 1) {
   System.out.println("Move Disk 1 from " + from +
   " to " + to);
   return;
  }

  // Move n-1 disks from the source tower to the 
  // intermediate tower
  moveTower(n-1, from, to, with);

  // Move the remaining disk from the source tower
  // to the destination tower
  System.out.println("Move Disk " + n + " from " +
  from + " to " + to);

  // Move the n-1 disks from the intermediate tower
  // to the destination tower
  moveTower(n-1, with, from, to);
 }
}

