  public void add(T element) 
  { 
    Node<T> node = new Node<>(element); 
    node.next = head; 
    head = node; 
  } 

  // remove the first node of the list 
  public void removeFirst() 
  { 
    head = head.next; 
  } 

  // printing the Linked List 
  public void printList() 
  { 
    Node<T> temp = head; 
    while (temp != null) { 
      System.out.print(temp.data + " "); 
      temp = temp.next; 
    } 
