void printAlternatePrime(int min, int max) 
{
    // Declaring a Boolean Array "prime[0..MAX]" and 
    // initializing it by true. A value in prime[i]
    // will finally be false if i is Not a prime, else 
    // true.
    bool prime[max+1];
    for (int i=0; i<max; i++)
        prime[i] = true;

    for (int p=2; p*p<=max; p++)
    {
        // If prime[p] is not changed, then 
        // it is a prime
        if (prime[p] == true)
        {
            // Update all multiples of p
            for (int i=p*2; i<=max; i += p)
                prime[i] = false;
        }
    }

    for (int i=min; i<max; i++)
    {
        if (prime[i] == true)
            printf ("%d ", i);
    }
}

