// Create strategy pattern
const strategypattern = {
  // Create actions
  bubble: arr => {
    for(let i=arr.length; i >=0; i--){
      for(let j=0; j < i; j++){
        if(arr[j] > arr[j+1]){
          let temp = arr[j];
          arr[j] = arr[j+1];
          arr[j+1] = temp;
        }
      }
    }
    return arr;
  },
  // Create actions
  insertion: arr => {
    let temp;
    for(let i=1; i < arr.length; i++){
      let j = i;
      temp = arr[i];
      while(arr[j-1] >= temp && j > 0){
        arr[j] = arr[j-1];
        j--;
      }
      arr[j] = temp;
    }
    return arr;
  },
  selection: arr => {
    let minIdx;
    let temp;
    for(let i=0; i < arr.length; i++){
      minIdx = i;
      for(let j=i+1; j < arr.length; j++){
        if(arr[j] < arr[minIdx]){
          minIdx = j;
        }
      }
      temp = arr[minIdx];
      arr[minIdx] = arr[i];
      arr[i] = temp;
    }
    return arr;
  }

};

// Use the strategy pattern to call sorting algorithm
function selectSortingAlgorithm(algorithm, arr) {
  return strategypattern[algorithm](arr);
}

