using namespace std;

vector<int> medianFilter(const vector<int>& input) {
    vector<int> output;

    for (int i = 0; i < input.size(); i++) {
        vector<int> window;
        if (i == 0) {
            window.push_back(input[i]);
            window.push_back(input[i+1]);
        } else if (i == input.size() - 1) {
            window.push_back(input[i-1]);
            window.push_back(input[i]);
        } else {
            window.push_back(input[i-1]);
            window.push_back(input[i]);
            window.push_back(input[i+1]);
        }

        sort(window.begin(), window.end());
        int median = 0;
        if (window.size() % 2 == 0)
            median = window[1];
        else
            median = window[window.size() / 2];
        output.push_back(median);
    }

    return output;
}

int main() {
    vector<int> array = {1, 5, 2, 4, 5, 3, 3, 3, 5, 4};
    vector<int> output = medianFilter(array);
    for (auto &i : output)
        cout << i << " ";
    cout << endl;
    return 0;
}

