@WebServlet("/title")
public class TitleServlet extends HttpServlet {
 private static final String PAGE_TITLE_REGEX = "<title>\\s*(.*?)\\s*</title>";

 @Override
 protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
 String url = req.getParameter("url");
 if (url != null) {
 String title = getTitleFromUrl(url);
 if (title != null) {
 resp.setStatus(HttpServletResponse.SC_OK);
 resp.getWriter().println(title);
 } else {
 resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Could not fetch page title");
 }
 } else {
 resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "No url parameter");
 }
 }

 private String getTitleFromUrl(String url) throws IOException {
 URL urlObj = new URL(url);
 try (InputStream is = urlObj.openStream()) {
 StringBuffer buffer = new StringBuffer(512);
 byte[] data = new byte[512];
 int read;
 while ((read = is.read(data)) != -1) {
 buffer.append(new String(data, 0, read));
 }
 return getTitleFromSource(buffer.toString());
 }
 }

 private String getTitleFromSource(String source) {
 java.util.regex.Pattern pattern = java.util.regex.Pattern.compile(PAGE_TITLE_REGEX);
 java.util.regex.Matcher matcher = pattern.matcher(source);
 if (matcher.find()) {
 return matcher.group(1);
 }
 return null;
 }
}

