function longestPalindrome(str) { 
	let longest = '';
	let maxLength = 0;

	for (let i = 0; i < str.length; i++) {
		let oddLength = centerPalindrome(str, i, i);
		let evenLength = centerPalindrome(str, i, i + 1);
		let currentMax = Math.max(oddLength, evenLength);
		if (currentMax > maxLength) {
			maxLength = currentMax;
			longest = str.substr(i - Math.floor(currentMax / 2), currentMax);
		}
	}
	return longest;
}

function centerPalindrome(str, left, right) {
	let leftIndex = left;
	let rightIndex = right;
	while (leftIndex >= 0 && rightIndex < str.length && str[leftIndex] === str[rightIndex]) {
		leftIndex--;
		rightIndex++;
	}
	return rightIndex - leftIndex - 1;
}

