public class CountUniqueSubstrings {

    public static int countUniqueSubstrings(String s) {
        int[] lastOccurrence = new int[128];
        Arrays.fill(lastOccurrence, -1);

        int uniqueSubstringLength = 0;
        int start = 0;

        for (int end = 0; end < s.length(); end++) {
            char c = s.charAt(end);
            if (lastOccurrence[c] >= start) {
                start = lastOccurrence[c] + 1;
            }
            lastOccurrence[c] = end;
            uniqueSubstringLength += end - start + 1;
        }

        return uniqueSubstringLength;
    }

    public static void main(String[] args) {
        String s = "abc";
        System.out.println(countUniqueSubstrings(s));
    }
}

