// in an array 
public static int peakElement(int[] array) 
{ 
    // Initialize maximum and its index 
    int max  = array[0];  
    int index = 0;  

    // Loop throughout the array 
    for (int i = 0; i < array.length; i++)  
    { 
        // Update 'max' and 'index' if  
        // any element is greater than 'max' 
        if (array[i] > max)  
        { 
