TreeNode* createBinaryTree(int arr[], int start, int end){
    if(start > end){
        return nullptr;
    }
    int mid = (start+end)/2;
    TreeNode* root = new TreeNode(arr[mid]);
    root->left = createBinaryTree(arr, start, mid - 1);
    root->right = createBinaryTree(arr, mid + 1, end);
    return root;
}

