public class RabinKarp {

    public static int indexOf(String text, String pattern, int primeNumber) {
        int m = pattern.length();
        int n = text.length();
        int patternHash = 0;
        int textHash = 0;
        int h = 1;

        //Calculate hash value of pattern and first window of text
        for (int i = 0; i < m - 1; i++) {
            h = (h * 256) % primeNumber;
            patternHash = (256 * patternHash + pattern.charAt(i)) % primeNumber;
            textHash = (256 * textHash + text.charAt(i)) % primeNumber;
        }

        //Calculate hash value for last character of pattern
        patternHash = (patternHash + pattern.charAt(m - 1)) % primeNumber;

        //Move the window
        for (int i = 0; i <= n - m; i++) {
            // Check the hash values of current window of text and pattern 
            // If the hash values match then only check for characters on by one
            if (patternHash == textHash) {
                int j;
                //Check for characters one by one
                for (j = 0; j < m; j++) {
                    if (text.charAt(i + j) != pattern.charAt(j)) {
                        break;
                    }
                }
                if (j == m) // Pattern found
                    return i;
            }

            // Calculate hashing for the next window of text
            if (i < n - m) {
                textHash = (256 * (textHash - text.charAt(i) * h) + text.charAt(i + m)) % primeNumber;
                //If we get negative value of textHash, convert it to positive
                if (textHash < 0)
                    textHash = (textHash + primeNumber);
            }
        }
        return -1;
    }
}

