import java.util.*;

public class Main {
 public static void main(String[] args) {
 String s = "The quick brown fox jumps over the lazy dog";

 String[] words = s.split(" ");
 Map<String, Integer> map = new HashMap<>();

 for (String word : words) {
 if (!map.containsKey(word)) {
 map.put(word, 1);
 } else {
 map.put(word, map.get(word) + 1);
 }
 }

 // Sort the map in descending order
 Map<String, Integer> sortedMap = sortByValueDescending(map);

 System.out.println("The 3 most used words are:");
 int count = 0;
 for (Map.Entry<String, Integer> entry : sortedMap.entrySet()) {
 if (count == 3)
 break;

 System.out.println(entry.getKey());
 count++;
 }
 }

 public static Map<String, Integer> sortByValueDescending(Map<String, Integer> map) {
 List<Map.Entry<String, Integer>> list = new ArrayList<>(map.entrySet());

 // Sort the list in reverse order
 Collections.sort(list, (o1, o2) -> o2.getValue().compareTo(o1.getValue()));

 // Put data from sorted list to map
 Map<String, Integer> sortedMap = new LinkedHashMap<>();
 for (Map.Entry<String, Integer> entry : list) {
 sortedMap.put(entry.getKey(), entry.getValue());
 }

 return sortedMap;
 }
}

