const TablePagination = ({ data }) => {
  const [ filteredData, setFilteredData ] = React.useState(data);
  const [ page, setPage ] = React.useState(1);
  const [ rowsPerPage, setRowsPerPage ] = React.useState(5);
  const rowsPerPageOptions = [5, 10, 25];

  // sorting column
  const handleSort = (clickedColumn) => {
    const sortOrder = (filteredData[0][clickedColumn] > filteredData[filteredData.length -1][clickedColumn]) ? MOST : LEAST
    const sortedData = [...filteredData].sort((a, b) => {
        let val1 = a[clickedColumn]
        let val2 = b[clickedColumn]
        return sortOrder === MOST ? (val1 < val2 ? 1 : -1): (val1 > val2 ? 1 : -1)
    });
    setFilteredData(sortedData);
  }

  return (
    <div>
      <table>
        <thead>
          <tr>
            {columns.map(column => (
              <th key={column.key} onClick={() => handleSort(column.key)} >
                {column.name}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {filteredData
            .slice(page * rowsPerPage - rowsPerPage, page * rowsPerPage)
            .map((row) => (
              <tr key={row.id}>
                {columns.map((column) => (
                  <td key={`${row.id}.${column.key}`}>{row[column.key]}</td>
                ))}
              </tr>
            ))}
        </tbody>
      </table>
      <div>
        <div>
          { rowsPerPageOptions.map((value) => (
            <label key={`rowsPerPage${value}`}>
              <input
                type="radio"
                value={value}
                checked={value === rowsPerPage}
                onChange={(e) => setRowsPerPage(parseInt(e.target.value, 10))}
