         )) }
       </div>
     </div>
     <div>
       <button type="button" onClick={() => setPage(page - 1)}>Previous</button>
       {page}
       <button type="button" onClick={() => setPage(page + 1)}>next</button>
     </div>
   </div>
  );
};

export default TablePagination;

