int simpsons_diversity_index(vector<int> population) { 
    int total_population = accumulate(population.begin(), population.end(), 0); 
    int diversity_index = 0; 

    for (int i : population) { 
        float prop = (float)i / total_population; 
        diversity_index = diversity_index + (prop * prop); 
    } 

    return 1 - diversity_index; 
} 

