def longest_common_substring(str1, str2):
    # if one of the strings is empty, return empty string
    if len(str1) == 0 or len(str2) == 0:
        return ""
    # generate a 2D matrix 
    M = [[0 for _ in range(len(str2) + 1)] for _ in range(len(str1) + 1)]
    # fill the matrix 
    for i in range(1 , len(str1) + 1):
        for j in range(1 , len(str2) + 1):
            if str1[i-1] == str2[j-1]:
                M[i][j] = 1 + M[i-1][j-1]
            else:
                M[i][j] = 0
    # get the longest common substring and its length
    longest_substring, max_length = "", 0 
    for i in range(0 , len(str1) + 1): 
        for j in range(0 , len(str2) + 1): 
            if M[i][j] > max_length: 
                max_length = M[i][j] 
                longest_substring = str1[i-max_length: i] 
    return longest_substring

