import java.util.HashMap;
import java.util.Map;

public class FrequentWordFinder {

    public static void main(String[] args) {
        // Enter the string to scan
        String inString = "This is a sample string with some words that appear multiple times.";

        // Count the occurences of each word
        HashMap<String, Integer> wordMap = countOccurences(inString);

        // Get the most frequent word
        String mostFreqWord = getMostFrequentWord(wordMap);

        // Print the result
        System.out.println("Most frequent word : " + mostFreqWord);
    }

    public static HashMap<String, Integer> countOccurences(String inString){
        // Split the input string into words
        String[] words = inString.split("\\s+");

        // Count the occurences
        HashMap<String, Integer> wordMap = new HashMap<>();
        for(int i=0; i<words.length; i++) {
            String key = words[i].toLowerCase();
            Integer count = wordMap.get(key);
            if (count == null) {
                wordMap.put(key, 1);
            } else {
                wordMap.put(key, count + 1);
            }
        }
        return wordMap;
    }

    public static String getMostFrequentWord(HashMap<String, Integer> wordMap) {
        // Get the most frequent word;
        Integer maxCount = 0;
        String maxWord = null;
        for (Map.Entry<String, Integer> entry : wordMap.entrySet()) {
            if (entry.getValue() > maxCount) {
                maxWord = entry.getKey();
                maxCount = entry.getValue();
            }
        }
        return maxWord;
    }

}

