//Function to multiply two matrices using Strassen's Algorithm

function strassen(A, B) {
   //base case
   if (A.length <= 1) {
      return A[0][0] * B[0][0];
   }

   // initializing the new sub-matrices  
   const a11 = []; 
   const a12 = []; 
   const a21 = []; 
   const a22 = []; 

   const b11 = []; 
   const b12 = []; 
   const b21 = []; 
   const b22 = []; 

   // Dividing matrices A and B into sub-matrices 
   const n = A.length; 
   for (let i = 0; i < n / 2; i++) { 
      for (let j = 0; j < n / 2; j++) { 
         a11[i][j] = A[i][j]; 
         a12[i][j] = A[i][j + n / 2]; 
         a21[i][j] = A[i + n / 2][j]; 
         a22[i][j] = A[i + n / 2][j + n / 2]; 

         b11[i][j] = B[i][j]; 
         b12[i][j] = B[i][j + n / 2]; 
         b21[i][j] = B[i + n / 2][j]; 
         b22[i][j] = B[i + n / 2][j + n / 2]; 
      } 
   } 

   // Calculating P1 to P7
   const P1 = strassen(a11, subtract(b12, b22)); 
   const P2 = strassen(add(a11, a12), b22); 
   const P3 = strassen(add(a21, a22), b11); 
   const P4 = strassen(a22, subtract(b21, b11)); 
   const P5 = strassen(add(a11, a22), add(b11, b22)); 
   const P6 = strassen(subtract(a12, a22), add(b21, b22)); 
   const P7 = strassen(subtract(a11, a21), add(b11, b12)); 

   // Calculating c11, c12, c21, and c22
   const c11 = subtract(add(add(P5, P4), P6), P2); 
   const c12 = add(P1, P2); 
   const c21 = add(P3, P4); 
   const c22 = subtract(subtract(add(P5, P1), P3), P7); 

   // creating the result matrix C
   let C = []; 
   for (let i = 0; i < n / 2; i++) { 
      for (let j = 0; j < n / 2; j++) { 
         C[i][j] = c11[i][j]; 
         C[i][j + n / 2] = c12[i][j]; 
         C[i + n / 2][j] = c21[i][j]; 
         C[i + n / 2][j + n / 2] = c22[i][j]; 
      } 
   } 
   return C; 
}

