function evaluatePostfix(expression) {
 // Create a stack to store operands.
 const stack = [];

 // Split the expression into individual tokens.
 const tokens = expression.split(' ');

 // Loop through the tokens in the expression.
 for (let i = 0; i < tokens.length; i++) {
 const token = tokens[i];

 // If the token is an operand, add it to the stack.
 if (!isNaN(parseInt(token))) {
 stack.push(parseInt(token));
 }
 // If the token is an operator, pop two operands from the stack.
 else {
 const b = stack.pop();
 const a = stack.pop();

 // Apply the operator to the two operands.
 switch (token) {
 case '+':
 stack.push(a + b);
 break;
 case '-':
 stack.push(a - b);
 break;
 case '*':
 stack.push(a * b);
 break;
 case '/':
 stack.push(a / b);
 break;
 }
 }
 }

 // Return the result from the stack.
 return stack.pop();
}

