public static int[][] xmlToAdjacencyMatrix(Node root) {
    Queue<Node> q = new LinkedList<>();
    q.add(root);
    Map<String, Integer> map = new HashMap<>();
    int matrixSize = 0;
    while (!q.isEmpty()) {
        Node node = q.poll();
        if (!map.containsKey(node.val)) {
            map.put(node.val, matrixSize);
            matrixSize++;
        }
        for (Node child : node.children) {
            if (!map.containsKey(child.val)) {
                map.put(child.val, matrixSize);
                matrixSize++;
            }
            q.add(child);
        }
    }
    int[][] matrix = new int[matrixSize][matrixSize];
    q = new LinkedList<>();
    q.add(root);
    while (!q.isEmpty()) {
        Node node = q.poll();
        int nodeIndex = map.get(node.val);
        for (Node child : node.children) {
            matrix[nodeIndex][map.get(child.val)] = 1;
            q.add(child);
        }
    }
    return matrix;
}

