fn combinate(items: Vec<i32>) -> Vec<Vec<i32>> {
    let len = items.len();
    let mut result: Vec<Vec<i32>> = Vec::new();
    let mut sub: Vec<i32> = Vec::new();

    fn helper(items: &Vec<i32>, len: usize, sub: &mut Vec<i32>, result: &mut Vec<Vec<i32>>, start: usize) {
        result.push(sub.to_vec());
        for i in start..len {
            sub.push(items[i]);
            helper(items, len, sub, result, i + 1);
            sub.pop();
        }
    }

    helper(&items, len, &mut sub, &mut result, 0);
    result
}

