function binarySearch(sortedArray, value){
 // Set min and max bounds
 let min = 0;
 let max = sortedArray.length - 1;

 // Iterate until min is greater than max
 while(min <= max){
 // Calculate middle index
 let mid = Math.floor((min + max) / 2);

 // Check if value is equal to middle index
 if(sortedArray[mid] === value){
 return mid;
 }
 // If value is greater than middle index, set min to mid + 1
 else if(value > sortedArray[mid]){
 min = mid + 1;
 }
 // Otherwise, value is less than middle index, set max to mid - 1
 else {
 max = mid - 1;
 }
 }

 // If value is not found in array, return -1
 return -1;
}

