void mergeArrays(int arr1[], int arr2[], int n, int m) 
{ 
    int i = 0, j = 0, k = 0; 

    // Temporary array to store merged array 
    int temp[n + m]; 

    // Merging process 
    while (i < n && j < m) 
    { 
        if (arr1[i] < arr2[j]) 
            temp[k++] = arr1[i++]; 

        else
            temp[k++] = arr2[j++]; 
    } 

    // Store remaining elements of array 1 
    while (i < n) 
        temp[k++] = arr1[i++]; 

    // Store remaining elements of array 2 
    while (j < m) 
        temp[k++] = arr2[j++]; 

    // copy the temporary array "temp[]" to 
    // the original array "arr[]" 
    for (i = 0; i < n + m ; i++) 
        cout << temp[i] << " "; 
} 

