def most_common_word(text):
    words = text.split()

    counter = {}
    max_count = 0

    for word in words:
        if word in counter:
            counter[word] += 1
            max_count = max(max_count, counter[word])
        else:
            counter[word] = 1

    common_words = []
    for word, count in counter.items():
        if count == max_count:
            common_words.append(word)

    return common_words

