import spacy
from spacy.lang.en.stop_words import STOP_WORDS 
from spacy.lang.en import English

# Create a text summarizer 
def summarize(text):
    # Create a spacy parser
    parser = English() 

    tokenizer = parser.Defaults.create_tokenizer(parser)
    tokens = tokenizer(text)

    # Create a function to remove stop words and punctuations
    def _filter_tokens(tokens):
        filtered_words = []
        for token in tokens:
            lexeme = parser.vocab[token.orth]
            if not (lexeme.is_stop or lexeme.is_punct):
                filtered_words.append(token.orth_)
        return filtered_words 

    # Process the text 
    normalized_words = _filter_tokens(tokens) 
    word_frequencies = {}
    for word in normalized_words:
        if word not in word_frequencies.keys():
            word_frequencies[word] = 1
        else:
            word_frequencies[word] += 1

    # Calculate the word importance 
    max_frequency = max(word_frequencies.values()) 
    for word in word_frequencies.keys():  
        word_frequencies[word] = (word_frequencies[word]/max_frequency)

    # Compute the sentence importance 
    sentence_list = [ sentence for sentence in text.split(".") ]

    sentence_scores = {}  
    for sentence in sentence_list:  
        for word in sentence.split(" "):
            if word.lower() in word_frequencies.keys():
                if len(sentence.split(' ')) < 30:
                    if sentence not in sentence_scores.keys():
                        sentence_scores[sentence] = word_frequencies[word.lower()]
                    else:
                        sentence_scores[sentence] += word_frequencies[word.lower()]

    # Construct the summary 
    summary = ''
    for sentence in sentence_scores:
        summary += " " + sentence

    return summary  

if __name__ == '__main__':
    text = "This is a test sentence. This is another test sentence."
    print(summarize(text)) # Output: This is a test sentence. This is another test sentence.

