        String res = "";
        int len = Math.min(s1.length(), s2.length());
        for (int i = 0; i < len; i++) {
            res += s2.charAt(i);
            res += s1.charAt(i);
        }

        // if one string is longer than the other
        if (s1.length() > s2.length()) {
            res += s1.substring(len);
        } else if (s2.length() > s1.length()) {
            res += s2.substring(len);
        }
        return res;
    }

