	# Class to detect if two strings are anagrams
	def __init__(self, string1, string2):
		# Set the strings
		self.string1 = string1
		self.string2 = string2

	# Detect if two strings are anagrams
	def is_anagram(self):
		# Check if both strings are the same size
		if len(self.string1) != len(self.string2):
			return False

		# Create a dictionary to store the number of characters in each word
		word_dict = {}

		# Populate the dictionary with characters from each word
		for char in self.string1:
			if char in word_dict.keys():
				word_dict[char] += 1
			else:
				word_dict[char] = 1

		# Decrement the characters for each word
		for char in self.string2:
			if char in word_dict.keys():
				word_dict[char] -= 1
			else:
				return False

		# Check if all values in the dictionary are zero
		for value in word_dict.values():
			if value != 0:
				return False

		return True

