func median(arr []int) (float64) {
  // Sort array
  for i:= 0; i < len(arr)-1; i++ {
    for j:=i+1; j < len(arr); j++ {
      if arr[i] > arr[j] {
        temp := arr[i]
        arr[i] = arr[j]
        arr[j] = temp
      }
    }
  }
 // Calculate median
 if len(arr) % 2 == 0 {
   return float64(arr[(len(arr)-1)/2] + arr[(len(arr)+1)/2]) / 2
 } else {
   return float64(arr[(len(arr)/2)])
 }
}

