public class CRR {

    public static double getCRR(TreeNode root) {

        if (root == null) {
            return 0;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        int noOfCrownNodes = 0;
        int noOfRootNodes = 0;
        queue.add(root);
        while (!queue.isEmpty()) {
            TreeNode currentNode = queue.remove();
            if (currentNode.left == null && currentNode.right == null) {
                noOfCrownNodes++;
            } else {
                noOfRootNodes++;
            }
            if (currentNode.left != null) {
                queue.add(currentNode.left);
            }
            if (currentNode.right != null) {
                queue.add(currentNode.right);
            }
        }
        return (double) noOfCrownNodes / noOfRootNodes;
    }
}

