public class WordCount {
    public static int wordCount(String text, String word) {
        int count = 0;
        text = text.toLowerCase(); 
        word = word.toLowerCase();

        for (int i = 0; i < text.length(); i++) { 
            // Check if the current index is the beginning of a match
            if (text.charAt(i) == word.charAt(0)) { 
                int index = 1; 
                while (index < word.length() && (i + index) < text.length()) { 
                    if (text.charAt(i + index) == word.charAt(index)) { 
                        index++; 
                    } else { 
                        break; 
                    } 
                } 

                if (index == word.length()) { 
                    count++; 
                } 
            }
        } 

        return count; 
    }

    public static void main(String[] args) { 
        String text = "The quick brown fox jumps over the lazy dog.";
        String word = "the";

        int count = wordCount(text, word);

        System.out.println("Number of times \"" + word + "\" appears in the text: " + count); 
    }
}

