public static Set<Integer> findDuplicates(int[] nums) {
    Set<Integer> duplicates = new HashSet<>();
    Set<Integer> seen = new HashSet<>();

    for (int num : nums) {
        if (seen.contains(num)) {
            duplicates.add(num);
        } else {
            seen.add(num);
        }
    }
    return duplicates;
}

