function LCS(a, b) 
{ 
    let aLen = a.length; 
    let bLen = b.length; 

    let dp = Array(aLen + 1).fill(null).map(() => Array(bLen + 1).fill(null)); 

    for (let i = 0; i <= aLen; i++) { 
        for (let j = 0; j <= bLen; j++) { 
            if (i == 0 || j == 0) 
                dp[i][j] = 0; 

            else if (a.charAt(i - 1) == b.charAt(j - 1)) 
                dp[i][j] = dp[i - 1][j - 1] + 1; 

            else
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]); 
        } 
    } 

    return dp[aLen][bLen]; 
}

