import numpy as np

# Define states
states = ('Rainy', 'Sunny')

# Define observations
observations = ['walk', 'shop', 'clean']

# Define start probabilities
start_probability = {'Rainy': 0.6, 'Sunny': 0.4}

# Define the transition probabilities
transition_probability = {
    'Rainy' : {'Rainy': 0.7, 'Sunny': 0.3},
    'Sunny' : {'Rainy': 0.4, 'Sunny': 0.6},
    }

# Define the emission probabilities
emission_probability = {
    'Rainy' : {'walk': 0.1, 'shop': 0.4, 'clean': 0.5},
    'Sunny' : {'walk': 0.6, 'shop': 0.3, 'clean': 0.1},
    }

# Create HMM
def classify(words):
    # split sentence into list of words
    sequence = words.split()

    # calculate the probability of each state
    prob = {}
    for state in states:
        prob[state]=start_probability[state]*emission_probability[state][sequence[0]]

    # use the forward algorithm to calculate the probability of the sequence
    for i in range(1, len(sequence)):
        a = {}
        for state in states:
            value = 0
            for prev_state in states:
                value += prob[prev_state] * transition_probability[prev_state][state] 
            a[state] = emission_probability[state][sequence[i]] * value
        prob = a

    # Normalize the values
    norm_prob = np.array(list(prob.values()))/np.sum(list(prob.values()))
    probability = dict(zip(prob.keys(), norm_prob))

    # return the state with the highest probability
    return max(probability,key=probability.get)

