public string FindLongestPalindrome(string input)
{
  string longestPalindrome = "";
  for (int i = 0; i < input.Length; i++)
  {
    for (int j = i + 1; j <= input.Length; j++)
    {
      string subString = input.Substring(i, j - i);
      string reverseSubString = new string(subString.Reverse().ToArray());
      if (subString == reverseSubString && longestPalindrome.Length < subString.Length)
      {
        longestPalindrome = subString;
      }
    }
  }
  return longestPalindrome;
}

