def remove_anagrams(words):
    ans = [] 
    for word in words:
        isAnagram = False
        word_sorted = ''.join(sorted(word))
        for item in ans:
            if word_sorted == ''.join(sorted(item)):
                isAnagram = True
                break
        if not isAnagram:
            ans.append(word)
    return ans

def compare_strings(str1, str2):
    str1_words = str1.split(' ')
    str2_words = str2.split(' ')

    result = ""

    for i in range(min(len(str1_words), len(str2_words))):
        if str1_words[i] != str2_words[i]:
            result += f"{str1_words[i]} <--> {str2_words[i]}\n"

    if len(str1_words) > len(str2_words):
        result += "\n".join(str1_words[len(str2_words):])
    elif len(str2_words) > len(str1_words):
        result += "\n".join(str2_words[len(str1_words):])

    return result

