    node *next;
};

class LinkedList {
    private:
    node *head, *tail;

public:
    LinkedList() {
        head = NULL;
        tail = NULL;
    }

    void addNode(int data) {
        node* n = new node;
        n->data = data;
        n->next = NULL;

        if (head == NULL) {
            head = n;
            tail = n;
        } else {
            tail->next = n;
            tail = n;
        }
    }

    void deleteNode(int data) {
        node* curr = head;
        node* prev = NULL;

        while (curr != NULL) {
            if (curr->data == data) {
                if (prev == NULL) {
                    head = curr->next;
                } else {
                    prev->next = curr->next
                }
                delete curr;
            }
            prev = curr;
            curr = curr->next;
        }
    }
}

