public class SumWithoutOperators {

 // Function to calculate sum without using + or - operators
 public static int computeSum(int num1, int num2) {

  // Base case
  if(num2 == 0){
   return num1;
  }

  // Add both numbers without carrying
  int sum = num1 ^ num2; 

  // Carry, but don't add to sum
  int carry = (num1 & num2) << 1;

  return computeSum(sum, carry);
 }

 public static void main(String[] args) {
  int num1 = 5;
  int num2 = 10;
  System.out.println("Sum = " + computeSum(num1, num2));
 }
}

