public class Stack {

 // Array used to implement the stack
 private String[] arr;

 // Index indicating the top element of the stack
 private int top;

 // Constructor to initialise the array size
 public Stack(int size) {
 arr = new String[size];
 top = -1;
 }

 // Method to add element to the top of the stack
 public boolean push(String data) {
 if (top < arr.length - 1) {
 top++;
 arr[top] = data;
 return true;
 }
 // Stack overflow
 return false;
 }

 // Method to remove top element of the stack
 public String pop() {
 if(top >= 0) {
 return arr[top--];
 }
 // Stack is empty
 return null;
 }

 // Method to get the size of the stack
 public int getSize() {
 return (top + 1);
 }

}

