def remove_outliers(data):
    outliers = []
    data_average = sum(data) / len(data)
    for d in data:
        if abs(d - data_average) > (3 * data_average):
            outliers.append(d)

    updated_data = [d for d in data if d not in outliers]
    return updated_data

