def max_overlap(text1, text2):
    max_overlap = 0
    for i in range(len(text2)):
        overlap = 0
        for j in range(len(text1)):
            if i + j < len(text2):
                if text1[j] == text2[i + j]:
                    overlap += 1
                else:
                    break
        max_overlap = max(max_overlap, overlap)
    return max_overlap

