public class threadSum {
 public static void main(String args[]) throws InterruptedException{
  int n = 30;

  Thread threadA = new Thread(new Runnable(){
    @Override
    public void run(){
      int sum = 0;
      for(int i=1; i<=n/2; i++){
        sum = sum + i;
      }
      System.out.println("Thread A sum is: "+sum);
    }
  });

  Thread threadB = new Thread(new Runnable(){
    @Override
    public void run(){
      int sum = 0;
      for(int i=n/2+1; i<=n; i++){
        sum = sum + i;
      }
      System.out.println("Thread B sum is: "+sum);
    }
  });

  threadA.start();
  threadB.start();

  threadA.join();
  threadB.join();
  System.out.println("Final Sum: "+(threadA.getSum()+threadB.getSum()));
 }
}

