public class Calculator {
    double firstNumber;
    double secondNumber;
    double result;
    String operator;

    void add() {
        result = firstNumber + secondNumber;
    }

    void subtract() {
        result = firstNumber - secondNumber;
    }

    void multiply() {
        result = firstNumber * secondNumber;
    }

    void divide() {
        result = firstNumber / secondNumber;
    }

    void compute() {
        switch (operator) {
            case "+":
                add();
                break;
            case "-":
                subtract();
                break;
            case "*":
                multiply();
                break;
            case "/":
                divide();
                break;
        }
    }

    public static void main(String[] args) {
        Calculator calculator = new Calculator();

        // Read first number
        System.out.print("Enter first number: ");
        Scanner scanner = new Scanner(System.in);
        calculator.firstNumber = scanner.nextDouble();

        // Read operator
        System.out.print("Enter operator (+, -, *, /): ");
        calculator.operator = scanner.next();

        // Read second number
        System.out.print("Enter second number: ");
        calculator.secondNumber = scanner.nextDouble();

        // Compute result
        calculator.compute();

        // Print the result
        System.out.println("Result: " + calculator.result);
    }
}

