using namespace std;

int binary_search(int arr[], int n, int target)
{
    int low = 0;
    int high = n-1;
    while (low <= high) {
        int mid = (low+high)/2;
        if (arr[mid] == target) return mid;
        else if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

int main()
{
    int arr[] = {1, 2, 3, 4, 5};
    int target = 3;

    int result = binary_search(arr, 5, target);
    if (result == -1) cout << "Target not found";
    else cout << "Target found at index: " << result;
    return 0;
}

