public class MainActivity extends AppCompatActivity {
    private static final int LINES = 20;
    private static final float RADIUS = 100;
    private Paint paint;
    private List<Path> paths;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);
        paths = new ArrayList<>();
        paint = new Paint(Paint.ANTI_ALIAS_FLAG);
        paint.setStyle(Paint.Style.STROKE);
        paint.setStrokeWidth(10f);
    }

    @Override
    protected void onDraw(Canvas canvas) {
        super.onDraw(canvas);
        drawMandalaPattern(canvas);
    }

    private void drawMandalaPattern(Canvas canvas) {
        // draw the lines
        for (int i = 0; i < LINES; i++) {
            paint.setColor(generateRandomColor());
            Path path = new Path();
            path.moveTo(generateRandomX(), generateRandomY());
            path.lineTo(generateRandomX(), generateRandomY());
            paths.add(path);
            canvas.drawPath(path, paint);
        }

        // draw the circles
        for (int i = 0; i < LINES; i++) {
            paint.setColor(generateRandomColor());
            Path path = paths.get(i);
            float startX = path.getBounds().centerX();
            float startY = path.getBounds().centerY();
            canvas.drawCircle(startX, startY, RADIUS, paint);
        }
    }

    private int generateRandomColor() {
        Random rand = new Random();
        return Color.parseColor(String.format("#%06x", rand.nextInt(0xffffff)));
    }

    private int generateRandomX() {
        Random rand = new Random();
        return rand.nextInt(getWidth());
    }

    private int generateRandomY() {
        Random rand = new Random();
        return rand.nextInt(getHeight());
    }
}

