public class CompareStrings {
    public static void main(String[] args) {
        String str1 = "abcdcbad";
        String str2 = "abcbadde";
        int maxLen = 0;
        for (int i = 0; i < str1.length(); i++) {
            int len = 0;
            for (int j = 0; j < str2.length() && i+j < str1.length(); j++) {
                int start = i;
                int end = i+j;
                boolean isPalin = true;
                while (start < end) {
                    if (str1.charAt(start) != str2.charAt(end)) {
                        isPalin = false;
                        break;
                    } 
                    start++;
                    end--;
                }
                if (isPalin) {
                    len++;
                    maxLen = Math.max(maxLen,len);
                } else {
                    len = 0;
                }
            }
        }
        System.out.println("Longest common palindromic substring is " + maxLen + " characters.");
    }
}

