def binary_search(arr, x):
    start = 0
    end = len(arr) - 1
    while start <= end:
        mid = (start + end) // 2
        if arr[mid] < x:
            start = mid + 1
        elif arr[mid] > x:
            end = mid - 1
        else:
            return mid
    return -1

def sort_by_length(string_list):
    # bubble sort
    for idx_i in range(len(string_list)):
        for idx_j in range(len(string_list) - idx_i - 1):
            if len(string_list[idx_j]) > len(string_list[idx_j + 1]):
                string_list[idx_j], string_list[idx_j + 1] = string_list[idx_j + 1], string_list[idx_j]
    return string_list

