public static int longestChain(String str) 
{ 
    int chain = 1; 
    int maxChain = 1; 

    for (int i = 0; i < str.length() - 1; i++) { 
        if (str.charAt(i) == str.charAt(i + 1)) { 
            chain++; 
            if (chain >= maxChain) 
                maxChain = chain; 
        } 
        else { 
            chain = 1; 
        } 
    } 

    return maxChain; 
} 

