public static boolean isAnagramPalindrome(String s) {
    if (s == null || s.length() == 0) {
        return false;
    }

    int[] mapTable = new int[26];
    for (int i=0; i<s.length(); i++) {
        int charValue = s.charAt(i) - 'a';
        mapTable[charValue]++;
    }

    int oddCount = 0;
    for (int count : mapTable) {
        if (count % 2 == 1) {
            oddCount ++;
        }
    }

    return oddCount <= 1;
}

