class LongestSubstring {

    static int longestSubstringWithoutRepeatingChars(String s) {
        int max_len = 0;
        int cur_len = 0;
        int visited[] = new int[256];

        for (int i = 0; i < visited.length; i++)
            visited[i] = -1;

        for (int i = 0; i < s.length(); i++) {
            int prev_index = visited[s.charAt(i)];

            if (prev_index == -1 || i - cur_len > prev_index)
                cur_len++;
            else {
                if (cur_len > max_len)
                    max_len = cur_len;

                cur_len = i - prev_index;
            }

            visited[s.charAt(i)] = i;
        }

        if (cur_len > max_len)
            max_len = cur_len;

        return max_len;
    }

    public static void main(String[] args) {
        String s = "ABCABDEFGHA";
        System.out.println("The length of the longest substring is: "
                    + longestSubstringWithoutRepeatingChars(s));
    }
}

