public static boolean isArmstrong(int number) 
{ 
    int n = String.valueOf(number).length(); 
    int temp = number, sum = 0; 
    while (number != 0) 
    { 
        int remainder = number % 10; 
        number = number / 10; 
        sum = sum + (int)Math.pow(remainder, n); 
    } 

    // Return true if Number is equal 
    // to sum after raising each digit 
    // to the power of total number of 
    // digits i.e. Armstrong number  
    return (sum == temp); 
}

