def minCoins(coins, total):
    table = [0 for _ in range(total+1)]
    for i in range(1, total+1):
        for coin in coins:
            if i >= coin:
                if table[i - coin] + 1 < table[i] or table[i] == 0:
                    table[i] = table[i - coin] + 1
    return table[total]

