class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self,data):
        node = TreeNode(data)

        if self.root is None:
            self.root = node
        else:
            current = self.root
            while True:
                if data < current.data:
                    if current.left:
                        current = current.left
                    else:
                        current.left = node
                        break
                elif data > current.data:
                    if current.right:
                        current = current.right
                    else:
                        current.right = node
                        break
                else:
