def matrix_multiply(a, b):
  m = len(a)
  n = len(a[0])
  l = len(b[0])

  if (len(b) != n):
    raise Exception('cannot multiply matrices. incorrect sizes')

  c = [[0] * l for _ in range(m)]
  for i in range(m):
    for j in range(l):
      total = 0
      for k in range(n):
        total += a[i][k] * b[k][i]
      c[i][j] = total

  return c

def play_tic_tac_toe(player1, player2):

    # Create empty board
    board = [["", "", ""],
             ["", "", ""],
             ["", "", ""]]

    # Let's decide the first player
    if (player1 == 'random'):
        player1_move = random_move(board)
    else:
        player1_move = player_move(player1, board)

    board[player1_move[0]][player1_move[1]] = player1

    # Check if player1 won
    if who_won(board) == 'Player 1':
        return True

    # Check if game is over
    if is_over(board):
        return False

    # If not, let's decide the player2 move
    if (player2 == 'random'):
        player2_move = random_move(board)
    else:
        player2_move = player_move(player2, board)

    board[player2_move[0]][player2_move[1]] = player2

    # Check if player2 won
    if who_won(board) == 'Player 2':
        return False


    # Check if game is over
    if is_over(board):
        return False

    # Otherwise, call the function again
    return play_tic_tac_toe(player1, player2) 

# Function to generate a random move
def random_move(board):
    moves = []

    # Add all empty moves in a list
    for i in range(3):
        for j in range(3):
            if board[i][j] == '':
                moves.append([i, j])

    # Generate and return a random move
    return random.choice(moves)

# To check if there's a winner
def who_won(board):
    # Check for horizontal
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2]:
            if board[i][0] != '':
                return 'Player ' + str(board[i][0])

    # Check for vertical
    for i in range(3):
        if board[0][i] == board[1][i] == board[2][i]:
            if board[0][i] != '':
                return 'Player ' + str(board[0][i])

    # Check for diagonal
    if board[0][0] == board[1][1] == board[2][2]:
        if board[0][0] != '':
            return 'Player ' + str(board[0][0])
    if board[0][2] == board[1][1] == board[2][0]:
        if board[0][2] != '':
            return 'Player ' + str(board[0][2])

# To check if the board is full
def is_over(board):
    for i in range(3):
        for j in range(3):
            if board[i][j] == '':
                return False
    return True

