public class LinkedList {

    private Node head;
    private int size;

    public LinkedList() {
        this.head = null;
        this.size = 0;
    }

    public void addNode(Node node) {
        if(this.head == null) {
            this.head = node;
        } else {
            Node temp = this.head;
            while(temp.getNext() != null) {
                temp = temp.getNext();
            }
            temp.setNext(node);
        }
        this.size++;
    }

    public void removeNode (int data) {
        if (this.head == null) {
            return;
        }
        if (this.head.getData() == data) {
            this.head = this.head.getNext();
        } else {
            Node temp = this.head;
            while(temp.getNext() != null) {
                if (temp.getNext().getData() == data) {
                    temp.setNext(temp.getNext().getNext());
                    break;
                }
                temp = temp.getNext();
            }
        }
        this.size--;
    }

}

int findMaxSumSubArray(int arr[], int n, int k) 
{ 
    int maxSum = 0; 
    int winSum = 0; 
    int winStart = 0; 

    // Find the sum of first window of size k 
    for (int i = 0; i < k; i++) 
        winSum += arr[i]; 

    // Slide the window 
    for (int i = k; i < n; i++) { 
        // Remove first element of previous window 
        winSum -= arr[i - k]; 

        // Add new element of current window 
        winSum += arr[i]; 

        // Update maximum window sum 
        maxSum = Math.max(maxSum, winSum); 
    } 

    return maxSum; 
}

