public class SentimentClassifier { 

    public static String classifyText(String text) { 
        String[] words = text.split(" "); 
        int score = 0; 

        // Create a HashMap to store the scores of each word 
        Map<String, Integer> scores = new HashMap<>(); 

        scores.put("positive", 1); 
        scores.put("negative", -1); 

        // Iterate through each word and calculate score 
        for (String word : words) { 
            if (scores.containsKey(word)) 
                score += scores.get(word); 
        } 

