def knapsack(items, capacity):
    # Create a matrix to store the maximum value at every weight capacity
    matrix = [[0 for _ in range(capacity + 1)] for _ in range(len(items))]

    # Iterate over the columns (weight capacity) and rows (items)
    for row, item in enumerate(items):
        for col in range(capacity + 1):        
            # Case 1: Don't Take the Item
            if item[0] > col:
                matrix[row][col] = matrix[row - 1][col]

            # Case 2: Take the Item
            else: 
                matrix[row][col] = max(matrix[row - 1][col], matrix[row - 1][col - item[0]] + item[1])
    return matrix[-1][-1]

