public class SortArray 
{ 
    // The function to sort an array using 
    // Insertion sort 
    void sort(int arr[]) 
    { 
        int n = arr.length; 
        for (int i=n-1; i>=0; i--) 
        { 
            int key = arr[i]; 

            int j = i+1; 
            while (j<n && arr[j] < key) 
            { 
                arr[j-1] = arr[j]; 
                j = j+1; 
            } 
            arr[j-1] = key; 
        } 

        // Print the sorted array 
        for (int i=0; i<n; ++i) 
            System.out.print(arr[i]+" "); 
    } 

    public static void main(String args[]) 
    { 
        SortArray ob = new SortArray(); 
        int arr[] = {2,3,8,6,1}; 
