    # Create an array to store result
    longest = [0 for _ in array]
    # Initialize the longest array with value 1
    for i in range(len(array)):
        longest[i] = 1
    for i in range(1, len(array)):
        for j in range(i):
            if array[i] >= array[j] and longest[i] < longest[j] + 1:
                longest[i] = longest[j] + 1
    lds = 0
