class Stack { 
    ListNode head; 

    // Push an element in the Stack 
    public void push(int n) 
    { 
        ListNode node = new ListNode(n); 
        if (head == null) { 
            head = node; 
        } 
        else { 
            ListNode temp = head; 
            head = node; 
            node.next = temp; 
        } 
    } 

    // Pop an element from the stack 
    public int pop() 
    { 
        int x = -1; 
        if (head == null) 
            System.out.println("Stack is Empty"); 
        else { 
            x = head.data; 
            head = head.next; 
        } 

        return x; 
    } 
}

