// Function to evaluate Postfix expression and return output
int EvaluatePostfix(string expression)
{
    stack <int> S;
    for(int i = 0;i< expression.length();i++) 
    {
        // Scanning each character from left. 
        if(expression[i] == ' ' || expression[i] == ',') 
            continue;

        else if(expression[i] == '+' || expression[i] == '-' || 
                expression[i] == '*' || expression[i] == '/') 
        {
            // If the scanned character is an operator, 
            int operand2 = S.top(); 
            S.pop(); 
            int operand1 = S.top(); 
            S.pop();

            int result = PerformOperation(expression[i], operand1, operand2);

            // Push back the result of the evaluation
            S.push(result);

        }
        else
        {
            // For a number
            int operand = 0; 
            while(i<expression.length() && 
                    expression[i] >= '0' && expression[i] <= '9') 
            { 
                // If the character is a digit then convert it to int
                // and push it onto the stack
                operand = (operand*10) + (expression[i] - '0'); 
                i++;
            }
            i--;

            // Push the operand on the stack
            S.push(operand);
        }
    }

    // If the expression is in the correct postfix form,
    // the number in the stack will be the final answer
    return S.top(); 
}

// Function to perform an operation and return output. 
int PerformOperation(char operation, int operand1, int operand2)
{
    if(operation == '+') 
        return operand1 + operand2;
    else if(operation == '-') 
        return operand1 - operand2;
    else if(operation == '*') 
        return operand1 * operand2;
    else if(operation == '/') 
        return operand1 / operand2;
    else
        cout<<"Unexpected Error \n";
    return -1; 
}

