object Solver {

 def solve(items: List[(Int, Int)], capacity: Int): (Int, List[(Int, Int)]) = {
  // table for storing results of subproblems
  val dpTable = Array.ofDim[Int](capacity+1, items.length+1)
  // fill in the table
  for (i <- 1 until capacity+1) {
   for (j <- 1 until items.length+1) {
    if (items(j-1)._1 <= i) {
     dpTable(i)(j) = Math.max( dpTable(i)(j-1), dpTable(i-items(j-1)._1)(j-1) + items(j-1)._2 )
    } else {
     dpTable(i)(j) = dpTable(i)(j-1)
    }
   }
  }

  // solution
  (dpTable(capacity)(items.length), getItems(items, dpTable))
 }

 private def getItems(items: List[(Int, Int)], dpTable: Array[Array[Int]]): List[(Int, Int)] = {
  var c = dpTable(0).length-1
  var w = dpTable.length-1
  val result = scala.collection.mutable.ListBuffer.empty[(Int, Int)]
  while (c > 0 && w > 0) {
   if (dpTable(w)(c) != dpTable(w)(c-1)) {
    result += items(c-1)
    w = w - items(c-1)._1
   }
   c = c - 1
  }
  result.toList
 }

}

