function knapsackGreedy(weights, values, capacity) {
 let maxValue = 0;
 let remainingCapacity = capacity;
 let selectedIndices = [];

 // Sort items based on value density 
 let sortedItems = weights.map((value, i) => ({
 value: (values[i]/value),
 weight: value
 })).sort((a, b) => b.value - a.value);

 for (let i = 0; i < weights.length; i++) {
  if (value > remainingCapacity) {
   break;
  }
  maxValue += sortedItems[i].value;
  selectedIndices.push(sortedItems[i].weight);
  remainingCapacity -= sortedItems[i].weight;
 }

 return {selectedIndices, maxValue};
}

