public static String caesarCipher(String message, int key) { 
  String ciphertext = ""; 
  for (int i = 0; i < message.length(); i++) { 
    if (Character.isUpperCase(message.charAt(i))) {

      int charPosition = message.charAt(i) - 64; 
      int keyVal = (charPosition + key) % 26; 
      char replaceVal = (char) (keyVal + 64); 
      ciphertext += replaceVal; 
    } 
    else {

      int charPosition = message.charAt(i) - 96; 
      int keyVal = (charPosition + key) % 26; 
      char replaceVal = (char) (keyVal + 96); 
      ciphertext += replaceVal; 
    } 
  } 
  return ciphertext; 
}

