function getThirdHighest(arr) {
  let highest = Math.max(...arr);
  let secondHighest;

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] !== highest) {
      secondHighest = Math.max(arr[i], secondHighest);
    }
  }

  let thirdHighest;

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] !== highest && arr[i] !== secondHighest) {
      thirdHighest = Math.max(arr[i], thirdHighest);
    }
  }

  return thirdHighest;
}

