def caesar_cipher_encrypt(message, shift):
    encoded_message = ''
    for c in message:
        if c.isalpha():
            num = ord(c)
            num += shift
            if c.isupper():
                if num > ord('Z'):
                    num -= 26
                elif num < ord('A'):
                    num += 26
            elif c.islower():
                if num > ord('z'):
                    num -= 26
                elif num < ord('a'):
                    num += 26
            encoded_message += chr(num)
        else:
            encoded_message += c
    return encoded_message

