int longestCommonSubstring(char* string1, char* string2)
{
    int n = strlen(string1);
    int m = strlen(string2);

    int maxLength = 0;

    int dp[n + 1][m + 1];

    for (int i = 0; i < n + 1; i++)
    {
        for (int j = 0; j < m + 1; j++)
        {
            if (i == 0 || j == 0) 
                dp[i][j] = 0;
            else if (string1[i - 1] == string2[j - 1])
            {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                maxLength = max(maxLength, dp[i][j]);
            }
            else 
                dp[i][j] = 0;
        }
    }
    return maxLength;
}

