public static <T extends Comparable<T>> List<T> insertionSort(
        List<T> list, T item) {

    int index = list.size();
    list.add(item);

    while (index > 0 && list.get(index).compareTo(list.get(index - 1)) < 0) {
        list.set(index, list.get(index - 1));
        list.set(index - 1, item);
        index--;
    }
    return list;
}

