// We will create a function that takes two parameters: the original string of classes and the class to remove
function removeClass(originalClasses, removeClass) {
  // Convert the strings to an array of classes
  let originalClassesArr = originalClasses.split(' ');
  let removeClassArr = removeClass.split(' ');

  // Iterate over the original classes array
  for (let i = 0; i < originalClassesArr.length; i++) {
    // Check if the current class matches the class to remove
    if (originalClassesArr[i] === removeClassArr[0]) {
      // Remove the class
      originalClassesArr.splice(i, 1);
    }
  }

  // Convert the array back to a string and return the string
  return originalClassesArr.join(' ');
}

