void sieveOfEratosthenes(int start, int end) 
{ 
	bool prime[end+1]; 
	memset(prime, true, sizeof(prime)); 

	for (int p=2; p*p<=end; p++) 
	{ 
		if (prime[p] == true) 
		{ 
			for (int i=p*p; i<=end; i += p) 
				prime[i] = false; 
		} 
	} 
	int count=0; 
	for (int p=start; p<=end; p++) 
	if (prime[p]) 
		count++; 

	cout << "Total number of prime numbers between given range : "<<count; 
}

