        sum += arr[i]; 

    // Calculate mean
    mean = (double)sum/n; 

    // Calculate median
    sort(arr, arr + n); 
    if (n % 2 == 0)
        median = (double)(arr[(n - 1) / 2] + arr[n / 2]) / 2.0; 
    else
        median = (double)arr[n / 2]; 

