    if (root == None): 
        return
    optimizeBST(root.left) 
    optimizeBST(root.right) 
    if (root.left != None): 
        root.left.rightMost = findMax(root.left) 
    if (root.right != None): 
        root.right.leftMost = findMin(root.right) 

def findMax(node): 
    if (node == None): 
        return
    while (node.right): 
        node = node.right 
    return node 

def findMin(node): 
    if (node == None): 
        return
    while (node.left): 
        node = node.left 
    return node

