// The Algorithm for the AI assistant playing Tic-Tac-Toe

// Stores the game board
let board = new Array(3).fill().map(() => new Array(3).fill(null));

// Function to check if the game is a draw
function isDraw(board) {
    let draw = true;
    for (let row=0; row<board.length; row++) {
        for (let column=0; column< board[row].length; column++) {
            if (board[row][column] === null) {
                draw = false;
            }
        }
    }
    return draw;
}

// Function to check if the game is won
function isWin(board) {
    let win = false;
    // Check all column combinations for a win
    for (let column=0; column< board.length; column++) {
        if (board[0][column] === board[1][column] && board[1][column] === board[2][column] && board[0][column] !== null && board[1][column] !== null && board[2][column] !== null) {
            win = true;
        }
    }

    // Check all row combinations for a win
    for (let row=0; row<board.length; row++) {
        if (board[row][0] === board[row][1] && board[row][1] === board[row][2] && board[row][0] !== null && board[row][1] !== null && board[row][2] !== null) {
            win = true;
        }
    }

    // Check the left-right diagonal combination for a win
    if (board[0][0] === board[1][1] && board[1][1] === board[2][2] && board[0][0] !== null && board[1][1] !== null && board[2][2] !== null) {
        win = true;
    }

    // Check the right-left diagonal combination for a win
    if (board[0][2] === board[1][1] && board[1][1] === board[2][0] && board[0][2] !== null && board[1][1] !== null && board[2][0] !== null) {
        win = true;
    }

    return win;
}

// The main Algorithm
function ticTacToe() {
    // Keep playing until the game is won or a draw
    while(!isWin(board) && !isDraw(board)) {
        // Get the AI's move
        let aiMove = getAIMove(board);

        // Update the board with the AI's move
        board = updateBoard(board, aiMove);
        console.log("AI move:", aiMove);

        // Check if game is won or draw
        if (isWin(board)) {
            console.log("AI wins!");
        }
        if (isDraw(board)) {
            console.log("Draw!");
        }

        // Get the other player's move
        let playerMove = getPlayerMove(board);

        // Update the board with the other player's move
        board = updateBoard(board, playerMove);
        console.log("Player move:", playerMove);

        // Check if game is won or draw
        if (isWin(board)) {
            console.log("Player wins!");
        }
        if (isDraw(board)) {
            console.log("Draw!");
        }
    }
}

