def fibonacci(n): 
    if n < 0: 
      return ValueError("Incorrect input") 

    f = [0, 1] 

    while len(f) < n + 1: 
        f.append(0) 

    if n <= 1: 
        return n 

    else: 
        for i in range(2, n + 1) : 
            f[i] = f[i-1] + f[i-2] 

    return f[n]

