    n = len(string) 

    if n == 0: 
        return 0

    count_x = 0
    count_y = 0

    maxlen = 0
    currlen = 0

    for i in range(n): 
        currlen += 1

        if string[i] == 'X': 
            count_x += 1

        elif string[i] == 'Y': 
            count_y += 1

        if count_x == count_y: 
            maxlen = max(maxlen, currlen) 

    return maxlen

