public static List<List<Integer>> getSubsetsWithSum(int[] arr, int sum) {
    // list to hold the subsets
    List<List<Integer>> subsets = new ArrayList<>();

    // compute subsets using backtracking recursion
    getSubsetsWithSum(arr, sum, 0, 0, new ArrayList<>(), subsets);

    return subsets;
}

public static void getSubsetsWithSum(int[] arr, int sum, int startIndex, int currSum, 
                            List<Integer> currSubset, List<List<Integer>> allSubsets) {
    if (currSum == sum) {
        allSubsets.add(new ArrayList<Integer>(currSubset));
        return;
    }

    // loop over elements starting from startIndex
    for (int i = startIndex; i < arr.length; i++) {
        // subsets should not have duplicates,
        // so use arr[i - 1] to avoid adding duplicate elements
        if (i > 0 && arr[i] == arr[i - 1]) {
            continue;
        }

        currSubset.add(arr[i]);
        getSubsetsWithSum(arr, sum, i + 1, currSum + arr[i], currSubset, allSubsets);
        currSubset.remove(currSubset.size() - 1);
    }
}

