public class VigenereCipher 
{  
    public static String encryptVigenere(String message, String key) 
    { 
        String encryptedMessage = ""; 
        char currentChar; 
        for(int i = 0; i < message.length();  i++) 
        { 
            currentChar = message.charAt(i); 

            // if current character is in the alphabet range
            if(currentChar >= 'a' && currentChar <= 'z') 
            {
                currentChar = (char)((int)currentChar + (int)(key.charAt(i)) % 26); 

                // if new character is greater 'z', substract 26
                if(currentChar > 'z') 
                { 
                    currentChar = (char)((int)currentChar - 26); 
                } 
            } 
            else if(currentChar >= 'A' && currentChar <= 'Z') 
            {
                currentChar = (char)((int)currentChar + (int)(key.charAt(i)) % 26); 

                // if character greater than 'Z', substract 26
                if(currentChar > 'Z') 
                { 
                    currentChar = (char)((int)currentChar - 26); 
                } 
            } 
            encryptedMessage = encryptedMessage +  currentChar; 
        } 
        return encryptedMessage; 
    } 

    // Driver Code 
    public static void main(String [] args) 
    { 
        Scanner scanner = new Scanner(System.in); 
        System.out.print("Enter the message: ");
        String message = scanner.nextLine();
        System.out.print("Enter the key: ");
        String key = scanner.nextLine();   
        System.out.print("Encrypted message: " + encryptVigenere(message, key)); 
    } 
}

