#define MAX_SIZE 101

// A structure to represent a stack
class Stack
{
    int top;
    int arr[MAX_SIZE];

public:
    Stack() { top = -1; }
    bool push(int x);
    int pop();
    bool isEmpty();
};

bool Stack::push(int x)
{
    if (top >= MAX_SIZE) {
        cout << "Stack Overflow";
        return false;
    }
    else {
        arr[++top] = x;
        return true;
</    }
}

int Stack::pop()
{
    if (top < 0) {
        cout << "Stack Underflow";
        return 0;
    }
    else {
        int x = arr[top--];
        return x;
    }
}

bool Stack::isEmpty()
{
    return (top < 0);
}

