def find_freq(my_list):
    # Create an empty dictionary to store counts
    counts = {}

    # Iterate over each element in the list
    for ele in my_list:
        # Initialize the count to 0
        count = 0

        # Iterate over the list again
        for e in my_list:
            # If the element is found in the list, increment the count by 1
            if ele == e:
                count += 1

        # Store the count in the dictionary
        counts[ele] = count

    # Print each element and its count
    for ele, count in counts.items():
        print(f"{ele} : {count}")

