public int primeSum(int n) 
{
    int sum = 0; 

    for (int i = 2; i <= n; i++) 
    { 
        if (isPrime(i)) 
            sum += i; 
    } 
    return sum; 
} 

// Function to check if a number is prime or not 
public boolean isPrime(int n) 
{ 
    // Edge case 
    if (n == 0 || n == 1) 
        return false; 

    // Check from 2 to n-1 
    for (int i = 2; i < n; i++) 
        if (n % i == 0) 
            return false; 

    return true; 
}

