int palindromicSequence(char string[]) {
  int len = strlen(string);
  int count = 0; 

for (int i = 0; i < len; i++)
  {  
    int left = i;
    int right = i;

    // match characters from both ends
    while (left >= 0 && right < len && string[left] == string[right]) {
        // palindromic sequence found
        if (right - left + 1 > 2)
            count++;

        // expand palindrome
        left--; 
        right++;
    }
  }

  return count;
}

