#include <string.h>

// Function to find the longest substring containing only
// given set of characters
char* longestSubstring(char* str, char* set)
{
	// store the length of strings
	int n = strlen(str);
	int m = strlen(set);

	// stores longest substring
	char* maxSubstring = (char*) malloc(n * sizeof(char));

	// temp stores current substring
	char* temp = (char*) malloc(n * sizeof(char));

	// pointer to store maximum length substring
	char* ptrMax = maxSubstring;
	char* ptrTemp = temp;

	// stores occurrence of characters in set
	int hashSet[256] = { 0 };

	// stores occurrence of characters in string
	int hashStr[256] = { 0 };

	// store all characters of set in hashset
	for (int i = 0; i < m; i++)
		hashSet[set[i]]++;

	int i = 0, j = 0;
	for (; i < n; i++)
	{
		// count occurrences of str[j]
		hashStr[str[i]]++;

		// if str[j] is present in set
		if (hashSet[str[i]] != 0 &&
			hashStr[str[i]] <= hashSet[str[i]] )
		{
			// append to current substring
			*ptrTemp = str[i];
			ptrTemp++;
		}

		// If str[i] is not present in set
		if (hashSet[str[i]] == 0 ||
			hashStr[str[i]] > hashSet[str[i]] ||
			i == n - 1)
		{
			// compare current longest substring
			// and substring starting from j and
			// ending at i
			if (strlen(maxSubstring) <
				(ptrTemp - temp))
			{
				ptrMax = maxSubstring;
				for (char* k = temp; k < ptrTemp ; k++)
					*(ptrMax++) = *k;
				*ptrMax = '\0';
			}

			// reset temp pointer and hashstrings
			ptrTemp = temp;
			memset(hashStr, 0, n);

			// set the new starting point
			j = i + 1;
		}
	}

	// free dynamically allocated memory
	free(temp);

	// return longest substring
	return maxSubstring;
}

