public class MainActivity extends AppCompatActivity {

    private TextView mScoreTextView;
    private int mScore = 0;
    private String mUserName;
    private Map<String, String> mQuestionsAndAnswers;
    private int mCurrentQuestion;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        mScoreTextView = findViewById(R.id.score);
        mScoreTextView.setText("Score: 0");
        showGetUserNameDialog();

        mQuestionsAndAnswers = new HashMap<String, String>();
        mQuestionsAndAnswers.put("What is the capital of India?", "New Delhi");
        mQuestionsAndAnswers.put("What is the capital of Japan?", "Tokyo");
        mQuestionsAndAnswers.put("What is the capital of the United States?", "Washington D.C.");
        mCurrentQuestion = 0;
    }

    private void showGetUserNameDialog() {
        Context context = this;
        LayoutInflater inflater = this.getLayoutInflater();

        View dialogView = inflater.inflate(R.layout.user_name_dialog, null);
        final EditText userNameEditText = dialogView.findViewById(R.id.user_name);

        AlertDialog.Builder builder = new AlertDialog.Builder(context);
        builder.setTitle("Trivia Quiz");
        builder.setMessage("Enter your name");
        builder.setView(dialogView);
        builder.setNegativeButton("Cancel", new DialogInterface.OnClickListener() {
            @Override
            public void onClick(DialogInterface dialogInterface, int i) {
                dialogInterface.cancel();
            }
        });
        builder.setPositiveButton("Ok", new DialogInterface.OnClickListener() {
            @Override
            public void onClick(DialogInterface dialogInterface, int i) {
                mUserName = userNameEditText.getText().toString();
                startNextQuestion();
            }
        });
        builder.show();
    }

    private void startNextQuestion() {
        // Show the new question
        String question = (String) mQuestionsAndAnswers.keySet().toArray()[mCurrentQuestion];
        TextView questionTextView = findViewById(R.id.question);
        questionTextView.setText(question);

        // Show the associated answer
        final String answer = mQuestionsAndAnswers.get(question);

        // Enable the Submit Button
        Button submitButton = findViewById(R.id.submit_response);
        submitButton.setEnabled(true);
    }

    public void onSubmitResponse(View view) {
        // Disable the SubmitButton
        Button submitButton = findViewById(R.id.submit_response);
        submitButton.setEnabled(false);

        // Get the response
        EditText responseEditText = findViewById(R.id.response);
        final String response = responseEditText.getText().toString();

        // Check if the response is correct
        boolean responseCorrect = response.equals(mQuestionsAndAnswers.get((String) mQuestionsAndAnswers.keySet().toArray()[mCurrentQuestion]));

        if (responseCorrect) {
            mScore++;
            mScoreTextView.setText("Score: " + mScore);
            Toast.makeText(this, "Correct!" , Toast.LENGTH_SHORT).show();
        } else {
            Toast.makeText(this, "Incorrect!" , Toast.LENGTH_SHORT).show();
        }

        // Advance to the next question
        mCurrentQuestion++;
        if (mCurrentQuestion < mQuestionsAndAnswers.size()) {
            startNextQuestion();
        } else {
            Toast.makeText(this, "The quiz is finished. Your final score is: " + mScore , Toast.LENGTH_LONG).show();
        }
    }
}

