class Polynomial:
    def __init__(self, coefficients):
        self.coefficients = coefficients

    # Function to evaluate the polynomial in a given x
    def evaluate(self, x):
        sum = 0
        for i, c in enumerate(self.coefficients):
            sum += c * x ** i
        return sum

    # Function to add two polynomials
    def add(self, other):
        len_self = len(self.coefficients)
        len_other = len(other.coefficients)
        if len_self > len_other:
            c_add = self.coefficients.copy()
            for i in range(len_other):
                c_add[i] += other.coefficients[i]
        else:
            c_add = other.coefficients.copy()
            for i in range(len_self):
                c_add[i] += self.coefficients[i]
        return Polynomial(c_add)

