int maxSubArraySum(int arr[], int n)
{
    int max_so_far = arr[0];
    int curr_max = arr[0];

    for (int i=1; i <n; i++)
    {
        curr_max = max(arr[i], curr_max+arr[i]);
        max_so_far = max(max_so_far, curr_max);   
    }
    return max_so_far;
}

def largest_subarray_sum(arr):
    # Create an empty dictionary 
    sum_map =  {} 

    sum_value = 0
    max_len = 0

    # Traverse through the array and store the cumulative 
    # sum values in the dictionary
    for i in range(0,len(arr)): 
        sum_value += arr[i] 

        if (sum_value == 0): 
            max_len = i + 1

        if sum_value in sum_map: 
            max_len = max(max_len, i - sum_map[sum_value]) 
        else: #Else put this sum in dictionary 
            sum_map[sum_value] = i 

    return max_len

