def delete(head, item):
  current = head
  if current is not None:
    if current.data == item:
      head = current.next
      current = None
      return head

  while current is not None:
    if current.data == item:
      break
    prev = current
    current = current.next

  if current == None:
    return head

  prev.next = current.next
  current = None

  return head

