def MWIS(G):
    dp = [float("-inf") for _ in range(len(G))]
    dp[0] = 0 

    for i in range(1, len(G)):
        dp[i] = max(G[i], G[i] + dp[i-1])

    return dp

def solution(G):
    final_array = [False] * len(G)
    dp = MWIS(G)

    for i in range(len(dp)):
        if(dp[i] == G[i] + dp[i-1]):
            final_array[i] = True

    return final_array

