def knapsack(items, capacity):
    x = [[0 for k in range(capacity + 1)] for i in range(len(items) + 1)]

    for i in range(1, len(items) + 1):
        for k in range(0, capacity + 1):
            if items[i-1]['weight'] > k:
                x[i][k] = x[i-1][k]
            else: 
                x[i][k] = max(x[i-1][k], x[i-1][k-items[i-1]['weight']] + items[i-1]['value'])

    return x[len(items)][capacity]

