public static String reduceConsecutiveRepeatingChars(String str) {
    // Create empty string
    StringBuilder reducedString = new StringBuilder(); 

    // Iterate over the characters of string
    char currChar = 0;
    for (char c : str.toCharArray()) {
        // Check if current character
        // is same as previous character
        if (c != currChar) {
            // If not, add the current character
            // to reduced string
            reducedString.append(c);
            currChar = c;
        }
    }

