import android.net.Uri;

public class ContactContentProvider extends ContentProvider {

 private ContactDbHelper mDbHelper;

 // Codes for the UriMatcher //
 private static final int CONTACTS = 100;
 private static final int CONTACTS_WITH_ID = 101;

 private static final UriMatcher sUriMatcher = buildUriMatcher();

 // Define a static buildUriMatcher method //
 public static UriMatcher buildUriMatcher() {
 // Initialize a UriMatcher with no matches by passing in NO_MATCH to the constructor
 UriMatcher uriMatcher = new UriMatcher(UriMatcher.NO_MATCH);

 /*
  All paths added to the UriMatcher have a corresponding int.
  For each kind of uri you may want to access, add the corresponding match with addURI.
  The two calls below add matches for the task directory and a single item by ID.
 */
 uriMatcher.addURI(ContactContract.AUTHORITY, ContactContract.PATH_CONTACTS, CONTACTS);
 uriMatcher.addURI(ContactContract.AUTHORITY, ContactContract.PATH_CONTACTS + "/#", CONTACTS_WITH_ID);

 return uriMatcher;
 }

 @Override
 public boolean onCreate() {
 mDbHelper = new ContactDbHelper(getContext());
 return true;
 }

 @Override
 public Uri insert(@NonNull Uri uri, @Nullable ContentValues values) {
 final SQLiteDatabase db = mDbHelper.getWritableDatabase();
 int match = sUriMatcher.match(uri);
 Uri returnUri; // URI to be returned

 switch (match) {
 case CONTACTS:
 // Insert new values into the database
 // Inserting values into contacts table
 long id = db.insert(ContactContract.ContactEntry.TABLE_NAME, null, values);
 if ( id > 0 ) {
 returnUri = ContentUris.withAppendedId(ContactContract.ContactEntry.CONTENT_URI, id);
 } else {
 throw new android.database.SQLException("Failed to insert row into " + uri);
 }
 break;
 // Default case throws an UnsupportedOperationException
 default:
 throw new UnsupportedOperationException("Unknown uri: " + uri);
 }

 // Notify the resolver if the uri has been changed, and return the newly inserted URI
 getContext().getContentResolver().notifyChange(uri, null);

 // Return constructed uri (this points to the newly inserted row of data)
 return returnUri;
 }

 @Override
 public Cursor query(@NonNull Uri uri, String[] projection, String selection,
 String[] selectionArgs, String sortOrder) {

