interface Shape {
 type: string;
 calculateArea(): number;
}

class Circle implements Shape {
 type: string;
 radius: number;

 constructor(radius: number) {
 this.type = 'circle';
 this.radius = radius;
 }

 calculateArea(): number {
 return Math.PI * Math.pow(this.radius, 2);
 }
}

class Rectangle implements Shape {
 type: string;
 width: number;
 length: number;

 constructor(width: number, length: number) {
 this.type = 'rectangle';
 this.width = width;
 this.length = length;
 }

 calculateArea(): number {
 return this.width * this.length;
 }
}

class Triangle implements Shape {
 type: string;
 base: number;
 height: number;

 constructor(base: number, height: number) {
 this.type = 'triangle';
 this.base = base;
 this.height = height;
 }

 calculateArea(): number {
 return 0.5 * this.base * this.height;
 }
}

// Create a ShapeFactory that allows users to select and
// construct a shape with given parameters.
class ShapeFactory {
 public static createShape(type: string, parameters: number[]): Shape {
 let shape: Shape;

 switch(type) {
 case 'circle':
 shape = new Circle(parameters[0]);
 break;
 case 'rectangle':
 shape = new Rectangle(parameters[0], parameters[1]);
 break;
 case 'triangle':
 shape = new Triangle(parameters[0], parameters[1]);
 break;
 default:
shape = null;
 break;
 }

 return shape;
 }

}

