public class Anagram { 

    // Function to generate 
    // all anagrams of the string 
    static void allAnagrams(String str) 
    { 
        // Call the function for printing all permutations 
        allAnagramsUtil(str, ""); 
    } 

    // Function to generate all anagrams of  
    // the string. This function takes two parameters: 
    // 1. String 
    // 2. prefix 
    static void allAnagramsUtil(String str, String prefix) 
    { 

        // If string has only one character 
        if (str.length() == 1) { 
            // Print the obtained anagram 
            System.out.println(prefix + str); 

            return; 
        } 

        // One by one add all characters  
        // from the string and recursively 
        // call for all anagrams 
        for (int i = 0; i < str.length(); i++) { 

            // Remove the character str[i] from string 
            String rem = str.substring(0, i) +  
                    str.substring(i + 1); 

            // Add the removed character to 
            //prefix and recurse for remaining string 
            allAnagramsUtil(rem, prefix + str.charAt(i)); 
        } 
    } 

    // Driver code 
    public static void main(String[] args) 
    { 
        String str = "ABC"; 
        allAnagrams(str); 
    } 
}

