def knapsack_dynamic_programming(W, items):
    """
    Implements a dynamic programming solution for the knapsack problem.
    """
    n = len(items)
    matrix = [[0 for _ in range(W+1)] for _ in range(n+1)]
    selected_items = [[False for _ in range(W+1)] for _ in range(n+1)]
    for i in range(1, n+1):
        weight, value = items[i-1]
        for j in range(W+1):
            if j < weight:
                matrix[i][j] = matrix[i-1][j]
            else:
                matrix[i][j] = max(matrix[i-1][j], matrix[i-1][j-weight] + value)
                if matrix[i-1][j-weight] + value > matrix[i-1][j]:
                    selected_items[i][j] = True
    return matrix, selected_items

