def longest_substring(input_string):
    max_length = 0
    current_length = 0
    start_index = 0
    charhash = {}
    for index, char in enumerate(input_string):
        if char not in charhash:
            current_length +=1
            charhash[char] = index
        else:
            if current_length > max_length:
                    max_length = current_length
            current_length = index - charhash[char]
            start_index = charhash[char] + 1
        charhash[char] = index
    return max_length

