def find_mode(list):
    # count the frequency of each element 
    counts = {}
    for element in list:
        if element not in counts:
            counts[element] = 1
        else:
            counts[element] += 1
    # find the most frequent element 
    mode = max(counts, key=counts.get)
    return mode

