import json

def suggest_movie(preferences, availability, genre, year):
    # Get list of movies that match user's preferences and availability
    matches = []
    for movie in availability:
        if movie['genre'] == genre and movie['year'] >= year:
            matches.append(movie['title'])

    # Get top matches by considering user's preferences
    top_matches = []
    for match in matches:
        score = 0
        for preference in preferences:
            if preference in match:
                score += 1
        top_matches.append((match, score))

    # Sort top matches in descending order based on score
    top_matches.sort(key=lambda x: x[1], reverse=True)

    # Return the title of the highest-scoring match
    if top_matches:
        return top_matches[0][0]
    else:
        return "No matches found"

