import java.util.HashMap;

public class RemoveDuplicates {

    public static int[] removeDuplicates(int[] array) {
        HashMap<Integer, Boolean> map = new HashMap<>();
        int[] distinctArray = new int[array.length];
        int count = 0;

        //Add elements to Hashmap if it doesn't exist
        for (int i = 0; i < array.length; i++) {
            if (!map.containsKey(array[i])) {
                map.put(array[i], true);
                distinctArray[count++] = array[i];
            }
        }
        //Create new array with the size of the distinct elements
        int[] res = new int[count];
        for (int i = 0; i < count; i++) {
            res[i] = distinctArray[i];
        }
        return res;
    }

    public static void main(String[] args) {
        int[] array = {1,1,2,3,4,4,4,4,4,5};

        int[] res = removeDuplicates(array);
        for (int i = 0; i < res.length; i++) {
            System.out.println(res[i]);
        }
    }
}

