// function for caesar encryption  
void caesar_encrypt(char *plain_text, int key)
{
    int i;

    for (i = 0; i < strlen(plain_text); i++)
    {
        // encrypt uppercase characters
        if (plain_text[i] >= 'A' && plain_text[i] <= 'Z')
        {
            plain_text[i] = plain_text[i] + key;

            // if the encrypted letter goes past 'Z', take it back to 'A'
            if (plain_text[i] > 'Z')
            {
                plain_text[i] = plain_text[i] - 26;
            }
        }

        // encrypt lowercase characters
        else if (plain_text[i] >= 'a' && plain_text[i] <= 'z')
        {
            plain_text[i] = plain_text[i] + key;

            // if the encrypted letter goes past 'z', take it back to 'a'
            if (plain_text[i] > 'z')
            {
                plain_text[i] = plain_text[i] - 26;
            }
        }
    }
}

// function for caesar decryption  
void caesar_decrypt(char *cipher_text, int key)
{
    int i;

    for (i = 0; i < strlen(cipher_text); i++)
    {
        // decrypt uppercase characters
        if (cipher_text[i] >= 'A' && cipher_text[i] <= 'Z')
        {
            cipher_text[i] = cipher_text[i] - key;

            // if the decrypted letter goes past 'A', take it back to 'Z'
            if (cipher_text[i] < 'A')
            {
                cipher_text[i] = cipher_text[i] + 26;
            }
        }

        // decrypt lowercase characters
        else if (cipher_text[i] >= 'a' && cipher_text[i] <= 'z')
        {
            cipher_text[i] = cipher_text[i] - key;

            // if the decrypted letter goes past 'a', take it back to 'z'
            if (cipher_text[i] < 'a')
            {
                cipher_text[i] = cipher_text[i] + 26;
            }
        }
    }
}

