def knapsack(items):
    n = len(items)
    V = [[0 for x in range(n+1)] for x in range(n+1)]

    for i in range(1, n+1):
        for w in range(1, n+1):
            if items[i-1][1] <= w:
                V[i][w] = max(items[i-1][0] + V[i-1][w-items[i-1][1]], V[i-1][w])
            else:
                V[i][w] = V[i-1][w]

    return V[n][n]

