// Function to print a 2D array in spiral pattern 
void spiralPrint(int rows, int cols, vector<vector<int> > arr) 
{ 
	// Initialize starting points 
	int r=0, c=0; 

	// While the row and columnsdid not touch end points 
	while ( r < rows && c < cols) 
	{ 
		// Print first row from the remaining rows 
		for (int i = c; i < cols; i++) 
			cout << arr[r][i] << " "; 
		r++; 

		// Print last column from the remaining columns 
		for (int i = r; i < rows; i++) 
			cout << arr[i][cols-1] << " "; 
		cols--; 

		// Print last row from the remaining rows 
		if ( r < rows) 
		{ 
			for (int i = cols-1; i >= c; i--) 
				cout << arr[rows-1][i] << " "; 
			rows--; 
		} 

		// Print first column from the remaining columns 
		if (c < cols) 
		{ 
			for (int i = rows-1; i >= r; i--) 
				cout << arr[i][c] << " "; 
			c++; 
		} 
	} 
} 

