public class MaximumSum { 

    public static int maxSum(int [][]mat) 
    { 
        // create an auxiliary matrix 
        int auxMat[][] = new int[mat.length][mat[0].length];    

        // Copy the 0th column of the matrix to the auxiliary matrice 
        for (int i = 0; i < auxMat.length; i++){ 
            auxMat[i][0] = mat[i][0]; 
        } 

        // Copy the 0th row of the matrix to the auxiliary matrix 
        for (int i = 0; i < auxMat[0].length; i++){ 
            auxMat[0][i] = mat[0][i]; 
        } 

        // Calculate the maximum sum of elements  
        // in the other cells 
        for (int i = 1; i < auxMat.length; i++){ 
            for (int j = 1; j < auxMat[0].length; j++) 
            { 
                // if the element with value 1 is found, 
                // increment it's value and add the value of 
                // the greatest neighbor in the auxiliary matrix 
                if (mat[i][j] == 1){ 
                    int maxVal = Math.max(auxMat[i][j - 1],  
                                            auxMat[i - 1][j]); 
                    auxMat[i][j] = maxVal + mat[i][j]; 
                } 
            } 
        } 
        // return the last cell of the auxiliary matrix 
        return auxMat[auxMat.length - 1][auxMat[0].length - 1]; 
    } 

