// Returns true if C is a submatrix of A (m x n) 
bool isSubmatrix(int A[][10], int m, int n, 
                 int B[][5], int p, int q) 
{ 
    // T stores the starting 
    // indexes of sub matrix 
    // found 
    int T[2] = { -1, -1 }; 

    int i, j; 

    // Iterate through main matrix and 
    // search a submatrix 
    for (i = 0; i <= m - p; i++) 
    { 
        for (j = 0; j <= n - q; j++) 
        { 
            // Store indexes of current 
            // submatrix 
            int x = i, y = j; 

            // To store the elements 
            // of current submatrix 
            int res[5]; 
            int k = 0; 

            while (k < 5) 
            { 
                res[k] = A[x][y]; 
                k++; 
                y++; 
            } 

            // Check res and B are same 
            // or not 
            int l; 
            for (l = 0; l < 5; l++) 
            { 
                if (res[l] != B[0][l]) 
                    break; 
            } 
            if (l == 5) 
            { 
                T[0] = i; 
                T[1] = j; 
                return true; 
            } 
        } 
    } 

    // No submatrix found
    return false; 
} 

