public class RandomPassword {
 private static final String CHAR_LOWER = "abcdefghijklmnopqrstuvwxyz";
 private static final String CHAR_UPPER = CHAR_LOWER.toUpperCase();
 private static final String NUMBER = "0123456789";

 private static final String DATA_FOR_RANDOM_STRING = CHAR_LOWER + CHAR_UPPER + NUMBER;
 private static Random random = new SecureRandom();

 public static String generateRandomPassword(int length) {
 StringBuilder sb = new StringBuilder(length);
 for (int i = 0; i < length; i++) {
 int rndCharAt = random.nextInt(DATA_FOR_RANDOM_STRING.length());
 char rndChar = DATA_FOR_RANDOM_STRING.charAt(rndCharAt);

 // exclude non-alphanumeric characters
 while(!((rndChar >= '0' && rndChar <='9') || (rndChar >='A' && rndChar <= 'Z') || (rndChar >='a' && rndChar <= 'z'))) {
 rndCharAt = random.nextInt(DATA_FOR_RANDOM_STRING.length());
 rndChar = DATA_FOR_RANDOM_STRING.charAt(rndCharAt);
 }

 sb.append(rndChar);
 }
 return sb.toString();
 }

public static void main(String[] args) {
 String randomPassword = generateRandomPassword(8);
 System.out.println(randomPassword);
}
