package com.example.connect.mysql;

import org.apache.kafka.connect.data.Schema;
import org.apache.kafka.connect.source.SourceRecord;
import org.apache.kafka.connect.source.SourceTask;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class MySqlSourceTask extends SourceTask {

 private String jdbcUrl;
 private String topicName;
 private MySqlConnectorConfig config;

 @Override
 public void start(Map<String, String> props) {
   jdbcUrl = props.get(MySqlConnectorConfig.CONNECTION_URL_CONFIG);
   topicName = props.get(MySqlConnectorConfig.TOPIC_CONFIG);
   config = new MySqlConnectorConfig(props);
 }

 @Override
 public List<SourceRecord> poll() throws InterruptedException {
   List<SourceRecord> sourceRecords = new ArrayList<>();

   MySqlSourceConnector connector = new MySqlSourceConnector(jdbcUrl);
   ResultSet resultSet = connector.executeQuery(config.getQuery());

   try {
     while (resultSet.next()) {
       Schema schema = connector.getSchema(resultSet);
       sourceRecords.add(new SourceRecord(
        connector.getSourcePartition(),
        connector.getSourceOffset(resultSet),
        topicName,
        schema,
        connector.getRecord(resultSet, schema)
        )
       );
     }
   } catch (SQLException e) {
     throw new RuntimeException("Error getting record from MySQL: " + e.toString(), e);
   }

   return sourceRecords;
 }


 @Override
 public void stop() {
   // Nothing to do
 }

 @Override
 public String version() {
   return VersionUtil.getVersion();
 }
}

