    if check_row == False: 
        return False

    check_col = all([k != grid[t][j] for t in range(9)]) 
    if check_col == False: 
        return False

    # check block 
    x_box = 3 * (i//3)
    y_box = 3 * (j//3)

    for row in range(x_box, x_box+3): 
        for col in range(y_box, y_box+3): 
            if grid[row][col] == k: 
