func processSlices(slice1, slice2 []int) []int {
 result := []int{}
 count1 := make(map[int]int)
 count2 := make(map[int]int)

 // Count the number of occurences for each value in both slices
 for _, v := range slice1 {
 count1[v]++
 }
 for _, v := range slice2 {
 count2[v]++
 }

 // Iterate over both slices and add common elements to the result slice
 for n, c1 := range count1 {
 if c2, ok := count2[n]; ok {
 if c1 == c2 {
 // The values and counts are equal, add the value and
 // count to the result
 result = append(result, n, c1)
 } else {
 // The values differ, add the value to the result
 result = append(result, n)
 }
 }
 }
 return result
}

