import java.util.Scanner;

public class TicTacToe {

 public static void main(String[] args) {
  char[][] board = new char[3][3];
  int xPos, yPos;
  Scanner sc = new Scanner(System.in);

  // Initialize board
  for (int i = 0; i < 3; i++) {
   for (int j = 0; j < 3; j++) {
    board[i][j] = '-';
   }
  }

  while (true) {
   printBoard(board);

   System.out.print("Enter x position: ");
   xPos = sc.nextInt();

   System.out.print("Enter y position: ");
   yPos = sc.nextInt();

   board[xPos][yPos] = 'X';

   // Check whether X won
   if (checkWinner('X', board)) {
    System.out.println("X won the game!");
    break;
   }

   // Computer's move
   int[] compMove = generateCompMove(board);
   board[compMove[0]][compMove[1]] = 'O';

   // Check whether O won
   if (checkWinner('O', board)) {
    System.out.println("O won the game!");
    break;
   }
  }

  printBoard(board);
 }

 public static void printBoard(char[][] board) {
  for (int i = 0; i < board.length; i++) {
   for (int j = 0; j < board[i].length; j++) {
    System.out.print(board[i][j] + " ");
   }
   System.out.println();
  }
 }

 public static boolean checkWinner(char player, char[][] board) {
  // Horizontal win
  for (int i = 0; i < board.length; i++) {
   if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
    return true;
   }
  }

  // Vertical win
  for (int j = 0; j < board.length; j++) {
   if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
    return true;
   }
  }

  // Diagonal win
  if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
   return true;
  }
  if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
   return true;
  }

  return false;
 }

 public static int[] generateCompMove(char[][] board) {
  int[] move = new int[2];

  // Generate random move
  while (true) {
   int x = (int)(Math.random() * 3);
   int y = (int)(Math.random() * 3);
   if (board[x][y] == '-') {
    move[0] = x;
    move[1] = y;
    break;
   }
  }

  return move;
 }

}

