const board = [
 ['', '', ''],
 ['', '', ''],
 ['', '', ''],
];
let currentPlayer = 'X';

function isGameOver() {
  let winner = null;
  // check for win
  for (let r = 0; r < 3; r++) {
    // check rows
    if (board[r][0] === board[r][1] && board[r][1] === board[r][2] && board[r][0] !== '') {
      winner = board[r][0];
    }
    // check columns
    if (board[0][r] === board[1][r] && board[1][r] === board[2][r] && board[0][r] !== '') {
      winner = board[0][r];
    }
  }
  // check diagonals
  if (board[0][0] === board[1][1] && board[1][1] === board[2][2] && board[0][0] !== '') {
    winner = board[0][0];
  }
  if (board[0][2] === board[1][1] && board[1][1] === board[2][0] && board[0][2] !== '') {
    winner = board[0][2];
  }
  // check for draw
  let hasEmpty = false;
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      if (board[r][c] === '') {
        hasEmpty = true;
      }
    }
  }
  if (!hasEmpty && winner === null) {
    return 'draw';
  }
  return winner;
}

function makeMove(row, col) {
  if (board[row][col] === '') {
    board[row][col] = currentPlayer;
  } else {
    console.error(`Position (${row}, ${col}) is already taken`);
  }
  let gameOver = isGameOver();
  if (gameOver === 'X') {
    console.log('X Wins!');
  } else if (gameOver === 'O') {
    console.log('O Wins!');
  } else if (gameOver === 'draw') {
    console.log('Tie game!');
  } else {
    currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
  }
}

