// Normalize an array so that its elements have a standard deviation of 1 and a mean of 0 
function normalizeArray(arr) {
  let mean = arr.reduce((a, b) => a + b, 0) / arr.length;
  let sd = Math.sqrt(arr.reduce((sq, n) => sq + Math.pow(n - mean, 2), 0) / arr.length);

  return arr.map(n => (n - mean) / sd);
}

