void rightRotatebyOne(int arr[], int n) 
{ 
	int temp = arr[n-1], i; 
	for (i = n-1; i > 0; i--) 
	 arr[i] = arr[i-1]; 
	arr[0] = temp; 
} 

//function to rotate an array by d elements 
void rotate(int arr[], int d, int n) 
{ 
	int i; 
	for (i = 0; i < d; i++) 
		rightRotatebyOne(arr, n); 
}

