def get_days(year, month):
  # check if the year is a leap year
  is_leap_year = ((year % 4 == 0) and (year % 100 != 0)) or (year % 400 == 0)

  if month == 2 and is_leap_year:
    return 29
  elif month == 2:
    return 28
  elif (month <= 7 and month %2 == 0) or (month > 7 and month %2 == 1):
    return 30
  else:
    return 31

