def find_most_anagrams(words):
  # Keep track of the number of anagrams for each word
  anagrams = {}

  # Iterate over all the words and find their anagrams
  for word in words:
    # Sort the word to find its anagram
    key = ''.join(sorted(word))

    # If the key is already in the dictionary, increment its value
    # otherwise add it with value 1
    if key in anagrams:
        anagrams[key] += 1
    else:
        anagrams[key] = 1

  # Find the maximum value in the dictionary    
  max_anagrams = 0
  anagram_word = ""

  for key, value in anagrams.items():
    if value > max_anagrams:
        max_anagrams = value
        anagram_word = key

  return anagram_word

