def is_latin_square(arr):
    # Check if the number of rows and columns is the same
    num_rows = len(arr)
    num_cols = len(arr[0])
    if num_rows != num_cols:
        return False

    # Check if each row has the same number of elements
    for row in arr: 
        if len(row) != num_cols:
            return False

    # Create a set to store all the elements in the array
    num_set = set()
    # Loop through the array and check if each element has previously appeared
    for row in arr:
        for num in row:
            if num in num_set:
                return False
            else:
                num_set.add(num)

    return True

