function transposeMatrix(arr) {
    var result = new Array(arr[0].length);
    for (var i = 0; i < arr[0].length; i++) {
        result[i] = new Array(arr.length - 1);
        for (var j = arr.length - 1; j > -1; j--) {
            result[i][j] = arr[j][i];
        }
    }
    return result;
}

