def findLongestPalindromicSubsequence(str): 

    # find the length of the string 
    n = len(str) 

    # Create a table to store results of subproblems 
    L = [[0 for x in range(n)] for x in range(n)] 

    # Strings of length 1 are palindrome of lentgh 1 
    for i in range(n): 
        L[i][i] = 1

    # Build the table. Note that the lower  
    # diagonal values of table are 
    # useless and not filled in the process.  
    # The values are filled in a  
    # manner similar to Matrix Chain  
    # Multiplication DP solution (See 
    # https://www.geeksforgeeks.org/dynamic-programming-set-4-longest-common-subsequence/) 
    for cl in range(2, n+1): 
        for i in range(n-cl+1): 
            j = i+cl-1
            if str[i] == str[j] and cl == 2: 
                L[i][j] = 2
            elif str[i] == str[j]: 
                L[i][j] = L[i+1][j-1] + 2
            else: 
                L[i][j] = max(L[i][j-1], L[i+1][j]); 

    # length of longest palindromic subsequence 
    return L[0][n-1]

