public static int[] removeDuplicates(int[] arr) {
	Set<Integer> set = new LinkedHashSet<>();
    for (int num : arr) {
        set.add(num);
    }

    int[] uniqueArr = new int[set.size()];
    int index = 0;
    for (int num : set) {
        uniqueArr[index++] = num;
    }

    return uniqueArr;
}

