def evaluate_expression(expression):
    stack = []
    for i in range(len(expression)):
        if expression[i] == "+" or expression[i] == "-" or expression[i] == "*":
            op2 = int(stack.pop())
            op1 = int(stack.pop())
            if expression[i] == "+":
                stack.append(op1 + op2)
            elif expression[i] == "-":
                stack.append(op1 - op2)
            else:
                stack.append(op1 * op2)
        else:
            stack.append(expression[i])
    return int(stack.pop())

