import random

class ConnectFour:
 def __init__(self):
  self.board = [[0 for i in range(7)] for j in range(6)]

 def get_board(self):
  return self.board

 def valid(self, position):
  return 0 <= position[0] < 6 and 0 <= position[1] < 7

 def set_position(self, position, cur_player):
  row, col = position 
  self.board[row][col] = cur_player

 def valid_positions(self):
  valid_positions = []
  for row in range(6):
   for col in range(7):
    if self.board[row][col] == 0:
     valid_positions.append((row, col))
  return valid_positions

 def minimax(self, depth, cur_player):
  if self.check_winner() == cur_player:
   return 10
  elif self.check_winner() == -cur_player:
   return -10
  elif self.check_winner() == 0:
   return 0

  if depth == 0:
   return 0

  moves = []
  for row, col in self.valid_positions():
   self.set_position( (row, col), cur_player )
   moves.append(self.minimax(depth-1, -cur_player))
   self.set_position( (row, col), 0)

  if cur_player == 1:
   return max(moves)
  else:
   return min(moves)

 def check_winner(self):
  board = self.get_board()

  # checking for rows
  for row in range(6):
   if board[row][0] == board[row][1] == board[row][2] == board[row][3] == board[row][4] == board[row][5] == board[row][6]:
    return board[row][0]

  # checking for columns
  for col in range(7):
   if board[0][col] == board[1][col] == board[2][col] == board[3][col] == board[4][col] == board[5][col]:
    return board[0][col]

  # checking for diagonals
  if (board[2][0] == board[3][1] == board[4][2] == board[5][3]) or (board[1][0] == board[2][1] == board[3][2] == board[4][3] == board[5][4]) or (board[0][0] == board[1][1] == board[2][2] == board[3][3] == board[4][4] == board[5][5]):
   return board[2][0]
  if (board[0][3] == board[1][2] == board[2][1] == board[3][0]) or (board[0][4] == board[1][3] == board[2][2] == board[3][1] == board[4][0]) or (board[0][5] == board[1][4] == board[2][3] == board[3][2] == board[4][1] == board[5][0]):
   return board[0][3]
  if (board[0][6] == board[1][5] == board[2][4] == board[3][3]) or (board[0][5] == board[1][4] == board[2][3] == board[3][2] == board[4][1]):
   return board[0][6]
  if (board[1][6] == board[2][5] == board[3][4] == board[4][3] == board[5][2]):
   return board[1][6]

  for i in range(6):
   for j in range(7):
    if board[i][j] == 0:
     return -1

  return 0

 def play(self):
  while True:
   user_input = input("Enter your choice: ")
   player_move = int(user_input)
   self.set_position(player_move, 1)

   valid_positions = ConnectFour.valid_positions(self)
   scores = []
   for move in valid_positions:
    self.set_position(move, -1)
    score = ConnectFour.minimax(self, 1, -1)
    self.set_position(move, 0)
    scores.append(score)

   ai_move = valid_positions[scores.index(max(scores))]
   self.set_position(ai_move, -1)

   if ConnectFour.check_winner(self) == -1:
    continue
   else:
    break

  if ConnectFour.check_winner(self) == 0:
   print("It's a draw!")
  elif ConnectFour.check_winner(self) == 1:
   print("You Win!")
  else:
   print("You Lose!")

