public class DuplicateNumberDetector {
 public static ArrayList<Integer> detectDuplicates(int[] list) {
  ArrayList<Integer> duplicates = new ArrayList<Integer>();

  for (int i = 0; i < list.length - 1; i++) {
   for (int j = i + 1; j < list.length; j++) {
    if (list[i] == list[j]) {
     duplicates.add(list[i]);
    }
   }
  }

  return duplicates;
 }

 public static void main(String[] args) {
  int[] list = {1, 2, 3, 2, 4};
  ArrayList<Integer> duplicates = detectDuplicates(list);

  System.out.println("Duplicate numbers in given list: " + duplicates);
 }
}

