"""
JavaScript program to find all prime numbers up to a given number
"""

function primeNumber(num) {
    // array to store prime numbers
    const primes = [];
    // iterate through all numbers up to `num`
    for (let i = 0; i <= num; i++) {
        // assume that all numbers are prime 
        let isPrime = true;

        // check if number is divisible by any of the numbers up to its square root 
        for (let j = 2; j <= Math.sqrt(i); j++) {
            if (i % j === 0) { 
                // if any of these is true, the number is not prime
                isPrime = false;
            }
        }

        // if prime, add number to array
        if (isPrime) {
            primes.push(i);
        }
    }

    return primes;
}

