def huffman_encoding(text):
    # Calculate probablities of each character in text

    freq = {}
    for char in text:
        if char not in freq:
            freq[char] = 0
        freq[char] += 1
    freq = { key: value/len(text) for key, value in freq.items() }

    # Build the Huffman Tree

    sorted_freq = sorted(freq.items(), key=lambda x: x[1])
    nodes = []
    for i in range(len(freq)-1):
        node_left = nodes.pop(0) if nodes else sorted_freq.pop(0)
        node_right = sorted_freq.pop(0)
        node = (node_left[0] + node_right[0], node_left[1] + node_right[1])
        nodes.append(node)
        sorted_freq.append(node)
        sorted_freq = sorted(sorted_freq, key=lambda x: x[1])

    # Generate codes

    code = {}
    build_code(nodes[0], '', code)
    return code

def build_code(node, s, code):
    if len(node[0]) == 1:
        code[node[0]] = s
    else:
        build_code(node[0][0], s+'0', code)
