char getMaxOccuringChar(string str) 
{ 
    // Insert all characters and its frequency 
    // in map 
    int n = str.length(); 
    int count[256] = {0}; 
    for (int i = 0; i < n; i++) 
        (count[str[i]])++; 

    int max = -1; // Initialize max count 
    char result;  // Initialize result 

    // Traversing through the string and 
    // maintaining the count of each character 
    for (int i = 0; i < n; i++) { 
        if (max < count[str[i]]) { 
            max = count[str[i]]; 
            result = str[i]; 
        } 
    } 

    return result; 
}

