def bubble_sort(x):
    size = len(x)
    # perform bubble sort
    swap = False
    while not swap:
        swap = True
        for i in range(size-1):
            if x[i] > x[i+1]:
                x[i], x[i+1] = x[i+1], x[i]
                swap = False

    return x

