    if len(str1) != len(str2):
        return False

    # create a dictionary to store characters and their counts for each string
    char_count_1 = {}
    char_count_2 = {}

    # add the characters from str1 to the dictionary
    for char in str1:
        if char not in char_count_1:
            char_count_1[char] = 1
        else:
            char_count_1[char] += 1

    # add the characters from str2 to the dictionary
    for char in str2:
        if char not in char_count_2:
            char_count_2[char] = 1
        else:
            char_count_2[char] += 1

    # check if the two dictionaries are identical
