public class TicTacToe {

    static char board[][] = new char[3][3];
    static int turns = 0;

    public static void main(String[] args) {
        initializeBoard();
        while(true) {
            displayBoard();
            turn(1);
            // 先手なのでチェックを行う
            if(checkWin(1)) {
                System.out.println("Player 1 Wins!");
                break;
            }
            else if(turns == 9) { 
                // 9回目なので引き分け
                System.out.println("Draw!");
                break;
            }
            turn(2);
            // 後手なのでチェックを行う
            if(checkWin(2)) {
                System.out.println("Player 2 Wins!");
                break;
            }			
            turns++;
        }
    }

    // 盤面の初期化
    public static void initializeBoard() {
        for(int i=0; i<3; i++) {
            for(int j=0; j<3; j++) {
                board[i][j] = '-';
            }
        }
    }

    // 盤面の表示
    public static void displayBoard() {
        for(int i=0; i<3; i++) {
            for(int j=0; j<3; j++) {
                System.out.print(board[i][j] + " ");
            }
            System.out.println();
        }
    }

    // プレイヤーが駒を動かす
    public static void turn(int player) {
        Scanner sc = new Scanner(System.in);

        boolean validMove = false;
        while(!validMove) {
            System.out.println("Player " + player + ", enter row:");
            int row = sc.nextInt() - 1;
            System.out.println("Player " + player + ", enter col:");
            int col = sc.nextInt() - 1;

            if(board[row][col] == '-') {
                board[row][col] = (player == 1) ? 'X' : 'O';
                validMove = true;
            }
            else {
                System.out.println("That position is already taken, please try again!");
            }
        }
    }

    // プレイヤーの勝利をチェック
    public static boolean checkWin(int player) {
        char playerChar = (player == 1) ? 'X' : 'O';
        boolean win = false;
        // 横チェック
        for(int i=0; i<3; i++) {
            win = (board[i][0] == playerChar) && (board[i][1] == playerChar) && (board[i][2] == playerChar);
            if(win) return true;
        }
        // 縦チェック
        for(int i=0; i<3; i++) {
            win = (board[0][i] == playerChar) && (board[1][i] == playerChar) && (board[2][i] == playerChar);
            if(win) return true;
        }
        // 対角チェック
        win = (board[0][0] == playerChar) && (board[1][1] == playerChar) && (board[2][2] == playerChar);
        if(win) return true;
        win = (board[0][2] == playerChar) && (board[1][1] == playerChar) && (board[2][0] == playerChar);
        if(win) return true;
        return false;
    }
}

def prime_numbers(start, end):
    primes = []
    for num in range(start, end + 1):
        if num > 1:
            for i in range(2, num):
                if (num % i) == 0:
                    break
            else:
                primes.append(num)
