 List<Integer> sequence = new ArrayList<>();

 int prev1 = 0;
 int prev2 = 1;

 sequence.add(prev1);
 if (n > 1) {
 sequence.add(prev2);

 for (int i = 2; i < n; i++) {
 int result = prev1 + prev2;
 sequence.add(result);

 prev1 = prev2;
 prev2 = result;
 }
 }

