// Function to generate the product arra
int *generate_product_array(int arr[], int n) 
{ 
	// Initializing result array 
	int *result = new int[n]; 

	int temp = 1; 

	// Iterate through the array 
	for (int i = 0; i < n; i++) 
	{ 
		result[i] = temp; 
		temp *= arr[i]; 
	} 

	temp = 1; 

	// Iterate through the array backwards 
	for (int i = n - 1; i >= 0; i--) 
	{ 
		result[i] *= temp; 
		temp *= arr[i]; 
	} 

	return result; 
} 

int main() 
{ 
	// Input array 
	int arr[] = {1, 2, 3}; 

	int n = sizeof(arr) / sizeof(arr[0]); 

	int *result = generate_product_array(arr, n); 

	// Printing the result array 
	cout << "The product array is: "; 
	for (int i = 0; i < n; i++) 
		cout << result[i] << " "; 

	return 0; 
}

