public static string MaxLenCommonSubString(string str1, string str2)
{
    int[,] arr = new int[str1.Length + 1, str2.Length + 1];
    int maxLen = 0;
    int maxIndexI = 0;
    int maxIndexJ = 0;

    for (int i = 0; i <= str1.Length; i++)
    {
        for (int j = 0; j <= str2.Length; j++)
        {
            if (i == 0 || j == 0)
                arr[i, j] = 0;
            else if (str1[i - 1] == str2[j - 1])
            {
                arr[i, j] = arr[i - 1, j - 1] + 1;
                if (arr[i, j] > maxLen)
                {
                    maxLen = arr[i, j];
                    maxIndexI = i;
                    maxIndexJ = j;
                }
            }
            else
            {
                arr[i, j] = 0;
            }
        }
    }

    // To get the longest common substring 
    string maxSubString = "";
    for (int i = maxIndexI; i > maxIndexI - maxLen; i--)
    {
        maxSubString += str1[i - 1];
    }
    return maxSubString;
}

