func sort(arr []int) []int {
    isSorted := false

    for !isSorted {
        isSorted = true
        for i, currentValue := range arr {
            if i == len(arr)-1 {
                break
            }
            nextValue := arr[i+1]

            if currentValue > nextValue {
                arr[i], arr[i+1] = arr[i+1], arr[i]
                isSorted = false
            }
        }
    }
    return arr
}

