int findLongestIncreasingSubsequence(int arr[], int n) { 
    int max_len = 1;
    int i, j;
    int dp[n];

	// Set the size of all the subsequences to 1 
    for (int i = 0; i < n; i++) 
        dp[i] = 1; 

    // For each element, check the subsequent element that is grater
    // than the current one and update max size based on the max size
	// encountered so far
    for (i = 1; i < n; i++) { 
        for (j = 0; j < i; j++) { 
            if (arr[i] > arr[j] && dp[i] < dp[j] + 1) 
                dp[i] = dp[j] + 1; 
        }

		// Update the max size if a larger subsequence is found
        if (max_len < dp[i]) 
            max_len = dp[i]; 
    } 

    return max_len; 
}

