function findLargestPalindrome(nums) {
  const result = nums.reduce((a, b) => {
    const stringNum = b.toString();
    const isPalindrome = stringNum.length === 1 || 
        stringNum.split('').reverse().join('') === stringNum;

    return isPalindrome && b > a ? b : a;
  }, 0);

  return result;
}

