void capitaliseLetters(char str[]) 
{ 
    int i = 0; 

    // Capitalize the first letter in string. 
    if (str[i] >= 'a' && str[i] <= 'z') 
        str[i] = str[i] - 32; 

    // Capitalize remaining all letter from the 2nd. 
    while (str[i] != '\0') { 
        if (str[i] == ' ') { 
            ++i; 

            // Capitalize the letter after the space. 
            if (str[i] >= 'a' && str[i] <= 'z') 
                str[i] = str[i] - 32; 
        } 
        ++i; 
    } 
} 

// Driver code 
int main() 
{ 
    char str[] = "the quick brown fox"; 

    capitaliseLetters(str); 

    printf("Capitalised string: %s\n", str); 

    return 0; 
}

