    int lowerBound = 1;
    int upperBound = 20;
    int i;
    int j;
    int isPrime;

    // Loop through every number from lowerBound to upperBound
    for(i=lowerBound;i<=upperBound;i++) {
        isPrime = 1;
        for(j=2;j<i;j++) {
            // A number is not prime if it can be divide by any numbers
            // from 2 to its square root
            if(i%j == 0) {
                isPrime = 0;
            }
        }
        if(isPrime == 1) {
            NSLog(@"%d is a prime number\n", i);
        }
    }
    return 0;
}

