public class CalculateMedian { 

    public static int findMedian(int[] arr) 
    { 
        int n = arr.length; 
        Arrays.sort(arr); 

        if (n % 2 == 0) 
            return (arr[n / 2] + arr[n / 2 - 1]) / 2; 

        return arr[n / 2]; 
    } 

    public static void main(String[] args) 
    { 
        int[] arr = { 3, 9, 1, 5, 6 }; 

        System.out.print("Median of the array is " + 
                              findMedian(arr)); 
    } 
}

