function simplifyBooleanExpression(expr) {
    expr = expr.replace(/\s+/g, "");
    let modifiedExpr = "";

    for (let i = 0; i < expr.length; i++) {
        let char = expr.charAt(i);
        if (char === "(" && expr.charAt(i+1) === "(" && expr.charAt(i+3) === ")" && expr.charAt(i+4) === ")") {
            modifiedExpr += expr.substring(i+1, i+4);
            i += 4;
        } else {
            modifiedExpr += char;
        }
    }

    return modifiedExpr;
}

