int findMax(int arr[], int n) {
    int max = arr[0];

    for (int i=1; i<n; i++)
        if (arr[i] > max)
            max = arr[i];

    return max;
}

int findMin(int arr[], int n) {
    int min = arr[0];

    for (int i=1; i<n; i++)
        if (arr[i] < min)
            min = arr[i];

    return min;
}

def quick_sort(arr):
    if len(arr) <= 1:
        return arr

    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quick_sort(left) + middle + quick_sort(right)

