def heapify(arr):
    n = len(arr)
    for i in range(n, -1, -1):
        heapify_helper(arr, n, i) 
    return arr

def heapify_helper(arr, n, i):     
    largest = i 
    left = 2 * i + 1      
    right = 2 * i + 2     

    if left < n and arr[i] < arr[left]: 
        largest = left 
    if right < n and arr[largest] < arr[right]: 
        largest = right 
    if largest != i: 
        arr[i],arr[largest] = arr[largest],arr[i] 
        heapify_helper(arr, n, largest)

