def travel_salesman(distance):
    n = len(distance)
    min_cost = float('inf')
    min_path = []

    def backtrack(visited, cur_node, cost):
        nonlocal min_cost
        nonlocal min_path
        if visited == (1 << n) - 1:
            if cost + distance[cur_node][0] < min_cost:
                min_cost = cost + distance[cur_node][0]
                min_path = path + [0]
            return
        for nxt_node in range(n):
            if (not visited & (1 << nxt_node)) and distance[cur_node][nxt_node] != float('inf'):
                backtrack(visited | (1 << nxt_node), nxt_node, cost + distance[cur_node][nxt_node])

    backtrack(1, 0, 0)
    return min_cost, min_path

