public class LongestSubstringWithoutRepeatingCharacters {
    public static String findLongestSubstring(String str) {
        int n = str.length();
        int curLen = 1; 
        int maxLen = 1; 
        int prevIndex; 
        int i; 
        int vis[] = new int[256]; 

        for (i = 0; i < 256; i++){ 
            vis[i] = -1; 
        } 

        vis[str.charAt(0)] = 0; 

        for (i = 1; i < n; i++) { 
            prevIndex = vis[str.charAt(i)]; 

            if (prevIndex == -1 || i - curLen > prevIndex) {
                curLen++; 
            }
            else { 
                if (curLen > maxLen) {
                    maxLen = curLen; 
                }

                curLen = i - prevIndex; 
            } 

            vis[str.charAt(i)] = i; 
        } 

        if (curLen > maxLen) {
            maxLen = curLen; 
        }

        return str.substring(i - maxLen,maxLen); 
    } 
}

