# Function to check whether an expression has balanced parentheses 
def is_balance(string): 
    stack = [] 
    bracket_map = {")": "(", "]": "[", "}": "{"} 

    # Iterate through the string 
    for char in string: 
        # Push to the stack if an opening bracket 
        if char in bracket_map.values(): 
            stack.append(char) 
        elif char in bracket_map.keys():
            top_element = stack.pop() if stack else '#' 
            # Check if mapping requirements are satisfied 
            if bracket_map[char] != top_element: 
                return False
    # Return true when all brackets are macthed
    return not stack 

