public static long maxSubarraySum(int[] arr) {
    long maxSum = 0;
    long currSum = 0;
    int i;

    for (i = 0; i < arr.length; i++) {
        // Increment the current sum by arr[i]
        currSum += arr[i];

        // If current sum is greater than maximum sum,
        // update the maximum sum
        if (currSum > maxSum) {
            maxSum = currSum;
        } 
    }

    // If all the elements in arr are negative, all sums will be negative.
    // So, the maxSum is the largest of all the negative sums
    if (maxSum == 0) {
        maxSum = currSum = arr[0];
        for (i = 1; i < arr.length; i++) {
            currSum = Math.max(arr[i], currSum + arr[i]);
            maxSum = Math.max(maxSum, currSum);
        }
    }

    return maxSum;
}

