 });

 // Iterate over words array
 for(let i=0; i < words.length; i++){

 // Generate hash for every word in array
 let temp_hash = {};
 words[i].split('').sort().forEach(function(letter){
 temp_hash[letter] = (temp_hash[letter] || 0) + 1;
 });

 // Check if hashes are equal
 if(JSON.stringify(word_hash) === JSON.stringify(temp_hash)){
