function permutations(arr) {
  let results = [];

  if (arr.length === 1) {
    results.push([...arr]);
  } else {
    for (let i = 0; i < arr.length; i++) {
      let currElement = arr[i];
      let remElements = [...arr.slice(0, i), ...arr.slice(i + 1)];
      let permutationsOfRemElements = permutations(remElements);

      for (let j = 0; j < permutationsOfRemElements.length; j++) {
        results.push([currElement, ...permutationsOfRemElements[j]]);
      }
    }
  }

  return results;
}

