pca <- function(x) {
  # Calculate the eigenvalues and eigenvectors using the eigen() function
  eigen_values <- eigen(cov(x))

  # Calculate the principal components by multiplying the eigenvectors
  # and the centered data matrix
  PCs <- eigen_values$vectors %*% scale(x, center = TRUE, scale = FALSE)

  return(list("PCs" = PCs, "eigenvalues" = eigen_values$values))
}

